function scheduleReminderTemplate(schedule, type, source = {}) {
    const timingSource = source.schedule || schedule;
    return {
        id: source.id || `care_${Date.now()}_${Math.random().toString(16).slice(2)}`,
        memberId: timingSource.memberId || schedule.memberId,
        type,
        enabled: true,
        startDate: timingSource.startDate || localDateKey(),
        endDate: timingSource.endDate || 'Ongoing',
        freq: scheduleTimingFrequency(timingSource) || timingSource.freq || 'QD',
        times: getScheduleTimes(timingSource),
        intervalHours: timingSource.intervalHours || null,
        intervalWeeks: timingSource.intervalWeeks || null,
        monthlyAnchor: timingSource.monthlyAnchor || '',
        timesPerWeek: timingSource.timesPerWeek || null,
        weekdays: Array.isArray(timingSource.weekdays) ? [...timingSource.weekdays] : [],
        qodStart: timingSource.qodStart || timingSource.startDate || '',
        startTime: timingSource.startTime || getScheduleTimes(timingSource)[0] || '',
        note: source.note || '',
        title: source.title || careReminderTypeLabel(type),
        sourceType: source.sourceType || '',
        sourceId: source.sourceId || '',
        sourceLabel: source.sourceLabel || '',
        sourceRefs: source.sourceType && source.sourceId ? [{ type: source.sourceType, id: source.sourceId, label: source.sourceLabel || '' }] : [],
        holdRule: source.holdRule || null
    };
}

function shiftDateKey(dateKey, offsetDays) {
    if (!dateKey || dateKey === 'Ongoing') return dateKey || '';
    const date = parseLocal(dateKey);
    if (!date) return dateKey;
    date.setDate(date.getDate() + offsetDays);
    return localDateKey(date);
}

function rebaseMonitoringReminderSchedule(config, sourceStart, targetStart, targetEnd = 'Ongoing') {
    if (!config) return null;
    if (config.byType) {
        return {
            byType: Object.entries(config.byType).reduce((acc, [typeId, typeConfig]) => {
                acc[typeId] = rebaseMonitoringReminderSchedule(typeConfig, sourceStart, targetStart, targetEnd);
                return acc;
            }, {})
        };
    }
    const offset = sourceStart && targetStart ? daysBetween(targetStart, sourceStart) : 0;
    const rebased = {
        ...config,
        startDate: shiftDateKey(config.startDate || sourceStart, offset) || targetStart,
        endDate: config.endDate === 'Ongoing' ? 'Ongoing' : (shiftDateKey(config.endDate || sourceStart, offset) || targetEnd || 'Ongoing'),
        monthlyAnchor: shiftDateKey(config.monthlyAnchor, offset),
        qodStart: shiftDateKey(config.qodStart, offset),
        weekdays: Array.isArray(config.weekdays) ? [...config.weekdays] : []
    };
    if (rebased.startDate < targetStart) rebased.startDate = targetStart;
    if (targetEnd && targetEnd !== 'Ongoing' && rebased.endDate !== 'Ongoing' && rebased.endDate > targetEnd) rebased.endDate = targetEnd;
    if (rebased.endDate !== 'Ongoing' && rebased.endDate < rebased.startDate) rebased.endDate = rebased.startDate;
    return rebased;
}

function careReminderHasSource(reminder, sourceType, sourceId) {
    if (!sourceType || !sourceId || !reminder) return false;
    if (reminder.sourceType === sourceType && reminder.sourceId === sourceId) return true;
    return Array.isArray(reminder.sourceRefs) && reminder.sourceRefs.some(ref => ref?.type === sourceType && ref?.id === sourceId);
}

function careReminderMergeKey(reminder) {
    return [
        reminder.memberId || '',
        reminder.type || '',
        reminder.startDate || '',
        reminder.endDate || '',
        scheduleTimingFrequency(reminder) || reminder.freq || '',
        getScheduleTimes(reminder).join(','),
        reminder.intervalHours || '',
        reminder.intervalWeeks || '',
        reminder.monthlyAnchor || '',
        reminder.timesPerWeek || '',
        Array.isArray(reminder.weekdays) ? reminder.weekdays.join(',') : '',
        reminder.qodStart || '',
        JSON.stringify(normalizeHoldRules(reminder.holdRule || null, reminder.memberId || ''))
    ].join('|');
}

function normalizeCareReminderSources(reminders = []) {
    const merged = new Map();
    reminders.forEach(reminder => {
        if (!reminder) return;
        const refs = Array.isArray(reminder.sourceRefs) && reminder.sourceRefs.length
            ? reminder.sourceRefs
            : (reminder.sourceType && reminder.sourceId ? [{ type: reminder.sourceType, id: reminder.sourceId, label: reminder.sourceLabel || '' }] : []);
        const shouldMerge = ['schedule', 'orderSet'].includes(reminder.sourceType) || refs.some(ref => ['schedule', 'orderSet'].includes(ref.type));
        if (!shouldMerge) {
            merged.set(reminder.id || `care_${Date.now()}_${Math.random()}`, { ...reminder, sourceRefs: refs });
            return;
        }
        const key = careReminderMergeKey(reminder);
        const existing = merged.get(key);
        if (!existing) {
            merged.set(key, { ...reminder, sourceRefs: [...refs] });
            return;
        }
        const sourceRefs = [...(existing.sourceRefs || [])];
        refs.forEach(ref => {
            if (ref?.type && ref?.id && !sourceRefs.some(item => item.type === ref.type && item.id === ref.id)) sourceRefs.push(ref);
        });
        const labels = sourceRefs.map(ref => ref.label).filter(Boolean);
        existing.sourceRefs = sourceRefs;
        existing.sourceLabel = labels.length ? Array.from(new Set(labels)).join(', ') : existing.sourceLabel;
        existing.sourceType = sourceRefs.length > 1 ? 'multiple' : existing.sourceType;
        existing.sourceId = sourceRefs.length > 1 ? sourceRefs.map(ref => ref.id).join(',') : existing.sourceId;
        existing.title = `${careReminderTypeLabel(existing.type, existing.memberId)} with ${existing.sourceLabel || 'linked medications'}`;
    });
    return [...merged.values()];
}

function replaceCareRemindersForSource(sourceType, sourceId, reminders = []) {
    ensureCareReminderStore();
    db.careReminders = db.careReminders
        .map(reminder => {
            if (!careReminderHasSource(reminder, sourceType, sourceId)) return reminder;
            const refs = Array.isArray(reminder.sourceRefs) ? reminder.sourceRefs.filter(ref => !(ref?.type === sourceType && ref?.id === sourceId)) : [];
            if (refs.length === 0) return null;
            return {
                ...reminder,
                sourceRefs: refs,
                sourceType: refs.length > 1 ? 'multiple' : refs[0].type,
                sourceId: refs.length > 1 ? refs.map(ref => ref.id).join(',') : refs[0].id,
                sourceLabel: Array.from(new Set(refs.map(ref => ref.label).filter(Boolean))).join(', ')
            };
        })
        .filter(Boolean);
    db.careReminders.push(...reminders);
    db.careReminders = normalizeCareReminderSources(db.careReminders);
}

function createCareRemindersForSchedule(schedule) {
    const types = Array.isArray(schedule.monitoringReminders) ? schedule.monitoringReminders : [];
    const med = db.inventory.find(item => item.id === schedule.medId);
    const sourceLabel = med ? med.name : 'Medication';
    const reminders = types.map(type => {
        const typeSchedule = monitoringScheduleForType(schedule.monitoringReminderSchedule, type);
        const reminderSchedule = typeSchedule
            ? { ...schedule, ...typeSchedule, memberId: schedule.memberId }
            : schedule;
        return scheduleReminderTemplate(schedule, type, {
            sourceType: 'schedule',
            sourceId: schedule.id,
            sourceLabel,
            note: schedule.monitoringReminderNote || '',
            title: `${careReminderTypeLabel(type, schedule.memberId)} with ${sourceLabel}`,
            schedule: reminderSchedule,
            holdRule: schedule.monitoringHoldRule || null
        });
    });
    replaceCareRemindersForSource('schedule', schedule.id, reminders);
    return reminders.length;
}

function createCareRemindersForOrderSet(orderSet) {
    const types = Array.isArray(orderSet.monitoringReminders) ? orderSet.monitoringReminders : [];
    if (!orderSet.memberId || types.length === 0) {
        replaceCareRemindersForSource('orderSet', orderSet.id, []);
        return 0;
    }
    const schedules = db.schedules.filter(schedule => schedule.orderSetId === orderSet.id);
    const reminders = [];
    const seen = new Set();
    types.forEach(type => {
        const typeSchedule = monitoringScheduleForType(orderSet.monitoringReminderSchedule, type);
        (typeSchedule ? [{ ...typeSchedule, memberId: orderSet.memberId }] : schedules).forEach(schedule => {
            const key = [
                type,
                schedule.startDate,
                schedule.endDate,
                scheduleTimingFrequency(schedule) || schedule.freq,
                getScheduleTimes(schedule).join(','),
                schedule.intervalHours || '',
                schedule.intervalWeeks || '',
                schedule.monthlyAnchor || '',
                (schedule.weekdays || []).join(','),
                schedule.timesPerWeek || '',
                schedule.qodStart || ''
            ].join('|');
            if (seen.has(key)) return;
            seen.add(key);
            reminders.push(scheduleReminderTemplate(schedule, type, {
                sourceType: 'orderSet',
                sourceId: orderSet.id,
                sourceLabel: orderSet.name,
                note: orderSet.monitoringReminderNote || '',
                title: `${careReminderTypeLabel(type, orderSet.memberId)} for ${orderSet.name}`,
                schedule,
                holdRule: orderSet.monitoringHoldRule || null
            }));
        });
    });
    replaceCareRemindersForSource('orderSet', orderSet.id, reminders);
    return reminders.length;
}

function careReminderFormIds(prefix) {
    return {
        type: `${prefix}-care-reminder-type`,
        freq: `${prefix}-care-reminder-freq`,
        start: `${prefix}-care-reminder-start`,
        end: `${prefix}-care-reminder-end`,
        controls: `${prefix}-care-reminder-frequency-controls`,
        note: `${prefix}-care-reminder-note`,
        editId: `${prefix}-care-reminder-edit-id`
    };
}

function careReminderTimeDefaults(freq) {
    return freq === 'Nightly' ? ['21:00'] : ['08:00', '12:00', '17:00', '21:00'];
}

window.renderCareReminderFrequencyControls = function(prefix = 'm', existing = null) {
    const ids = careReminderFormIds(prefix);
    const freq = document.getElementById(ids.freq)?.value || 'QD';
    const container = document.getElementById(ids.controls);
    if (!container) return;
    const times = Array.isArray(existing?.times) ? existing.times : [];
    const defaults = careReminderTimeDefaults(freq);
    const count = freq === 'QXH' ? 1 : getExpectedTimeCount(freq);
    const weekdaySelected = Array.isArray(existing?.weekdays) ? existing.weekdays.map(Number) : [];
    const weekHtml = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map((day, index) => {
        const inputId = `${prefix}-care-weekday-${index}`;
        return `<span class="weekday-option"><input id="${inputId}" class="${prefix}-care-weekday" type="checkbox" value="${index}" ${weekdaySelected.includes(index) ? 'checked' : ''}><label for="${inputId}">${day}</label></span>`;
    }).join('');
    container.innerHTML = `
        <div class="care-reminder-extra-row ${freq === 'QOD' ? '' : 'hidden'}">
            <label>Every-other-day start:<input id="${prefix}-care-qod-start" type="date" value="${escapeHtml(existing?.qodStart || document.getElementById(ids.start)?.value || localDateKey())}"></label>
        </div>
        <div class="care-reminder-extra-row ${freq === 'Monthly' ? '' : 'hidden'}">
            <label>First monthly reminder:<input id="${prefix}-care-monthly-anchor" type="date" value="${escapeHtml(existing?.monthlyAnchor || document.getElementById(ids.start)?.value || localDateKey())}"></label>
        </div>
        <div class="care-reminder-extra-row ${freq === 'QXH' ? '' : 'hidden'}">
            <label>Every:<input id="${prefix}-care-interval-hours" type="number" min="1" max="24" step="1" value="${escapeHtml(existing?.intervalHours || 8)}"> hrs</label>
        </div>
        <div class="care-reminder-extra-row ${freq === 'QXW' ? '' : 'hidden'}">
            <label>Every:<input id="${prefix}-care-interval-weeks" type="number" min="1" max="52" step="1" value="${escapeHtml(existing?.intervalWeeks || 2)}"> weeks</label>
        </div>
        <div class="care-reminder-extra-row ${freq === 'XPW' ? '' : 'hidden'}">
            <label>Times per week:<input id="${prefix}-care-times-per-week" type="number" min="1" max="7" step="1" value="${escapeHtml(existing?.timesPerWeek || Math.max(weekdaySelected.length, 1))}"></label>
        </div>
        <div class="weekday-picker care-reminder-weekdays ${['QXW', 'XPW'].includes(freq) ? '' : 'hidden'}"><span>Days:</span>${weekHtml}</div>
        <div class="care-reminder-times">
            ${Array.from({ length: count }, (_, index) => `<label>${freq === 'QXH' ? 'Start time' : `Time ${index + 1}`}<input class="${prefix}-care-time" type="time" value="${escapeHtml(times[index] || defaults[index] || '08:00')}"></label>`).join('')}
        </div>
    `;
    if (['QXW', 'XPW'].includes(freq) && weekdaySelected.length === 0) {
        const startDate = document.getElementById(ids.start)?.value || localDateKey();
        const weekday = parseLocal(startDate)?.getDay() ?? new Date().getDay();
        const checkbox = container.querySelector(`.${prefix}-care-weekday[value="${weekday}"]`);
        if (checkbox) checkbox.checked = true;
    }
};

function collectCareReminderFromProfile(memberId) {
    const prefix = 'm';
    const ids = careReminderFormIds(prefix);
    const type = document.getElementById(ids.type)?.value || 'bp';
    const freq = document.getElementById(ids.freq)?.value || 'QD';
    const startDate = document.getElementById(ids.start)?.value || localDateKey();
    const endDate = document.getElementById(ids.end)?.value || 'Ongoing';
    const rawTimes = Array.from(document.querySelectorAll(`.${prefix}-care-time`)).map(input => input.value).filter(Boolean);
    const intervalHours = freq === 'QXH' ? parseInt(document.getElementById(`${prefix}-care-interval-hours`)?.value, 10) : null;
    const intervalWeeks = freq === 'QXW' ? parseInt(document.getElementById(`${prefix}-care-interval-weeks`)?.value, 10) : null;
    const monthlyAnchor = freq === 'Monthly' ? document.getElementById(`${prefix}-care-monthly-anchor`)?.value : '';
    const weekdays = ['QXW', 'XPW'].includes(freq)
        ? Array.from(document.querySelectorAll(`.${prefix}-care-weekday:checked`)).map(input => parseInt(input.value, 10)).sort()
        : [];
    const timesPerWeek = freq === 'XPW' ? parseInt(document.getElementById(`${prefix}-care-times-per-week`)?.value, 10) : null;
    if (endDate !== 'Ongoing' && endDate < startDate) return { error: 'Reminder end date cannot be before the start date.' };
    if (freq === 'QXH' && (!Number.isInteger(intervalHours) || intervalHours < 1 || intervalHours > 24)) return { error: 'Every X hours must be between 1 and 24.' };
    if (freq === 'QXW' && (!Number.isInteger(intervalWeeks) || intervalWeeks < 1 || intervalWeeks > 52)) return { error: 'Every X weeks must be between 1 and 52.' };
    if (freq === 'XPW' && (!Number.isInteger(timesPerWeek) || timesPerWeek < 1 || timesPerWeek > 7)) return { error: 'Times per week must be between 1 and 7.' };
    if (['QXW', 'XPW'].includes(freq) && weekdays.length === 0) return { error: 'Select at least one weekday for this reminder.' };
    if (freq === 'XPW' && weekdays.length !== timesPerWeek) return { error: `Select exactly ${timesPerWeek} weekday${timesPerWeek === 1 ? '' : 's'}.` };
    if (freq === 'Monthly' && !monthlyAnchor) return { error: 'Enter the first monthly reminder date.' };
    if (rawTimes.length !== (freq === 'QXH' ? 1 : getExpectedTimeCount(freq))) return { error: 'Enter all reminder times.' };
    const times = freq === 'QXH' ? generateIntervalTimes(rawTimes[0], intervalHours) : Array.from(new Set(rawTimes)).sort();
    if (times.length !== rawTimes.length && freq !== 'QXH') return { error: 'Reminder times cannot be duplicated.' };
    return {
        id: document.getElementById(ids.editId)?.value || `care_${Date.now()}_${Math.random().toString(16).slice(2)}`,
        memberId,
        type,
        enabled: true,
        startDate,
        endDate,
        freq,
        times,
        intervalHours,
        intervalWeeks,
        monthlyAnchor: monthlyAnchor || '',
        timesPerWeek,
        weekdays,
        qodStart: freq === 'QOD' ? (document.getElementById(`${prefix}-care-qod-start`)?.value || startDate) : '',
        startTime: freq === 'QXH' ? rawTimes[0] : (times[0] || ''),
        note: document.getElementById(ids.note)?.value.trim() || '',
        title: careReminderTypeLabel(type, memberId),
        sourceType: 'member',
        sourceId: memberId,
        sourceLabel: 'Member profile'
    };
}

window.clearMemberCareReminderForm = function() {
    const ids = careReminderFormIds('m');
    const safeSet = (id, value) => {
        const el = document.getElementById(id);
        if (el) el.value = value;
    };
    safeSet(ids.editId, '');
    renderMonitoringParameterTypeSelect('m', 'bp', currentEditingMemberId);
    safeSet(ids.type, 'bp');
    safeSet(ids.freq, 'QD');
    safeSet(ids.start, localDateKey());
    safeSet(ids.end, '');
    safeSet(ids.note, '');
    renderCareReminderFrequencyControls('m');
    const saveButton = document.getElementById('m-care-reminder-save-button');
    if (saveButton) saveButton.textContent = 'Add Reminder';
};

function careReminderNextInstances(reminder, days = 14, fromDate = new Date()) {
    const start = new Date(fromDate);
    start.setHours(0, 0, 0, 0);
    const rows = [];
    for (let i = 0; i < days; i++) {
        const date = new Date(start);
        date.setDate(start.getDate() + i);
        const dateKey = localDateKey(date);
        if (!isScheduleDueOnDate(reminder, dateKey)) continue;
        getScheduleTimes(reminder).forEach(time => {
            rows.push({
                date: dateKey,
                time,
                logged: careReminderReadingLoggedForInstance(reminder, dateKey, time)
            });
        });
    }
    return rows.sort((a, b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`));
}

function careReminderSourceText(reminder) {
    const refs = Array.isArray(reminder.sourceRefs) ? reminder.sourceRefs.filter(ref => ref?.label) : [];
    if (refs.length > 1) return `Linked medications: ${Array.from(new Set(refs.map(ref => ref.label))).join(', ')}`;
    if (reminder.sourceType === 'schedule') return `Medication: ${reminder.sourceLabel || 'scheduled medication'}`;
    if (reminder.sourceType === 'orderSet') return `Regimen: ${reminder.sourceLabel || 'assigned regimen'}`;
    return reminder.sourceLabel || 'Member profile';
}

function careReminderStatusBucket(reminder, today = localDateKey()) {
    const instances = careReminderNextInstances(reminder, 14);
    const todayInstances = instances.filter(instance => instance.date === today);
    if (todayInstances.some(instance => !instance.logged)) return 'today';
    if (todayInstances.length && todayInstances.every(instance => instance.logged)) return 'logged';
    return instances.length ? 'upcoming' : 'inactive';
}

function careReminderDashboardRow(reminder) {
    const type = monitoringParameterTypeById(reminder.type, reminder.memberId);
    const instances = careReminderNextInstances(reminder, 14);
    const next = instances.find(instance => !instance.logged) || instances[0];
    const nextText = next
        ? `${next.date} ${next.time}${next.logged ? ' logged' : ''}`
        : 'No upcoming date in the next 14 days';
    const todayInstances = careReminderNextInstances(reminder, 1).filter(instance => instance.date === localDateKey());
    const loggedCount = todayInstances.filter(instance => instance.logged).length;
    const statusText = todayInstances.length === 0
        ? 'Scheduled'
        : loggedCount === todayInstances.length
            ? 'Logged today'
            : loggedCount > 0
                ? `${loggedCount}/${todayInstances.length} logged`
                : 'Scheduled';
    const loggedToday = todayInstances.length > 0 && loggedCount === todayInstances.length;
    return `<div class="care-reminder-row care-reminder-dashboard-row" style="--reminder-color:${escapeHtml(type.color || '#eef8ff')};">
        <span class="care-reminder-icon">${escapeHtml(type.icon || 'MP')}</span>
        <span class="care-reminder-copy">
            <strong>${monitoringLinkedSymbolHtml(reminder.type, reminder.memberId)}${escapeHtml(careReminderTypeLabel(reminder.type, reminder.memberId))}</strong>
            <small><b>${escapeHtml(formatFrequency(reminder))}</b> ${escapeHtml(getScheduleTimes(reminder).join(', ') || 'No time set')}</small>
            <small>Next: ${escapeHtml(nextText)}</small>
            <small>${escapeHtml(careReminderSourceText(reminder))}${reminder.note ? ` | ${escapeHtml(reminder.note)}` : ''}</small>
        </span>
        <span class="care-reminder-actions">
            <span class="care-reminder-status ${loggedToday ? 'logged' : ''}">${escapeHtml(statusText)}</span>
            <button type="button" onclick="logCareReminderReading('${escapeHtml(reminder.id)}', '${escapeHtml(next?.date || '')}', '${escapeHtml(next?.time || '')}')">Log</button>
            <button type="button" onclick="editMemberCareReminder('${escapeHtml(reminder.id)}')">Edit</button>
            <button type="button" onclick="deleteMemberCareReminder('${escapeHtml(reminder.id)}')">Delete</button>
        </span>
    </div>`;
}

function renderMemberCareReminders(memberId = currentEditingMemberId) {
    const list = document.getElementById('member-care-reminder-list');
    if (!list) return;
    if (!memberId) {
        list.innerHTML = '<div class="empty-state">Save the member before adding reminders.</div>';
        return;
    }
    renderMonitoringParameterTypeSelect('m', document.getElementById('m-care-reminder-type')?.value || 'bp', memberId);
    const reminders = ensureCareReminderStore()
        .filter(reminder => reminder.memberId === memberId && reminder.enabled !== false)
        .sort((a, b) => (timeToMinutes(getScheduleTimes(a)[0]) ?? 9999) - (timeToMinutes(getScheduleTimes(b)[0]) ?? 9999) || careReminderTypeLabel(a.type, a.memberId).localeCompare(careReminderTypeLabel(b.type, b.memberId)));
    if (reminders.length === 0) {
        list.innerHTML = '<div class="empty-state">No monitoring parameters scheduled.</div>';
        return;
    }
    const today = localDateKey();
    const profileReminderCount = reminders.filter(reminder => careReminderVitalType(reminder.type, reminder.memberId) === 'med-monitor').length;
    const dueToday = reminders.filter(reminder => careReminderNextInstances(reminder, 1).some(instance => instance.date === today && !instance.logged)).length;
    const loggedToday = reminders.filter(reminder => careReminderNextInstances(reminder, 1).some(instance => instance.date === today && instance.logged)).length;
    const buckets = reminders.reduce((acc, reminder) => {
        const bucket = careReminderStatusBucket(reminder, today);
        if (!acc[bucket]) acc[bucket] = [];
        acc[bucket].push(reminder);
        return acc;
    }, {});
    const group = (title, bucket, empty) => buckets[bucket]?.length
        ? `<details class="care-reminder-group" open><summary>${escapeHtml(title)} (${buckets[bucket].length})</summary>${buckets[bucket].map(careReminderDashboardRow).join('')}</details>`
        : `<details class="care-reminder-group"><summary>${escapeHtml(title)} (0)</summary><div class="empty-state">${escapeHtml(empty)}</div></details>`;
    list.innerHTML = `
        <div class="monitoring-schedule-dashboard">
            <div class="monitoring-schedule-stat"><strong>${reminders.length}</strong><span>Scheduled</span></div>
            <div class="monitoring-schedule-stat today"><strong>${dueToday}</strong><span>Due today</span></div>
            <div class="monitoring-schedule-stat logged"><strong>${loggedToday}</strong><span>Logged today</span></div>
            <div class="monitoring-schedule-stat labs"><strong>${profileReminderCount}</strong><span>Lab/level</span></div>
        </div>
        ${group('Due today', 'today', 'No monitoring parameters due today.')}
        ${group('Logged today', 'logged', 'No monitoring parameters logged today yet.')}
        ${group('Upcoming', 'upcoming', 'No upcoming monitoring parameters in the next 14 days.')}
        ${group('Inactive / out of range', 'inactive', 'No inactive monitoring parameters.')}`;
}

window.saveMemberCareReminder = async function() {
    const member = db.family.find(item => item.id === currentEditingMemberId);
    if (!member) {
        await appAlert('Save the member before adding reminders.');
        return;
    }
    const reminder = collectCareReminderFromProfile(member.id);
    if (reminder.error) {
        await appAlert(reminder.error, 'Reminder Needs Review');
        return;
    }
    ensureCareReminderStore();
    const existingIndex = db.careReminders.findIndex(item => item.id === reminder.id);
    if (existingIndex >= 0) db.careReminders[existingIndex] = { ...db.careReminders[existingIndex], ...reminder };
    else db.careReminders.push(reminder);
    addAudit(existingIndex >= 0 ? 'Reminder updated' : 'Reminder added', memberDisplayName(member), `${careReminderTypeLabel(reminder.type, member.id)} | ${formatFrequency(reminder)} ${getScheduleTimes(reminder).join(', ')}`);
    await sync();
    clearMemberCareReminderForm();
    refreshMonitoringAfterLog(member.id);
};

window.editMemberCareReminder = function(id) {
    const reminder = ensureCareReminderStore().find(item => item.id === id);
    if (!reminder) return;
    const ids = careReminderFormIds('m');
    const safeSet = (fieldId, value) => {
        const el = document.getElementById(fieldId);
        if (el) el.value = value ?? '';
    };
    safeSet(ids.editId, reminder.id);
    renderMonitoringParameterTypeSelect('m', reminder.type || 'bp', reminder.memberId);
    safeSet(ids.type, reminder.type || 'bp');
    safeSet(ids.freq, scheduleTimingFrequency(reminder) || reminder.freq || 'QD');
    safeSet(ids.start, reminder.startDate || localDateKey());
    safeSet(ids.end, reminder.endDate === 'Ongoing' ? '' : (reminder.endDate || ''));
    safeSet(ids.note, reminder.note || '');
    renderCareReminderFrequencyControls('m', reminder);
    const saveButton = document.getElementById('m-care-reminder-save-button');
    if (saveButton) saveButton.textContent = 'Update Reminder';
    document.getElementById(ids.type)?.scrollIntoView({ block: 'center', behavior: 'smooth' });
    setTimeout(() => document.getElementById(ids.type)?.focus(), 80);
};

window.deleteMemberCareReminder = async function(id) {
    if (!await appConfirm('Delete this reminder?', 'Delete Reminder')) return;
    ensureCareReminderStore();
    db.careReminders = db.careReminders.filter(item => item.id !== id);
    await sync();
    refreshMonitoringAfterLog(currentEditingMemberId);
};

function currentTimeInputValue(date = new Date()) {
    return `${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;
}

function refreshMonitoringAfterLog(memberId) {
    window.renderVitals?.();
    window.renderVitalDashboard?.();
    if (memberId || currentEditingMemberId) renderMemberCareReminders(memberId || currentEditingMemberId);
    if (currentEditingMemberId) {
        const trends = document.getElementById('member-vitals-trends');
        if (trends) renderMemberVitalCharts(currentEditingMemberId, trends);
        const reminders = document.getElementById('member-care-reminder-list');
        if (reminders && currentEditingMemberId !== memberId) renderMemberCareReminders(currentEditingMemberId);
    }
    window.renderCalendar?.();
}

function careReminderLogFieldsHtml(reminder, targetType, now = new Date()) {
    const member = db.family.find(item => item.id === reminder.memberId);
    const dateTimeHtml = `
        <div class="field-row">
            <label>Date:</label><input name="date" type="date" value="${escapeHtml(localDateKey(now))}">
            <label>Time:</label><input name="time" type="time" value="${escapeHtml(currentTimeInputValue(now))}">
        </div>`;
    let fields = '';
    if (targetType === 'bp') {
        fields = reminder.type === 'hr'
            ? `<div class="field-row" style="margin-top:8px;">
                    <label>Heart rate / pulse:</label><input name="hr" type="number" step="1" style="width:80px;"> <span>bpm</span>
                </div>`
            : `<div class="field-row" style="margin-top:8px;">
                    <label>Systolic:</label><input name="systolic" type="number" step="1" style="width:70px;">
                    <label>Diastolic:</label><input name="diastolic" type="number" step="1" style="width:70px;">
                    <label>HR / pulse:</label><input name="hr" type="number" step="1" style="width:70px;"> <span>bpm optional</span>
                </div>`;
    } else if (targetType === 'weight') {
        fields = `<div class="field-row" style="margin-top:8px;">
            <label>Weight:</label><input name="weight" type="number" step="0.1" style="width:90px;">
            <select name="weightUnit"><option value="lb">lb</option><option value="kg">kg</option></select>
        </div>`;
    } else if (targetType === 'glucose') {
        fields = `<div class="field-row" style="margin-top:8px;">
            <label>Blood glucose:</label><input name="glucose" type="number" step="1" style="width:90px;"> <span>mg/dL</span>
        </div>`;
    } else if (targetType === 'temperature') {
        fields = `<div class="field-row" style="margin-top:8px;">
            <label>Temperature:</label><input name="temperature" type="number" step="0.1" style="width:90px;">
            <select name="temperatureUnit"><option value="F">Fahrenheit (F)</option><option value="C">Celsius (C)</option></select>
        </div>`;
    } else if (targetType === 'med-monitor') {
        const profile = monitoringProfileById(member, String(reminder.type || '').slice('monitor:'.length));
        fields = profile
            ? `<div class="field-row" style="margin-top:8px;">
                    <label>${escapeHtml(profile.labName)}:</label><input name="monitorValue" type="number" step="any" style="width:90px;">
                    <span>${escapeHtml(profile.unit || 'value')}</span>
                    <span class="form-help">${escapeHtml(monitoringGoalText(profile))}</span>
                </div>`
            : '<div class="form-help">This monitoring profile could not be found.</div>';
    }
    return `
        ${dateTimeHtml}
        ${fields}
        <div class="field-row-stacked" style="margin-top:8px;">
            <label>Note:</label>
            <textarea name="notes" rows="3" style="width:100%; resize:vertical;" placeholder="Optional note, result, symptoms, or follow-up">${escapeHtml(reminder.note || '')}</textarea>
        </div>`;
}

function buildCareReminderReading(reminder, targetType, result) {
    const reading = {
        id: `vital_${Date.now()}_${Math.random().toString(16).slice(2)}`,
        memberId: reminder.memberId,
        type: targetType,
        date: result.date || localDateKey(),
        time: result.time || currentTimeInputValue(),
        notes: result.notes || '',
        sourceReminderId: reminder.id,
        sourceReminderType: reminder.type
    };
    if (targetType === 'bp') {
        if (reminder.type === 'hr') {
            reading.hr = parseAmount(result.hr, NaN);
            if (!Number.isFinite(reading.hr)) return { error: 'Heart rate / pulse is required.' };
            reading.systolic = '';
            reading.diastolic = '';
        } else {
            reading.systolic = parseAmount(result.systolic, NaN);
            reading.diastolic = parseAmount(result.diastolic, NaN);
            reading.hr = parseAmount(result.hr, NaN);
            if (!Number.isFinite(reading.systolic) || !Number.isFinite(reading.diastolic)) return { error: 'Systolic and diastolic BP are required.' };
            if (!Number.isFinite(reading.hr)) reading.hr = '';
        }
    } else if (targetType === 'weight') {
        reading.weight = parseAmount(result.weight, NaN);
        reading.weightUnit = result.weightUnit || 'lb';
        if (!Number.isFinite(reading.weight)) return { error: 'Weight is required.' };
    } else if (targetType === 'glucose') {
        reading.glucose = parseAmount(result.glucose, NaN);
        if (!Number.isFinite(reading.glucose)) return { error: 'Blood glucose is required.' };
    } else if (targetType === 'temperature') {
        reading.temperature = parseAmount(result.temperature, NaN);
        reading.temperatureUnit = result.temperatureUnit || 'F';
        if (!Number.isFinite(reading.temperature)) return { error: 'Temperature is required.' };
    } else if (targetType === 'med-monitor') {
        const member = db.family.find(item => item.id === reminder.memberId);
        const profile = monitoringProfileById(member, String(reminder.type || '').slice('monitor:'.length));
        const monitorValue = parseAmount(result.monitorValue, NaN);
        if (!profile || !Number.isFinite(monitorValue)) return { error: 'A valid monitored lab or level value is required.' };
        reading.type = 'med-monitor';
        reading.monitoringId = profile.id;
        reading.monitorValue = monitorValue;
        reading.monitorName = profile.labName;
        reading.medicationName = profile.medicationName;
        reading.monitorUnit = profile.unit;
        reading.goalLow = profile.goalLow;
        reading.goalHigh = profile.goalHigh;
        reading.medId = profile.medId || '';
    }
    return { reading };
}

window.logCareReminderReading = async function(id, scheduledDate = '', scheduledTime = '') {
    const reminder = ensureCareReminderStore().find(item => item.id === id);
    if (!reminder) return;
    const targetType = careReminderVitalType(reminder.type, reminder.memberId);
    if (!['bp', 'weight', 'glucose', 'temperature', 'med-monitor'].includes(targetType)) {
        const parameterType = monitoringParameterTypeById(reminder.type, reminder.memberId);
        const holdCap = parameterType.holdCapability;
        const now = new Date();
        const result = await showActionModal(`Document ${careReminderTypeLabel(reminder.type, reminder.memberId)}`, `
            <div class="field-row">
                <label>Date:</label><input name="date" type="date" value="${escapeHtml(localDateKey(now))}">
                <label>Time:</label><input name="time" type="time" value="${escapeHtml(`${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`)}">
            </div>
            ${holdCap?.enabled ? `<div class="field-row" style="margin-top:8px;">
                <label>${escapeHtml(holdCap.metricLabel || parameterType.label || 'Value')}:</label>
                <input name="customValue" type="number" step="any" style="width:90px;">
                <span>${escapeHtml(holdCap.unit || '')}</span>
            </div>` : ''}
            <div class="field-row-stacked" style="margin-top:8px;">
                <label>Note:</label>
                <textarea name="notes" rows="3" style="width:100%; resize:none;" placeholder="Optional note, result, or follow-up">${escapeHtml(reminder.note || '')}</textarea>
            </div>
        `, 'Save Log');
        if (!result) return;
        const customValue = holdCap?.enabled ? parseAmount(result.customValue, NaN) : 1;
        if (holdCap?.enabled && !Number.isFinite(customValue)) {
            await appAlert(`Enter a numeric value for ${holdCap.metricLabel || parameterType.label}.`);
            return;
        }
        db.vitals.push({
            id: `vital_${Date.now()}_${Math.random().toString(16).slice(2)}`,
            memberId: reminder.memberId,
            type: targetType || 'custom',
            customReminderType: reminder.type,
            date: result.date || localDateKey(now),
            time: result.time || '08:00',
            sourceReminderId: reminder.id,
            sourceReminderType: reminder.type,
            sourceReminderScheduledDate: scheduledDate || '',
            sourceReminderScheduledTime: scheduledTime || '',
            value: customValue,
            valueLabel: holdCap?.metricLabel || '',
            valueUnit: holdCap?.unit || '',
            notes: result.notes || ''
        });
        addAudit('Monitoring parameter documented', careReminderTypeLabel(reminder.type, reminder.memberId), `${result.date || localDateKey(now)} ${result.time || ''}`);
        await sync();
        refreshMonitoringAfterLog(reminder.memberId);
        return;
    }
    const now = new Date();
    const result = await showActionModal(`Log ${careReminderTypeLabel(reminder.type, reminder.memberId)}`, careReminderLogFieldsHtml(reminder, targetType, now), 'Save Log');
    if (!result) return;
    const built = buildCareReminderReading(reminder, targetType, result);
    if (built.error) {
        await appAlert(built.error);
        return;
    }
    built.reading.sourceReminderScheduledDate = scheduledDate || '';
    built.reading.sourceReminderScheduledTime = scheduledTime || '';
    db.vitals.unshift(built.reading);
    addAudit('Monitoring parameter documented', careReminderTypeLabel(reminder.type, reminder.memberId), `${built.reading.date} ${built.reading.time}`);
    await sync();
    refreshMonitoringAfterLog(reminder.memberId);
};

function careReminderReadingLoggedForInstance(reminder, date, time) {
    const targetType = careReminderVitalType(reminder?.type, reminder?.memberId);
    const targetMinutes = timeToMinutes(time);
    return db.vitals.some(reading => {
        if (reading.memberId !== reminder.memberId || reading.type !== targetType) return false;
        if (targetType === 'med-monitor' && reading.monitoringId !== String(reminder.type || '').slice('monitor:'.length)) return false;
        if (targetType === 'bp') {
            if (reminder.type === 'hr' && !Number.isFinite(parseAmount(reading.hr, NaN))) return false;
            if (reminder.type === 'bp' && (!Number.isFinite(parseAmount(reading.systolic, NaN)) || !Number.isFinite(parseAmount(reading.diastolic, NaN)))) return false;
        }
        if (!['bp', 'weight', 'glucose', 'temperature', 'med-monitor'].includes(targetType) && reading.customReminderType !== reminder.type) return false;
        if (reading.sourceReminderId === reminder.id && reading.sourceReminderScheduledDate === date && reading.sourceReminderScheduledTime === time) return true;
        if (reading.date !== date) return false;
        const readingMinutes = timeToMinutes(reading.time || '00:00');
        if (targetMinutes === null || readingMinutes === null) return true;
        return readingMinutes >= targetMinutes - 60 && readingMinutes <= targetMinutes + 180;
    });
}

function parseAmount(value, fallback = 0) {
    const amount = parseFloat(value);
    return Number.isFinite(amount) ? amount : fallback;
}

function normalizeNumberForDisplay(amount) {
    const value = typeof amount === 'number' ? amount : Number(amount);
    if (!Number.isFinite(value)) return value;
    const rounded = Number(value.toFixed(8));
    return Math.abs(value - rounded) < 1e-9 ? rounded : value;
}

function isAtOrBelowThreshold(stock, threshold) {
    const stockAmount = parseAmount(stock, NaN);
    const thresholdAmount = parseAmount(threshold, NaN);
    if (!Number.isFinite(stockAmount) || !Number.isFinite(thresholdAmount)) return false;
    return stockAmount <= thresholdAmount + 1e-9;
}

function parseMoney(value, fallback = 0) {
    const amount = parseFloat(String(value || '').replace(/[$,\s]/g, ''));
    return Number.isFinite(amount) ? amount : fallback;
}

function formatAmount(value) {
    const amount = normalizeNumberForDisplay(typeof value === 'number' ? value : Number(value));
    if (!Number.isFinite(amount)) return '0';
    return amount.toLocaleString('en-US', {
        useGrouping: false,
        maximumFractionDigits: 20
    });
}

function getMemberGoals(member) {
    return {
        glucose: { preset: 'diabetic', ...glucoseGoalPresets.diabetic, ...(member?.vitalGoals?.glucose || {}) },
        bp: { ...defaultBpGoals, ...(member?.vitalGoals?.bp || {}) },
        hr: { ...defaultHrGoals, ...(member?.vitalGoals?.hr || {}) },
        weight: { ...defaultWeightGoals, ...(member?.vitalGoals?.weight || {}) }
    };
}

function updateGoalReferenceNotes() {
    const glucosePreset = document.getElementById('m-glucose-preset')?.value || 'custom';
    const bpPreset = document.getElementById('m-bp-preset')?.value || 'custom';
    const glucoseNote = document.getElementById('m-glucose-goal-note');
    const bpNote = document.getElementById('m-bp-goal-note');
    if (glucoseNote) glucoseNote.textContent = glucoseGoalPresets[glucosePreset]?.note || glucoseGoalPresets.custom.note;
    if (bpNote) bpNote.textContent = bpGoalPresets[bpPreset]?.note || bpGoalPresets.custom.note;
}

window.markGoalPresetCustom = function(selectId) {
    const select = document.getElementById(selectId);
    if (select) select.value = 'custom';
    updateGoalReferenceNotes();
};

window.applyGlucosePreset = function() {
    const preset = document.getElementById('m-glucose-preset')?.value || 'custom';
    const goals = glucoseGoalPresets[preset];
    if (!goals) return;
    if (preset === 'custom') {
        updateGoalReferenceNotes();
        return;
    }
    document.getElementById('m-glucose-low').value = goals.low;
    document.getElementById('m-glucose-high').value = goals.high;
    updateGoalReferenceNotes();
};

window.applyBpPreset = function() {
    const preset = document.getElementById('m-bp-preset')?.value || 'custom';
    const goals = bpGoalPresets[preset];
    if (!goals) return;
    if (preset === 'custom') {
        updateGoalReferenceNotes();
        return;
    }
    document.getElementById('m-bp-sys-low').value = goals.systolicLow;
    document.getElementById('m-bp-sys-high').value = goals.systolicHigh;
    document.getElementById('m-bp-dia-low').value = goals.diastolicLow;
    document.getElementById('m-bp-dia-high').value = goals.diastolicHigh;
    updateGoalReferenceNotes();
};

function setMemberGoalFields(member) {
    const goals = getMemberGoals(member);
    const safeSet = (id, value) => {
        const el = document.getElementById(id);
        if (el) el.value = value ?? '';
    };
    safeSet('m-glucose-preset', goals.glucose.preset);
    safeSet('m-glucose-low', goals.glucose.low);
    safeSet('m-glucose-high', goals.glucose.high);
    safeSet('m-bp-preset', goals.bp.preset || 'treated');
    safeSet('m-bp-sys-low', goals.bp.systolicLow);
    safeSet('m-bp-sys-high', goals.bp.systolicHigh);
    safeSet('m-bp-dia-low', goals.bp.diastolicLow);
    safeSet('m-bp-dia-high', goals.bp.diastolicHigh);
    safeSet('m-hr-low', goals.hr.low);
    safeSet('m-hr-high', goals.hr.high);
    safeSet('m-weight-low', goals.weight.low);
    safeSet('m-weight-high', goals.weight.high);
    safeSet('m-weight-unit', goals.weight.unit || 'lb');
    updateGoalReferenceNotes();
}

function collectMemberGoals() {
    const goals = {
        glucose: {
            preset: document.getElementById('m-glucose-preset').value,
            low: parseAmount(document.getElementById('m-glucose-low').value, 70),
            high: parseAmount(document.getElementById('m-glucose-high').value, 180)
        },
        bp: {
            preset: document.getElementById('m-bp-preset')?.value || 'custom',
            systolicLow: parseAmount(document.getElementById('m-bp-sys-low').value, 90),
            systolicHigh: parseAmount(document.getElementById('m-bp-sys-high').value, 130),
            diastolicLow: parseAmount(document.getElementById('m-bp-dia-low').value, 60),
            diastolicHigh: parseAmount(document.getElementById('m-bp-dia-high').value, 80)
        },
        hr: {
            low: parseAmount(document.getElementById('m-hr-low').value, 60),
            high: parseAmount(document.getElementById('m-hr-high').value, 100)
        },
        weight: {
            low: document.getElementById('m-weight-low').value === '' ? '' : parseAmount(document.getElementById('m-weight-low').value, NaN),
            high: document.getElementById('m-weight-high').value === '' ? '' : parseAmount(document.getElementById('m-weight-high').value, NaN),
            unit: document.getElementById('m-weight-unit').value || 'lb'
        }
    };
    if (goals.glucose.high <= goals.glucose.low) {
        void appAlert('Glucose high goal must be greater than glucose low goal.', 'Goal Needs Review');
        return null;
    }
    if (goals.bp.systolicHigh <= goals.bp.systolicLow || goals.bp.diastolicHigh <= goals.bp.diastolicLow) {
        void appAlert('BP high goals must be greater than BP low goals.', 'Goal Needs Review');
        return null;
    }
    if (goals.hr.high <= goals.hr.low) {
        void appAlert('Heart rate high goal must be greater than heart rate low goal.', 'Goal Needs Review');
        return null;
    }
    if (Number.isFinite(goals.weight.low) && Number.isFinite(goals.weight.high) && goals.weight.high <= goals.weight.low) {
        void appAlert('Weight high goal must be greater than weight low goal.', 'Goal Needs Review');
        return null;
    }
    return goals;
}

function escapeHtml(value) {
    return String(value ?? '').replace(/[&<>"']/g, char => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
    }[char]));
}

function getComponentUnit(component, med) {
    return component.unit || med.units || 'mg';
}

function formatComponentStrength(component, med, includeName = false) {
    const name = includeName && component.name ? `${component.name} ` : '';
    const rawStrength = Number.isFinite(parseAmount(component.strengthAmount, NaN))
        ? parseAmount(component.strengthAmount)
        : parseAmount(component.strength);
    const perAmount = parseAmount(component.perAmount, NaN);
    const denominator = component.perUnit && Number.isFinite(perAmount) && perAmount > 0
        ? `/${perAmount === 1 ? '' : formatAmount(perAmount)}${component.perUnit}`
        : '';
    return `${name}${formatAmount(rawStrength)}${getComponentUnit(component, med)}${denominator}`;
}

function sharedComponentDenominator(components) {
    if (!Array.isArray(components) || components.length === 0) return null;
    const firstAmount = parseAmount(components[0].perAmount, NaN);
    const firstUnit = components[0].perUnit || '';
    if (!firstUnit || !Number.isFinite(firstAmount) || firstAmount <= 0) return null;
    const isShared = components.every(component =>
        component.perUnit === firstUnit &&
        parseAmount(component.perAmount, NaN) === firstAmount
    );
    return isShared ? { amount: firstAmount, unit: firstUnit } : null;
}

function formatCombinationStrength(med, includeNames = false, includeSolidDenominator = true) {
    const components = med?.components || [];
    const sharedDenominator = sharedComponentDenominator(components);
    if (!sharedDenominator) {
        return components.map(component => formatComponentStrength(component, med, includeNames)).join('/');
    }
    const numerators = components.map(component => {
        const name = includeNames && component.name ? `${component.name} ` : '';
        const rawStrength = Number.isFinite(parseAmount(component.strengthAmount, NaN))
            ? parseAmount(component.strengthAmount)
            : parseAmount(component.strength) * sharedDenominator.amount;
        return `${name}${formatAmount(rawStrength)}${getComponentUnit(component, med)}`;
    });
    const isLiquidDenominator = ['mL', 'L'].includes(sharedDenominator.unit);
    const denominator = includeSolidDenominator || isLiquidDenominator
        ? `/${sharedDenominator.amount === 1 ? '' : formatAmount(sharedDenominator.amount)}${sharedDenominator.unit}`
        : '';
    return `${numerators.join('/')}${denominator}`;
}

function formatInventoryUnits(med) {
    if (!med?.isCombination || !Array.isArray(med.components) || med.components.length === 0) {
        return normalizeSlashPartsText(med?.units || '');
    }
    const units = Array.from(new Set(med.components.map(component => getComponentUnit(component, med)).filter(Boolean)));
    const sharedDenominator = sharedComponentDenominator(med.components);
    return normalizeSlashPartsText(`${units.join('/')}${sharedDenominator ? `/${formatAmount(sharedDenominator.amount)}${sharedDenominator.unit}` : ''}`);
}

function compactRepeatedDenominatorText(value) {
    const text = String(value || '').trim().replace(/\s*\n+\s*/g, ' / ').replace(/\s{2,}/g, ' ');
    if (!text) return '';
    const parts = text.split(/\s+\/\s+/).map(part => part.trim()).filter(Boolean);
    if (parts.length < 2) return text;
    const matches = parts.map(part => part.match(/^(.+?)\/([A-Za-z%µ]+)$/));
    if (!matches.every(Boolean)) return text;
    const denominator = matches[0][2];
    if (!matches.every(match => match[2] === denominator)) return text;
    return `${matches.map(match => match[1]).join('/')}/${denominator}`;
}

function normalizeSlashPartsText(value) {
    const text = compactRepeatedDenominatorText(value);
    if (!text.includes('/')) return text;
    const parts = text.split('/').map(part => part.trim()).filter(Boolean);
    while (
        parts.length > 2 &&
        parts[parts.length - 1].toLowerCase() === parts[parts.length - 2].toLowerCase()
    ) {
        parts.pop();
    }
    return parts.join('/');
}

function splitUnitBasis(value) {
    const parts = normalizeSlashPartsText(value).split('/').map(part => part.trim()).filter(Boolean);
    return {
        activeUnit: parts[0] || '',
        perUnit: parts.length > 1 ? parts[parts.length - 1] : ''
    };
}

function parseStrengthToken(value) {
    const text = normalizeSlashPartsText(value);
    const match = text.match(/^(-?\d+(?:\.\d+)?)(.*)$/);
    if (!match) return { amount: NaN, activeUnit: '', perUnit: '' };
    const units = splitUnitBasis(match[2].trim());
    return {
        amount: parseAmount(match[1], NaN),
        activeUnit: units.activeUnit,
        perUnit: units.perUnit
    };
}

function normalizeSingleStrengthSpec(source = {}, fallbackUnit = 'mg') {
    const parsedStrength = parseStrengthToken(source.strength ?? source.strengthAmount ?? '');
    const units = splitUnitBasis(source.activeUnit || source.units || parsedStrength.activeUnit || fallbackUnit);
    const perFromUnit = units.perUnit || parsedStrength.perUnit;
    const strengthAmount = Number.isFinite(parseAmount(source.strengthAmount, NaN))
        ? parseAmount(source.strengthAmount, NaN)
        : (Number.isFinite(parsedStrength.amount) ? parsedStrength.amount : parseAmount(source.strength, NaN));
    const activeUnit = units.activeUnit || parsedStrength.activeUnit || fallbackUnit;
    const perAmount = parseAmount(source.perAmount, 1);
    const perUnit = source.perUnit || perFromUnit || '';
    const hasDenominator = perUnit && Number.isFinite(perAmount) && perAmount > 0;
    const normalizedStrength = hasDenominator && Number.isFinite(strengthAmount)
        ? strengthAmount / perAmount
        : strengthAmount;
    const normalizedUnits = normalizeSlashPartsText(hasDenominator ? `${activeUnit}/${perUnit}` : activeUnit);
    return {
        strengthAmount,
        activeUnit,
        perAmount: hasDenominator ? perAmount : null,
        perUnit: hasDenominator ? perUnit : '',
        strength: normalizedStrength,
        units: normalizedUnits,
        displayStrength: Number.isFinite(strengthAmount)
            ? (hasDenominator
                ? `${formatAmount(strengthAmount)}${activeUnit}/${perAmount === 1 ? '' : formatAmount(perAmount)}${perUnit}`
                : `${formatAmount(strengthAmount)}${activeUnit}`)
            : combineStrengthAndUnits(source.strength, normalizedUnits)
    };
}

function formatInventoryUnitsForColumn(med) {
    if (!med) return '';
    if (med.isCombination && Array.isArray(med.components) && med.components.length > 0) {
        return Array.from(new Set(med.components.map(component => getComponentUnit(component, med)).filter(Boolean))).join('/');
    }
    return splitUnitBasis(med.units || med.activeUnit || '').activeUnit || med.units || '';
}

function combineStrengthAndUnits(strength, units) {
    const strengthText = normalizeSlashPartsText(strength);
    const unitText = normalizeSlashPartsText(units);
    if (!strengthText) return unitText;
    if (!unitText) return strengthText;
    const normalizedStrength = strengthText.replace(/\s+/g, '');
    const normalizedUnit = unitText.replace(/\s+/g, '');
    return normalizedStrength.endsWith(normalizedUnit) ? strengthText : `${strengthText}${unitText}`;
}

function compoundRecipeStrengthText(recipe) {
    const calculatedComponents = Array.isArray(recipe?.calculatedComponents)
        ? recipe.calculatedComponents
            .map(component => ({
                ...component,
                strength: parseAmount(component.strength, parseAmount(component.strengthAmount, NaN)),
                strengthAmount: parseAmount(component.strengthAmount, parseAmount(component.strength, NaN)),
                perAmount: parseAmount(component.perAmount, 1),
                perUnit: component.perUnit || recipe.yieldUnit || ''
            }))
            .filter(component =>
                Number.isFinite(parseAmount(component.strength, NaN)) ||
                Number.isFinite(parseAmount(component.strengthAmount, NaN))
            )
        : [];
    if (calculatedComponents.length > 1) {
        return formatCombinationStrength({ isCombination: true, components: calculatedComponents }, false, true);
    }
    return combineStrengthAndUnits(recipe?.finalStrength, recipe?.finalUnits);
}

function componentPerUnitOptionsHtml(selected = '') {
    return componentPerUnitOptions
        .map(unit => `<option value="${unit}" ${unit === selected ? 'selected' : ''}>${unit || 'unit'}</option>`)
        .join('');
}

function comboEditorConfig(prefix = 'med') {
    const modal = prefix === 'modal';
    const receive = prefix === 'receive';
    return {
        rowSelector: receive ? '#receive-ingredient-list .receive-combo-row' : (modal ? '#modal-ingredient-list .modal-combo-row' : '#ingredient-list .combo-row'),
        rowListId: receive ? 'receive-ingredient-list' : (modal ? 'modal-ingredient-list' : 'ingredient-list'),
        sharedCheckId: receive ? 'receive-combo-use-shared-per' : (modal ? 'modal-combo-use-shared-per' : 'combo-use-shared-per'),
        sharedAmountId: receive ? 'receive-combo-shared-per-amount' : (modal ? 'modal-combo-shared-per-amount' : 'combo-shared-per-amount'),
        sharedUnitId: receive ? 'receive-combo-shared-per-unit' : (modal ? 'modal-combo-shared-per-unit' : 'combo-shared-per-unit'),
        previewId: receive ? 'receive-combination-preview' : (modal ? 'modal-combination-preview' : 'combination-preview'),
        formulationId: receive ? 'receive-new-formulation' : (modal ? 'modal-formulation' : 'med-formulation'),
        nameClass: receive ? '.receive-ing-name' : (modal ? '.modal-ing-name' : '.ing-name'),
        strengthClass: receive ? '.receive-ing-strength' : (modal ? '.modal-ing-strength' : '.ing-strength'),
        unitClass: receive ? '.receive-ing-unit' : (modal ? '.modal-ing-unit' : '.ing-unit'),
        perAmountClass: receive ? '.receive-ing-per-amount' : (modal ? '.modal-ing-per-amount' : '.ing-per-amount'),
        perUnitClass: receive ? '.receive-ing-per-unit' : (modal ? '.modal-ing-per-unit' : '.ing-per-unit')
    };
}

function getComboSharedBasis(prefix = 'med') {
    const config = comboEditorConfig(prefix);
    const useShared = document.getElementById(config.sharedCheckId)?.checked !== false;
    const formulation = document.getElementById(config.formulationId)?.value || 'Other';
    const amountInput = document.getElementById(config.sharedAmountId);
    const unitInput = document.getElementById(config.sharedUnitId);
    const defaultUnit = defaultPerUnitForFormulation(formulation);
    if (unitInput && !unitInput.value && defaultUnit) unitInput.value = defaultUnit;
    return {
        useShared,
        amount: parseAmount(amountInput?.value, NaN),
        unit: unitInput?.value || ''
    };
}

function collectCombinationComponents(prefix = 'med') {
    const config = comboEditorConfig(prefix);
    const shared = getComboSharedBasis(prefix);
    const rows = Array.from(document.querySelectorAll(config.rowSelector));
    let invalidDenominator = false;
    const components = rows.map(row => {
        const name = row.querySelector(config.nameClass)?.value.trim() || '';
        const strengthAmount = parseAmount(row.querySelector(config.strengthClass)?.value, NaN);
        const unit = row.querySelector(config.unitClass)?.value || 'mg';
        const rowPerAmount = parseAmount(row.querySelector(config.perAmountClass)?.value, NaN);
        const rowPerUnit = row.querySelector(config.perUnitClass)?.value || '';
        const perAmount = shared.useShared ? shared.amount : rowPerAmount;
        const perUnit = shared.useShared ? shared.unit : rowPerUnit;
        if (perUnit && (!Number.isFinite(perAmount) || perAmount <= 0)) invalidDenominator = true;
        const hasDenominator = perUnit && Number.isFinite(perAmount) && perAmount > 0;
        return {
            name,
            strength: hasDenominator ? strengthAmount / perAmount : strengthAmount,
            strengthAmount,
            unit,
            perAmount: hasDenominator ? perAmount : null,
            perUnit: hasDenominator ? perUnit : ''
        };
    }).filter(component => component.name && Number.isFinite(component.strengthAmount) && component.strengthAmount > 0);
    return { components, invalidDenominator, shared };
}

function setCombinationSharedBasis(prefix = 'med', components = []) {
    const config = comboEditorConfig(prefix);
    const shared = sharedComponentDenominator(components);
    const formulation = document.getElementById(config.formulationId)?.value || 'Other';
    const defaultUnit = defaultPerUnitForFormulation(formulation);
    const sharedCheck = document.getElementById(config.sharedCheckId);
    const sharedAmount = document.getElementById(config.sharedAmountId);
    const sharedUnit = document.getElementById(config.sharedUnitId);
    if (sharedCheck) sharedCheck.checked = !!shared || components.length === 0;
    if (sharedAmount) sharedAmount.value = shared ? formatAmount(shared.amount) : '1';
    if (sharedUnit) sharedUnit.value = shared?.unit || defaultUnit || '';
}

window.updateCombinationPreview = function(prefix = 'med') {
    const config = comboEditorConfig(prefix);
    const list = document.getElementById(config.rowListId);
    const preview = document.getElementById(config.previewId);
    const { components, invalidDenominator, shared } = collectCombinationComponents(prefix);
    if (list) list.classList.toggle('use-shared-basis', shared.useShared);
    if (!preview) return;
    if (invalidDenominator) {
        preview.className = 'combo-strength-preview error';
        preview.textContent = 'Enter a valid package basis greater than 0.';
        return;
    }
    if (!components.length) {
        preview.className = 'combo-strength-preview';
        preview.textContent = 'Add ingredients to preview the combined strength.';
        return;
    }
    const comboMed = { isCombination: true, components };
    preview.className = 'combo-strength-preview ok';
    const previewLabel = components.length > 1 ? `Strength preview (${components.length} ingredients)` : 'Strength preview';
    preview.textContent = `${previewLabel}: ${formatCombinationStrength(comboMed, components.length > 1)}`;
};

function formatMedStrength(med, includeNames = false, includeSolidDenominator = false) {
    if (!med) return '';
    if (med.isCombination && med.components && med.components.length > 0) {
        return formatCombinationStrength(med, includeNames, includeSolidDenominator);
    }
    const normalized = normalizeSingleStrengthSpec(med, splitUnitBasis(med.units || '').activeUnit || 'mg');
    if (Number.isFinite(parseAmount(med.strengthAmount, NaN)) && med.activeUnit) {
        if (normalized.perUnit && Number.isFinite(parseAmount(normalized.perAmount, NaN))) {
            const isLiquidDenominator = ['ml', 'l'].includes(String(normalized.perUnit).toLowerCase());
            const denominator = includeSolidDenominator || isLiquidDenominator
                ? `/${parseAmount(normalized.perAmount) === 1 ? '' : formatAmount(parseAmount(normalized.perAmount))}${normalized.perUnit}`
                : '';
            return normalizeSlashPartsText(`${formatAmount(parseAmount(normalized.strengthAmount))}${normalized.activeUnit}${denominator}`);
        }
        return normalizeSlashPartsText(`${formatAmount(parseAmount(normalized.strengthAmount))}${normalized.activeUnit}`);
    }
    if (Number.isFinite(parseAmount(med.strength, NaN)) && med.units && !String(med.units).includes('/')) {
        return normalizeSlashPartsText(`${formatAmount(parseAmount(med.strength))}${med.units}`);
    }
    if (med.displayStrength) return normalizeSlashPartsText(med.displayStrength);
    return combineStrengthAndUnits(med.strength, med.units);
}

function formatLabelMedStrength(med, includeNames = false) {
    return formatMedStrength(med, includeNames, false);
}

function formatPrescribedDose(med, doseQty) {
    const qty = parseAmount(doseQty);
    if (!med) return '';

    if (isTopicalMedication(med)) {
        return `${formatAmount(qty)} ${med.administrationUnit || 'application'}`;
    }

    if (med.isCombination && med.components && med.components.length > 0) {
        return med.components.map(component => {
            const total = parseAmount(component.strength) * qty;
            return `${formatAmount(total)}${getComponentUnit(component, med)}`;
        }).join('/');
    }

    const medUnits = String(med.units || '');
    const doseUnit = medUnits.includes('/') ? medUnits.split('/')[0] : medUnits;
    return `${formatAmount(parseAmount(med.strength) * qty)}${doseUnit}`;
}

function formatQtyForSchedule(schedule, med) {
    const numericQty = parseAmount(schedule.doseQty);
    const qty = formatAmount(numericQty);
    const rawUnit = med.administrationUnit || med.formulation || 'unit';
    const pluralUnits = {
        tablet: 'tablets',
        capsule: 'capsules',
        packet: 'packets',
        spray: 'sprays',
        drop: 'drops',
        inhalation: 'inhalations',
        patch: 'patches',
        suppository: 'suppositories',
        application: 'applications',
        bottle: 'bottles',
        container: 'containers',
        tube: 'tubes',
        jar: 'jars',
        unit: 'units'
    };
    const unitKey = String(rawUnit).toLowerCase();
    const unit = numericQty === 1 ? rawUnit : (pluralUnits[unitKey] || rawUnit);
    return `${qty} ${unit}`;
}

function formatStrengthWithPerDoseQty(schedule, med) {
    const strength = formatPrescribedDose(med, schedule.doseQty);
    const perDoseQty = formatQtyForSchedule(schedule, med);
    return `${strength}${perDoseQty ? ` (${perDoseQty})` : ''}`;
}

function formatCurrency(value) {
    const amount = typeof value === 'number' ? value : parseMoney(value, NaN);
    if (!Number.isFinite(amount)) return '$0.00';
    return amount.toLocaleString('en-US', { style: 'currency', currency: 'USD' });
}

function formatMultiMedLabelName(schedule, med) {
    if (!med || !schedule) return 'Unknown medication';
    const actualDose = formatPrescribedDose(med, schedule.doseQty);
    return `${med.name}${actualDose ? ` ${actualDose}` : ''}`;
}

function prnLimitText(schedule) {
    const maxDoses = parseInt(schedule?.prnMaxDoses, 10);
    if (schedule?.freq !== 'PRN' || !Number.isInteger(maxDoses) || maxDoses < 1) return '';
    const windowHours = parseInt(schedule.prnWindowHours, 10) || 24;
    return ` | Max ${maxDoses}/${windowHours}h`;
}

function imageSrc(pathOrDataUrl) {
    if (!pathOrDataUrl) return '';
    if (/^(data:|https?:|blob:)/i.test(pathOrDataUrl)) return pathOrDataUrl;
    return `file://${pathOrDataUrl}`;
}

function getNextScheduledDose(schedule, fromDate = new Date()) {
    const times = getScheduleTimes(schedule).sort();
    const currentDateKey = localDateKey(fromDate);
    const currentTime = `${fromDate.getHours().toString().padStart(2, '0')}:${fromDate.getMinutes().toString().padStart(2, '0')}`;

    if (schedule.freq === 'PRN' && !hasScheduledPrnReminders(schedule)) {
        return { date: currentDateKey, time: 'PRN' };
    }

    for (let i = 0; i < 366; i++) {
        const candidate = new Date(fromDate);
        candidate.setHours(0, 0, 0, 0);
        candidate.setDate(candidate.getDate() + i);
        const dateKey = localDateKey(candidate);
        if (!isScheduleDueOnDate(schedule, dateKey)) continue;

        const nextTime = i === 0 ? times.find(time => time >= currentTime) : times[0];
        if (nextTime) return { date: dateKey, time: nextTime };
    }

    return { date: schedule.startDate || currentDateKey, time: times[0] || 'PRN' };
}

function formatDoseDateTime(schedule) {
    const nextDose = getNextScheduledDose(schedule);
    const date = parseLocal(nextDose.date);
    const displayDate = date ? date.toLocaleDateString() : nextDose.date;
    const times = getScheduleTimes(schedule);
    return `${displayDate} | ${times.length > 0 ? times.join(', ') : nextDose.time}`;
}

function scheduleInstanceKey(scheduleId, date, time) {
    return `${scheduleId}|${date}|${time || 'PRN'}`;
}

function isScheduleInstanceDocumented(scheduleId, date, time) {
    const key = scheduleInstanceKey(scheduleId, date, time);
    const schedule = db.schedules.find(item => item.id === scheduleId);
    if (schedule && findHistoryForScheduleInstance(schedule, { date, time, key })) return true;
    return db.history.some(entry => entry.scheduleInstanceKey === key);
}

function getScheduleInstancesForDate(schedule, dateStr) {
    if (!schedule || !isScheduleDueOnDate(schedule, dateStr)) return [];
    if (scheduleTimingFrequency(schedule) === 'QXH') {
        const dayStart = parseLocal(dateStr);
        const dayEnd = parseLocal(dateStr);
        if (!dayStart || !dayEnd) return [];
        dayStart.setHours(0, 0, 0, 0);
        dayEnd.setHours(23, 59, 59, 999);
        const scheduleStart = dateTimeFromParts(schedule.startDate, schedule.startTime || schedule.times?.[0]);
        const from = scheduleStart && scheduleStart > dayStart ? scheduleStart : dayStart;
        return rollingIntervalInstancesBetween(schedule, from, dayEnd)
            .map(dateTimeParts)
            .filter(instance => instance.date === dateStr && isScheduleDueOnDate(schedule, instance.date))
            .sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time))
            .map(instance => ({
                date: instance.date,
                time: instance.time,
                key: scheduleInstanceKey(schedule.id, instance.date, instance.time)
            }))
            .filter(instance => !(schedule.excludedInstances || []).includes(instance.key));
    }
    const times = getScheduleTimes(schedule);
    if (times.length === 0) {
        return [{ date: dateStr, time: 'PRN', key: scheduleInstanceKey(schedule.id, dateStr, 'PRN') }];
    }
    return times
        .slice()
        .sort((a, b) => timeToMinutes(a) - timeToMinutes(b))
        .map(time => ({ date: dateStr, time, key: scheduleInstanceKey(schedule.id, dateStr, time) }))
        .filter(instance => !(schedule.excludedInstances || []).includes(instance.key));
}

function getAvailableScheduleInstancesForDate(schedule, dateStr) {
    return getScheduleInstancesForDate(schedule, dateStr)
        .filter(instance => !isScheduleInstanceDocumented(schedule.id, instance.date, instance.time));
}

function getScheduleInstancesInRange(schedule, startDate, endDate) {
    const start = parseLocal(startDate);
    const end = parseLocal(endDate);
    if (!schedule || !start || !end || end < start) return [];

    const instances = [];
    const cursor = new Date(start);
    while (cursor <= end) {
        instances.push(...getScheduleInstancesForDate(schedule, localDateKey(cursor)));
        cursor.setDate(cursor.getDate() + 1);
    }
    return instances;
}

function collectMemberScheduleDoseRows(memberId, startDate, endDate) {
    const start = parseLocal(startDate);
    const end = parseLocal(endDate);
    if (!memberId || !start || !end || end < start) return [];

    const memberSchedules = db.schedules.filter(schedule => schedule.memberId === memberId && !isScheduleArchived(schedule));
    const rows = [];
    const cursor = new Date(start);
    while (cursor <= end) {
        const dateKey = localDateKey(cursor);
        memberSchedules.forEach(schedule => {
            const med = db.inventory.find(item => item.id === schedule.medId);
            if (!med) return;
            getScheduleInstancesForDate(schedule, dateKey).forEach(instance => {
                rows.push({ schedule, med, instance });
            });
        });
        cursor.setDate(cursor.getDate() + 1);
    }

    return rows.sort((a, b) => {
        if (a.instance.date !== b.instance.date) return a.instance.date.localeCompare(b.instance.date);
        const byTime = timeToMinutes(a.instance.time) - timeToMinutes(b.instance.time);
        if (byTime !== 0) return byTime;
        return (a.med.name || '').localeCompare(b.med.name || '', undefined, { sensitivity: 'base' });
    });
}

function getInstanceSelectionRange(schedule) {
    const today = localDateKey();
    const lookback = new Date();
    lookback.setDate(lookback.getDate() - 30);
    const lookbackKey = localDateKey(lookback);
    const start = schedule.startDate && schedule.startDate > lookbackKey ? schedule.startDate : lookbackKey;
    if (schedule.endDate && schedule.endDate !== 'Ongoing') return { start, end: schedule.endDate };
    const end = new Date();
    end.setDate(end.getDate() + 30);
    return { start, end: localDateKey(end) };
}

function getNextAvailableScheduleInstance(schedule, fromDate = new Date()) {
    const currentDateKey = localDateKey(fromDate);
    const currentTime = `${fromDate.getHours().toString().padStart(2, '0')}:${fromDate.getMinutes().toString().padStart(2, '0')}`;

    for (let i = 0; i < 366; i++) {
        const candidate = new Date(fromDate);
        candidate.setHours(0, 0, 0, 0);
        candidate.setDate(candidate.getDate() + i);
        const dateKey = localDateKey(candidate);
        const instances = getAvailableScheduleInstancesForDate(schedule, dateKey);
        const next = i === 0
            ? instances.find(instance => instance.time === 'PRN' || instance.time >= currentTime)
            : instances[0];
        if (next) return next;
    }
    return null;
}

function doseStatusLabel(status) {
    return {
        given: 'Given as scheduled',
        late: 'Given late',
        early: 'Given early',
        skipped: 'Skipped',
        missed: 'Missed / forgotten',
        refused: 'Refused',
        held: 'Held',
        wasted: 'Wasted'
    }[status] || 'Given as scheduled';
}

function getLabelClass(parts, lineCount = 0) {
    const length = parts.filter(Boolean).join(' ').length;
    if (length > 170 || lineCount > 6) return 'label-page label-dense';
    if (length > 120 || lineCount > 4) return 'label-page label-compact';
    return 'label-page';
}

function printPreparedArea() {
    const printArea = document.getElementById('print-area');
    document.body.appendChild(printArea);
    printArea.style.display = 'block';
    setTimeout(() => window.print(), 50);
}

let pendingLabelHtml = '';
let pendingPrepackDefinition = null;

function fitLabelPages(container) {
    const densityClasses = ['label-compact', 'label-dense', 'label-ultra-dense', 'label-micro'];
    container.querySelectorAll('.label-page').forEach(page => {
        const textElements = page.querySelectorAll('.label-date, .label-title, .label-small, .label-med-row, .compound-label-strength, .med-kit-label-row');
        textElements.forEach(element => {
            element.style.removeProperty('font-size');
            element.style.removeProperty('line-height');
        });
        page.classList.remove(...densityClasses);
        for (const densityClass of densityClasses) {
            if (page.scrollHeight <= page.clientHeight + 1 && page.scrollWidth <= page.clientWidth + 1) break;
            page.classList.add(densityClass);
        }
        for (let attempt = 0; attempt < 3 && (page.scrollHeight > page.clientHeight + 1 || page.scrollWidth > page.clientWidth + 1); attempt++) {
            const heightRatio = page.clientHeight / page.scrollHeight;
            const widthRatio = page.clientWidth / page.scrollWidth;
            const fitRatio = Math.max(Math.min(heightRatio, widthRatio, 1) * 0.96, 0.7);
            textElements.forEach(element => {
                const styles = getComputedStyle(element);
                element.style.fontSize = `${parseFloat(styles.fontSize) * fitRatio}px`;
                element.style.lineHeight = '0.82';
            });
        }
    });
    pendingLabelHtml = container.innerHTML;
}

function previewLabelHtml(labelHtml, prepackDefinition = null) {
    pendingLabelHtml = labelHtml;
    pendingPrepackDefinition = prepackDefinition;
    const modal = document.getElementById('label-preview-modal');
    const content = document.getElementById('label-preview-content');
    if (!modal || !content) {
        const printArea = document.getElementById('print-area');
        printArea.innerHTML = labelHtml;
        printPreparedArea();
        return;
    }
    content.innerHTML = labelHtml;
    modal.style.display = 'flex';
    const scheduleButton = document.getElementById('schedule-prepack-button');
    if (scheduleButton) scheduleButton.style.display = prepackDefinition && !prepackDefinition.existingQueueId ? 'inline-block' : 'none';
    fitLabelPages(content);
    requestAnimationFrame(() => {
        fitLabelPages(content);
        if (document.fonts?.ready) {
            document.fonts.ready.then(() => fitLabelPages(content));
        }
    });
}

window.closeLabelPreview = function() {
    pendingLabelHtml = '';
    pendingPrepackDefinition = null;
    const modal = document.getElementById('label-preview-modal');
    if (modal) modal.style.display = 'none';
    const scheduleButton = document.getElementById('schedule-prepack-button');
    if (scheduleButton) scheduleButton.style.display = 'none';
};

window.schedulePendingPrepack = async function() {
    if (!pendingPrepackDefinition || pendingPrepackDefinition.existingQueueId) return;
    const definition = pendingPrepackDefinition;
    const firstDue = firstPrepackDueDateTime(definition);
    const defaults = defaultActualDateTime();
    window.closeLabelPreview();
    const result = await showActionModal('Schedule Prepack', `
        <div class="field-row">
            <label>Prepack date:</label><input name="prepackDate" type="date" value="${defaults.date}">
            <label>Time:</label><input name="prepackTime" type="time" value="${defaults.time}">
        </div>
        <div id="schedule-prepack-warning" class="inline-error" style="display:none; margin-top:8px;"></div>
        ${firstDue ? `<div class="form-help" style="margin-top:8px;">Schedule this before the first dose due: <strong>${escapeHtml(formatDateTimeForDisplay(firstDue.date, firstDue.time))}</strong>.</div>` : ''}
    `, 'Add to Queue', async body => {
        const values = collectNamedInputs(body);
        const warning = body.querySelector('#schedule-prepack-warning');
        const setWarning = text => {
            if (!warning) return;
            warning.textContent = text;
            warning.style.display = text ? '' : 'none';
        };
        if (!values.prepackDate || !values.prepackTime) {
            setWarning('Choose the date and time when this prepack should be prepared.');
            return false;
        }
        if (firstDue) {
            const scheduledAt = localDateTimeValue(values.prepackDate, values.prepackTime);
            const firstDueAt = localDateTimeValue(firstDue.date, firstDue.time);
            if (scheduledAt && firstDueAt && scheduledAt >= firstDueAt) {
                setWarning(`Prepack must be scheduled before the first medication is due (${formatDateTimeForDisplay(firstDue.date, firstDue.time)}).`);
                return false;
            }
        }
        setWarning('');
        return values;
    });
    if (!result) return;
    await createPrepackQueue(definition, {
        labelsPrinted: false,
        scheduledFor: `${result.prepackDate}T${result.prepackTime}`
    });
    switchTab('prepackage');
};

function localDateTimeValue(dateKey, timeValue = '00:00') {
    if (!dateKey) return null;
    const date = parseLocal(dateKey);
    if (!date || isNaN(date.getTime())) return null;
    const minutes = timeToMinutes(timeValue || '00:00');
    const safeMinutes = Number.isFinite(minutes) ? minutes : 0;
    date.setHours(Math.floor(safeMinutes / 60), safeMinutes % 60, 0, 0);
    return date;
}

function formatDateTimeForDisplay(dateKey, timeValue = '') {
    return `${dateKey || ''}${timeValue ? ` ${String(timeValue).slice(0, 5)}` : ''}`.trim();
}

function firstPrepackDueDateTime(definition) {
    const candidates = [];
    (definition?.days || []).forEach(day => {
        const dayStart = firstDateInPrepackDay(day) || day.date;
        (day.items || []).forEach(item => {
            let date = dayStart;
            let time = String(item.time || '').slice(0, 5);
            if (isRangePrepackItem(item)) {
                const bounds = prepackItemRangeBounds(day, item);
                date = bounds.start || dayStart;
                const schedule = prepackItemSchedule(item);
                time = getScheduleTimes(schedule)[0] || '00:00';
            }
            if (!date) return;
            if (!/^\d{2}:\d{2}$/.test(time)) time = '00:00';
            const value = localDateTimeValue(date, time);
            if (value) candidates.push({ date, time, value });
        });
    });
    return candidates.sort((a, b) => a.value - b.value)[0] || null;
}

window.printPreviewedLabel = async function() {
    if (!pendingLabelHtml) return;
    const printArea = document.getElementById('print-area');
    printArea.innerHTML = pendingLabelHtml;
    const prepackDefinition = pendingPrepackDefinition;
    window.closeLabelPreview();
    if (prepackDefinition?.existingQueueId && !prepackDefinition.reprintOnly) await commitPrepackPrint(prepackDefinition);
    printPreparedArea();
};

function ensureActionModal() {
    let modal = document.getElementById('action-modal');
    if (modal) return modal;

    modal = document.createElement('div');
    modal.id = 'action-modal';
    modal.className = 'modal-overlay';
    modal.style.display = 'none';
    modal.innerHTML = `
        <div class="window action-modal-window">
            <div class="title-bar">
                <div class="title-bar-text" id="action-modal-title">Action</div>
                <div class="title-bar-controls">
                    <button aria-label="Minimize" id="action-modal-min"></button>
                    <button aria-label="Close" id="action-modal-x"></button>
                </div>
            </div>
            <div class="window-body">
                <div id="action-modal-body"></div>
                <div class="field-row" style="justify-content:flex-end; margin-top:10px;">
                    <button id="action-modal-ok">OK</button>
                    <button id="action-modal-cancel">Cancel</button>
                </div>
            </div>
        </div>`;
    document.body.appendChild(modal);
    return modal;
}

const workspaceTasks = new Map();
let activeMemberTaskId = '';

function updateWorkspaceTaskbar() {
    const taskbar = document.getElementById('workspace-taskbar');
    if (!taskbar) return;
    const tasks = Array.from(workspaceTasks.values());
    taskbar.classList.toggle('has-tasks', tasks.length > 0);
    taskbar.innerHTML = tasks.map(task => `
        <div class="taskbar-task ${task.active ? 'is-active' : ''} ${task.type ? `taskbar-${escapeHtml(task.type)}` : ''} ${task.sex ? `taskbar-sex-${escapeHtml(task.sex)}` : ''}" style="${task.color ? `--patient-color:${escapeHtml(task.color)};` : ''}" title="${escapeHtml(task.label)}">
            <button type="button" class="taskbar-button" onclick="restoreWorkspaceTask('${escapeHtml(task.id)}')">
                ${task.iconHtml || '<span class="win98-icon icon-view"></span>'}
                <span class="taskbar-label">${escapeHtml(task.label)}</span>
            </button>
            <button type="button" class="taskbar-close" onclick="event.stopPropagation(); closeWorkspaceTask('${escapeHtml(task.id)}')" title="Close">X</button>
        </div>
    `).join('');
}

function registerWorkspaceTask(id, label, restoreFn, options = {}) {
    workspaceTasks.forEach(task => { task.active = false; });
    workspaceTasks.set(id, {
        id,
        label,
        restoreFn,
        active: true,
        type: options.type || 'window',
        iconHtml: options.iconHtml || '',
        color: options.color || '',
        sex: options.sex || ''
    });
    updateWorkspaceTaskbar();
}

window.restoreWorkspaceTask = function(id) {
    const task = workspaceTasks.get(id);
    if (!task) return;
    if (id !== 'action-modal') {
        const actionModal = document.getElementById('action-modal');
        if (actionModal) actionModal.style.display = 'none';
    }
    if (!id.startsWith('member-modal-')) {
        const memberModal = document.getElementById('member-modal');
        if (memberModal) memberModal.style.display = 'none';
    }
    workspaceTasks.forEach(item => { item.active = item.id === id; });
    updateWorkspaceTaskbar();
    task.restoreFn?.();
};

function setWorkspaceTaskActive(id, active) {
    const task = workspaceTasks.get(id);
    if (!task) return;
    task.active = active;
    updateWorkspaceTaskbar();
}

function removeWorkspaceTask(id) {
    workspaceTasks.delete(id);
    if (activeMemberTaskId === id) activeMemberTaskId = '';
    updateWorkspaceTaskbar();
}

window.closeWorkspaceTask = async function(id) {
    if (id === 'action-modal') {
        document.getElementById('action-modal-x')?.click();
        return;
    }
    if (id.startsWith('member-modal-')) {
        const modal = document.getElementById('member-modal');
        if (activeMemberTaskId === id && modal) {
            await saveMemberFromProfile({ closeAfter: true });
            return;
        }
        removeWorkspaceTask(id);
    }
};

function iconClassForButtonText(text) {
    const value = String(text || '').toLowerCase();
    if (!value) return '';
    if (value.includes('label') || value.includes('print')) return 'icon-label';
    if (value.includes('schedule') || value.includes('calendar') || value.includes('today') || value.includes('day')) return 'icon-calendar';
    if (value.includes('prepack')) return 'icon-box';
    if (value.includes('recipe') || value.includes('compound') || value.includes('prep')) return 'icon-recipe';
    if (value.includes('regimen')) return 'icon-regimen';
    if (value.includes('monitor') || value.includes('vital') || value.includes('reading')) return 'icon-monitor';
    if (value.includes('inventory') || value.includes('stock') || value.includes('restock')) return 'icon-inventory';
    if (value.includes('formulary')) return 'icon-formulary';
    if (value.includes('order') || value.includes('receive')) return value.includes('receive') ? 'icon-receive' : 'icon-order';
    if (value.includes('profile') || value.includes('person') || value.includes('member') || value.includes('provider')) return 'icon-family';
    if (value.includes('view') || value.includes('open') || value.includes('pdf') || value.includes('report')) return 'icon-view';
    if (value.includes('clear') || value.includes('delete') || value.includes('cancel')) return 'icon-clear';
    if (value.includes('add') || value.includes('save') || value.includes('generate')) return 'icon-view';
    return '';
}

function enhanceButtonIcons(root = document) {
    root.querySelectorAll('button').forEach(button => {
        if (
            button.dataset.iconEnhanced === 'true' ||
            button.querySelector('.win98-icon') ||
            button.closest('.title-bar-controls') ||
            button.closest('.rich-text-toolbar') ||
            button.classList.contains('taskbar-button') ||
            button.classList.contains('taskbar-close') ||
            button.classList.contains('inventory-builder-remove') ||
            button.classList.contains('recipe-row-remove') ||
            button.classList.contains('combo-row-remove')
        ) return;
        const iconClass = iconClassForButtonText(button.textContent);
        if (!iconClass) return;
        const icon = document.createElement('span');
        icon.className = `win98-icon ${iconClass}`;
        button.prepend(icon);
        button.dataset.iconEnhanced = 'true';
    });
}

function collectNamedInputs(container) {
    const result = {};
    container.querySelectorAll('input[name], select[name], textarea[name]').forEach(input => {
        if (input.type === 'checkbox') {
            if (!result[input.name]) result[input.name] = [];
            if (input.checked) result[input.name].push(input.value);
        } else if (input.type === 'radio') {
            if (input.checked) result[input.name] = input.value;
        } else {
            if (Object.prototype.hasOwnProperty.call(result, input.name)) {
                result[input.name] = Array.isArray(result[input.name])
                    ? [...result[input.name], input.value]
                    : [result[input.name], input.value];
            } else {
                result[input.name] = input.value;
            }
        }
    });
    return result;
}

function showActionModal(title, bodyHtml, confirmText = 'OK', collectFn = null) {
    const modal = ensureActionModal();
    const windowEl = modal.querySelector('.action-modal-window');
    const body = modal.querySelector('#action-modal-body');
    const ok = modal.querySelector('#action-modal-ok');
    const cancel = modal.querySelector('#action-modal-cancel');
    const close = modal.querySelector('#action-modal-x');
    const minimize = modal.querySelector('#action-modal-min');
    const isTaskbarWindow = bodyHtml.includes('data-action-modal-size="wide"') || bodyHtml.includes('bulk-container-preview-shell');
    const taskId = 'action-modal';

    modal.querySelector('#action-modal-title').innerText = title;
    body.innerHTML = bodyHtml;
    windowEl?.classList.toggle('action-modal-window-wide', isTaskbarWindow);
    ok.innerText = confirmText;
    enhanceButtonIcons(body);
    renderGuidedHelpTips(body);
    if (minimize) minimize.style.display = isTaskbarWindow ? '' : 'none';
    modal.style.display = 'flex';
    if (isTaskbarWindow) {
        registerWorkspaceTask(taskId, title, () => {
            modal.style.display = 'flex';
            setWorkspaceTaskActive(taskId, true);
        }, {
            type: 'function',
            iconHtml: title.toLowerCase().includes('order')
                ? '<span class="win98-icon icon-order"></span>'
                : '<span class="win98-icon icon-formulary"></span>'
        });
    } else {
        removeWorkspaceTask(taskId);
    }

    return new Promise(resolve => {
        const cleanup = value => {
            ok.onclick = null;
            cancel.onclick = null;
            close.onclick = null;
            if (minimize) minimize.onclick = null;
            windowEl?.classList.remove('action-modal-window-wide');
            removeWorkspaceTask(taskId);
            modal.style.display = 'none';
            resolve(value);
        };
        ok.onclick = async () => {
            const value = collectFn ? await collectFn(body) : collectNamedInputs(body);
            if (value === false) return;
            cleanup(value);
        };
        cancel.onclick = () => cleanup(null);
        close.onclick = () => cleanup(null);
        if (minimize) {
            minimize.onclick = () => {
                modal.style.display = 'none';
                setWorkspaceTaskActive(taskId, false);
            };
        }
    });
}

function showChildActionModal(title, bodyHtml, confirmText = 'OK', collectFn = null) {
    const modal = document.createElement('div');
    modal.className = 'modal-overlay child-action-modal';
    modal.style.display = 'flex';
    modal.innerHTML = `
        <div class="window action-modal-window">
            <div class="title-bar">
                <div class="title-bar-text">${escapeHtml(title)}</div>
                <div class="title-bar-controls">
                    <button aria-label="Close" data-child-modal-close></button>
                </div>
            </div>
            <div class="window-body">
                <div class="child-action-modal-body">${bodyHtml}</div>
                <div class="field-row" style="justify-content:flex-end; margin-top:10px;">
                    <button data-child-modal-ok>${escapeHtml(confirmText)}</button>
                    <button data-child-modal-cancel>Cancel</button>
                </div>
            </div>
        </div>`;
    document.body.appendChild(modal);
    enhanceButtonIcons(modal);
    const body = modal.querySelector('.child-action-modal-body');
    const ok = modal.querySelector('[data-child-modal-ok]');
    const cancel = modal.querySelector('[data-child-modal-cancel]');
    const close = modal.querySelector('[data-child-modal-close]');
    return new Promise(resolve => {
        const cleanup = value => {
            ok.onclick = null;
            cancel.onclick = null;
            close.onclick = null;
            modal.remove();
            resolve(value);
        };
        ok.onclick = () => cleanup(collectFn ? collectFn(body) : collectNamedInputs(body));
        cancel.onclick = () => cleanup(null);
        close.onclick = () => cleanup(null);
    });
}

async function appAlert(message, title = 'PharmAtlas') {
    await showActionModal(title, `<div style="font-size:11px; padding:4px 0;">${escapeHtml(message)}</div>`, 'OK');
}

async function appConfirm(message, title = 'Confirm') {
    const result = await showActionModal(title, `<div style="font-size:11px; padding:4px 0;">${escapeHtml(message)}</div>`, 'OK');
    return result !== null;
}

// Keep legacy validation calls inside the application so native Electron dialogs
// never block focus after a message is dismissed.
window.alert = message => { void appAlert(String(message)); };

function dosageFormDefinition(formulation = 'Other') {
    return dosageFormDefinitions[formulation] || dosageFormDefinitions.Other;
}

function isTopicalFormulation(formulation = '') {
    return ['Cream', 'Ointment', 'Gel', 'Lotion', 'Foam', 'Shampoo', 'Topical Packet', 'Topical Solution', 'Tube', 'Jar'].includes(formulation);
}

function dosageFormUsesContainerTracking(formulation = '') {
    return dosageFormDefinition(formulation).containerTracking === true;
}

function defaultInventoryBehaviorForFormulation(formulation = 'Other') {
    return dosageFormUsesContainerTracking(formulation) ? 'container-finish' : 'per-dose';
}

function defaultInventoryUnitForFormulation(formulation = 'Other', behavior = '') {
    const def = dosageFormDefinition(formulation);
    if ((behavior || defaultInventoryBehaviorForFormulation(formulation)) === 'container-finish') {
        return def.containerUnit || def.stockUnit || 'container';
    }
    return def.stockUnit || formulationDoseUnits[formulation] || 'unit';
}

function defaultAdministrationUnitForFormulation(formulation = 'Other') {
    const def = dosageFormDefinition(formulation);
    return def.adminUnit || formulationDoseUnits[formulation] || 'unit';
}

function defaultPerUnitForFormulation(formulation = 'Other') {
    const def = dosageFormDefinition(formulation);
    return def.perUnit || '';
}

function isConcentrationFormulation(formulation = 'Other') {
    return dosageFormDefinition(formulation).strengthStyle === 'concentration';
}

function defaultStrengthUnitForFormulation(formulation = 'Other') {
    const style = dosageFormDefinition(formulation).strengthStyle;
    if (style === 'topical') return '%';
    if (style === 'bulk') return 'mg';
    return 'mg';
}

function dosageFormMeasurementProfile(formulation = 'Other', behavior = '') {
    const def = dosageFormDefinition(formulation);
    const inventoryBehavior = dosageFormUsesContainerTracking(formulation)
        ? 'container-finish'
        : (behavior || defaultInventoryBehaviorForFormulation(formulation));
    const perUnit = def.perUnit || '';
    const strengthUnit = defaultStrengthUnitForFormulation(formulation);
    const stockUnit = defaultInventoryUnitForFormulation(formulation, inventoryBehavior);
    const adminUnit = defaultAdministrationUnitForFormulation(formulation);
    const guidanceByStyle = {
        concentration: `Enter concentration as amount per volume, for example 5 mg per 1 mL. Stock is counted in ${stockUnit}.`,
        topical: `Enter topical strength as %, mg/g, or amount per ${perUnit || 'container'}. Stock is counted by ${stockUnit}; administrations are documented as ${adminUnit}.`,
        bulk: `Enter powder potency or amount per ${perUnit || 'g'}. Stock is counted by weight/quantity, usually ${stockUnit}.`,
        'per-unit': `Enter the amount in one ${perUnit || adminUnit || stockUnit}. Stock and doses are counted by ${stockUnit}.`
    };
    return {
        formulation,
        strengthStyle: def.strengthStyle || 'per-unit',
        strengthUnit,
        perAmount: 1,
        perUnit,
        stockUnit,
        adminUnit,
        inventoryBehavior,
        containerTracking: inventoryBehavior === 'container-finish',
        guidance: guidanceByStyle[def.strengthStyle] || guidanceByStyle['per-unit']
    };
}

function isTopicalMedication(med) {
    return isTopicalFormulation(med?.formulation || '');
}

function usesContainerTracking(med) {
    return med?.inventoryBehavior === 'container-finish' || dosageFormUsesContainerTracking(med?.formulation || '');
}

function isReturnPrepackExcludedMedication(med, schedule = null, item = null) {
    if (!med) return true;
    return requiresExplicitUnopenedForPrepackReturn(med) && !scheduleAllowsWholeContainerReturn(schedule, item);
}

function requiresExplicitUnopenedForPrepackReturn(med) {
    if (!med) return true;
    const formulation = String(med.formulation || '').toLowerCase();
    const adminUnit = String(med.administrationUnit || '').toLowerCase();
    const inventoryUnit = String(inventoryUnitFor(med) || '').toLowerCase();
    return usesContainerTracking(med) ||
        formulation.includes('nasal') ||
        formulation.includes('optic') ||
        formulation.includes('ophthalmic') ||
        formulation.includes('otic') ||
        formulation.includes('spray') ||
        formulation.includes('drop') ||
        adminUnit.includes('spray') ||
        adminUnit.includes('drop') ||
        ['tube', 'jar', 'bottle', 'container'].some(unit => inventoryUnit.includes(unit));
}

function scheduleAllowsWholeContainerReturn(schedule, item = null) {
    if (item?.containerUnopened === true) return true;
    return schedule?.containerOpened === false;
}

function returnPrepackRowWasteOnly(row) {
    const med = row?.med || db.inventory.find(candidate => candidate.id === row?.item?.medId);
    if (!med) return true;
    return requiresExplicitUnopenedForPrepackReturn(med) && !scheduleAllowsWholeContainerReturn(row?.schedule, row?.item);
}

function returnPrepackRowHandlingText(row) {
    if (!returnPrepackRowWasteOnly(row)) return '';
    const med = row?.med || db.inventory.find(candidate => candidate.id === row?.item?.medId);
    const unit = inventoryUnitFor(med);
    if (requiresExplicitUnopenedForPrepackReturn(med)) {
        return `Waste only unless marked unopened. ${unit ? `${unit.charAt(0).toUpperCase()}${unit.slice(1)}` : 'Container'} products such as creams, nasal sprays, drops, inhalers, tubes, bottles, and jars must be confirmed unopened before returning to stock.`;
    }
    return 'Waste only.';
}

function containerOpenStatusButtonHtml(schedule, med) {
    if (!requiresExplicitUnopenedForPrepackReturn(med)) return '';
    const state = schedule?.containerOpened;
    const className = state === true
        ? 'container-open-status opened'
        : state === false ? 'container-open-status unopened' : 'container-open-status unknown';
    const text = state === true ? 'Opened' : state === false ? 'Unopened' : 'Container Status';
    const title = state === true
        ? 'Marked opened: prepacked containers will not be returnable.'
        : state === false
            ? 'Marked unopened: unused prepacked containers can be returned.'
            : 'Choose whether this container has been opened for return tracking.';
    return `<button class="${className}" title="${escapeHtml(title)}" onclick="event.stopPropagation(); setScheduleContainerOpenState('${escapeHtml(schedule.id)}')">${escapeHtml(text)}</button>`;
}

function finishedContainerButtonText(med) {
    const unit = String(inventoryUnitFor(med) || '').toLowerCase();
    return unit.includes('bottle') ? 'Finished Bottle' : 'Finished Container';
}

function inventoryUnitFor(med) {
    return med?.inventoryUnit || defaultInventoryUnitForFormulation(med?.formulation || 'Other', med?.inventoryBehavior);
}

function ensureMedKits() {
    db.medKits = Array.isArray(db.medKits) ? db.medKits : [];
}

function medKitName(kit) {
    return String(kit?.name || '').trim() || 'Unnamed Kit';
}

function medKitItemId() {
    return `kit_item_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function kitItemMed(item) {
    return db.inventory.find(med => med.id === item.medId) || null;
}

function createMedKitScanCode() {
    let code = '';
    do {
        code = `PA-KIT-${Math.random().toString(36).slice(2, 8).toUpperCase()}`;
    } while ((db.medKits || []).some(kit => normalizeMedicationCode(kit.scanCode) === code) || barcodeConflictItems(code).length);
    return code;
}

function ensureMedKitScanCode(kit) {
    if (!kit) return '';
    const existing = normalizeMedicationCode(kit.scanCode);
    if (existing) {
        kit.scanCode = existing;
        return existing;
    }
    kit.scanCode = createMedKitScanCode();
    kit.updatedAt = new Date().toISOString();
    return kit.scanCode;
}

function medKitScanCode(kit) {
    if (!kit?.id) return '';
    return ensureMedKitScanCode(kit);
}

function medKitFromScannedPayload(code) {
    const raw = String(code || '').trim();
    if (!raw) return null;
    ensureMedKits();
    const normalized = normalizeMedicationCode(raw);
    const directMatch = db.medKits.find(kit => normalizeMedicationCode(kit.scanCode) === normalized);
    if (directMatch) return directMatch;
    const [prefix, kitId] = raw.split('|');
    if (String(prefix || '').toUpperCase() !== 'PA-KIT' || !kitId) return null;
    const normalizedKitId = String(kitId).toUpperCase();
    return db.medKits.find(kit => String(kit.id || '').toUpperCase() === normalizedKitId) || null;
}

function medKitItemSourceValue(kit, item) {
    return kit?.id && item?.id ? `${kit.id}|${item.id}` : 'main';
}

function medKitAvailableChoices(kit, medId = '') {
    if (!kit) return [];
    return (kit.items || [])
        .map(item => ({ kit, item, med: kitItemMed(item) }))
        .filter(choice =>
            choice.med &&
            parseAmount(choice.item.qty, 0) > 0 &&
            (!medId || choice.item.medId === medId)
        );
}

function medKitLabelCapacity(size, hasCode = false) {
    const width = Number(size?.width) || 2.25;
    const height = Number(size?.height) || 1.25;
    const area = width * height;
    const wideBonus = width >= 3 ? 2 : 0;
    const codePenalty = hasCode ? 2 : 0;
    return Math.max(3, Math.floor(area * 2.6) + wideBonus - codePenalty);
}

function medKitLabelPages(choices, size, hasCode) {
    const queue = choices.slice();
    const pages = [];
    while (queue.length) {
        const codeOnPage = hasCode;
        const capacity = medKitLabelCapacity(size, codeOnPage);
        pages.push({
            choices: queue.splice(0, capacity),
            hasCode: codeOnPage
        });
    }
    if (!pages.length) pages.push({ choices: [], hasCode });
    return pages;
}

function medKitLabelOptionSize(values = {}) {
    const sizeId = values.sizeId || localStorage.getItem('pharmAtlasMedKitLabelSize') || 'thermal-225-125';
    const preset = customLabelSizeById(sizeId);
    if (sizeId !== 'custom') return preset;
    return {
        ...preset,
        width: Math.max(0.8, parseAmount(values.customWidth, parseAmount(localStorage.getItem('pharmAtlasMedKitLabelCustomWidth'), preset.width))),
        height: Math.max(0.5, parseAmount(values.customHeight, parseAmount(localStorage.getItem('pharmAtlasMedKitLabelCustomHeight'), preset.height)))
    };
}

window.toggleMedKitLabelCustomSize = function(value) {
    const row = document.getElementById('med-kit-label-custom-size');
    if (row) row.style.display = value === 'custom' ? 'flex' : 'none';
};

function medKitLabelHtml(kit, options = {}) {
    const choices = medKitAvailableChoices(kit);
    const size = options.size || customLabelSizeById(options.sizeId || localStorage.getItem('pharmAtlasMedKitLabelSize') || 'thermal-225-125');
    const kitCode = medKitScanCode(kit);
    const barcodeDataUrl = kitCode ? aztecBarcodeDataUrl(kitCode) : '';
    const pages = medKitLabelPages(choices, size, !!barcodeDataUrl);
    const styleVars = `--custom-label-width:${size.width}in; --custom-label-height:${size.height}in;`;
    const pageHtml = pages.map((page, index) => {
        const medLines = page.choices.map(({ med }) =>
            `<div class="med-kit-label-row">${escapeHtml(inventoryDisplayName(med))}</div>`
        ).join('');
        const pageText = [medKitName(kit), ...page.choices.map(({ med }) => inventoryDisplayName(med))];
        const labelClass = `${getLabelClass(pageText, page.choices.length + 2)} med-kit-label-page ${page.hasCode ? 'has-med-kit-code' : ''}`;
        const pageCounter = pages.length > 1 ? ` (${index + 1}/${pages.length})` : '';
        return `<div class="${labelClass}" style="${styleVars}">
            <div class="med-kit-label-copy">
                <div class="label-title med-kit-label-title">${escapeHtml(medKitName(kit))}</div>
                <div class="label-small med-kit-label-subtitle">Med Kit Contents${pageCounter}</div>
                <div class="med-kit-label-list">${medLines || '<div class="label-small">No medications in this kit.</div>'}</div>
            </div>
            ${page.hasCode ? `<img class="med-kit-label-aztec" src="${barcodeDataUrl}" alt="Med kit Aztec barcode">` : ''}
        </div>`;
    }).join('');
    return `${options.includePrintStyle ? customLabelPrintSizeStyle(size) : ''}${pageHtml}`;
}

function isExpiringWithinDays(dateValue, days = 10) {
    const date = parseLocal(dateValue);
    if (!date) return false;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const cutoff = new Date(today);
    cutoff.setDate(cutoff.getDate() + days);
    return date <= cutoff;
}

function medKitHasExpiringSoon(kit) {
    return (kit?.items || []).some(item => isExpiringWithinDays(item.expiry, 10));
}

function kitSourceOptionsForMed(medId) {
    ensureMedKits();
    const sources = [];
    db.medKits.forEach(kit => {
        (kit.items || []).forEach(item => {
            if (item.medId === medId && parseAmount(item.qty, 0) > 0) {
                sources.push({ kit, item });
            }
        });
    });
    return sources;
}

function kitSourceSelectHtml(medId) {
    const sources = kitSourceOptionsForMed(medId);
    if (sources.length === 0) return '';
    const options = sources.map(({ kit, item }) => {
        const med = kitItemMed(item);
        const unit = med ? inventoryUnitFor(med) : item.unit || 'unit';
        return `<option value="${escapeHtml(`${kit.id}|${item.id}`)}">${escapeHtml(`${medKitName(kit)} - ${formatAmount(parseAmount(item.qty))} ${unit} available`)}</option>`;
    }).join('');
    return `<div class="field-row" style="margin-top:8px;">
        <label>Inventory source:</label>
        <select name="inventorySource" style="width:260px;">
            <option value="main">Main inventory</option>
            ${options}
        </select>
    </div>`;
}

function consumeFromKitSource(sourceValue, med, qty) {
    if (!sourceValue || sourceValue === 'main') return { sourceLabel: 'Main inventory', kitItem: null, stockSource: 'main' };
    const [kitId, itemId] = String(sourceValue).split('|');
    const kit = db.medKits.find(candidate => candidate.id === kitId);
    const item = kit?.items?.find(candidate => candidate.id === itemId && candidate.medId === med.id);
    if (!kit || !item) return { error: 'The selected med kit item could not be found.' };
    if (parseAmount(item.qty, 0) < qty) {
        return { error: `Insufficient kit quantity. ${medKitName(kit)} has ${formatAmount(parseAmount(item.qty))} ${inventoryUnitFor(med)}.` };
    }
    item.qty = parseAmount(item.qty, 0) - qty;
    if (item.qty <= 0) kit.items = kit.items.filter(candidate => candidate.id !== item.id);
    kit.updatedAt = new Date().toISOString();
    return { sourceLabel: `Med Kit (${medKitName(kit)})`, kitItem: item, kitId, kitItemId: itemId, stockSource: 'kit' };
}

function restoreQuantityToKit(entry, med, qty) {
    if (!entry?.kitId || !med || !Number.isFinite(qty) || qty <= 0) return false;
    ensureMedKits();
    const kit = db.medKits.find(candidate => candidate.id === entry.kitId);
    if (!kit) return false;
    kit.items = Array.isArray(kit.items) ? kit.items : [];
    let item = kit.items.find(candidate => candidate.id === entry.kitItemId && candidate.medId === med.id)
        || kit.items.find(candidate => candidate.medId === med.id && String(candidate.expiry || '') === String(entry.kitExpiry || med.expiry || ''));
    if (!item) {
        item = {
            id: entry.kitItemId || medKitItemId(),
            medId: med.id,
            qty: 0,
            unit: inventoryUnitFor(med),
            expiry: entry.kitExpiry || med.expiry || '',
            addedAt: new Date().toISOString()
        };
        kit.items.push(item);
    }
    item.qty = parseAmount(item.qty, 0) + qty;
    item.updatedAt = new Date().toISOString();
    kit.updatedAt = new Date().toISOString();
    return true;
}

function medKitSourceFromValue(sourceValue, medId = '') {
    if (!sourceValue || sourceValue === 'main') return null;
    const [kitId, itemId] = String(sourceValue).split('|');
    const kit = db.medKits?.find(candidate => candidate.id === kitId);
    const item = kit?.items?.find(candidate => candidate.id === itemId && (!medId || candidate.medId === medId));
    return kit && item ? { kit, item, kitId, itemId } : null;
}

function prepackItemSourceSelectHtml(queueId, item) {
    const sources = kitSourceOptionsForMed(item?.medId);
    if (!sources.length) return '';
    const current = item.inventorySource || 'main';
    const options = sources.map(({ kit, item: kitItem }) => {
        const med = kitItemMed(kitItem);
        const unit = med ? inventoryUnitFor(med) : kitItem.unit || 'unit';
        const value = `${kit.id}|${kitItem.id}`;
        return `<option value="${escapeHtml(value)}" ${current === value ? 'selected' : ''}>${escapeHtml(`${medKitName(kit)} (${formatAmount(parseAmount(kitItem.qty))} ${unit})`)}</option>`;
    }).join('');
    return `<label class="prepack-source-select">Source:
        <select onchange="setPrepackItemSource('${escapeHtml(queueId)}','${escapeHtml(item.id)}',this.value)" ${isPreparedPrepackItem(item) ? 'disabled' : ''}>
            <option value="main" ${current === 'main' ? 'selected' : ''}>Main inventory</option>
            ${options}
        </select>
    </label>`;
}

window.setPrepackItemSource = async function(queueId, itemId, sourceValue) {
    const queue = db.prepackQueues.find(candidate => candidate.id === queueId);
    const item = queue?.days?.flatMap(day => day.items || []).find(candidate => candidate.id === itemId);
    if (!queue || !item) return;
    if (isPreparedPrepackItem(item)) {
        await appAlert('This item has already been prepared. Undo it before changing the inventory source.');
        renderPrepackageQueues();
        return;
    }
    item.inventorySource = sourceValue || 'main';
    await sync();
}

function returnKitItemToInventory(kit, item) {
    const med = kitItemMed(item);
    if (!med) return false;
    med.stock = parseAmount(med.stock, 0) + parseAmount(item.qty, 0);
    if (parseAmount(med.maxCapacity, 0) < parseAmount(med.stock, 0)) med.maxCapacity = med.stock;
    kit.items = (kit.items || []).filter(candidate => candidate.id !== item.id);
    kit.updatedAt = new Date().toISOString();
    return true;
}

function removeKitItemFromKit(kit, item) {
    if (!kit || !item) return;
    kit.items = (kit.items || []).filter(candidate => candidate.id !== item.id);
    kit.updatedAt = new Date().toISOString();
}

function defaultActualDateTime() {
    const now = new Date();
    return {
        date: localDateKey(now),
        time: `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`
    };
}

async function requestActualAdministration(title, extraHtml = '', confirmText = 'Administer') {
    const defaults = defaultActualDateTime();
    const result = await showActionModal(title, `
        <div class="field-row">
            <label>Date Taken:</label><input name="actualDate" type="date" value="${defaults.date}">
            <label>Time:</label><input name="actualTime" type="time" value="${defaults.time}">
        </div>
        ${extraHtml}
    `, confirmText);
    if (!result) return null;
    if (!result.actualDate || !result.actualTime) {
        await appAlert("Actual date and time are required.");
        return null;
    }
    return result;
}

async function requestScheduledDoseDocumentation(schedule, title) {
    const med = db.inventory.find(item => item.id === schedule.medId);
    const defaults = defaultActualDateTime();
    const range = getInstanceSelectionRange(schedule);
    const instances = getScheduleInstancesInRange(schedule, range.start, range.end);
    const availableInstances = instances.filter(instance => !isScheduleInstanceDocumented(schedule.id, instance.date, instance.time));
    if (instances.length === 0) {
        await appAlert("No scheduled dose instances were found for this medication.");
        return null;
    }
    if (availableInstances.length === 0) {
        await appAlert("All scheduled dose instances in the selectable range have already been documented.");
        return null;
    }
    const nextInstance = getNextAvailableScheduleInstance(schedule);
    const options = instances.map(instance => {
        const documented = isScheduleInstanceDocumented(schedule.id, instance.date, instance.time);
        const selected = nextInstance && nextInstance.date === instance.date && nextInstance.time === instance.time ? 'selected' : '';
        return `<option value="${escapeHtml(`${instance.date}|${instance.time}`)}" ${selected} ${documented ? 'disabled' : ''}>${escapeHtml(instance.date)} ${escapeHtml(instance.time)}${documented ? ' - already documented' : ''}</option>`;
    }).join('');

    const result = await showActionModal(title, `
        <div class="field-row">
            <label>Scheduled dose:</label>
            <select name="scheduledInstance" style="width:220px;">${options || '<option value="">No scheduled doses</option>'}</select>
        </div>
        <div class="field-row" style="margin-top:8px;">
            <label>Status:</label>
            <select name="doseStatus">
                <option value="given">Given as scheduled</option>
                <option value="late">Given late</option>
                <option value="early">Given early</option>
                <option value="skipped">Skipped</option>
                <option value="missed">Missed / forgotten</option>
                <option value="refused">Refused</option>
                <option value="held">Held</option>
                <option value="wasted">Wasted</option>
            </select>
        </div>
        <div class="field-row" style="margin-top:8px;">
            <label>Date documented/taken:</label><input name="actualDate" type="date" value="${defaults.date}">
            <label>Time:</label><input name="actualTime" type="time" value="${defaults.time}">
        </div>
        ${med ? kitSourceSelectHtml(med.id) : ''}
        <div class="field-row-stacked" style="margin-top:8px;">
            <label>Note:</label>
            <textarea name="doseNote" rows="2" style="width:100%; resize:none;" placeholder="Optional note"></textarea>
        </div>
    `, 'Save');
    if (!result) return null;
    const [scheduledDate, scheduledTime] = String(result.scheduledInstance || '').split('|');
    result.scheduledDate = scheduledDate;
    result.scheduledTime = scheduledTime;
    if (!result.scheduledDate || !result.scheduledTime || !result.actualDate || !result.actualTime) {
        await appAlert("Scheduled date/time and documented date/time are required.");
        return null;
    }
    if (!isScheduleDueOnDate(schedule, result.scheduledDate) || !getScheduleInstancesForDate(schedule, result.scheduledDate).some(instance => instance.time === result.scheduledTime)) {
        await appAlert("That medication is not scheduled for the selected date and time.");
        return null;
    }
    if (isScheduleInstanceDocumented(schedule.id, result.scheduledDate, result.scheduledTime)) {
        await appAlert("That scheduled dose instance has already been documented.");
        return null;
    }
    normalizeScheduledDoseActualTime(result);
    return result;
}

function normalizeScheduledDoseActualTime(actual) {
    const status = actual?.doseStatus || 'given';
    if (['given', 'skipped', 'missed', 'refused', 'held', 'wasted'].includes(status) && actual.scheduledDate && actual.scheduledTime) {
        actual.actualDate = actual.scheduledDate;
        actual.actualTime = actual.scheduledTime;
    }
    return actual;
}

function formatActualTimestamp(actual) {
    return `${actual.actualDate} ${actual.actualTime}`;
}

function memberDisplayName(member) {
    return member ? `${member.lastName}, ${member.firstName}` : 'Unknown member';
}

function memberOptionsHtml(selected = '') {
    return db.family
        .slice()
        .sort((a, b) => memberDisplayName(a).localeCompare(memberDisplayName(b), undefined, { sensitivity: 'base' }))
        .map(member => `<option value="${member.id}" ${member.id === selected ? 'selected' : ''}>${escapeHtml(memberDisplayName(member))}</option>`)
        .join('');
}

function assignedMemberIds(med) {
    return Array.isArray(med?.assignedMemberIds) ? med.assignedMemberIds.filter(Boolean) : [];
}

function medicationAssignedToMember(med, memberId) {
    const assigned = assignedMemberIds(med);
    return assigned.length === 0 || assigned.includes(memberId);
}

function medicationAssignmentText(med) {
    const assigned = assignedMemberIds(med);
    if (assigned.length === 0) return 'All members';
    const names = assigned
        .map(id => db.family.find(member => member.id === id))
        .filter(Boolean)
        .map(memberDisplayName);
    return names.length ? names.join(', ') : 'Selected members';
}

function renderMedicationAssignmentControls(prefix, selectedIds = null) {
    const mode = document.getElementById(`${prefix}-assignment-mode`);
    const container = document.getElementById(`${prefix}-assigned-members`);
    if (!mode || !container) return;
    const currentSelected = selectedIds || Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).map(input => input.value);
    if (selectedIds) mode.value = selectedIds.length ? 'selected' : 'all';
    container.innerHTML = db.family.length
        ? db.family
            .slice()
            .sort((a, b) => memberDisplayName(a).localeCompare(memberDisplayName(b), undefined, { sensitivity: 'base' }))
            .map(member => {
                const inputId = `${prefix}-assigned-${member.id}`;
                return `<label class="member-assignment-option" for="${escapeHtml(inputId)}">
                    <input id="${escapeHtml(inputId)}" type="checkbox" value="${escapeHtml(member.id)}" ${currentSelected.includes(member.id) ? 'checked' : ''}>
                    <span>${escapeHtml(memberDisplayName(member))}</span>
                </label>`;
            }).join('')
        : '<span class="form-help">Add members before assigning inventory.</span>';
    container.style.display = mode.value === 'selected' ? 'flex' : 'none';
}

window.updateMedicationAssignmentMode = function(prefix) {
    renderMedicationAssignmentControls(prefix);
};

function collectMedicationAssignment(prefix) {
    const mode = document.getElementById(`${prefix}-assignment-mode`)?.value || 'all';
    if (mode !== 'selected') return [];
    return Array.from(document.querySelectorAll(`#${prefix}-assigned-members input[type="checkbox"]:checked`))
        .map(input => input.value)
        .filter(Boolean);
}

function prescriberDisplayName(prescriber) {
    if (!prescriber) return '';
    return [prescriber.name, prescriber.specialty].filter(Boolean).join(' - ');
}

function prescriberIdentityKey(prescriber) {
    return [
        prescriber?.name,
        prescriber?.specialty,
        prescriber?.phone,
        prescriber?.fax,
        prescriber?.email,
        prescriber?.address
    ].map(value => String(value || '').trim().toLowerCase()).join('|');
}

function normalizeMemberDiagnoses(member) {
    if (Array.isArray(member?.diagnosesList)) return member.diagnosesList.filter(Boolean);
    if (Array.isArray(member?.diagnoses)) return member.diagnoses.filter(Boolean);
    return String(member?.diagnoses || '')
        .split(/[\n,;]+/)
        .map(item => item.trim())
        .filter(Boolean);
}

function memberPrescriberIds(member) {
    return Array.isArray(member?.prescriberIds) ? member.prescriberIds.filter(Boolean) : [];
}

function memberPrimaryPrescriberId(member) {
    const ids = memberPrescriberIds(member);
    return ids.includes(member?.primaryPrescriberId) ? member.primaryPrescriberId : '';
}

function memberPrescriberRecords(member) {
    const ids = new Set(memberPrescriberIds(member));
    return db.prescribers.filter(prescriber => ids.has(prescriber.id));
}

function pharmacyDisplayName(pharmacy) {
    if (!pharmacy) return '';
    return [pharmacy.name, pharmacy.phone].filter(Boolean).join(' - ');
}

function pharmacyIdentityKey(pharmacy) {
    return [
        pharmacy?.name,
        pharmacy?.phone,
        pharmacy?.fax,
        pharmacy?.email,
        pharmacy?.address,
        pharmacy?.website
    ].map(value => String(value || '').trim().toLowerCase()).join('|');
}

function memberPharmacyIds(member) {
    return Array.isArray(member?.pharmacyIds) ? member.pharmacyIds.filter(Boolean) : [];
}

function memberPrimaryPharmacyId(member) {
    const ids = memberPharmacyIds(member);
    return ids.includes(member?.primaryPharmacyId) ? member.primaryPharmacyId : '';
}

function memberPharmacyRecords(member) {
    const ids = new Set(memberPharmacyIds(member));
    return (db.pharmacies || []).filter(pharmacy => ids.has(pharmacy.id));
}

function getMemberDiagnoses(member) {
    return normalizeMemberDiagnoses(member);
}

function getMemberAllergies(member) {
    return normalizeMemberAllergies(member);
}

function memberMonitoringProfiles(member) {
    return Array.isArray(member?.monitoringProfiles) ? member.monitoringProfiles.filter(Boolean) : [];
}

function normalizeMemberAllergies(member) {
    return Array.isArray(member?.allergies)
        ? member.allergies
            .map(item => ({
                id: item.id || `allergy_${Date.now()}_${Math.random().toString(16).slice(2)}`,
                type: item.type === 'intolerance' ? 'intolerance' : 'allergy',
                medId: item.medId || '',
                name: String(item.name || '').trim(),
                reaction: String(item.reaction || '').trim()
            }))
            .filter(item => item.medId || item.name)
        : [];
}

function allergyTypeLabel(type) {
    return type === 'intolerance' ? 'Intolerance' : 'Allergy';
}

function allergyDisplayName(record) {
    const med = record?.medId ? db.inventory.find(item => item.id === record.medId) : null;
    return med ? `${med.name} ${formatMedStrength(med)}` : (record?.name || 'Unnamed');
}

function medicationAllergySearchText(med) {
    return [
        med?.name,
        formatMedStrength(med || {}),
        ...(med?.components || []).flatMap(component => [component.name, component.unit])
    ].filter(Boolean).join(' ').toLowerCase();
}

function allergyMatchesMedication(record, med) {
    if (!record || !med) return false;
    if (record.medId && record.medId === med.id) return true;
    const allergyName = String(record.name || '').trim().toLowerCase();
    if (!allergyName) return false;
    return medicationAllergySearchText(med).includes(allergyName) ||
        allergyName.includes(String(med.name || '').trim().toLowerCase());
}

function medicationAllergyMatches(member, med) {
    return normalizeMemberAllergies(member).filter(record => allergyMatchesMedication(record, med));
}

function prescriberOptionsHtml(selected = '', memberId = '', includeAll = true) {
    const member = db.family.find(item => item.id === memberId);
    const allowedIds = member ? new Set(memberPrescriberIds(member)) : null;
    const primaryId = memberPrimaryPrescriberId(member);
    const seen = new Set();
    const prescribers = db.prescribers
        .slice()
        .filter(prescriber => includeAll || !allowedIds || allowedIds.has(prescriber.id) || prescriber.id === selected)
        .filter(prescriber => {
            const key = prescriberIdentityKey(prescriber) || prescriber.id;
            if (prescriber.id !== selected && seen.has(key)) return false;
            seen.add(key);
            return true;
        })
        .sort((a, b) => Number(b.id === primaryId) - Number(a.id === primaryId) || prescriberDisplayName(a).localeCompare(prescriberDisplayName(b), undefined, { sensitivity: 'base' }));
    return `<option value="">Optional</option>` + prescribers
        .map(prescriber => `<option value="${prescriber.id}" ${prescriber.id === selected ? 'selected' : ''}>${prescriber.id === primaryId ? '&#9733; ' : ''}${escapeHtml(prescriberDisplayName(prescriber))}</option>`)
        .join('');
}

function prescriberNameById(id) {
    const prescriber = db.prescribers.find(item => item.id === id);
    return prescriber ? prescriberDisplayName(prescriber) : '';
}

function pharmacyOptionsHtml(selected = '', memberId = '', includeAll = true) {
    const member = db.family.find(item => item.id === memberId);
    const allowedIds = member ? new Set(memberPharmacyIds(member)) : null;
    const primaryId = memberPrimaryPharmacyId(member);
    const seen = new Set();
    const pharmacies = (db.pharmacies || [])
        .slice()
        .filter(pharmacy => includeAll || !allowedIds || allowedIds.has(pharmacy.id) || pharmacy.id === selected)
        .filter(pharmacy => {
            const key = pharmacyIdentityKey(pharmacy) || pharmacy.id;
            if (pharmacy.id !== selected && seen.has(key)) return false;
            seen.add(key);
            return true;
        })
        .sort((a, b) => Number(b.id === primaryId) - Number(a.id === primaryId) || pharmacyDisplayName(a).localeCompare(pharmacyDisplayName(b), undefined, { sensitivity: 'base' }));
    return `<option value="">Optional</option>` + pharmacies
        .map(pharmacy => `<option value="${escapeHtml(pharmacy.id)}" ${pharmacy.id === selected ? 'selected' : ''}>${pharmacy.id === primaryId ? '&#9733; ' : ''}${escapeHtml(pharmacyDisplayName(pharmacy))}</option>`)
        .join('');
}

function pharmacyNameById(id) {
    const pharmacy = (db.pharmacies || []).find(item => item.id === id);
    return pharmacy ? pharmacyDisplayName(pharmacy) : '';
}

function getHiddenJson(id, fallback = []) {
    const input = document.getElementById(id);
    if (!input?.value) return fallback;
    try {
        const parsed = JSON.parse(input.value);
        return Array.isArray(parsed) ? parsed : fallback;
    } catch {
        return fallback;
    }
}

function setHiddenJson(id, value) {
    const input = document.getElementById(id);
    if (input) input.value = JSON.stringify(value || []);
}

function currentMemberMedicationList() {
    return getHiddenJson('m-current-med-list-data');
}

function currentMemberDiscontinuedMedicationList() {
    return getHiddenJson('m-current-discontinued-med-list-data');
}

function doseQtyWithParentheses(value) {
    const parts = String(value || '').split(';').map(part => part.trim()).filter(Boolean);
    if (parts.length >= 2) return `${parts[0]} (${parts.slice(1).join('; ')})`;
    return parts[0] || '';
}

function medicationNameWithStrength(med) {
    if (!med) return '';
    return `${med.name || ''} ${formatMedStrength(med) || ''}`.trim();
}

function currentMemberLabDocuments() {
    return getHiddenJson('m-lab-documents-data');
}

function currentMemberProgressNotes() {
    return getHiddenJson('m-progress-notes-data');
}

function defaultCurrentMedicationListForMember(memberId) {
    if (!memberId) return [];
    const byMed = new Map();
    db.schedules
        .filter(schedule => schedule.memberId === memberId && !isScheduleArchived(schedule))
        .forEach(schedule => {
            const med = db.inventory.find(item => item.id === schedule.medId);
            if (!med || byMed.has(med.id)) return;
            byMed.set(med.id, {
                medId: med.id,
                doseQty: `${formatPrescribedDose(med, schedule.doseQty)}${schedule.doseQty ? `; ${formatQtyForSchedule(schedule, med)}` : ''}`,
                indication: schedule.indication || '',
                prescriberId: schedule.prescriberId || med.prescriberId || '',
                pharmacyId: schedule.pharmacyId || med.pharmacyId || '',
                frequency: `${formatFrequency(schedule)} ${getScheduleTimes(schedule).join(', ') || 'PRN'}`.trim()
            });
        });
    return [...byMed.values()];
}

window.switchMemberProfileTab = function(tab = 'main') {
    captureMemberProfileState(currentEditingMemberId, { activeTab: tab });
    document.querySelectorAll('.member-profile-tab').forEach(button => {
        button.classList.toggle('active', button.dataset.memberProfileTab === tab);
    });
    document.querySelectorAll('[data-member-section]').forEach(section => {
        section.style.display = section.dataset.memberSection === tab ? '' : 'none';
    });
    document.querySelector('.member-profile-window')?.classList.toggle('diary-workbench', tab === 'diary');
    const rail = document.getElementById('member-profile-right-panel');
    if (rail) {
        rail.style.display = tab === 'main' ? '' : 'none';
    }
    updateProgressNoteSidePanel();
    renderMemberContextRail(currentEditingMemberId);
    if (tab === 'orders') renderMemberCommandScanPanel();
};

function latestMemberReading(memberId, types) {
    const typeSet = new Set(Array.isArray(types) ? types : [types]);
    return db.vitals
        .filter(reading => reading.memberId === memberId && typeSet.has(reading.type))
        .slice()
        .sort((a, b) => String(`${b.date || ''} ${b.time || ''}`).localeCompare(String(`${a.date || ''} ${a.time || ''}`)))[0] || null;
}

function latestMemberReadingSummary(memberId) {
    const bp = latestMemberReading(memberId, ['bp', 'bp_hr']);
    const glucose = latestMemberReading(memberId, 'glucose');
    const weight = latestMemberReading(memberId, 'weight');
    const temperature = latestMemberReading(memberId, 'temperature');
    return [
        bp ? `BP ${bp.systolic || '--'}/${bp.diastolic || '--'}${bp.hr || bp.heartRate ? `, HR ${bp.hr || bp.heartRate}` : ''}` : '',
        glucose ? `Glucose ${glucose.glucose || glucose.value || '--'} mg/dL` : '',
        weight ? `Weight ${weight.weight || weight.value || '--'} ${weight.weightUnit || weight.unit || ''}`.trim() : '',
        temperature ? `Temp ${temperature.temperature || temperature.value || '--'} ${temperature.tempUnit || temperature.unit || ''}`.trim() : ''
    ].filter(Boolean);
}

function memberGoalSnapshot(member) {
    const goals = member?.vitalGoals || {};
    const pieces = [];
    if (goals.bp) {
        const bp = goals.bp;
        pieces.push(`BP ${bp.sysMin || '--'}-${bp.sysMax || '--'}/${bp.diaMin || '--'}-${bp.diaMax || '--'}`);
    }
    if (goals.hr) {
        pieces.push(`HR ${goals.hr.min || '--'}-${goals.hr.max || '--'} bpm`);
    }
    if (goals.glucose) {
        pieces.push(`Glucose ${goals.glucose.low || '--'}-${goals.glucose.high || '--'} mg/dL`);
    }
    if (goals.weight) {
        pieces.push(`Weight ${goals.weight.low || '--'}-${goals.weight.high || '--'} ${goals.weight.unit || 'lb'}`);
    }
    return pieces;
}

function renderMemberContextRail(memberId = currentEditingMemberId) {
    const rail = document.getElementById('member-profile-right-panel');
    if (!rail) return;
    const activeTab = document.querySelector('.member-profile-tab.active')?.dataset.memberProfileTab || 'main';
    if (activeTab !== 'main') {
        rail.innerHTML = '';
        rail.style.display = 'none';
        return;
    }
    const member = db.family.find(item => item.id === memberId);
    if (!member) {
        rail.innerHTML = `
            <div class="rail-titlebar">Profile Snapshot</div>
            <div class="rail-empty">Save this member before the side panel can summarize medications, safety items, and notes.</div>`;
        return;
    }
    const activeSchedules = db.schedules.filter(schedule => schedule.memberId === member.id && !isScheduleArchived(schedule));
    const prnCount = activeSchedules.filter(schedule => schedule.freq === 'PRN').length;
    const heldSchedules = activeSchedules.filter(schedule => activeMedicationHoldInfo(schedule)?.active);
    const diagnoses = currentEditingMemberId === member.id ? getHiddenJson('m-diagnoses-data') : normalizeMemberDiagnoses(member);
    const allergies = currentEditingMemberId === member.id ? getHiddenJson('m-allergies-data') : normalizeMemberAllergies(member);
    const notes = (currentEditingMemberId === member.id ? currentMemberProgressNotes() : (Array.isArray(member.progressNotes) ? member.progressNotes : []))
        .slice()
        .sort((a, b) => String(`${b.date || ''} ${b.time || ''}`).localeCompare(String(`${a.date || ''} ${a.time || ''}`)));
    const importantNotes = notes.filter(note => progressNoteFlags(note).important || progressNoteFlags(note).followup || progressNoteFlags(note).provider || progressNoteFlags(note).pinned).slice(0, 3);
    const readings = latestMemberReadingSummary(member.id);
    const goals = memberGoalSnapshot(member);
    const primaryPrescriberId = memberPrimaryPrescriberId(member);
    const primaryPharmacyId = memberPrimaryPharmacyId(member);
    const careTeam = [
        ...memberPrescriberIds(member).map(id => {
            const prescriber = db.prescribers.find(item => item.id === id);
            return prescriber ? {
                name: prescriberDisplayName(prescriber),
                primary: id === primaryPrescriberId,
                title: 'Primary provider'
            } : null;
        }),
        ...memberPharmacyIds(member).map(id => {
            const pharmacy = (db.pharmacies || []).find(item => item.id === id);
            return pharmacy ? {
                name: pharmacyDisplayName(pharmacy),
                primary: id === primaryPharmacyId,
                title: 'Primary pharmacy'
            } : null;
        })
    ].filter(Boolean).slice(0, 4);

    rail.innerHTML = `
        <div class="rail-titlebar">Profile Snapshot</div>
        <div class="member-rail-identity">
            ${memberTaskIconHtml(member)}
            <div>
                <strong>${escapeHtml(memberDisplayName(member))}</strong>
                <small>${escapeHtml(member.dob ? `DOB ${member.dob}` : 'DOB not entered')}${member.bmi ? ` | BMI ${escapeHtml(member.bmi)}` : ''}</small>
            </div>
        </div>
        <div class="rail-metric-grid compact">
            <button type="button" class="rail-metric ok" onclick="switchMemberProfileTab('orders')"><span>Active</span><strong>${activeSchedules.length}</strong></button>
            <button type="button" class="rail-metric watch" onclick="switchMemberProfileTab('orders')"><span>PRN</span><strong>${prnCount}</strong></button>
            <button type="button" class="rail-metric danger" onclick="switchMemberProfileTab('orders')"><span>Held</span><strong>${heldSchedules.length}</strong></button>
            <button type="button" class="rail-metric exception" onclick="switchMemberProfileTab('diary')"><span>Notes</span><strong>${notes.length}</strong></button>
        </div>
        <fieldset class="rail-section">
            <legend>Safety</legend>
            <div class="rail-chip-line">${allergies.length ? allergies.slice(0, 3).map(record => `<span class="rail-chip danger">${escapeHtml(allergyDisplayName(record))}</span>`).join('') : '<span class="rail-chip ok">No allergies entered</span>'}</div>
            <div class="rail-muted">${diagnoses.length ? escapeHtml(diagnoses.slice(0, 4).join(', ')) : 'No diagnoses entered.'}</div>
        </fieldset>
        <fieldset class="rail-section">
            <legend>Monitoring</legend>
            <div class="rail-muted">${goals.length ? escapeHtml(goals.join(' | ')) : 'Goals not entered.'}</div>
            <div class="rail-list mini">${readings.length ? readings.map(item => `<div>${escapeHtml(item)}</div>`).join('') : '<div>No recent readings.</div>'}</div>
        </fieldset>
        <fieldset class="rail-section">
            <legend>Care Team</legend>
            <div class="rail-list mini">${careTeam.length ? careTeam.map(item => `<div>${item.primary ? `<span class="win98-star primary-care-star" title="${escapeHtml(item.title)}">&#9733;</span>` : ''}${escapeHtml(item.name)}</div>`).join('') : '<div>No providers or pharmacies added.</div>'}</div>
        </fieldset>
        <fieldset class="rail-section">
            <legend>Follow-Up Notes</legend>
            <div class="rail-list">${importantNotes.length ? importantNotes.map(note => `
                <button type="button" class="rail-list-button note" onclick="switchMemberProfileTab('diary'); previewMemberProgressNote('${escapeHtml(note.id)}')">
                    <strong>${escapeHtml(note.title || 'Untitled note')}</strong>
                    <small>${escapeHtml(note.date || '')} ${escapeHtml((normalizeProgressNoteTags(note.tags).slice(0, 3).join(', ') || '').trim())}</small>
                </button>`).join('') : '<div class="rail-empty">No pinned or follow-up notes.</div>'}</div>
        </fieldset>
        <fieldset class="rail-section">
            <legend>Quick Navigation</legend>
            <div class="rail-action-grid">
                <button type="button" onclick="switchMemberProfileTab('summary')">Summary</button>
                <button type="button" onclick="switchMemberProfileTab('monitoring')">Monitoring</button>
                <button type="button" onclick="switchMemberProfileTab('diary')">Diary</button>
                <button type="button" onclick="switchMemberProfileTab('orders')">Schedules</button>
            </div>
        </fieldset>`;
}

function renderMemberCurrentMedicationList() {
    const container = document.getElementById('member-current-med-list');
    if (!container) return;
    const rows = currentMemberMedicationList()
        .map(item => {
            const med = db.inventory.find(candidate => candidate.id === item.medId);
            if (!med) return '';
            const prescriber = item.prescriberName || (item.prescriberId ? prescriberNameById(item.prescriberId) : medicationSummaryPrescriberName(null, med));
            const pharmacy = item.pharmacyId ? pharmacyNameById(item.pharmacyId) : medicationSummaryPharmacyName(null, med);
            return `<tr>
                <td><strong>${escapeHtml(medicationNameWithStrength(med))}</strong></td>
                <td>${escapeHtml(doseQtyWithParentheses(item.doseQty || ''))}</td>
                <td>${escapeHtml(item.indication || 'Not specified')}</td>
                <td>${escapeHtml(prescriber || 'Not specified')}</td>
                <td>${escapeHtml(pharmacy || 'Not specified')}</td>
                <td>${escapeHtml(item.frequency || '')}</td>
                <td>${escapeHtml(item.directions || '')}</td>
            </tr>`;
        })
        .filter(Boolean)
        .join('');
    container.innerHTML = `
        <table class="win98-report-table current-med-list-table">
            <thead><tr><th>Medication</th><th>Dose / Qty</th><th>Used For</th><th>Prescriber</th><th>Pharmacy</th><th>Frequency</th><th>Directions / Comments</th></tr></thead>
            <tbody>${rows || '<tr><td colspan="7">No current list saved. Use Create/Edit Current List to select inventory items.</td></tr>'}</tbody>
        </table>
        ${currentMemberDiscontinuedMedicationList().length ? `
            <div class="current-list-discontinued-block">
                <strong>Discontinued medications / supplements</strong>
                <ul>
                    ${currentMemberDiscontinuedMedicationList().map(item => {
                        const med = item.medId ? db.inventory.find(candidate => candidate.id === item.medId) : null;
                        const name = med ? medicationNameWithStrength(med) : (item.name || item.medication || '');
                        if (!name) return '';
                        const prescriber = item.prescriberName ? `Prescriber: ${item.prescriberName}; ` : '';
                        return `<li><strong>${escapeHtml(name)}</strong> - ${escapeHtml(prescriber)}stopped by ${escapeHtml(item.discontinuedBy || 'not specified')}${item.discontinuedDate ? ` on ${escapeHtml(item.discontinuedDate)}` : ''}${item.directions ? `; ${escapeHtml(item.directions)}` : ''}</li>`;
                    }).filter(Boolean).join('')}
                </ul>
            </div>
        ` : ''}`;
}

function currentMedicationListRows(member) {
    const list = Array.isArray(member?.currentMedicationList) && member.currentMedicationList.length
        ? member.currentMedicationList
        : defaultCurrentMedicationListForMember(member?.id);
    return list
        .map(item => {
            const med = db.inventory.find(candidate => candidate.id === item.medId);
            if (!med) return null;
            return {
                medId: med.id,
                medication: medicationNameWithStrength(med),
                dose: doseQtyWithParentheses(item.doseQty || ''),
                usedFor: item.indication || 'Not specified',
                prescriber: item.prescriberName || (item.prescriberId ? prescriberNameById(item.prescriberId) : medicationSummaryPrescriberName(null, med)),
                pharmacy: item.pharmacyId ? pharmacyNameById(item.pharmacyId) : medicationSummaryPharmacyName(null, med),
                frequency: item.frequency || '',
                directions: item.directions || ''
            };
        })
        .filter(Boolean);
}

const currentMedicationListColumns = [
    { id: 'medication', label: 'Medication' },
    { id: 'dose', label: 'Dose / Qty' },
    { id: 'usedFor', label: 'Used For' },
    { id: 'prescriber', label: 'Prescriber' },
    { id: 'pharmacy', label: 'Pharmacy' },
    { id: 'frequency', label: 'Frequency' },
    { id: 'directions', label: 'Directions / Comments' },
    { id: 'stoppedBy', label: 'Stopped By', stoppedOnly: true },
    { id: 'stopDate', label: 'Stop Date', stoppedOnly: true }
];

const defaultCurrentMedicationListColumnIds = currentMedicationListColumns.map(column => column.id);

function currentMedicationListSelectedColumns(options = {}) {
    const selectedIds = Array.isArray(options.columnIds) && options.columnIds.length
        ? new Set(options.columnIds)
        : new Set(defaultCurrentMedicationListColumnIds);
    const columns = currentMedicationListColumns.filter(column => selectedIds.has(column.id));
    return columns.length ? columns : currentMedicationListColumns;
}

function currentMedicationListSelectedRows(member, options = {}) {
    const rows = currentMedicationListRows(member);
    if (Array.isArray(options.medIds)) {
        const selectedMedIds = new Set(options.medIds);
        return rows.filter(item => selectedMedIds.has(item.medId));
    }
    return rows;
}

function currentMedicationDiscontinuedRows(member) {
    const list = Array.isArray(member?.currentMedicationDiscontinuedList)
        ? member.currentMedicationDiscontinuedList
        : [];
    return list
        .map(item => {
            const med = item.medId ? db.inventory.find(candidate => candidate.id === item.medId) : null;
            const manualName = item.name || item.medication || '';
            if (!med && !manualName) return null;
            return {
                medId: med?.id || item.manualId || item.id || manualName,
                medication: med ? medicationNameWithStrength(med) : manualName,
                dose: doseQtyWithParentheses(item.doseQty || ''),
                usedFor: item.indication || 'Not specified',
                prescriber: item.prescriberName || 'Not specified',
                pharmacy: item.pharmacyId ? pharmacyNameById(item.pharmacyId) : (item.pharmacyName || 'Not specified'),
                frequency: item.frequency || '',
                stoppedBy: item.discontinuedBy || 'Not specified',
                stopDate: item.discontinuedDate || '',
                directions: item.directions || ''
            };
        })
        .filter(Boolean)
        .sort((a, b) => String(b.stopDate || '').localeCompare(String(a.stopDate || '')) || a.medication.localeCompare(b.medication));
}

function memberCurrentMedsReportBody(member, options = {}) {
    const columns = currentMedicationListSelectedColumns(options);
    const activeColumns = columns.filter(column => !column.stoppedOnly);
    const discontinuedColumns = columns;
    const rows = currentMedicationListSelectedRows(member, options).map(item => `
        <tr>
            ${activeColumns.map(column => `<td>${column.id === 'medication' ? `<strong>${escapeHtml(item.medication)}</strong>` : escapeHtml(item[column.id] || '')}</td>`).join('')}
        </tr>`).join('');
    const discontinuedRows = options.includeDiscontinued
        ? currentMedicationDiscontinuedRows(member).map(item => `
            <tr>
                ${discontinuedColumns.map(column => `<td>${column.id === 'medication' ? `<strong>${escapeHtml(item.medication)}</strong>` : escapeHtml(item[column.id] || '')}</td>`).join('')}
            </tr>`).join('')
        : '';
    return `
        <h2>${escapeHtml(memberDisplayName(member))}</h2>
        <h2>Current Meds / Supplements List</h2>
        <table>
            <thead><tr>${activeColumns.map(column => `<th>${escapeHtml(column.label)}</th>`).join('')}</tr></thead>
            <tbody>${rows || `<tr><td colspan="${activeColumns.length || 1}">No current meds or supplements saved.</td></tr>`}</tbody>
        </table>
        ${options.includeDiscontinued ? `
            <h2>Discontinued Medications / Supplements</h2>
            <table class="discontinued-report-table">
                <thead><tr>${discontinuedColumns.map(column => `<th>${escapeHtml(column.label)}</th>`).join('')}</tr></thead>
                <tbody>${discontinuedRows || `<tr><td colspan="${discontinuedColumns.length || 1}">No discontinued medications selected.</td></tr>`}</tbody>
            </table>
        ` : ''}`;
}

function currentMedsOptionsFromModalBody(body) {
    const medIds = [...body.querySelectorAll('input[name="currentListMedIds"]:checked')].map(input => input.value);
    const columnIds = [...body.querySelectorAll('input[name="currentListColumnIds"]:checked')].map(input => input.value);
    const includeDiscontinued = body.querySelector('input[name="currentListIncludeDiscontinued"]')?.checked === true;
    return { medIds, columnIds, includeDiscontinued };
}

window.refreshCurrentMedsReportPreview = function(memberId) {
    const member = db.family.find(item => item.id === memberId);
    const body = document.getElementById('action-modal-body');
    const preview = document.getElementById('current-meds-report-preview');
    if (!member || !body || !preview) return;
    preview.innerHTML = memberCurrentMedsReportBody(member, currentMedsOptionsFromModalBody(body));
};

async function chooseCurrentMedsOutputOptions(member, mode) {
    const rows = currentMedicationListRows(member);
    const medicationOptions = rows.map(item => {
        const inputId = `current-list-med-${item.medId}`;
        return `<label class="current-list-print-row" for="${escapeHtml(inputId)}">
            <input id="${escapeHtml(inputId)}" type="checkbox" name="currentListMedIds" value="${escapeHtml(item.medId)}" checked onchange="refreshCurrentMedsReportPreview('${escapeHtml(member.id)}')">
            <span class="current-list-print-copy">
                <strong>${escapeHtml(item.medication)}</strong>
                <small>${escapeHtml([item.dose, item.frequency].filter(Boolean).join(' | '))}</small>
            </span>
        </label>`;
    }).join('');
    const columnOptions = currentMedicationListColumns.map(column => `
        <label class="summary-column-chip">
            <input type="checkbox" name="currentListColumnIds" value="${escapeHtml(column.id)}" checked onchange="refreshCurrentMedsReportPreview('${escapeHtml(member.id)}')">
            <span>${escapeHtml(column.label)}</span>
        </label>`).join('');
    const discontinuedCount = currentMedicationDiscontinuedRows(member).length;
    const result = await showActionModal(`${mode === 'pdf' ? 'PDF' : 'Print'} Current Meds / Supplements List`, `
        <div data-action-modal-size="wide" class="medication-summary-output-modal">
            <div class="summary-output-layout">
                <div class="summary-output-options">
                    <fieldset>
                        <legend>Current List Items</legend>
                        <div class="summary-select-actions">
                            <button type="button" onclick="setMedicationSummaryChecks('currentListMedIds', true); refreshCurrentMedsReportPreview('${escapeHtml(member.id)}')">Select All</button>
                            <button type="button" onclick="setMedicationSummaryChecks('currentListMedIds', false); refreshCurrentMedsReportPreview('${escapeHtml(member.id)}')">Clear</button>
                        </div>
                        <div class="summary-option-list current-list-option-list">${medicationOptions || '<div class="empty-state">No current meds or supplements saved.</div>'}</div>
                    </fieldset>
                    <fieldset>
                        <legend>Columns</legend>
                        <div class="summary-column-list">${columnOptions}</div>
                    </fieldset>
                    <fieldset>
                        <legend>Optional Sections</legend>
                        <label class="summary-column-chip report-section-chip">
                            <input type="checkbox" name="currentListIncludeDiscontinued" ${discontinuedCount ? 'checked' : ''} onchange="refreshCurrentMedsReportPreview('${escapeHtml(member.id)}')">
                            <span>Show discontinued list (${discontinuedCount})</span>
                        </label>
                    </fieldset>
                </div>
                <fieldset class="summary-preview-fieldset">
                    <legend>Built-in Preview</legend>
                    <div id="current-meds-report-preview" class="summary-report-preview">
                        ${memberCurrentMedsReportBody(member, { medIds: rows.map(item => item.medId), columnIds: defaultCurrentMedicationListColumnIds, includeDiscontinued: !!discontinuedCount })}
                    </div>
                </fieldset>
            </div>
        </div>
    `, mode === 'pdf' ? 'Generate PDF' : 'Print', currentMedsOptionsFromModalBody);
    if (!result) return null;
    if (!result.medIds.length && !(result.includeDiscontinued && currentMedicationDiscontinuedRows(member).length)) {
        await appAlert('Select at least one current medication/supplement or include the discontinued list.');
        return chooseCurrentMedsOutputOptions(member, mode);
    }
    if (!result.columnIds.length) {
        await appAlert('Select at least one column to include.');
        return chooseCurrentMedsOutputOptions(member, mode);
    }
    return result;
}

window.generateMemberCurrentMedsPdfReport = async function(memberId = currentEditingMemberId) {
    const member = db.family.find(item => item.id === memberId);
    if (!member) return appAlert('Open a saved member profile before generating a current meds/supplements PDF.');
    const options = await chooseCurrentMedsOutputOptions(member, 'pdf');
    if (!options) return;
    await saveReportPdf(
        'Current Meds / Supplements List',
        memberCurrentMedsReportBody(member, options),
        `Current_Meds_Supplements_${member.lastName}_${member.firstName}`,
        { preview: false }
    );
};

window.printMemberCurrentMedsReport = async function(memberId = currentEditingMemberId) {
    const member = db.family.find(item => item.id === memberId);
    if (!member) {
        appAlert('Open a saved member profile before printing a current meds/supplements list.');
        return;
    }
    const options = await chooseCurrentMedsOutputOptions(member, 'print');
    if (!options) return;
    printReportFromPreview(
        'Current Meds / Supplements List',
        memberCurrentMedsReportBody(member, options)
    );
};

window.filterCurrentMedsBuilder = function() {
    const query = String(document.getElementById('current-meds-builder-search')?.value || '').trim().toLowerCase();
    document.querySelectorAll('.current-meds-builder-row, .current-meds-discontinued-row').forEach(row => {
        row.style.display = !query || row.dataset.search.includes(query) ? '' : 'none';
    });
};

window.currentMedsBuilderSelectionChanged = function(input) {
    input?.closest('.current-meds-builder-row')?.classList.toggle('selected', !!input.checked);
    renderCurrentMedsBuilderPreview();
};

window.currentMedsDiscontinuedSelectionChanged = function(input) {
    input?.closest('.current-meds-discontinued-row')?.classList.toggle('selected', !!input.checked);
    renderCurrentMedsBuilderPreview();
};

window.addManualCurrentMedsDiscontinuedRow = function() {
    const list = document.getElementById('current-meds-manual-discontinued-list');
    if (!list) return;
    const rowId = `manual-disc-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    list.insertAdjacentHTML('beforeend', manualCurrentMedsDiscontinuedRowHtml({ manualId: rowId }));
    renderCurrentMedsBuilderPreview();
};

window.removeManualCurrentMedsDiscontinuedRow = function(rowId) {
    document.querySelector(`#action-modal-body .current-meds-manual-discontinued-row[data-row-id="${cssEscape(rowId)}"]`)?.remove();
    renderCurrentMedsBuilderPreview();
};

window.removeCurrentMedsBuilderSelection = function(medId, kind = 'active') {
    const selector = kind === 'discontinued' ? '.current-meds-discontinued-row' : '.current-meds-builder-row';
    const inputName = kind === 'discontinued' ? 'currentDiscontinuedMedIds' : 'currentMedIds';
    const row = [...document.querySelectorAll(`#action-modal-body ${selector}`)]
        .find(candidate => candidate.dataset.medId === medId);
    const input = row?.querySelector(`input[name="${inputName}"]`);
    if (!input) return;
    input.checked = false;
    if (kind === 'discontinued') {
        currentMedsDiscontinuedSelectionChanged(input);
    } else {
        currentMedsBuilderSelectionChanged(input);
    }
};

window.renderCurrentMedsBuilderPreview = function() {
    const body = document.getElementById('action-modal-body');
    const panel = document.getElementById('current-meds-builder-preview');
    if (!body || !panel) return;
    const selectedRows = [...body.querySelectorAll('.current-meds-builder-row')]
        .filter(row => row.querySelector('input[name="currentMedIds"]')?.checked);
    const selectedDiscontinuedRows = [...body.querySelectorAll('.current-meds-discontinued-row')]
        .filter(row => row.querySelector('input[name="currentDiscontinuedMedIds"]')?.checked);
    const manualDiscontinuedRows = [...body.querySelectorAll('.current-meds-manual-discontinued-row')]
        .filter(row => row.querySelector('input[name="manualDiscontinuedName"]')?.value.trim());
    const activeHtml = selectedRows.length ? selectedRows.map(row => {
        const medId = row.dataset.medId || '';
        const name = row.querySelector('.current-meds-builder-name strong')?.textContent || 'Medication';
        const dose = row.querySelector('input[name="currentDoseQty"]')?.value.trim() || 'Dose not entered';
        const indication = row.querySelector('input[name="currentIndication"]')?.value.trim() || 'Use not entered';
        const frequency = row.querySelector('input[name="currentFrequency"]')?.value.trim() || 'Frequency not entered';
        const directions = row.querySelector('input[name="currentDirections"]')?.value.trim() || '';
        const prescriber = row.querySelector('input[name="currentPrescriberName"]')?.value.trim() || 'Optional';
        const pharmacySelect = row.querySelector('select[name="currentPharmacyId"]');
        const pharmacy = pharmacySelect?.selectedOptions?.[0]?.textContent || 'Optional';
        return `<div class="current-meds-preview-item">
            <div class="current-meds-preview-copy">
                <strong>${escapeHtml(name)}</strong>
                <small>${escapeHtml(dose)} | ${escapeHtml(frequency)}</small>
                <small>Used for: ${escapeHtml(indication)}</small>
                <small>Prescriber: ${escapeHtml(prescriber)}</small>
                <small>Pharmacy: ${escapeHtml(pharmacy)}</small>
                ${directions ? `<small>Directions: ${escapeHtml(directions)}</small>` : ''}
            </div>
            <button type="button" class="inventory-builder-remove" onclick="removeCurrentMedsBuilderSelection('${escapeHtml(medId)}')" title="Remove from selected list">X</button>
        </div>`;
    }).join('') : '<div class="empty-state">Checked medications will appear here.</div>';
    const discontinuedHtml = [...selectedDiscontinuedRows, ...manualDiscontinuedRows].length ? [...selectedDiscontinuedRows, ...manualDiscontinuedRows].map(row => {
        const medId = row.dataset.medId || '';
        const rowId = row.dataset.rowId || '';
        const manual = row.classList.contains('current-meds-manual-discontinued-row');
        const name = manual
            ? row.querySelector('input[name="manualDiscontinuedName"]')?.value.trim() || 'Medication'
            : row.querySelector('.current-meds-builder-name strong')?.textContent || 'Medication';
        const prescriber = row.querySelector('input[name="currentDiscontinuedPrescriberName"], input[name="manualDiscontinuedPrescriberName"]')?.value.trim() || 'Not specified';
        const stoppedBy = row.querySelector('input[name="currentDiscontinuedBy"], input[name="manualDiscontinuedBy"]')?.value.trim() || 'Not specified';
        const stoppedDate = row.querySelector('input[name="currentDiscontinuedDate"], input[name="manualDiscontinuedDate"]')?.value || '';
        const dose = row.querySelector('input[name="currentDiscontinuedDoseQty"], input[name="manualDiscontinuedDoseQty"]')?.value.trim() || 'Dose not entered';
        const indication = row.querySelector('input[name="currentDiscontinuedIndication"], input[name="manualDiscontinuedIndication"]')?.value.trim() || 'Use not entered';
        const frequency = row.querySelector('input[name="currentDiscontinuedFrequency"], input[name="manualDiscontinuedFrequency"]')?.value.trim() || 'Frequency not entered';
        const directions = row.querySelector('input[name="currentDiscontinuedDirections"], input[name="manualDiscontinuedDirections"]')?.value.trim() || '';
        const pharmacySelect = row.querySelector('select[name="currentDiscontinuedPharmacyId"]');
        const pharmacy = pharmacySelect?.selectedOptions?.[0]?.textContent || row.querySelector('input[name="manualDiscontinuedPharmacyName"]')?.value.trim() || 'Optional';
        return `<div class="current-meds-preview-item stopped">
            <div class="current-meds-preview-copy">
                <strong>${escapeHtml(name)}</strong>
                <small>${escapeHtml(dose)} | ${escapeHtml(frequency)}</small>
                <small>Used for: ${escapeHtml(indication)}</small>
                <small>Prescriber: ${escapeHtml(prescriber)}</small>
                <small>Stopped by: ${escapeHtml(stoppedBy)}</small>
                ${stoppedDate ? `<small>Stop date: ${escapeHtml(stoppedDate)}</small>` : ''}
                <small>Pharmacy: ${escapeHtml(pharmacy)}</small>
                ${directions ? `<small>Directions: ${escapeHtml(directions)}</small>` : ''}
            </div>
            <button type="button" class="inventory-builder-remove" onclick="${manual ? `removeManualCurrentMedsDiscontinuedRow('${escapeHtml(rowId)}')` : `removeCurrentMedsBuilderSelection('${escapeHtml(medId)}', 'discontinued')`}" title="Remove from discontinued list">X</button>
        </div>`;
    }).join('') : '<div class="empty-state">Stopped meds selected below will appear here.</div>';
    panel.innerHTML = `
        <div class="current-meds-preview-heading">Currently taking</div>
        ${activeHtml}
        <div class="current-meds-preview-heading stopped">Discontinued / stopped</div>
        ${discontinuedHtml}`;
};

function manualCurrentMedsDiscontinuedRowHtml(item = {}) {
    const rowId = item.manualId || item.id || `manual-disc-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    return `<div class="current-meds-manual-discontinued-row" data-row-id="${escapeHtml(rowId)}">
        <label>Name / strength<input name="manualDiscontinuedName" type="text" placeholder="e.g. Lisinopril 10mg" value="${escapeHtml(item.name || item.medication || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
        <label>Dose / Qty<input name="manualDiscontinuedDoseQty" type="text" placeholder="e.g. 1 tablet" value="${escapeHtml(item.doseQty || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
        <label>Used For<input name="manualDiscontinuedIndication" type="text" placeholder="e.g. blood pressure" value="${escapeHtml(item.indication || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
        <label>Prescriber<input name="manualDiscontinuedPrescriberName" type="text" list="current-discontinued-provider-options" placeholder="Choose provider or type name" value="${escapeHtml(item.prescriberName || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
        <label>Stopped by<input name="manualDiscontinuedBy" type="text" list="current-discontinued-provider-options" placeholder="Choose provider or type name" value="${escapeHtml(item.discontinuedBy || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
        <label>Stop date (optional)<input name="manualDiscontinuedDate" type="date" value="${escapeHtml(item.discontinuedDate || '')}" onchange="renderCurrentMedsBuilderPreview()"></label>
        <label>Pharmacy<input name="manualDiscontinuedPharmacyName" type="text" placeholder="Optional pharmacy" value="${escapeHtml(item.pharmacyName || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
        <label>Frequency<input name="manualDiscontinuedFrequency" type="text" placeholder="e.g. daily, PRN" value="${escapeHtml(item.frequency || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
        <label>Directions / comments<input name="manualDiscontinuedDirections" type="text" placeholder="Reason, directions, or comment" value="${escapeHtml(item.directions || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
        <button type="button" class="inventory-builder-remove" onclick="removeManualCurrentMedsDiscontinuedRow('${escapeHtml(rowId)}')">X</button>
    </div>`;
}

window.openMemberCurrentMedsBuilder = async function() {
    let seedList = currentMemberMedicationList();
    if (seedList.length === 0 && currentEditingMemberId) {
        seedList = defaultCurrentMedicationListForMember(currentEditingMemberId);
    }
    const existing = new Map(seedList.map(item => [item.medId, item]));
    const discontinuedSeedList = currentMemberDiscontinuedMedicationList();
    const existingDiscontinued = new Map(discontinuedSeedList.filter(item => item.medId).map(item => [item.medId, item]));
    const manualDiscontinuedRows = discontinuedSeedList
        .filter(item => !item.medId)
        .map(item => manualCurrentMedsDiscontinuedRowHtml(item))
        .join('');
    const member = currentEditingMemberId ? db.family.find(item => item.id === currentEditingMemberId) : null;
    const memberProviderIds = member ? new Set(memberPrescriberIds(member)) : new Set();
    const memberPharmacyIdsSet = member ? new Set(memberPharmacyIds(member)) : new Set();
    const memberProviderNameOptions = db.prescribers
        .filter(prescriber => memberProviderIds.has(prescriber.id))
        .sort((a, b) => prescriberDisplayName(a).localeCompare(prescriberDisplayName(b), undefined, { sensitivity: 'base' }))
        .map(prescriber => `<option value="${escapeHtml(prescriberDisplayName(prescriber))}"></option>`)
        .join('');
    const memberPharmacyOptions = selected => {
        const options = (db.pharmacies || [])
            .filter(pharmacy => memberPharmacyIdsSet.has(pharmacy.id))
            .sort((a, b) => pharmacyDisplayName(a).localeCompare(pharmacyDisplayName(b), undefined, { sensitivity: 'base' }))
            .map(pharmacy => `<option value="${escapeHtml(pharmacy.id)}" ${pharmacy.id === selected ? 'selected' : ''}>${escapeHtml(pharmacyDisplayName(pharmacy))}</option>`)
            .join('');
        return `<option value="">Optional</option>${options}`;
    };
    const inventoryRows = db.inventory
        .slice()
        .sort((a, b) => inventoryDisplayName(a).localeCompare(inventoryDisplayName(b), undefined, { sensitivity: 'base' }))
        .map(med => {
            const saved = existing.get(med.id) || {};
            const inputId = `current-med-${med.id}`;
            const searchText = `${med.name} ${formatMedStrength(med)} ${formatInventoryUnits(med)}`.toLowerCase();
            const savedPrescriberName = saved.prescriberName || (saved.prescriberId ? prescriberNameById(saved.prescriberId) : '');
            return `<div class="formulary-item inventory-builder-source-item current-meds-builder-row ${saved.medId ? 'selected' : ''}" data-med-id="${escapeHtml(med.id)}" data-search="${escapeHtml(searchText)}">
                <input id="${escapeHtml(inputId)}" name="currentMedIds" type="checkbox" value="${escapeHtml(med.id)}" ${saved.medId ? 'checked' : ''} onchange="currentMedsBuilderSelectionChanged(this)">
                <label class="current-meds-builder-name" for="${escapeHtml(inputId)}">
                    <span><strong>${escapeHtml(med.name)}</strong><small>${escapeHtml(formatMedStrength(med))} | ${escapeHtml(formatAmount(parseAmount(med.stock)))} ${escapeHtml(inventoryUnitFor(med))} on hand</small></span>
                </label>
                <div class="current-meds-builder-fields">
                    <label>Dose / Qty<input name="currentDoseQty" data-med-id="${escapeHtml(med.id)}" type="text" placeholder="e.g. 1 tablet, 5 mL, 2 puffs" value="${escapeHtml(saved.doseQty || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
                    <label>Used For<input name="currentIndication" data-med-id="${escapeHtml(med.id)}" type="text" placeholder="e.g. allergies, migraine" value="${escapeHtml(saved.indication || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
                    <label>Prescriber<input name="currentPrescriberName" data-med-id="${escapeHtml(med.id)}" type="text" list="current-discontinued-provider-options" placeholder="Choose provider or type name" value="${escapeHtml(savedPrescriberName)}" oninput="renderCurrentMedsBuilderPreview()"></label>
                    <label>Pharmacy<select name="currentPharmacyId" data-med-id="${escapeHtml(med.id)}" onchange="renderCurrentMedsBuilderPreview()">${memberPharmacyOptions(saved.pharmacyId || med.pharmacyId || '')}</select></label>
                    <label>Frequency<input name="currentFrequency" data-med-id="${escapeHtml(med.id)}" type="text" placeholder="e.g. daily, PRN, weekly" value="${escapeHtml(saved.frequency || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
                    <label class="current-meds-directions-field">Directions / comments<input name="currentDirections" data-med-id="${escapeHtml(med.id)}" type="text" placeholder="e.g. Take 1 tablet twice daily" value="${escapeHtml(saved.directions || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
                </div>
            </div>`;
        })
        .join('');
    const discontinuedRows = db.inventory
        .slice()
        .sort((a, b) => inventoryDisplayName(a).localeCompare(inventoryDisplayName(b), undefined, { sensitivity: 'base' }))
        .map(med => {
            const saved = existingDiscontinued.get(med.id) || {};
            const inputId = `current-disc-med-${med.id}`;
            const searchText = `${med.name} ${formatMedStrength(med)} ${formatInventoryUnits(med)}`.toLowerCase();
            const savedPrescriberName = saved.prescriberName || '';
            const savedStoppedBy = saved.discontinuedBy || '';
            return `<div class="formulary-item inventory-builder-source-item current-meds-discontinued-row ${saved.medId ? 'selected' : ''}" data-med-id="${escapeHtml(med.id)}" data-search="${escapeHtml(searchText)}">
                <input id="${escapeHtml(inputId)}" name="currentDiscontinuedMedIds" type="checkbox" value="${escapeHtml(med.id)}" ${saved.medId ? 'checked' : ''} onchange="currentMedsDiscontinuedSelectionChanged(this)">
                <label class="current-meds-builder-name" for="${escapeHtml(inputId)}">
                    <span><strong>${escapeHtml(medicationNameWithStrength(med))}</strong><small>${escapeHtml(formatAmount(parseAmount(med.stock)))} ${escapeHtml(inventoryUnitFor(med))} on hand</small></span>
                </label>
                <div class="current-meds-discontinued-fields">
                    <label>Dose / Qty<input name="currentDiscontinuedDoseQty" data-med-id="${escapeHtml(med.id)}" type="text" placeholder="e.g. 1 tablet" value="${escapeHtml(saved.doseQty || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
                    <label>Used For<input name="currentDiscontinuedIndication" data-med-id="${escapeHtml(med.id)}" type="text" placeholder="e.g. sleep, pain" value="${escapeHtml(saved.indication || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
                    <label>Prescriber<input name="currentDiscontinuedPrescriberName" data-med-id="${escapeHtml(med.id)}" type="text" list="current-discontinued-provider-options" placeholder="Choose provider or type name" value="${escapeHtml(savedPrescriberName)}" oninput="renderCurrentMedsBuilderPreview()"></label>
                    <label>Stopped by<input name="currentDiscontinuedBy" data-med-id="${escapeHtml(med.id)}" type="text" list="current-discontinued-provider-options" placeholder="Choose provider or type name" value="${escapeHtml(savedStoppedBy)}" oninput="renderCurrentMedsBuilderPreview()"></label>
                    <label>Stop date (optional)<input name="currentDiscontinuedDate" data-med-id="${escapeHtml(med.id)}" type="date" value="${escapeHtml(saved.discontinuedDate || '')}" onchange="renderCurrentMedsBuilderPreview()"></label>
                    <label>Pharmacy<select name="currentDiscontinuedPharmacyId" data-med-id="${escapeHtml(med.id)}" onchange="renderCurrentMedsBuilderPreview()">${memberPharmacyOptions(saved.pharmacyId || med.pharmacyId || '')}</select></label>
                    <label>Frequency<input name="currentDiscontinuedFrequency" data-med-id="${escapeHtml(med.id)}" type="text" placeholder="e.g. daily, PRN" value="${escapeHtml(saved.frequency || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
                    <label class="current-meds-discontinued-directions-field">Directions / comments<input name="currentDiscontinuedDirections" data-med-id="${escapeHtml(med.id)}" type="text" placeholder="Reason, directions, or comment" value="${escapeHtml(saved.directions || '')}" oninput="renderCurrentMedsBuilderPreview()"></label>
                </div>
            </div>`;
        })
        .join('');
    const modalPromise = showActionModal('Create/Edit Current Meds & Supplements List', `
        <div data-action-modal-size="wide" class="current-meds-builder inventory-builder-layout">
            <datalist id="current-discontinued-provider-options">${memberProviderNameOptions}</datalist>
            <div class="current-meds-builder-source inventory-builder-source">
                <div class="current-meds-builder-toolbar">
                    <label>Search inventory</label>
                    <input id="current-meds-builder-search" type="text" placeholder="Find medication or supplement..." oninput="filterCurrentMedsBuilder()">
                </div>
                <fieldset class="current-meds-builder-section">
                    <legend>Currently Taking</legend>
                    <div class="current-meds-builder-list">${inventoryRows || '<div class="empty-state">No inventory items available.</div>'}</div>
                </fieldset>
                <fieldset class="current-meds-builder-section stopped">
                    <legend>Discontinued / Stopped</legend>
                    <div class="current-meds-builder-list discontinued">${discontinuedRows || '<div class="empty-state">No inventory items available.</div>'}</div>
                    <div class="manual-discontinued-toolbar">
                        <button type="button" onclick="addManualCurrentMedsDiscontinuedRow()">+ Add manual stopped med</button>
                        <span>Use this for medications/supplements not stored in inventory.</span>
                    </div>
                    <div id="current-meds-manual-discontinued-list" class="current-meds-manual-discontinued-list">${manualDiscontinuedRows}</div>
                </fieldset>
            </div>
            <div class="current-meds-builder-selected">
                <div class="inventory-builder-panel-title">Selected medications</div>
                <div id="current-meds-builder-preview" class="inventory-builder-panel"></div>
            </div>
        </div>
    `, 'Save List', body => {
        const selectedIds = new Set([...body.querySelectorAll('input[name="currentMedIds"]:checked')].map(input => input.value));
        const discontinuedIds = new Set([...body.querySelectorAll('input[name="currentDiscontinuedMedIds"]:checked')].map(input => input.value));
        return {
            activeList: [...selectedIds].map(medId => ({
                medId,
                doseQty: body.querySelector(`input[name="currentDoseQty"][data-med-id="${cssEscape(medId)}"]`)?.value.trim() || '',
                indication: body.querySelector(`input[name="currentIndication"][data-med-id="${cssEscape(medId)}"]`)?.value.trim() || '',
                prescriberName: body.querySelector(`input[name="currentPrescriberName"][data-med-id="${cssEscape(medId)}"]`)?.value.trim() || '',
                pharmacyId: body.querySelector(`select[name="currentPharmacyId"][data-med-id="${cssEscape(medId)}"]`)?.value || '',
                frequency: body.querySelector(`input[name="currentFrequency"][data-med-id="${cssEscape(medId)}"]`)?.value.trim() || '',
                directions: body.querySelector(`input[name="currentDirections"][data-med-id="${cssEscape(medId)}"]`)?.value.trim() || ''
            })),
            discontinuedList: [
                ...[...discontinuedIds].map(medId => ({
                    medId,
                    doseQty: body.querySelector(`input[name="currentDiscontinuedDoseQty"][data-med-id="${cssEscape(medId)}"]`)?.value.trim() || '',
                    indication: body.querySelector(`input[name="currentDiscontinuedIndication"][data-med-id="${cssEscape(medId)}"]`)?.value.trim() || '',
                    prescriberName: body.querySelector(`input[name="currentDiscontinuedPrescriberName"][data-med-id="${cssEscape(medId)}"]`)?.value.trim() || '',
                    discontinuedBy: body.querySelector(`input[name="currentDiscontinuedBy"][data-med-id="${cssEscape(medId)}"]`)?.value.trim() || '',
                    discontinuedDate: body.querySelector(`input[name="currentDiscontinuedDate"][data-med-id="${cssEscape(medId)}"]`)?.value || '',
                    pharmacyId: body.querySelector(`select[name="currentDiscontinuedPharmacyId"][data-med-id="${cssEscape(medId)}"]`)?.value || '',
                    frequency: body.querySelector(`input[name="currentDiscontinuedFrequency"][data-med-id="${cssEscape(medId)}"]`)?.value.trim() || '',
                    directions: body.querySelector(`input[name="currentDiscontinuedDirections"][data-med-id="${cssEscape(medId)}"]`)?.value.trim() || ''
                })),
                ...[...body.querySelectorAll('.current-meds-manual-discontinued-row')]
                    .map(row => ({
                        manualId: row.dataset.rowId || `manual-disc-${Date.now()}-${Math.random().toString(16).slice(2)}`,
                        name: row.querySelector('input[name="manualDiscontinuedName"]')?.value.trim() || '',
                        doseQty: row.querySelector('input[name="manualDiscontinuedDoseQty"]')?.value.trim() || '',
                        indication: row.querySelector('input[name="manualDiscontinuedIndication"]')?.value.trim() || '',
                        prescriberName: row.querySelector('input[name="manualDiscontinuedPrescriberName"]')?.value.trim() || '',
                        discontinuedBy: row.querySelector('input[name="manualDiscontinuedBy"]')?.value.trim() || '',
                        discontinuedDate: row.querySelector('input[name="manualDiscontinuedDate"]')?.value || '',
                        pharmacyName: row.querySelector('input[name="manualDiscontinuedPharmacyName"]')?.value.trim() || '',
                        frequency: row.querySelector('input[name="manualDiscontinuedFrequency"]')?.value.trim() || '',
                        directions: row.querySelector('input[name="manualDiscontinuedDirections"]')?.value.trim() || ''
                    }))
                    .filter(item => item.name)
            ]
        };
    });
    renderCurrentMedsBuilderPreview();
    const result = await modalPromise;
    if (!result) return;
    setHiddenJson('m-current-med-list-data', result.activeList || []);
    setHiddenJson('m-current-discontinued-med-list-data', result.discontinuedList || []);
    if (member) {
        member.currentMedicationList = result.activeList || [];
        member.currentMedicationDiscontinuedList = result.discontinuedList || [];
        await sync();
    }
    renderMemberCurrentMedicationList();
};

function renderMemberLabDocuments() {
    const container = document.getElementById('member-lab-document-list');
    if (!container) return;
    const docs = currentMemberLabDocuments();
    container.innerHTML = docs.length
        ? docs.map(doc => `<div class="member-lab-document-card">
            <div>
                <strong>${escapeHtml(doc.name || 'Lab PDF')}</strong>
                <div class="form-help">${escapeHtml(doc.date || 'No date')}${doc.notes ? ` | ${escapeHtml(doc.notes)}` : ''}</div>
            </div>
            <div class="field-row">
                <button type="button" onclick="previewMemberLabPdf('${escapeHtml(doc.id)}')">Preview PDF</button>
                <button type="button" onclick="removeMemberLabPdf('${escapeHtml(doc.id)}')">Remove</button>
            </div>
        </div>`).join('')
        : '<div class="empty-state">No lab PDFs saved for this member.</div>';
}

window.addMemberLabPdf = async function(input = null) {
    const fileInput = input || document.getElementById('member-lab-pdf-input');
    const file = fileInput?.files?.[0];
    if (!file) return;
    if (file.type !== 'application/pdf' && !/\.pdf$/i.test(file.name || '')) {
        await appAlert('Select a PDF lab document.');
        if (fileInput) fileInput.value = '';
        return;
    }
    const dataUrl = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
    const doc = {
        id: `lab_${Date.now()}_${Math.random().toString(16).slice(2)}`,
        name: document.getElementById('member-lab-title')?.value.trim() || file.name || 'Lab PDF',
        fileName: file.name || '',
        date: document.getElementById('member-lab-date')?.value || localDateKey(),
        notes: document.getElementById('member-lab-notes')?.value.trim() || '',
        dataUrl,
        addedAt: new Date().toISOString()
    };
    const docs = [doc, ...currentMemberLabDocuments()];
    setHiddenJson('m-lab-documents-data', docs);
    const member = currentEditingMemberId ? db.family.find(item => item.id === currentEditingMemberId) : null;
    if (member) {
        member.labDocuments = docs;
        await sync();
    }
    if (fileInput) fileInput.value = '';
    const title = document.getElementById('member-lab-title');
    if (title) title.value = '';
    const notes = document.getElementById('member-lab-notes');
    if (notes) notes.value = '';
    renderMemberLabDocuments();
};

window.previewMemberLabPdf = async function(docId) {
    const doc = currentMemberLabDocuments().find(item => item.id === docId);
    if (!doc) return;
    await showActionModal(`Lab PDF Preview: ${doc.name || 'Document'}`, `
        <div data-action-modal-size="wide" class="lab-pdf-preview-shell">
            <div class="form-help">${escapeHtml(doc.date || 'No date')}${doc.fileName ? ` | File: ${escapeHtml(doc.fileName)}` : ''}${doc.notes ? ` | ${escapeHtml(doc.notes)}` : ''}</div>
            <iframe class="lab-pdf-preview-frame" src="${escapeHtml(doc.dataUrl)}"></iframe>
        </div>
    `, 'Close');
};

window.removeMemberLabPdf = async function(docId) {
    if (!await appConfirm('Remove this lab PDF from the member profile?', 'Remove Lab PDF')) return;
    const docs = currentMemberLabDocuments().filter(item => item.id !== docId);
    setHiddenJson('m-lab-documents-data', docs);
    const member = currentEditingMemberId ? db.family.find(item => item.id === currentEditingMemberId) : null;
    if (member) {
        member.labDocuments = docs;
        await sync();
    }
    renderMemberLabDocuments();
};

function defaultProgressNoteTime() {
    const now = new Date();
    return `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
}

function resetProgressNoteEditor() {
    const date = document.getElementById('m-progress-note-date');
    const time = document.getElementById('m-progress-note-time');
    const title = document.getElementById('m-progress-note-title');
    const tags = document.getElementById('m-progress-note-tags');
    const editId = document.getElementById('m-progress-note-edit-id');
    const editor = document.getElementById('m-progress-note-editor');
    const color = document.getElementById('m-progress-note-color');
    const saveButton = document.getElementById('m-progress-note-save-button');
    if (date) date.value = localDateKey();
    if (time) time.value = defaultProgressNoteTime();
    if (title) title.value = '';
    if (tags) tags.value = '';
    if (editId) editId.value = '';
    if (editor) editor.innerHTML = '';
    if (color) color.value = '#000000';
    if (saveButton) saveButton.innerHTML = '<span class="button-plus-sign">+</span>Add Entry';
    renderProgressNoteTemplateSelect();
    ['template', 'link-type', 'link-id'].forEach(suffix => {
        const input = document.getElementById(`m-progress-note-${suffix}`);
        if (input) input.value = '';
    });
    ['pinned', 'important', 'followup', 'provider', 'private', 'resolved'].forEach(suffix => {
        const input = document.getElementById(`m-progress-note-${suffix}`);
        if (input) input.checked = false;
    });
    ['pain', 'mood', 'sleep', 'nausea', 'energy'].forEach(suffix => {
        const input = document.getElementById(`m-progress-note-${suffix}`);
        if (input) input.value = '';
    });
    const disableRatings = document.getElementById('m-progress-note-disable-ratings');
    if (disableRatings) disableRatings.checked = false;
    toggleProgressNoteScales(false);
    const fileInput = document.getElementById('m-progress-note-attachment');
    if (fileInput) fileInput.value = '';
    pendingProgressNoteAttachments = [];
    updateProgressNoteFlagVisuals();
    renderProgressNoteLinkOptions();
    renderProgressNoteAttachmentList();
    refreshProgressNoteTagSuggestions();
}

function safeProgressNoteColor(value) {
    const color = String(value || '').trim();
    if (/^#[0-9a-f]{6}$/i.test(color)) return color.toLowerCase();
    const rgb = color.match(/^rgb\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*\)$/i);
    if (!rgb) return '';
    const parts = rgb.slice(1).map(Number);
    if (parts.some(part => !Number.isInteger(part) || part < 0 || part > 255)) return '';
    return `#${parts.map(part => part.toString(16).padStart(2, '0')).join('')}`;
}

function sanitizeProgressNoteHtml(html) {
    const template = document.createElement('template');
    template.innerHTML = String(html || '');
    const allowed = new Set(['B', 'STRONG', 'I', 'EM', 'U', 'BR', 'P', 'DIV', 'UL', 'OL', 'LI', 'SPAN', 'FONT']);
    const cleanNode = node => {
        if (node.nodeType === Node.TEXT_NODE) return document.createTextNode(node.textContent || '');
        if (node.nodeType !== Node.ELEMENT_NODE) return document.createTextNode('');
        const tag = node.tagName.toUpperCase();
        const children = Array.from(node.childNodes).map(cleanNode);
        if (!allowed.has(tag)) {
            const fragment = document.createDocumentFragment();
            children.forEach(child => fragment.appendChild(child));
            return fragment;
        }
        const clean = document.createElement(tag === 'FONT' ? 'span' : tag.toLowerCase());
        if (tag === 'SPAN' || tag === 'FONT') {
            const color = safeProgressNoteColor(node.getAttribute('color') || node.style?.color);
            if (color) clean.style.color = color;
        }
        children.forEach(child => clean.appendChild(child));
        return clean;
    };
    const output = document.createElement('div');
    Array.from(template.content.childNodes).forEach(node => output.appendChild(cleanNode(node)));
    return output.innerHTML.trim();
}

function progressNotePlainText(html) {
    const temp = document.createElement('div');
    temp.innerHTML = sanitizeProgressNoteHtml(html);
    return String(temp.textContent || '').replace(/\s+/g, ' ').trim();
}

function progressNoteDayLabel(dateStr) {
    const date = parseLocal(dateStr);
    if (!date) return 'No Date';
    return date.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
}

function normalizeProgressNoteTags(value) {
    const source = Array.isArray(value) ? value.join(',') : String(value || '');
    return Array.from(new Set(source
        .split(',')
        .map(tag => tag.trim())
        .filter(Boolean)
        .map(tag => tag.slice(0, 32))));
}

function progressNoteTagsHtml(tags = []) {
    return normalizeProgressNoteTags(tags)
        .map(tag => `<span class="profile-diary-tag">${escapeHtml(tag)}</span>`)
        .join('');
}

function progressNoteFlags(note = {}) {
    const flags = note.flags || {};
    return {
        pinned: !!flags.pinned,
        important: !!flags.important,
        followup: !!flags.followup,
        provider: !!flags.provider,
        private: !!flags.private,
        resolved: !!flags.resolved
    };
}

window.updateProgressNoteFlagVisuals = function() {
    document.querySelectorAll('.profile-diary-flag-toggle').forEach(label => {
        const input = label.querySelector('input[type="checkbox"]');
        label.classList.toggle('selected', !!input?.checked);
    });
    updateProgressNoteSidePanel();
};

window.toggleProgressNoteScales = function(forceOpen = null) {
    if (document.getElementById('m-progress-note-disable-ratings')?.checked) forceOpen = false;
    const panel = document.getElementById('m-progress-note-scales-panel');
    const button = document.querySelector('.profile-diary-scale-toggle-row button');
    if (!panel) return;
    const open = forceOpen === null ? panel.style.display === 'none' : !!forceOpen;
    panel.style.display = open ? '' : 'none';
    if (button) button.textContent = open ? 'Hide ratings' : 'Add ratings';
};

window.toggleProgressNoteRatingsDisabled = function(disabled) {
    if (disabled) {
        ['pain', 'mood', 'sleep', 'nausea', 'energy'].forEach(suffix => {
            const input = document.getElementById(`m-progress-note-${suffix}`);
            if (input) input.value = '';
        });
        toggleProgressNoteScales(false);
    }
    const button = document.querySelector('.profile-diary-scale-toggle-row button');
    if (button) button.disabled = !!disabled;
    const label = document.querySelector('.profile-diary-ratings-off-toggle');
    if (label) label.classList.toggle('selected', !!disabled);
    updateProgressNoteSidePanel();
};

function progressNoteFlagBadgesHtml(note = {}) {
    const flags = progressNoteFlags(note);
    const badges = [];
    if (flags.pinned) badges.push(['pinned', 'Pinned']);
    if (flags.important) badges.push(['important', 'Important']);
    if (flags.followup) badges.push(['followup', 'Follow-up']);
    if (flags.provider) badges.push(['provider', 'Provider']);
    if (flags.private) badges.push(['private', 'Private']);
    if (flags.resolved) badges.push(['resolved', 'Resolved']);
    return badges.map(([key, label]) => `<span class="profile-diary-badge ${key}">${escapeHtml(label)}</span>`).join('');
}

function progressNoteScaleValue(value, min, max) {
    const parsed = Number(value);
    if (!Number.isFinite(parsed)) return '';
    return Math.min(max, Math.max(min, parsed));
}

function collectProgressNoteScales() {
    if (document.getElementById('m-progress-note-disable-ratings')?.checked) return {};
    return {
        pain: progressNoteScaleValue(document.getElementById('m-progress-note-pain')?.value, 0, 10),
        mood: progressNoteScaleValue(document.getElementById('m-progress-note-mood')?.value, 1, 5),
        sleep: progressNoteScaleValue(document.getElementById('m-progress-note-sleep')?.value, 1, 5),
        nausea: progressNoteScaleValue(document.getElementById('m-progress-note-nausea')?.value, 0, 10),
        energy: progressNoteScaleValue(document.getElementById('m-progress-note-energy')?.value, 1, 5)
    };
}

function progressNoteScalesHtml(scales = {}) {
    const labels = [
        ['pain', 'Pain', '/10'],
        ['mood', 'Mood', '/5'],
        ['sleep', 'Sleep', '/5'],
        ['nausea', 'Nausea', '/10'],
        ['energy', 'Energy', '/5']
    ];
    const chips = labels
        .filter(([key]) => scales[key] !== '' && scales[key] !== undefined && scales[key] !== null)
        .map(([key, label, suffix]) => `<span class="profile-diary-scale-chip ${key}">${escapeHtml(label)}: <strong>${escapeHtml(scales[key])}${suffix}</strong></span>`);
    return chips.length ? `<div class="profile-diary-scale-chips">${chips.join('')}</div>` : '';
}

function progressNoteAttachmentIcon(attachment = {}) {
    return /pdf/i.test(attachment.type || attachment.name || '') ? 'PDF' : 'IMG';
}

function progressNoteAttachmentsHtml(note = {}) {
    const attachments = Array.isArray(note.attachments) ? note.attachments : [];
    if (!attachments.length) return '';
    return `<div class="profile-diary-attachment-preview">
        <strong>Attachments</strong>
        ${attachments.map(file => `
            <button type="button" onclick="previewProgressNoteAttachment('${escapeHtml(note.id)}', '${escapeHtml(file.id)}')">
                <span class="profile-diary-file-chip">${escapeHtml(progressNoteAttachmentIcon(file))}</span>
                ${escapeHtml(file.name || 'Attachment')}
            </button>`).join('')}
    </div>`;
}

function progressNoteLinkedContext(note = {}) {
    const link = note.link || {};
    if (!link.type || !link.id) return '';
    if (link.type === 'medication') {
        const schedule = db.schedules.find(item => item.id === link.id);
        const med = schedule ? db.inventory.find(item => item.id === schedule.medId) : null;
        return med ? `${med.name} ${formatMedStrength(med)} | ${formatFrequency(schedule)} ${getScheduleTimes(schedule).join(', ') || 'PRN'}`.trim() : 'Medication link unavailable';
    }
    if (link.type === 'administration') {
        const entry = db.history.find(item => item.id === link.id);
        return entry ? `${entry.timestamp || ''} | ${entry.medName || 'Medication'} | ${doseStatusLabel(entry.doseStatus || 'given')}` : 'Administration link unavailable';
    }
    if (link.type === 'vital') {
        const reading = db.vitals.find(item => item.id === link.id);
        return reading ? `${reading.date || ''} ${reading.time || ''} | ${reading.type || 'Monitoring'} | ${formatVitalReading(reading)}` : 'Monitoring link unavailable';
    }
    if (link.type === 'lab') {
        const doc = currentMemberLabDocuments().find(item => item.id === link.id);
        return doc ? `${doc.date || 'No date'} | ${doc.name || 'Lab PDF'}` : 'Lab link unavailable';
    }
    if (link.type === 'regimen') {
        const set = (db.orderSets || []).find(item => item.id === link.id);
        return set ? `${set.name || 'Regimen'}${set.start ? ` | ${set.start}` : ''}${set.end ? ` to ${set.end}` : ''}` : 'Regimen link unavailable';
    }
    if (link.type === 'inventory') {
        const med = db.inventory.find(item => item.id === link.id);
        return med ? `${med.name} ${formatMedStrength(med)}` : 'Inventory link unavailable';
    }
    return '';
}

function progressNoteLinkHtml(note = {}) {
    const context = progressNoteLinkedContext(note);
    return context ? `<div class="profile-diary-linked-context"><strong>Linked:</strong> ${escapeHtml(context)}</div>` : '';
}

function progressNoteSearchText(note) {
    return [
        note.title,
        note.date,
        note.time,
        progressNoteLinkedContext(note),
        progressNotePlainText(note.html),
        ...(Array.isArray(note.tags) ? note.tags : []),
        ...Object.entries(progressNoteFlags(note)).filter(([, value]) => value).map(([key]) => key),
        ...Object.entries(note.scales || {}).map(([key, value]) => `${key} ${value}`),
        ...(Array.isArray(note.attachments) ? note.attachments.map(file => file.name || '') : [])
    ].join(' ').toLowerCase();
}

function updateProgressNoteTagFilter(notes) {
    const select = document.getElementById('m-progress-note-tag-filter');
    if (!select) return;
    const selected = select.value || '';
    const tags = Array.from(new Set(notes.flatMap(note => normalizeProgressNoteTags(note.tags))))
        .sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
    select.innerHTML = '<option value="">All tags</option>' + tags
        .map(tag => `<option value="${escapeHtml(tag)}" ${tag === selected ? 'selected' : ''}>${escapeHtml(tag)}</option>`)
        .join('');
    if (selected && !tags.includes(selected)) select.value = '';
}

function progressNoteLinkOptions(type, selected = '') {
    const memberId = currentEditingMemberId;
    if (!type) return '<option value="">Choose after selecting a link type</option>';
    if (type === 'medication') {
        const schedules = db.schedules
            .filter(schedule => schedule.memberId === memberId && !isScheduleArchived(schedule))
            .sort((a, b) => {
                const medA = db.inventory.find(item => item.id === a.medId);
                const medB = db.inventory.find(item => item.id === b.medId);
                return inventoryDisplayName(medA || {}).localeCompare(inventoryDisplayName(medB || {}), undefined, { sensitivity: 'base' });
            });
        return '<option value="">Select medication</option>' + schedules.map(schedule => {
            const med = db.inventory.find(item => item.id === schedule.medId);
            const text = med ? `${med.name} ${formatMedStrength(med)} (${formatFrequency(schedule)} ${getScheduleTimes(schedule).join(', ') || 'PRN'})` : 'Medication';
            return `<option value="${escapeHtml(schedule.id)}" ${schedule.id === selected ? 'selected' : ''}>${escapeHtml(text)}</option>`;
        }).join('');
    }
    if (type === 'administration') {
        const entries = db.history
            .filter(entry => entry.memberId === memberId)
            .slice()
            .sort((a, b) => String(b.timestamp || '').localeCompare(String(a.timestamp || '')))
            .slice(0, 100);
        return '<option value="">Select administration</option>' + entries.map(entry => {
            const text = `${entry.timestamp || 'No time'} - ${entry.medName || 'Medication'} - ${doseStatusLabel(entry.doseStatus || 'given')}`;
            return `<option value="${escapeHtml(entry.id)}" ${entry.id === selected ? 'selected' : ''}>${escapeHtml(text)}</option>`;
        }).join('');
    }
    if (type === 'vital') {
        const readings = db.vitals
            .filter(reading => reading.memberId === memberId)
            .slice()
            .sort((a, b) => String(`${b.date || ''} ${b.time || ''}`).localeCompare(String(`${a.date || ''} ${a.time || ''}`)))
            .slice(0, 100);
        return '<option value="">Select monitoring reading</option>' + readings.map(reading => {
            const text = `${reading.date || ''} ${reading.time || ''} - ${vitalTypeLabel(reading.type, reading)} - ${formatVitalReading(reading)}`;
            return `<option value="${escapeHtml(reading.id)}" ${reading.id === selected ? 'selected' : ''}>${escapeHtml(text)}</option>`;
        }).join('');
    }
    if (type === 'lab') {
        return '<option value="">Select lab PDF</option>' + currentMemberLabDocuments().map(doc => {
            const text = `${doc.date || 'No date'} - ${doc.name || 'Lab PDF'}`;
            return `<option value="${escapeHtml(doc.id)}" ${doc.id === selected ? 'selected' : ''}>${escapeHtml(text)}</option>`;
        }).join('');
    }
    if (type === 'regimen') {
        const sets = (db.orderSets || [])
            .filter(set => !memberId || !set.memberId || set.memberId === memberId)
            .sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''), undefined, { sensitivity: 'base' }));
        return '<option value="">Select regimen</option>' + sets.map(set => {
            return `<option value="${escapeHtml(set.id)}" ${set.id === selected ? 'selected' : ''}>${escapeHtml(set.name || 'Regimen')}</option>`;
        }).join('');
    }
    if (type === 'inventory') {
        const items = db.inventory
            .filter(med => medicationAssignedToMember(med, memberId))
            .slice()
            .sort((a, b) => inventoryDisplayName(a).localeCompare(inventoryDisplayName(b), undefined, { sensitivity: 'base' }));
        return '<option value="">Select inventory item</option>' + items.map(med => {
            return `<option value="${escapeHtml(med.id)}" ${med.id === selected ? 'selected' : ''}>${escapeHtml(`${med.name} ${formatMedStrength(med)}`)}</option>`;
        }).join('');
    }
    return '<option value="">No items available</option>';
}

window.renderProgressNoteLinkOptions = function(selectedId = '') {
    const type = document.getElementById('m-progress-note-link-type')?.value || '';
    const select = document.getElementById('m-progress-note-link-id');
    if (!select) return;
    select.innerHTML = progressNoteLinkOptions(type, selectedId);
};

