function frequencyOptionsHtml(selected = 'QD') {
    const options = [
        ['ONCE', 'One time'],
        ['QD', 'Daily'],
        ['BID', 'Twice daily'],
        ['TID', '3 times daily'],
        ['QID', '4 times daily'],
        ['Nightly', 'Nightly'],
        ['QOD', 'Every other day'],
        ['QW', 'Once Weekly'],
        ['QXW', 'Every X Weeks'],
        ['XPW', 'X Times Per Week'],
        ['QXH', 'Every X Hours'],
        ['PRN', 'As needed'],
        ['Monthly', 'Once Monthly']
    ];
    return options.map(([value, label]) => `<option value="${value}" ${value === selected ? 'selected' : ''}>${label}</option>`).join('');
}

function prnFrequencyOptionsHtml(selected = '') {
    const options = [
        ['', 'None'],
        ['ONCE', 'One time'],
        ['QD', 'Daily'],
        ['BID', 'Twice daily'],
        ['TID', '3 times daily'],
        ['QID', '4 times daily'],
        ['Nightly', 'Nightly'],
        ['QOD', 'Every other day'],
        ['QW', 'Once Weekly'],
        ['QXW', 'Every X Weeks'],
        ['XPW', 'X Times Per Week'],
        ['QXH', 'Every X Hours'],
        ['Monthly', 'Once Monthly']
    ];
    return options.map(([value, label]) => `<option value="${value}" ${value === selected ? 'selected' : ''}>${label}</option>`).join('');
}

let weekdayPickerId = 0;

function weekdayCheckboxesHtml(className, selectedDays = []) {
    const selected = new Set((selectedDays || []).map(Number));
    const pickerId = ++weekdayPickerId;
    return ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
        .map((day, index) => {
            const inputId = `${className}-${pickerId}-${index}`;
            return `<span class="weekday-option"><input id="${inputId}" class="${className}" type="checkbox" value="${index}" ${selected.has(index) ? 'checked' : ''}><label for="${inputId}">${day}</label></span>`;
        })
        .join('');
}

function medicationOptionsHtml(selected = '') {
    return db.inventory
        .slice()
        .sort((a, b) => (a.name || '').localeCompare(b.name || '', undefined, { sensitivity: 'base' }))
        .map(med => `<option value="${med.id}" ${med.id === selected ? 'selected' : ''}>${med.name} ${formatMedStrength(med)}</option>`)
        .join('');
}

function getOrderSetRowMed(row) {
    return db.inventory.find(m => m.id === row.querySelector('.os-med-strength')?.value);
}

function updateOrderSetRowDose(row) {
    const med = getOrderSetRowMed(row);
    const doseQty = parseAmount(row.querySelector('.os-dose')?.value, NaN);
    const units = row.querySelector('.os-units');
    const calculated = row.querySelector('.os-calculated-dose');

    if (units) units.innerText = med ? (med.administrationUnit || med.formulation || 'unit(s)') : 'unit(s)';
    if (!calculated) return;
    calculated.value = med && Number.isFinite(doseQty) && doseQty > 0
        ? formatPrescribedDose(med, doseQty)
        : '';
    const title = row.querySelector('.regimen-med-row-title strong');
    const subtitle = row.querySelector('.regimen-med-row-title small');
    const badge = row.querySelector('.regimen-med-row-badge');
    if (title) title.textContent = med?.name || 'New regimen medication';
    if (subtitle) subtitle.textContent = med ? formatMedStrength(med) : 'Search inventory and choose a strength';
    if (badge) badge.textContent = med?.name ? med.name.charAt(0).toUpperCase() : '+';
}

function updateOrderSetStrengthOptions(row, selectedMedId = '') {
    const input = row.querySelector('.os-med-search');
    const strengthSelect = row.querySelector('.os-med-strength');
    if (!input || !strengthSelect) return;

    const matches = db.inventory.filter(med => med.name === input.value);
    strengthSelect.innerHTML = '';
    matches.forEach(med => {
        const opt = document.createElement('option');
        opt.value = med.id;
        opt.innerText = formatMedStrength(med);
        if (med.id === selectedMedId) opt.selected = true;
        strengthSelect.appendChild(opt);
    });
    input.style.backgroundColor = matches.length > 0 ? '#e0ffe0' : '';
    updateOrderSetRowDose(row);
    renderOrderSetMedicationPreview(row);
    renderOrderSetBuilderSummary();
}

function renderOrderSetMedicationPreview(row = null) {
    const preview = document.getElementById('order-set-med-preview');
    if (!preview) return;
    const activeRow = row || document.querySelector('#order-set-med-list .order-set-med-row.active') || document.querySelector('#order-set-med-list .order-set-med-row');
    const med = activeRow ? getOrderSetRowMed(activeRow) : null;
    if (!med) {
        preview.innerHTML = '<div class="empty-state">Select a medication.</div>';
        return;
    }
    const image = med.imagePath
        ? `<img src="${imageSrc(med.imagePath)}" alt="${escapeHtml(med.name)}">`
        : '<div class="schedule-med-no-photo">No Photo</div>';
    const doseQty = activeRow.querySelector('.os-dose')?.value || '';
    const calculatedDose = doseQty ? formatPrescribedDose(med, doseQty) : '';
    preview.innerHTML = `
        <div class="schedule-med-photo">${image}</div>
        <div class="schedule-med-details">
            <div><b>${escapeHtml(med.name)}</b></div>
            <div>${escapeHtml(formatMedStrength(med))}</div>
            <div>On hand: ${escapeHtml(formatAmount(parseAmount(med.stock)))} ${escapeHtml(inventoryUnitFor(med))}</div>
            ${calculatedDose ? `<div>Dose preview: <b>${escapeHtml(calculatedDose)}</b></div>` : ''}
            <div>Expires: ${escapeHtml(med.expiry || 'N/A')}</div>
            ${med.notes ? `<div>${escapeHtml(med.notes)}</div>` : ''}
        </div>`;
}

function setActiveOrderSetRow(row) {
    document.querySelectorAll('#order-set-med-list .order-set-med-row.active').forEach(item => item.classList.remove('active'));
    if (row) row.classList.add('active');
    renderOrderSetMedicationPreview(row);
}

function renderOrderSetBuilderSummary() {
    const container = document.getElementById('order-set-builder-summary');
    if (!container) return;
    const rows = Array.from(document.querySelectorAll('#order-set-med-list .order-set-med-row'));
    if (rows.length === 0) {
        container.innerHTML = 'No medications added yet.';
        renderOrderSetPdfPreview();
        return;
    }
    container.innerHTML = rows.map((row, index) => {
        const med = getOrderSetRowMed(row);
        const dose = row.querySelector('.os-calculated-dose')?.value || '';
        const qty = row.querySelector('.os-dose')?.value || '';
        const freq = row.querySelector('.os-freq')?.value || '';
        const prnFreq = row.querySelector('.os-prn-schedule-freq')?.value || '';
        const effectiveFreq = freq === 'PRN' && prnFreq ? `PRN + ${prnFreq}` : freq;
        const times = Array.from(row.querySelectorAll('.os-time-input')).map(input => input.value).filter(Boolean).join(', ');
        return `<div class="regimen-summary-line">
            <span class="regimen-summary-index">${index + 1}</span>
            <span><strong>${escapeHtml(med ? med.name : 'Select medication')}</strong><br>
            <small>${escapeHtml([dose || (qty ? `Qty ${qty}` : ''), effectiveFreq, times].filter(Boolean).join(' | ') || 'Incomplete')}</small></span>
        </div>`;
    }).join('');
    renderOrderSetPdfPreview();
}

function orderSetBuilderTitle() {
    const name = document.getElementById('order-set-name')?.value.trim() || 'Untitled regimen';
    const memberSelect = document.getElementById('order-set-member');
    const memberId = memberSelect?.value || '';
    const memberText = memberSelect?.selectedOptions?.[0]?.textContent || 'Reusable template';
    const startDate = document.getElementById('order-set-start')?.value || localDateKey();
    const endDate = document.getElementById('order-set-end')?.value || 'Ongoing';
    return { name, memberId, memberText, startDate, endDate };
}

function normalizeRegimenCycleStartDay(value) {
    const parsed = parseInt(value, 10);
    return Number.isInteger(parsed) && parsed > 0 ? parsed : 1;
}

function normalizeRegimenCycleDuration(value) {
    const parsed = parseInt(value, 10);
    return Number.isInteger(parsed) && parsed > 0 ? parsed : null;
}

function regimenDayNumberForDate(regimenStart, date) {
    if (!regimenStart || !date) return null;
    const start = parseLocal(regimenStart);
    const target = parseLocal(date);
    if (!start || !target) return null;
    start.setHours(0, 0, 0, 0);
    target.setHours(0, 0, 0, 0);
    return Math.round((target - start) / 86400000) + 1;
}

function regimenDurationDaysBetween(startDate, endDate) {
    if (!startDate || !endDate) return null;
    const start = parseLocal(startDate);
    const end = parseLocal(endDate);
    if (!start || !end) return null;
    start.setHours(0, 0, 0, 0);
    end.setHours(0, 0, 0, 0);
    const days = Math.round((end - start) / 86400000) + 1;
    return days > 0 ? days : null;
}

function regimenCycleMode(item = {}) {
    const safeItem = item || {};
    return safeItem.cycleMode === 'dates' || safeItem.cycleStartDate || safeItem.cycleEndDate ? 'dates' : 'days';
}

function orderSetItemDateWindow(item, regimenStart, regimenEnd) {
    const mode = regimenCycleMode(item);
    let startDay = normalizeRegimenCycleStartDay(item?.cycleStartDay || 1);
    let duration = normalizeRegimenCycleDuration(item?.cycleDurationDays);
    let startDate = regimenStart || localDateKey();
    let endDate = regimenEnd || 'Ongoing';
    if (mode === 'dates' && item?.cycleStartDate) {
        startDate = item.cycleStartDate;
        endDate = item.cycleEndDate || item.cycleStartDate;
        startDay = regimenDayNumberForDate(regimenStart, startDate) || startDay;
        duration = regimenDurationDaysBetween(startDate, endDate);
    } else {
        if (regimenStart && startDay > 1) startDate = addDaysKey(regimenStart, startDay - 1);
        if (duration) endDate = addDaysKey(startDate, duration - 1);
    }
    if (regimenEnd && regimenEnd !== 'Ongoing' && endDate !== 'Ongoing' && endDate > regimenEnd) endDate = regimenEnd;
    return {
        startDate,
        endDate,
        cycleMode: mode,
        cycleStartDay: startDay,
        cycleDurationDays: duration,
        cycleStartDate: mode === 'dates' ? startDate : '',
        cycleEndDate: mode === 'dates' ? endDate : ''
    };
}

function regimenCycleText(item, regimenStart = '', regimenEnd = '') {
    const window = orderSetItemDateWindow(item, regimenStart || localDateKey(), regimenEnd || 'Ongoing');
    const startDay = window.cycleStartDay || 1;
    const duration = window.cycleDurationDays;
    if (startDay === 1 && !duration) return 'Entire regimen';
    const endDay = duration ? startDay + duration - 1 : null;
    const dayText = endDay ? `Regimen days ${startDay}-${endDay}` : `From regimen day ${startDay}`;
    const dateText = window.startDate ? ` (${window.startDate} - ${window.endDate || 'Ongoing'})` : '';
    return `${dayText}${dateText}`;
}

function orderSetRowPreviewItem(row, index) {
    const med = getOrderSetRowMed(row);
    const freq = row.querySelector('.os-freq')?.value || '';
    const prnScheduleFreq = row.querySelector('.os-prn-schedule-freq')?.value || '';
    const timingFreq = freq === 'PRN' ? prnScheduleFreq : freq;
    const doseQty = row.querySelector('.os-dose')?.value || '';
    const intervalHours = parseInt(row.querySelector('.os-interval-hours')?.value, 10);
    const intervalWeeks = parseInt(row.querySelector('.os-interval-weeks')?.value, 10);
    const timesPerWeek = parseInt(row.querySelector('.os-times-per-week')?.value, 10);
    const weekdays = Array.from(row.querySelectorAll('.os-weekday-input:checked')).map(input => input.value);
    const rawTimes = Array.from(row.querySelectorAll('.os-time-input')).map(input => input.value).filter(Boolean);
    const header = orderSetBuilderTitle();
    const cycleStartDay = normalizeRegimenCycleStartDay(row.querySelector('.os-cycle-start')?.value || 1);
    const cycleDurationDays = normalizeRegimenCycleDuration(row.querySelector('.os-cycle-duration')?.value || '');
    const cycleMode = row.querySelector('.os-cycle-mode')?.value || 'days';
    const proxy = {
        freq,
        prnScheduleFreq,
        times: timingFreq === 'QXH' && rawTimes[0] && intervalHours ? generateIntervalTimes(rawTimes[0], intervalHours) : rawTimes,
        intervalHours,
        intervalWeeks,
        timesPerWeek,
        weekdays,
        qodStart: row.querySelector('.os-qod-start')?.value || '',
        monthlyAnchor: row.querySelector('.os-anchor-date')?.value || '',
        anchorDate: row.querySelector('.os-anchor-date')?.value || '',
        cycleMode,
        cycleStartDay,
        cycleDurationDays,
        cycleStartDate: cycleMode === 'dates' ? (row.querySelector('.os-cycle-start-date')?.value || '') : '',
        cycleEndDate: cycleMode === 'dates' ? (row.querySelector('.os-cycle-end-date')?.value || '') : ''
    };
    const linkMode = row.querySelector('.os-link-mode')?.value || '';
    const linkTargets = selectedOptionValues(row.querySelector('.os-link-target'))
        .map(rowId => document.querySelector(`#order-set-med-list .order-set-med-row[data-row-id="${cssEscape(rowId)}"]`))
        .filter(Boolean)
        .map(targetRow => getOrderSetRowMed(targetRow)?.name || 'Linked medication');
    return {
        index,
        name: med?.name || row.querySelector('.os-med-search')?.value.trim() || 'Choose medication',
        strength: med ? formatMedStrength(med) : '',
        dose: med && doseQty ? formatPrescribedDose(med, doseQty) : (doseQty ? `Qty ${doseQty}` : 'Dose not entered'),
        quantity: med && doseQty ? formatQtyForSchedule({ doseQty }, med) : '',
        schedule: `${formatFrequency(proxy)} ${getScheduleTimes(proxy).join(', ') || (freq === 'PRN' ? 'as needed' : '')}`.trim() || 'Schedule not entered',
        cycle: regimenCycleText(proxy, header.startDate, header.endDate),
        indication: row.querySelector('.os-indication')?.value.trim() || '',
        instructions: row.querySelector('.os-instructions')?.value.trim() || '',
        linkText: linkMode && linkTargets.length
            ? `${linkMode === 'together' ? 'Take together with' : 'Choose only one from'}: ${linkTargets.join(', ')}`
            : ''
    };
}

function orderSetBuilderPreviewItems() {
    return Array.from(document.querySelectorAll('#order-set-med-list .order-set-med-row'))
        .map((row, index) => orderSetRowPreviewItem(row, index + 1));
}

const regimenReportColumns = [
    { id: 'medication', label: 'Medication' },
    { id: 'dose', label: 'Dose / Qty' },
    { id: 'schedule', label: 'Frequency / Times' },
    { id: 'cycle', label: 'Regimen Days' },
    { id: 'usedFor', label: 'Used For' },
    { id: 'instructions', label: 'Instructions' }
];

const defaultRegimenReportColumnIds = regimenReportColumns.map(column => column.id);

function regimenReportSelectedColumns(options = {}) {
    const selectedIds = Array.isArray(options.columnIds) && options.columnIds.length
        ? new Set(options.columnIds)
        : new Set(defaultRegimenReportColumnIds);
    const columns = regimenReportColumns.filter(column => selectedIds.has(column.id));
    return columns.length ? columns : regimenReportColumns;
}

function regimenReportSelectedItems(items, options = {}) {
    const selectedIndexes = Array.isArray(options.itemIndexes) && options.itemIndexes.length
        ? new Set(options.itemIndexes.map(index => String(index)))
        : null;
    if (!selectedIndexes) return items;
    return items.filter(item => selectedIndexes.has(String(item.index)));
}

function regimenItemReportRows(items, columns) {
    return items.map(item => `
        <tr>
            ${columns.map(column => {
                if (column.id === 'medication') return `<td><strong>${escapeHtml(item.name)}</strong>${item.strength ? `<br><small>${escapeHtml(item.strength)}</small>` : ''}</td>`;
                if (column.id === 'dose') return `<td>${escapeHtml(item.dose)}${item.quantity ? `<br><small>${escapeHtml(item.quantity)}</small>` : ''}</td>`;
                if (column.id === 'schedule') return `<td><strong>${escapeHtml(item.schedule)}</strong>${item.linkText ? `<br><small>${escapeHtml(item.linkText)}</small>` : ''}</td>`;
                if (column.id === 'cycle') return `<td>${escapeHtml(item.cycle || 'Entire regimen')}</td>`;
                if (column.id === 'usedFor') return `<td>${escapeHtml(item.indication || 'Not specified')}</td>`;
                if (column.id === 'instructions') return `<td>${escapeHtml(item.instructions || '')}</td>`;
                return '<td></td>';
            }).join('')}
        </tr>`).join('');
}

function regimenReminderReportHtml(types, note = '', memberId = '') {
    if ((!types || types.length === 0) && !note) return '';
    const chips = (types || []).map(type => {
        const parameter = monitoringParameterTypeById(type, memberId);
        return `<span style="display:inline-block; margin:2px 4px 2px 0; padding:3px 6px; border:1px solid #008000; background:${escapeHtml(parameter.color || '#e8ffe8')}; color:#004000; font-weight:bold;">${escapeHtml(careReminderTypeLabel(type, memberId))}</span>`;
    }).join('');
    return `<div style="margin:8px 0; padding:8px; border:1px solid #8a8a8a; background:#f3fff3;">
        <strong>Monitoring parameters:</strong> ${chips || 'None selected'}
        ${note ? `<div><small>${escapeHtml(note)}</small></div>` : ''}
    </div>`;
}

function regimenReportBody(title, memberText, startDate, endDate, items, reminderTypes = [], reminderNote = '', memberId = '', options = {}) {
    const selectedItems = regimenReportSelectedItems(items, options);
    const columns = regimenReportSelectedColumns(options);
    const rows = regimenItemReportRows(selectedItems, columns);
    return `
        <div class="regimen-report">
            <div style="padding:10px; border:2px solid #004a99; background:#e6f2ff;">
                <h2 style="margin:0 0 4px; color:#000080;">${escapeHtml(title)}</h2>
                <div><strong>For:</strong> ${escapeHtml(memberText || 'Reusable template')} &nbsp; <strong>Dates:</strong> ${escapeHtml(startDate || 'Not set')} - ${escapeHtml(endDate || 'Ongoing')}</div>
            </div>
            ${regimenReminderReportHtml(reminderTypes, reminderNote, memberId)}
            <h2>Regimen Medications</h2>
            <table>
                <thead><tr>${columns.map(column => `<th>${escapeHtml(column.label)}</th>`).join('')}</tr></thead>
                <tbody>${rows || `<tr><td colspan="${columns.length}">No medications added to this regimen.</td></tr>`}</tbody>
            </table>
        </div>`;
}

function regimenReportBodyFromBuilder(options = {}) {
    const header = orderSetBuilderTitle();
    return regimenReportBody(
        header.name,
        header.memberText,
        header.startDate,
        header.endDate,
        orderSetBuilderPreviewItems(),
        selectedMonitoringReminderTypes('order-set'),
        document.getElementById('order-set-reminder-note')?.value.trim() || '',
        header.memberId,
        options
    );
}

window.renderOrderSetPdfPreview = function() {
    const preview = document.getElementById('order-set-pdf-preview');
    if (!preview) return;
    preview.innerHTML = regimenReportBodyFromBuilder();
};

function regimenPreviewFilenamePrefix(name) {
    return `Regimen_${String(name || 'Untitled').replace(/[^a-z0-9]+/gi, '_').replace(/^_+|_+$/g, '') || 'Untitled'}`;
}

let regimenReportPreviewContext = null;

function regimenReportOptionsFromModalBody(body) {
    const itemIndexes = [...body.querySelectorAll('input[name="regimenReportItemIndexes"]:checked')].map(input => input.value);
    const columnIds = [...body.querySelectorAll('input[name="regimenReportColumnIds"]:checked')].map(input => input.value);
    return { itemIndexes, columnIds };
}

window.refreshRegimenReportOptionsPreview = function() {
    const source = regimenReportPreviewContext;
    const body = document.getElementById('action-modal-body');
    const preview = document.getElementById('regimen-report-options-preview');
    if (!source || !body || !preview) return;
    const options = regimenReportOptionsFromModalBody(body);
    preview.innerHTML = regimenReportBody(source.title, source.memberText, source.startDate, source.endDate, source.items, source.reminderTypes, source.reminderNote, source.memberId, options);
};

function regimenReportSourceFromBuilder() {
    const header = orderSetBuilderTitle();
    return {
        title: header.name,
        memberText: header.memberText,
        startDate: header.startDate,
        endDate: header.endDate,
        items: orderSetBuilderPreviewItems(),
        reminderTypes: selectedMonitoringReminderTypes('order-set'),
        reminderNote: document.getElementById('order-set-reminder-note')?.value.trim() || '',
        memberId: header.memberId,
        filePrefix: regimenPreviewFilenamePrefix(header.name)
    };
}

async function chooseRegimenReportOutputOptions(source, mode) {
    regimenReportPreviewContext = source;
    const itemOptions = source.items.map(item => `
        <label class="summary-option-row">
            <input type="checkbox" name="regimenReportItemIndexes" value="${escapeHtml(item.index)}" checked onchange="refreshRegimenReportOptionsPreview()">
            <span><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml([item.dose, item.schedule, item.cycle].filter(Boolean).join(' | '))}</small></span>
        </label>`).join('');
    const columnOptions = regimenReportColumns.map(column => `
        <label class="summary-column-chip">
            <input type="checkbox" name="regimenReportColumnIds" value="${escapeHtml(column.id)}" checked onchange="refreshRegimenReportOptionsPreview()">
            <span>${escapeHtml(column.label)}</span>
        </label>`).join('');
    const result = await showActionModal(`${mode === 'pdf' ? 'PDF' : mode === 'email' ? 'Email' : 'Print'} Regimen Preview`, `
        <div data-action-modal-size="wide" class="medication-summary-output-modal regimen-output-modal">
            <div class="summary-output-layout">
                <div class="summary-output-options">
                    <fieldset>
                        <legend>Regimen Medications</legend>
                        <div class="summary-select-actions">
                            <button type="button" onclick="setMedicationSummaryChecks('regimenReportItemIndexes', true); refreshRegimenReportOptionsPreview()">Select All</button>
                            <button type="button" onclick="setMedicationSummaryChecks('regimenReportItemIndexes', false); refreshRegimenReportOptionsPreview()">Clear</button>
                        </div>
                        <div class="summary-option-list">${itemOptions || '<div class="empty-state">No regimen medications added.</div>'}</div>
                    </fieldset>
                    <fieldset>
                        <legend>Columns</legend>
                        <div class="summary-column-list">${columnOptions}</div>
                    </fieldset>
                </div>
                <fieldset class="summary-preview-fieldset">
                    <legend>Built-in Preview</legend>
                    <div id="regimen-report-options-preview" class="summary-report-preview regimen-report-options-preview">
                        ${regimenReportBody(source.title, source.memberText, source.startDate, source.endDate, source.items, source.reminderTypes, source.reminderNote, source.memberId, { itemIndexes: source.items.map(item => item.index), columnIds: defaultRegimenReportColumnIds })}
                    </div>
                </fieldset>
            </div>
        </div>
    `, mode === 'pdf' ? 'Generate PDF' : mode === 'email' ? 'Continue' : 'Print', regimenReportOptionsFromModalBody);
    regimenReportPreviewContext = null;
    if (!result) return null;
    if (!result.itemIndexes.length) {
        await appAlert('Select at least one regimen medication to include.');
        return chooseRegimenReportOutputOptions(source, mode);
    }
    if (!result.columnIds.length) {
        await appAlert('Select at least one column to include.');
        return chooseRegimenReportOutputOptions(source, mode);
    }
    return result;
}

window.generateRegimenPreviewPdf = async function() {
    const source = regimenReportSourceFromBuilder();
    const options = await chooseRegimenReportOutputOptions(source, 'pdf');
    if (!options) return;
    await saveReportPdf(
        `Regimen - ${source.title}`,
        regimenReportBody(source.title, source.memberText, source.startDate, source.endDate, source.items, source.reminderTypes, source.reminderNote, source.memberId, options),
        source.filePrefix,
        { preview: false }
    );
};

window.printRegimenPreview = async function() {
    const source = regimenReportSourceFromBuilder();
    const options = await chooseRegimenReportOutputOptions(source, 'print');
    if (!options) return;
    printReportFromPreview(`Regimen - ${source.title}`, regimenReportBody(source.title, source.memberText, source.startDate, source.endDate, source.items, source.reminderTypes, source.reminderNote, source.memberId, options));
};

window.emailRegimenPreview = async function() {
    const source = regimenReportSourceFromBuilder();
    const options = await chooseRegimenReportOutputOptions(source, 'email');
    if (!options) return;
    const result = await showActionModal('Email Regimen PDF', `
        <div class="field-row-stacked">
            <label>Email address:</label>
            <input name="email" type="email" style="width:100%;" placeholder="recipient@example.com">
        </div>
        <div class="field-row-stacked" style="margin-top:8px;">
            <label>Message:</label>
            <textarea name="message" rows="4" style="width:100%; resize:none;">Attached is the ${escapeHtml(source.title)} regimen.</textarea>
        </div>
    `, 'Send Email');
    if (!result) return;
    const email = String(result.email || '').trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        await appAlert('Enter a valid email address before sending the regimen.');
        return;
    }
    await emailReportPdf(
        `Regimen - ${source.title}`,
        regimenReportBody(source.title, source.memberText, source.startDate, source.endDate, source.items, source.reminderTypes, source.reminderNote, source.memberId, options),
        source.filePrefix,
        email,
        result.message
    );
};

window.addOrderSetMedicationRow = function(item = null) {
    const container = document.getElementById('order-set-med-list');
    if (!container) return;
    const selectedMed = item?.medId ? db.inventory.find(med => med.id === item.medId) : null;
    const row = document.createElement('div');
    row.className = 'sunken-panel order-set-med-row';
    row.dataset.rowId = item?.rowId || `osrow_${++orderSetRowCounter}`;
    row.dataset.linkTargetRowId = item?.linkTargetRowId || '';
    row.dataset.linkTargetRowIds = uniqueValues(item?.linkTargetRowIds?.length ? item.linkTargetRowIds : (item?.linkTargetRowId ? [item.linkTargetRowId] : [])).join(',');
    row.innerHTML = `
        <div class="regimen-med-row-title">
            <span class="regimen-med-row-badge">${escapeHtml(selectedMed?.name ? selectedMed.name.charAt(0).toUpperCase() : '+')}</span>
            <div>
                <strong>${escapeHtml(selectedMed?.name || 'New regimen medication')}</strong>
                <small>${escapeHtml(selectedMed ? formatMedStrength(selectedMed) : 'Search inventory and choose a strength')}</small>
            </div>
            <button type="button" class="os-remove">Remove</button>
        </div>
        <div class="regimen-med-grid">
            <div class="regimen-med-section">
                <div class="regimen-section-title">Medication</div>
                <label>Med:<input class="os-med-search" list="med-options" placeholder="Search..." value="${escapeHtml(selectedMed?.name || '')}"></label>
                <label>Strength:<select class="os-med-strength"></select></label>
            </div>
            <div class="regimen-med-section">
                <div class="regimen-section-title">Dose</div>
                <label>Dose Qty:<input class="os-dose" type="number" step="0.1" value="${item?.doseQty || ''}"></label>
                <span class="os-units"></span>
                <label>Calculated Dose:<input class="os-calculated-dose" type="text" disabled></label>
            </div>
            <div class="regimen-med-section">
                <div class="regimen-section-title">Schedule</div>
                <label>Frequency:<select class="os-freq">${frequencyOptionsHtml(item?.freq || 'QD')}</select></label>
                <div class="field-row os-qod"><label>QOD Start:</label><input class="os-qod-start" type="date" value="${item?.qodStart || ''}"></div>
                <div class="field-row os-anchor"><label>First dose date:</label><input class="os-anchor-date" type="date" value="${item?.anchorDate || ''}"></div>
                <div class="field-row os-interval"><label>Every:</label><input class="os-interval-hours" type="number" min="1" max="24" step="1" value="${item?.intervalHours || 8}"><span>hrs</span></div>
                <div class="field-row os-week-interval"><label>Every:</label><input class="os-interval-weeks" type="number" min="1" max="52" step="1" value="${item?.intervalWeeks || 2}"><span>weeks</span></div>
                <div class="field-row os-weekly-count"><label>Times per week:</label><input class="os-times-per-week" type="number" min="1" max="7" step="1" value="${item?.timesPerWeek || Math.max(item?.weekdays?.length || 0, 1)}"></div>
                <div class="weekday-picker os-weekdays"><span>Days:</span>${weekdayCheckboxesHtml('os-weekday-input', item?.weekdays || [])}</div>
                <div class="field-row os-prn-limit"><label>PRN Max:</label><input class="os-prn-max-doses" type="number" min="1" step="1" value="${item?.prnMaxDoses || ''}"><span>doses per</span><input class="os-prn-window-hours" type="number" min="1" max="168" step="1" value="${item?.prnWindowHours || 24}"><span>hrs</span><label>Frequency:</label><select class="os-prn-schedule-freq">${prnFrequencyOptionsHtml(item?.prnScheduleFreq || '')}</select></div>
                <div class="field-row-stacked"><label>Administration Time(s)</label><div class="os-time-fields"></div></div>
            </div>
        </div>
        <div class="regimen-cycle-row">
            <div>
                <strong>Regimen therapy days</strong>
                <small>Use when this medication only runs during part of the regimen, such as days 1-5 of a cycle.</small>
            </div>
            <label>Set by
                <select class="os-cycle-mode">
                    <option value="days" ${regimenCycleMode(item) !== 'dates' ? 'selected' : ''}>Start day + duration</option>
                    <option value="dates" ${regimenCycleMode(item) === 'dates' ? 'selected' : ''}>Specific dates</option>
                </select>
            </label>
            <div class="os-cycle-days-fields">
                <label>Start day<input class="os-cycle-start" type="number" min="1" step="1" value="${escapeHtml(item?.cycleStartDay || 1)}"></label>
                <label>For<input class="os-cycle-duration" type="number" min="1" step="1" placeholder="all" value="${escapeHtml(item?.cycleDurationDays || '')}"></label>
                <span>day(s)</span>
            </div>
            <div class="os-cycle-date-fields">
                <label>Start date<input class="os-cycle-start-date" type="date" value="${escapeHtml(item?.cycleStartDate || '')}"></label>
                <label>End date<input class="os-cycle-end-date" type="date" value="${escapeHtml(item?.cycleEndDate || '')}"></label>
            </div>
        </div>
        <div class="field-row os-link-row">
            <label>Link to:</label><div class="os-link-target link-choice-panel"></div>
            <label>Meaning:</label>
            <select class="os-link-mode">
                <option value="" ${!item?.linkMode ? 'selected' : ''}>None</option>
                <option value="together" ${item?.linkMode === 'together' ? 'selected' : ''}>Must take together</option>
                <option value="choose-one" ${item?.linkMode === 'choose-one' ? 'selected' : ''}>Choose only one</option>
            </select>
        </div>
        <div class="regimen-notes-grid">
            <label>Used for / Indication<input class="os-indication" type="text" value="${escapeHtml(item?.indication || '')}" placeholder="Reason this medication/supplement is used"></label>
            <label>Instructions<textarea class="os-instructions" rows="2">${escapeHtml(item?.instructions || '')}</textarea></label>
        </div>
    `;
    row.addEventListener('click', event => {
        if (!event.target.closest('button')) setActiveOrderSetRow(row);
    });
    row.querySelector('.os-freq').addEventListener('change', () => { renderOrderSetRowControls(row); renderOrderSetBuilderSummary(); });
    row.querySelector('.os-prn-schedule-freq').addEventListener('change', () => { renderOrderSetRowControls(row); renderOrderSetBuilderSummary(); });
    row.querySelector('.os-med-search').addEventListener('input', () => { updateOrderSetStrengthOptions(row); renderOrderSetLinkOptions(); });
    row.querySelector('.os-med-strength').addEventListener('change', () => { updateOrderSetRowDose(row); renderOrderSetLinkOptions(); renderOrderSetMedicationPreview(row); renderOrderSetBuilderSummary(); });
    row.querySelector('.os-dose').addEventListener('input', () => { updateOrderSetRowDose(row); renderOrderSetMedicationPreview(row); renderOrderSetBuilderSummary(); });
    row.querySelector('.os-remove').addEventListener('click', () => { row.remove(); renderOrderSetLinkOptions(); renderOrderSetBuilderSummary(); renderOrderSetMedicationPreview(); });
    row.querySelectorAll('.os-indication, .os-instructions, .os-time-input').forEach(input => input.addEventListener('input', renderOrderSetBuilderSummary));
    row.querySelectorAll('.os-link-mode, .os-interval-hours, .os-interval-weeks, .os-times-per-week, .os-prn-max-doses, .os-prn-window-hours, .os-qod-start, .os-anchor-date, .os-cycle-mode, .os-cycle-start, .os-cycle-duration, .os-cycle-start-date, .os-cycle-end-date').forEach(input => {
        const handleChange = () => {
            renderOrderSetCycleControls(row);
            renderOrderSetIntervalPreview(row);
            renderOrderSetBuilderSummary();
        };
        input.addEventListener('input', handleChange);
        input.addEventListener('change', handleChange);
    });
    row.querySelectorAll('.os-weekday-input').forEach(input => input.addEventListener('change', renderOrderSetBuilderSummary));
    container.appendChild(row);
    updateOrderSetStrengthOptions(row, item?.medId || '');
    renderOrderSetRowControls(row, scheduleTimingFrequency(item) === 'QXH' ? [item?.startTime || item?.times?.[0]] : item?.times);
    renderOrderSetCycleControls(row);
    renderOrderSetLinkOptions();
    setActiveOrderSetRow(row);
    renderOrderSetBuilderSummary();
};

function orderSetRowLabel(row) {
    const med = getOrderSetRowMed(row);
    const dose = row.querySelector('.os-dose')?.value || '';
    const freq = row.querySelector('.os-freq')?.value || '';
    const intervalHours = parseInt(row.querySelector('.os-interval-hours')?.value, 10);
    const freqLabel = freq === 'QXH' && Number.isInteger(intervalHours) ? `Q${intervalHours}H` : freq;
    return med ? `${med.name} ${formatMedStrength(med)}${dose ? ` - Qty ${dose}` : ''}${freqLabel ? ` (${freqLabel})` : ''}` : 'Select medication first';
}

function renderOrderSetLinkOptions() {
    const rows = Array.from(document.querySelectorAll('#order-set-med-list .order-set-med-row'));
    rows.forEach(row => {
        const panel = row.querySelector('.os-link-target');
        if (!panel) return;
        const selected = uniqueValues((row.dataset.linkTargetRowIds || row.dataset.linkTargetRowId || '').split(','));
        const choices = rows
            .filter(candidate => candidate !== row)
            .map(candidate => ({ id: candidate.dataset.rowId, label: orderSetRowLabel(candidate) }));
        renderLinkChoicePanel(panel, choices, selected, `openOrderSetLinkPicker('${row.dataset.rowId}')`);
    });
}

window.openOrderSetLinkPicker = async function(rowId) {
    const row = Array.from(document.querySelectorAll('#order-set-med-list .order-set-med-row'))
        .find(candidate => candidate.dataset.rowId === rowId);
    if (!row) return;
    const rows = Array.from(document.querySelectorAll('#order-set-med-list .order-set-med-row'));
    const choices = rows
        .filter(candidate => candidate !== row)
        .map(candidate => ({ id: candidate.dataset.rowId, label: orderSetRowLabel(candidate) }));
    const selected = await chooseLinkedMedications('Choose Linked Regimen Medications', choices, selectedOptionValues(row.querySelector('.os-link-target')));
    if (selected === null) return;
    row.dataset.linkTargetRowIds = selected.join(',');
    row.dataset.linkTargetRowId = selected[0] || '';
    renderOrderSetLinkOptions();
    renderOrderSetBuilderSummary();
};

function renderOrderSetCycleControls(row) {
    if (!row) return;
    const mode = row.querySelector('.os-cycle-mode')?.value || 'days';
    const daysFields = row.querySelector('.os-cycle-days-fields');
    const dateFields = row.querySelector('.os-cycle-date-fields');
    if (daysFields) daysFields.style.display = mode === 'dates' ? 'none' : 'grid';
    if (dateFields) dateFields.style.display = mode === 'dates' ? 'grid' : 'none';
    if (mode === 'dates') {
        const regimenStart = document.getElementById('order-set-start')?.value || localDateKey();
        const start = row.querySelector('.os-cycle-start-date');
        const end = row.querySelector('.os-cycle-end-date');
        if (start && !start.value) start.value = regimenStart;
        if (end && !end.value) end.value = start?.value || regimenStart;
    }
}

function renderOrderSetRowControls(row, existingTimes = null) {
    const rawFreq = row.querySelector('.os-freq').value;
    const prnScheduleFreq = rawFreq === 'PRN' ? (row.querySelector('.os-prn-schedule-freq')?.value || '') : '';
    const freq = rawFreq === 'PRN' ? prnScheduleFreq : rawFreq;
    row.querySelector('.os-qod').style.display = freq === 'QOD' ? 'flex' : 'none';
    row.querySelector('.os-anchor').style.display = ['QW', 'Monthly'].includes(freq) ? 'flex' : 'none';
    const anchorInput = row.querySelector('.os-anchor-date');
    if (['QW', 'Monthly'].includes(freq) && anchorInput && !anchorInput.value) {
        anchorInput.value = document.getElementById('order-set-start')?.value || localDateKey();
    }
    row.querySelector('.os-interval').style.display = freq === 'QXH' ? 'flex' : 'none';
    row.querySelector('.os-week-interval').style.display = freq === 'QXW' ? 'flex' : 'none';
    row.querySelector('.os-weekly-count').style.display = freq === 'XPW' ? 'flex' : 'none';
    row.querySelector('.os-weekdays').style.display = ['QXW', 'XPW'].includes(freq) ? 'flex' : 'none';
    row.querySelector('.os-prn-limit').style.display = rawFreq === 'PRN' ? 'flex' : 'none';
    if (['QXW', 'XPW'].includes(freq) && !row.querySelector('.os-weekday-input:checked')) {
        const startDate = document.getElementById('order-set-start')?.value || localDateKey();
        const weekday = parseLocal(startDate)?.getDay() ?? new Date().getDay();
        const checkbox = row.querySelector(`.os-weekday-input[value="${weekday}"]`);
        if (checkbox) checkbox.checked = true;
    }
    const timeContainer = row.querySelector('.os-time-fields');
    timeContainer.innerHTML = '';
    if (rawFreq === 'PRN' && !freq) {
        timeContainer.innerHTML = '<span style="font-size:11px;">No scheduled PRN frequency selected.</span>';
        return;
    }

    const times = Array.isArray(existingTimes) ? existingTimes : [];
    const count = freq === 'QXH' ? 1 : getExpectedTimeCount(freq);
    for (let i = 0; i < count; i++) {
        const timeRow = document.createElement('div');
        timeRow.className = 'field-row';
        timeRow.style.marginBottom = '4px';
        const label = freq === 'QXH' ? 'Start time:' : `Dose ${i + 1}:`;
        timeRow.innerHTML = `<label>${label}</label><input class="os-time-input" type="time" value="${times[i] || defaultTimeForIndex(i, freq)}">`;
        timeContainer.appendChild(timeRow);
    }
    row.querySelectorAll('.os-time-input').forEach(input => input.addEventListener('input', renderOrderSetBuilderSummary));
    if (freq === 'QXH') {
        const preview = document.createElement('div');
        preview.className = 'interval-preview sunken-panel os-interval-preview';
        timeContainer.appendChild(preview);
        const update = () => renderOrderSetIntervalPreview(row);
        row.querySelector('.os-time-input')?.addEventListener('input', update);
        row.querySelector('.os-interval-hours')?.addEventListener('input', update);
        document.getElementById('order-set-start')?.addEventListener('input', update);
        document.getElementById('order-set-end')?.addEventListener('input', update);
        renderOrderSetIntervalPreview(row);
    }
}

function renderOrderSetIntervalPreview(row) {
    const preview = row.querySelector('.os-interval-preview');
    if (!preview) return;
    const regimenStartDate = document.getElementById('order-set-start')?.value || localDateKey();
    const regimenEndValue = document.getElementById('order-set-end')?.value || '';
    const itemWindow = orderSetItemDateWindow({
        cycleMode: row.querySelector('.os-cycle-mode')?.value || 'days',
        cycleStartDay: row.querySelector('.os-cycle-start')?.value || 1,
        cycleDurationDays: row.querySelector('.os-cycle-duration')?.value || '',
        cycleStartDate: row.querySelector('.os-cycle-start-date')?.value || '',
        cycleEndDate: row.querySelector('.os-cycle-end-date')?.value || ''
    }, regimenStartDate, regimenEndValue || 'Ongoing');
    const startDate = itemWindow.startDate;
    const endValue = itemWindow.endDate === 'Ongoing' ? '' : itemWindow.endDate;
    const startTime = row.querySelector('.os-time-input')?.value || '';
    const intervalHours = parseInt(row.querySelector('.os-interval-hours')?.value, 10);
    if (!startDate || !startTime || !Number.isInteger(intervalHours) || intervalHours < 1 || intervalHours > 24) {
        preview.innerHTML = '<div class="interval-preview-empty">Enter regimen start, start time, and interval to preview doses.</div>';
        return;
    }

    const previewEnd = parseLocal(startDate);
    previewEnd.setDate(previewEnd.getDate() + 2);
    const endDate = endValue ? parseLocal(endValue) : null;
    const through = endDate && endDate < previewEnd ? endDate : previewEnd;
    through.setHours(23, 59, 59, 999);
    const schedule = {
        id: 'preview',
        freq: 'QXH',
        startDate,
        endDate: endValue || 'Ongoing',
        startTime,
        times: [startTime],
        intervalHours
    };
    const from = dateTimeFromParts(startDate, startTime);
    const grouped = rollingIntervalInstancesBetween(schedule, from, through)
        .map(dateTimeParts)
        .filter(item => isScheduleDueOnDate(schedule, item.date))
        .reduce((map, item) => {
            if (!map.has(item.date)) map.set(item.date, []);
            map.get(item.date).push(item.time);
            return map;
        }, new Map());
    preview.innerHTML = grouped.size
        ? `<table class="interval-preview-table"><thead><tr><th>Date</th><th>Administration times</th></tr></thead><tbody>${Array.from(grouped.entries()).map(([date, times]) => `<tr><td>${escapeHtml(date)}</td><td>${times.map(escapeHtml).join(', ')}</td></tr>`).join('')}</tbody></table>`
        : '<div class="interval-preview-empty">No doses fall inside the regimen window.</div>';
}

function collectOrderSetItem(row) {
    const medId = row.querySelector('.os-med-strength').value;
    const doseQty = row.querySelector('.os-dose').value;
    const freq = row.querySelector('.os-freq').value;
    const prnScheduleFreq = freq === 'PRN' ? (row.querySelector('.os-prn-schedule-freq')?.value || '') : '';
    const timingFreq = freq === 'PRN' ? prnScheduleFreq : freq;
    const rawTimes = Array.from(row.querySelectorAll('.os-time-input')).map(input => input.value).filter(Boolean);
    const intervalHours = timingFreq === 'QXH' ? parseInt(row.querySelector('.os-interval-hours').value, 10) : null;
    const intervalWeeks = timingFreq === 'QXW' ? parseInt(row.querySelector('.os-interval-weeks').value, 10) : null;
    const timesPerWeek = timingFreq === 'XPW' ? parseInt(row.querySelector('.os-times-per-week').value, 10) : null;
    const weekdays = ['QXW', 'XPW'].includes(timingFreq)
        ? Array.from(row.querySelectorAll('.os-weekday-input:checked')).map(input => parseInt(input.value, 10)).sort()
        : [];
    const prnMaxDoses = freq === 'PRN' ? parseInt(row.querySelector('.os-prn-max-doses')?.value, 10) : null;
    const prnWindowHours = freq === 'PRN' ? parseInt(row.querySelector('.os-prn-window-hours')?.value, 10) : null;
    const regimenStart = document.getElementById('order-set-start')?.value || localDateKey();
    const regimenEnd = document.getElementById('order-set-end')?.value || '';
    const cycleMode = row.querySelector('.os-cycle-mode')?.value || 'days';
    const cycleStartDay = normalizeRegimenCycleStartDay(row.querySelector('.os-cycle-start')?.value || 1);
    const cycleDurationDays = normalizeRegimenCycleDuration(row.querySelector('.os-cycle-duration')?.value || '');
    const cycleStartDate = row.querySelector('.os-cycle-start-date')?.value || '';
    const cycleEndDate = row.querySelector('.os-cycle-end-date')?.value || '';
    const cycleFields = {
        cycleMode,
        cycleStartDay,
        cycleDurationDays,
        cycleStartDate: cycleMode === 'dates' ? cycleStartDate : '',
        cycleEndDate: cycleMode === 'dates' ? cycleEndDate : ''
    };
    if (!medId || !doseQty) {
        return { error: "Each regimen medication needs a medication, strength, and dose quantity." };
    }
    if (row.querySelector('.os-cycle-start')?.value && cycleStartDay < 1) {
        return { error: "Regimen therapy day start must be 1 or higher." };
    }
    if (cycleMode === 'dates') {
        if (!cycleStartDate || !cycleEndDate) {
            return { error: "Specific regimen therapy dates need both a start date and end date." };
        }
        if (cycleEndDate < cycleStartDate) {
            return { error: "Regimen therapy end date cannot be before the therapy start date." };
        }
        if (regimenStart && cycleStartDate < regimenStart) {
            return { error: "Regimen therapy start date cannot be before the regimen start date." };
        }
        if (regimenEnd && cycleEndDate > regimenEnd) {
            return { error: "Regimen therapy end date cannot be after the regimen end date." };
        }
    } else if (cycleDurationDays && regimenEnd) {
        const therapyEnd = addDaysKey(addDaysKey(regimenStart, cycleStartDay - 1), cycleDurationDays - 1);
        if (therapyEnd > regimenEnd) {
            return { error: "Regimen therapy days extend past the regimen end date. Shorten the duration or extend the regimen." };
        }
    }
    const selectedLinkTargetRowIds = selectedOptionValues(row.querySelector('.os-link-target'));
    const linkMode = row.querySelector('.os-link-mode')?.value || '';
    const linkTargetRowIds = linkMode ? selectedLinkTargetRowIds : [];
    if (selectedLinkTargetRowIds.length > 0 && !linkMode) {
        return { error: "Choose what the regimen medication link means: must take together or choose only one." };
    }
    if (linkMode && linkTargetRowIds.length === 0) {
        return { error: "Linked regimen medications need another medication selected." };
    }
    if (timingFreq === 'QXH') {
        if (!Number.isInteger(intervalHours) || intervalHours < 1 || intervalHours > 24 || !rawTimes[0]) {
            return { error: "Every X Hours rows need a valid interval and start time." };
        }
        return {
            medId,
            doseQty,
            freq,
            prnScheduleFreq,
            times: generateIntervalTimes(rawTimes[0], intervalHours),
            intervalHours,
            intervalWeeks: null,
            timesPerWeek: null,
            weekdays: [],
            prnMaxDoses: prnMaxDoses || null,
            prnWindowHours: prnWindowHours || 24,
            ...cycleFields,
            startTime: rawTimes[0],
            qodStart: '',
            anchorDate: '',
            rowId: row.dataset.rowId,
            linkTargetRowIds,
            linkTargetRowId: linkTargetRowIds[0] || '',
            linkGroup: '',
            linkMode: row.querySelector('.os-link-mode')?.value || '',
            linkRules: linkTargetRowIds.map(targetRowId => ({ targetRowId, mode: linkMode })),
            indication: row.querySelector('.os-indication')?.value.trim() || '',
            instructions: row.querySelector('.os-instructions').value
        };
    }
    if (freq === 'PRN') {
        if (row.querySelector('.os-prn-max-doses')?.value && (!Number.isInteger(prnMaxDoses) || prnMaxDoses < 1)) {
            return { error: "PRN maximum doses must be 1 or higher." };
        }
        if (row.querySelector('.os-prn-window-hours')?.value && (!Number.isInteger(prnWindowHours) || prnWindowHours < 1 || prnWindowHours > 168)) {
            return { error: "PRN maximum window must be between 1 and 168 hours." };
        }
        if (!timingFreq) {
            return {
                medId,
                doseQty,
                freq,
                prnScheduleFreq: '',
                times: [],
                intervalHours: null,
                intervalWeeks: null,
                timesPerWeek: null,
                weekdays: [],
                prnMaxDoses: prnMaxDoses || null,
                prnWindowHours: prnWindowHours || 24,
                ...cycleFields,
                startTime: '',
                qodStart: '',
                anchorDate: '',
                rowId: row.dataset.rowId,
                linkTargetRowIds,
                linkTargetRowId: linkTargetRowIds[0] || '',
                linkGroup: '',
                linkMode,
                linkRules: linkTargetRowIds.map(targetRowId => ({ targetRowId, mode: linkMode })),
                indication: row.querySelector('.os-indication')?.value.trim() || '',
                instructions: row.querySelector('.os-instructions').value
            };
        }
    }
    if (timingFreq === 'QXW') {
        if (!Number.isInteger(intervalWeeks) || intervalWeeks < 1 || intervalWeeks > 52) {
            return { error: "Every X Weeks rows need an interval between 1 and 52 weeks." };
        }
        if (weekdays.length === 0) return { error: "Every X Weeks rows need at least one selected weekday." };
    }
    if (timingFreq === 'XPW') {
        if (!Number.isInteger(timesPerWeek) || timesPerWeek < 1 || timesPerWeek > 7) {
            return { error: "Times per week must be between 1 and 7." };
        }
        if (weekdays.length !== timesPerWeek) {
            return { error: `Select exactly ${timesPerWeek} weekday${timesPerWeek === 1 ? '' : 's'} for the X Times Per Week row.` };
        }
    }
    if (timingFreq) {
        const expected = getExpectedTimeCount(timingFreq);
        if (rawTimes.length !== expected) {
            return { error: `Each ${timingFreq} order needs ${expected} administration time${expected === 1 ? '' : 's'}.` };
        }
    }
    return {
        medId,
        doseQty,
        freq,
        prnScheduleFreq,
        times: Array.from(new Set(rawTimes)).sort(),
        intervalHours: null,
        intervalWeeks,
        timesPerWeek,
        weekdays,
        prnMaxDoses: prnMaxDoses || null,
        prnWindowHours: prnWindowHours || 24,
        ...cycleFields,
        startTime: rawTimes[0] || '',
        qodStart: timingFreq === 'QOD' ? row.querySelector('.os-qod-start').value : '',
        anchorDate: ['QW', 'Monthly'].includes(timingFreq) ? row.querySelector('.os-anchor-date').value : '',
        rowId: row.dataset.rowId,
        linkTargetRowIds,
        linkTargetRowId: linkTargetRowIds[0] || '',
        linkGroup: '',
        linkMode: row.querySelector('.os-link-mode')?.value || '',
        linkRules: linkTargetRowIds.map(targetRowId => ({ targetRowId, mode: linkMode })),
        indication: row.querySelector('.os-indication')?.value.trim() || '',
        instructions: row.querySelector('.os-instructions').value
    };
}

function orderSetItemToSchedule(orderSet, item, index, existingSchedule = null) {
    const med = db.inventory.find(inv => inv.id === item.medId);
    const itemWindow = orderSetItemDateWindow(item, orderSet.startDate, orderSet.endDate);
    const timingFreq = scheduleTimingFrequency(item) || item.freq;
    const itemStartDate = ['QW', 'Monthly'].includes(timingFreq) && item.anchorDate ? item.anchorDate : itemWindow.startDate;
    const itemEndDate = timingFreq === 'ONCE' ? itemStartDate : itemWindow.endDate;
    return {
        id: existingSchedule?.id || `${orderSet.id}_${Date.now()}_${index}`,
        memberId: orderSet.memberId,
        medId: item.medId,
        doseQty: item.doseQty,
        prescriberId: item.prescriberId || med?.prescriberId || '',
        freq: item.freq,
        prnScheduleFreq: item.prnScheduleFreq || '',
        startDate: itemStartDate,
        endDate: itemEndDate,
        indication: item.indication || '',
        instructions: item.instructions,
        qodStart: timingFreq === 'QOD' ? (item.qodStart || itemStartDate) : '',
        times: item.times,
        intervalHours: item.intervalHours,
        intervalWeeks: item.intervalWeeks || null,
        monthlyAnchor: timingFreq === 'Monthly' ? (item.anchorDate || itemStartDate) : '',
        timesPerWeek: item.timesPerWeek || null,
        weekdays: item.weekdays || [],
        prnMaxDoses: item.prnMaxDoses || null,
        prnWindowHours: item.prnWindowHours || 24,
        cycleMode: itemWindow.cycleMode,
        cycleStartDay: itemWindow.cycleStartDay,
        cycleDurationDays: itemWindow.cycleDurationDays,
        cycleStartDate: itemWindow.cycleStartDate || '',
        cycleEndDate: itemWindow.cycleEndDate || '',
        startTime: item.startTime || item.times[0] || '',
        isOneTime: timingFreq === 'ONCE' || (itemStartDate === itemEndDate && itemEndDate !== 'Ongoing'),
        orderSetId: orderSet.id,
        orderSetName: orderSet.name,
        rowId: item.rowId || '',
        linkGroup: item.linkGroup || '',
        linkMode: item.linkMode || '',
        linkTargetRowIds: item.linkTargetRowIds || (item.linkTargetRowId ? [item.linkTargetRowId] : []),
        linkTargetRowId: item.linkTargetRowId || '',
        linkRules: item.linkRules || [],
        monitoringHoldRule: orderSet.monitoringHoldRule || null,
        rollingAnchorDate: existingSchedule?.rollingAnchorDate || '',
        rollingAnchorTime: existingSchedule?.rollingAnchorTime || ''
    };
}

function orderSetItemTimingProxy(item, startDate, endDate) {
    const itemWindow = orderSetItemDateWindow(item, startDate, endDate);
    const timingFreq = scheduleTimingFrequency(item) || item.freq;
    const itemStartDate = ['QW', 'Monthly'].includes(timingFreq) && item.anchorDate ? item.anchorDate : itemWindow.startDate;
    return {
        ...item,
        id: item.rowId,
        startDate: itemStartDate,
        endDate: timingFreq === 'ONCE' ? itemStartDate : itemWindow.endDate,
        monthlyAnchor: timingFreq === 'Monthly' ? (item.anchorDate || itemStartDate) : '',
        qodStart: timingFreq === 'QOD' ? (item.qodStart || itemStartDate) : '',
        cycleMode: itemWindow.cycleMode,
        cycleStartDay: itemWindow.cycleStartDay,
        cycleDurationDays: itemWindow.cycleDurationDays,
        cycleStartDate: itemWindow.cycleStartDate || '',
        cycleEndDate: itemWindow.cycleEndDate || ''
    };
}

function resolveOrderSetItemLinks(items) {
    const byRowId = new Map(items.map(item => [item.rowId, item]));
    items.forEach(item => {
        if (!item.linkMode) {
            item.linkTargetRowId = '';
            item.linkTargetRowIds = [];
            item.linkGroup = '';
            item.linkRules = [];
            return;
        }
        item.linkTargetRowIds = uniqueValues(item.linkTargetRowIds?.length ? item.linkTargetRowIds : (item.linkTargetRowId ? [item.linkTargetRowId] : []))
            .filter(targetRowId => byRowId.has(targetRowId));
        item.linkTargetRowId = item.linkTargetRowIds[0] || '';
        if (!item.linkTargetRowId) return;
        const target = byRowId.get(item.linkTargetRowId);
        const group = `regimen-link-${target.rowId}`;
        item.linkGroup = group;
        item.linkRules = item.linkTargetRowIds.map(targetRowId => ({ targetRowId, mode: item.linkMode }));
    });
    return items;
}

window.clearOrderSetBuilder = function() {
    document.getElementById('order-set-edit-id').value = '';
    document.getElementById('order-set-name').value = '';
    document.getElementById('order-set-start').value = localDateKey();
    document.getElementById('order-set-end').value = '';
    document.getElementById('order-set-med-list').innerHTML = '';
    setMonitoringReminderSelection('order-set', [], '', document.getElementById('order-set-member')?.value || '');
    syncMonitoringParameterScheduleUi('order-set');
    addOrderSetMedicationRow();
    renderOrderSetMedicationPreview();
    renderOrderSetBuilderSummary();
};

window.saveOrderSet = async function() {
    const editId = document.getElementById('order-set-edit-id').value;
    const memberId = document.getElementById('order-set-member').value;
    const name = document.getElementById('order-set-name').value.trim();
    const startDate = document.getElementById('order-set-start').value || localDateKey();
    const endDate = document.getElementById('order-set-end').value || 'Ongoing';
    if (!name) {
        await appAlert("Order set name is required.");
        document.getElementById('order-set-name').focus();
        return;
    }

    const items = [];
    for (const row of Array.from(document.querySelectorAll('#order-set-med-list .order-set-med-row'))) {
        const item = collectOrderSetItem(row);
        if (!item || item.error) {
            await appAlert(item?.error || "Check the regimen medication rows.");
            return;
        }
        const itemTimingFreq = scheduleTimingFrequency(item) || item.freq;
        const itemWindow = orderSetItemDateWindow(item, startDate, endDate);
        if (itemWindow.endDate !== 'Ongoing' && itemWindow.startDate > itemWindow.endDate) {
            await appAlert('One regimen medication starts after the regimen end date. Adjust the regimen therapy days or extend the regimen end date.');
            return;
        }
        if (['QW', 'Monthly'].includes(itemTimingFreq)) {
            item.anchorDate = item.anchorDate || itemWindow.startDate;
            if (item.anchorDate < itemWindow.startDate || (itemWindow.endDate !== 'Ongoing' && item.anchorDate > itemWindow.endDate)) {
                await appAlert(`The first ${itemTimingFreq === 'QW' ? 'weekly' : 'monthly'} dose date must be inside the regimen start/end window.`);
                return;
            }
        }
        items.push(item);
    }
    if (items.length === 0) {
        await appAlert("Add at least one medication to the regimen.");
        return;
    }
    const monitoringConfig = collectMonitoringScheduleConfig('order-set', memberId);
    if (monitoringConfig.error) {
        await appAlert(monitoringConfig.error);
        return;
    }
    resolveOrderSetItemLinks(items);
    const itemTimingProxies = items.map(item => orderSetItemTimingProxy(item, startDate, endDate));
    for (const currentTiming of itemTimingProxies) {
        const mismatch = requiredTogetherSchedules(currentTiming, itemTimingProxies)
            .find(target => !schedulesHaveAlignedTiming(currentTiming, target));
        if (mismatch) {
            const currentMed = db.inventory.find(med => med.id === currentTiming.medId);
            const mismatchMed = db.inventory.find(med => med.id === mismatch.medId);
            await appAlert(`Regimen medications marked must-take-together need the same date, frequency, and administration time.\n\n${currentMed?.name || 'This medication'}: ${timingMismatchLabel(currentTiming)}\n${mismatchMed?.name || 'Linked medication'}: ${timingMismatchLabel(orderSetItemTimingProxy(mismatch, startDate, endDate))}`);
            return;
        }
    }

    const orderSetId = editId || Date.now().toString();
    const existingIndex = db.orderSets.findIndex(set => set.id === orderSetId);
    const existingSet = existingIndex >= 0 ? db.orderSets[existingIndex] : null;
    const orderSet = {
        id: orderSetId,
        memberId,
        name,
        startDate,
        endDate,
        items,
        monitoringReminders: monitoringConfig.types,
        monitoringReminderNote: monitoringConfig.note,
        monitoringReminderSchedule: monitoringConfig.schedule,
        monitoringHoldRule: monitoringConfig.holdRule,
        favorite: existingSet?.favorite || false,
        status: '',
        completedAt: ''
    };
    if (existingIndex >= 0) db.orderSets[existingIndex] = orderSet;
    else db.orderSets.push(orderSet);

    const existingSchedules = db.schedules.filter(schedule => schedule.orderSetId === orderSet.id);
    const existingByRowId = new Map(existingSchedules.filter(schedule => schedule.rowId).map(schedule => [schedule.rowId, schedule]));
    const claimedScheduleIds = new Set();
    const matchExistingSchedule = item => {
        const byRow = item.rowId ? existingByRowId.get(item.rowId) : null;
        if (byRow && !claimedScheduleIds.has(byRow.id)) {
            claimedScheduleIds.add(byRow.id);
            return byRow;
        }
        const fallback = existingSchedules.find(schedule =>
            !claimedScheduleIds.has(schedule.id) &&
            schedule.medId === item.medId &&
            schedule.freq === item.freq
        );
        if (fallback) claimedScheduleIds.add(fallback.id);
        return fallback || null;
    };

    db.schedules = db.schedules.filter(schedule => schedule.orderSetId !== orderSet.id);
    if (memberId) {
        db.schedules.push(...items.map((item, index) => orderSetItemToSchedule(orderSet, item, index, matchExistingSchedule(item))));
    }
    createCareRemindersForOrderSet(orderSet);

    await sync();
    clearOrderSetBuilder();
};

window.editOrderSet = function(id) {
    const set = db.orderSets.find(orderSet => orderSet.id === id);
    if (!set) return;
    const memberModal = document.getElementById('member-modal');
    if (memberModal?.style.display === 'flex') {
        minimizeMemberModal();
    }
    document.getElementById('order-set-edit-id').value = set.id;
    document.getElementById('order-set-member').value = set.memberId;
    document.getElementById('order-set-name').value = set.name;
    document.getElementById('order-set-start').value = set.startDate;
    document.getElementById('order-set-end').value = set.endDate === 'Ongoing' ? '' : set.endDate;
    document.getElementById('order-set-med-list').innerHTML = '';
    setMonitoringReminderSelection('order-set', set.monitoringReminders || [], set.monitoringReminderNote || '', set.memberId || '', set.monitoringReminderSchedule || null, set.monitoringHoldRule || null);
    set.items.forEach(item => addOrderSetMedicationRow(item));
    switchTab('order-sets');
};

window.assignOrderSet = async function(id) {
    const source = db.orderSets.find(orderSet => orderSet.id === id);
    if (!source) return;
    if (db.family.length === 0) {
        await appAlert("Add a member before assigning a regimen.");
        return;
    }

    const result = await showActionModal(`Assign Regimen: ${source.name}`, `
        <div class="field-row">
            <label>Member:</label>
            <select name="memberId">${memberOptionsHtml(source.memberId || '')}</select>
        </div>
        <div class="field-row" style="margin-top:8px;">
            <label>Start:</label><input name="startDate" type="date" value="${escapeHtml(source.startDate || localDateKey())}">
            <label>End:</label><input name="endDate" type="date" value="${source.endDate === 'Ongoing' ? '' : escapeHtml(source.endDate || '')}">
        </div>
    `, 'Assign');
    if (!result) return;
    if (!result.memberId || !result.startDate) {
        await appAlert("Member and start date are required to assign a regimen.");
        return;
    }

    const assignedSet = {
        ...source,
        id: Date.now().toString(),
        templateId: source.templateId || source.id,
        memberId: result.memberId,
        startDate: result.startDate,
        endDate: result.endDate || 'Ongoing',
        monitoringReminderSchedule: rebaseMonitoringReminderSchedule(source.monitoringReminderSchedule, source.startDate, result.startDate, result.endDate || 'Ongoing'),
        monitoringHoldRule: source.monitoringHoldRule || null,
        items: source.items.map(item => {
            const timingFreq = scheduleTimingFrequency(item) || item.freq;
            if (!['QW', 'Monthly'].includes(timingFreq) || !item.anchorDate || !source.startDate) return { ...item };
            const offset = Math.max(daysBetween(item.anchorDate, source.startDate), 0);
            const rebasedAnchor = parseLocal(result.startDate);
            rebasedAnchor.setDate(rebasedAnchor.getDate() + offset);
            return { ...item, anchorDate: localDateKey(rebasedAnchor) };
        })
    };
    const invalidAnchor = assignedSet.items.find(item =>
        ['QW', 'Monthly'].includes(scheduleTimingFrequency(item) || item.freq) &&
        item.anchorDate &&
        (() => {
            const window = orderSetItemDateWindow(item, assignedSet.startDate, assignedSet.endDate);
            return item.anchorDate < window.startDate || (window.endDate !== 'Ongoing' && item.anchorDate > window.endDate);
        })()
    );
    if (invalidAnchor) {
        await appAlert('The assigned date range is too short for one of the weekly/monthly first-dose dates. Extend the end date or edit the regimen.');
        return;
    }

    db.orderSets.push(assignedSet);
    db.schedules.push(...assignedSet.items.map((item, index) => orderSetItemToSchedule(assignedSet, item, index)));
    createCareRemindersForOrderSet(assignedSet);
    await sync();
};

window.deleteOrderSet = async function(id) {
    if (!await appConfirm("Delete this regimen and its related schedules?", "Delete Regimen")) return;
    db.orderSets = db.orderSets.filter(set => set.id !== id);
    db.schedules = db.schedules.filter(schedule => schedule.orderSetId !== id);
    replaceCareRemindersForSource('orderSet', id, []);
    await sync();
    const memberModal = document.getElementById('member-modal');
    if (currentEditingMemberId && memberModal?.style.display === 'flex') {
        await openMemberModal(currentEditingMemberId, 'orders');
    }
};

window.printOrderSetLabel = function(id) {
    const set = db.orderSets.find(orderSet => orderSet.id === id);
    if (!set) return;
    const member = db.family.find(m => m.id === set.memberId);
    const sourceItems = set.memberId
        ? db.schedules.filter(schedule => schedule.orderSetId === set.id)
        : set.items.map(item => ({ ...item, startDate: set.startDate, endDate: set.endDate }));
    const entries = sourceItems.map(schedule => {
        const med = db.inventory.find(item => item.id === schedule.medId);
        if (!med) return null;
        const timing = schedule.freq === 'PRN'
            ? `${formatFrequency(schedule)}${getScheduleTimes(schedule).length ? ` at ${getScheduleTimes(schedule).join(', ')}` : ''}`
            : `${formatFrequency(schedule)} at ${getScheduleTimes(schedule).join(', ')}`;
        const detail = `Qty ${formatQtyForSchedule(schedule, med)} | Dose ${formatPrescribedDose(med, schedule.doseQty)} | ${timing}`;
        const displayName = formatMultiMedLabelName(schedule, med);
        return {
            med,
            schedule,
            displayName,
            detail,
            instructions: schedule.instructions || '',
            size: displayName.length + detail.length + String(schedule.instructions || '').length
        };
    }).filter(Boolean);
    if (entries.length === 0) {
        void appAlert(set.memberId
            ? 'This assigned regimen has no active medications to print.'
            : 'This reusable regimen has no medications to print.');
        return;
    }

    const pages = [];
    let page = [];
    let pageSize = 0;
    entries.forEach(entry => {
        if (page.length > 0 && (page.length >= 4 || pageSize + entry.size > 285)) {
            pages.push(page);
            page = [];
            pageSize = 0;
        }
        page.push(entry);
        pageSize += entry.size;
    });
    if (page.length) pages.push(page);

    const labels = pages.map((pageEntries, pageIndex) => {
        const rows = pageEntries.map(entry => `
            <div class="label-med-row order-set-label-row">
                <span class="order-set-label-med">${escapeHtml(entry.displayName)}</span><br>
                ${escapeHtml(entry.detail)}
                ${entry.instructions ? `<br>Note: ${escapeHtml(entry.instructions)}` : ''}
            </div>`).join('');
        const memberLine = member
            ? `${member.firstName} ${member.lastName} | ${set.startDate}-${set.endDate}`
            : 'Reusable regimen';
        const continuation = pages.length > 1 ? ` | ${pageIndex + 1}/${pages.length}` : '';
        return `
            <div class="${getLabelClass([set.name, memberLine, rows], pageEntries.length * 2 + 2)}">
                <div class="label-title">${escapeHtml(set.name)}${escapeHtml(continuation)}</div>
                <div class="label-small">${escapeHtml(memberLine)}</div>
                ${rows}
            </div>`;
    });
    previewLabelHtml(labels.join(''));
};

window.printOrderSetMedicationLabel = async function(id) {
    const set = db.orderSets.find(orderSet => orderSet.id === id);
    if (!set) return;
    const schedules = db.schedules.filter(schedule => schedule.orderSetId === set.id);
    if (!set.memberId || schedules.length === 0) {
        await appAlert('Assign this regimen to a member before printing individual medication labels.');
        return;
    }

    const options = schedules.map(schedule => {
        const med = db.inventory.find(item => item.id === schedule.medId);
        if (!med) return '';
        return `<option value="${escapeHtml(schedule.id)}">${escapeHtml(med.name)} ${escapeHtml(formatMedStrength(med))} - ${escapeHtml(formatFrequency(schedule))}</option>`;
    }).join('');
    const result = await showActionModal(`Individual Labels: ${set.name}`, `
        <div class="field-row-stacked">
            <label>Medication:</label>
            <select name="scheduleId" style="width:100%;">${options}</select>
        </div>
    `, 'Choose Dates');
    if (result?.scheduleId) await window.printSingleLabel(result.scheduleId);
};

function regimenLinkedDetailsText(item, sourceItems) {
    const linked = linkedSchedulesFor(item, sourceItems);
    if (!linked.length) return '';
    const modeText = item.linkMode === 'choose-one'
        ? 'Choose only one with'
        : 'Take together with';
    const names = linked.map(linkedItem => {
        const med = db.inventory.find(candidate => candidate.id === linkedItem.medId);
        return med ? med.name : 'Linked medication';
    });
    return `${modeText}: ${uniqueValues(names).join(', ')}`;
}

function regimenReportItemsFromOrderSet(set) {
    if (!set) return [];
    const sourceItems = set.memberId
        ? db.schedules.filter(schedule => schedule.orderSetId === set.id && !isScheduleArchived(schedule))
        : (set.items || []).map(item => orderSetItemTimingProxy(item, set.startDate, set.endDate));
    return sourceItems.map((item, index) => {
        const med = db.inventory.find(candidate => candidate.id === item.medId);
        const times = getScheduleTimes(item);
        return {
            index: index + 1,
            name: med?.name || 'Unknown medication',
            strength: med ? formatMedStrength(med) : '',
            dose: med ? formatPrescribedDose(med, item.doseQty) : (item.doseQty || ''),
            quantity: med ? formatQtyForSchedule(item, med) : '',
            schedule: `${formatFrequency(item)} ${times.join(', ') || (item.freq === 'PRN' ? 'as needed' : '')}`.trim(),
            cycle: regimenCycleText(item, set.startDate, set.endDate),
            indication: item.indication || '',
            instructions: item.instructions || '',
            linkText: linkedSchedulesFor(item, sourceItems).length
                ? regimenLinkedDetailsText(item, sourceItems)
                : ''
        };
    });
}

function regimenReportSourceFromOrderSet(set) {
    const member = set?.memberId ? db.family.find(item => item.id === set.memberId) : null;
    return {
        title: set?.name || 'Regimen',
        memberText: member ? memberDisplayName(member) : 'Reusable template',
        startDate: set?.startDate || '',
        endDate: set?.endDate || 'Ongoing',
        items: regimenReportItemsFromOrderSet(set),
        reminderTypes: set?.monitoringReminders || [],
        reminderNote: set?.monitoringReminderNote || '',
        memberId: set?.memberId || '',
        filePrefix: regimenPreviewFilenamePrefix(set?.name || 'Regimen')
    };
}

function regimenReportBodyFromOrderSet(set, options = {}) {
    const source = regimenReportSourceFromOrderSet(set);
    return regimenReportBody(source.title, source.memberText, source.startDate, source.endDate, source.items, source.reminderTypes, source.reminderNote, source.memberId, options);
}

window.generateRegimenReportPdf = async function(id) {
    const set = db.orderSets.find(orderSet => orderSet.id === id);
    if (!set) return appAlert('Regimen not found.');
    const source = regimenReportSourceFromOrderSet(set);
    const options = await chooseRegimenReportOutputOptions(source, 'pdf');
    if (!options) return;
    await saveReportPdf(
        `Regimen - ${set.name}`,
        regimenReportBodyFromOrderSet(set, options),
        regimenPreviewFilenamePrefix(set.name),
        { preview: false }
    );
};

window.printRegimenReport = async function(id) {
    const set = db.orderSets.find(orderSet => orderSet.id === id);
    if (!set) {
        appAlert('Regimen not found.');
        return;
    }
    const source = regimenReportSourceFromOrderSet(set);
    const options = await chooseRegimenReportOutputOptions(source, 'print');
    if (!options) return;
    printReportFromPreview(`Regimen - ${set.name}`, regimenReportBodyFromOrderSet(set, options));
};

window.fillRegimenProviderEmail = function(providerId) {
    const emailInput = document.querySelector('#action-modal-body input[name="email"]');
    const provider = db.prescribers.find(item => item.id === providerId);
    if (emailInput) emailInput.value = provider?.email || '';
};

window.emailRegimenReport = async function(id) {
    const set = db.orderSets.find(orderSet => orderSet.id === id);
    if (!set) return appAlert('Regimen not found.');
    const source = regimenReportSourceFromOrderSet(set);
    const options = await chooseRegimenReportOutputOptions(source, 'email');
    if (!options) return;
    const member = set.memberId ? db.family.find(item => item.id === set.memberId) : null;
    const providers = member ? memberPrescriberIds(member)
        .map(providerId => db.prescribers.find(item => item.id === providerId))
        .filter(Boolean)
        .sort((a, b) => prescriberDisplayName(a).localeCompare(prescriberDisplayName(b), undefined, { sensitivity: 'base' })) : [];
    const defaultProvider = providers.find(provider => provider.email) || providers[0];
    const providerOptions = providers
        .map(provider => `<option value="${escapeHtml(provider.id)}" ${provider.id === defaultProvider?.id ? 'selected' : ''}>${escapeHtml(prescriberDisplayName(provider))}${provider.email ? ` - ${escapeHtml(provider.email)}` : ' - no email saved'}</option>`)
        .join('');
    const result = await showActionModal('Send Regimen to Provider', `
        <div class="field-row-stacked">
            <label>Provider profile:</label>
            <select name="providerId" onchange="fillRegimenProviderEmail(this.value)" style="width:100%;">
                <option value="">Enter an email manually</option>
                ${providerOptions}
            </select>
        </div>
        <div class="field-row-stacked" style="margin-top:8px;">
            <label>Recipient email:</label>
            <input name="email" type="email" value="${escapeHtml(defaultProvider?.email || '')}" style="width:100%;" placeholder="provider@example.com">
        </div>
        <div class="field-row-stacked" style="margin-top:8px;">
            <label>Message:</label>
            <textarea name="message" rows="4" style="width:100%; resize:none;">Attached is the ${escapeHtml(set.name)} regimen${member ? ` for ${escapeHtml(memberDisplayName(member))}` : ''}.</textarea>
        </div>
    `, 'Send Email');
    if (!result) return;
    const email = String(result.email || '').trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        await appAlert('Select a provider with an email address or enter a valid email manually.');
        return;
    }
    await emailReportPdf(
        `Regimen - ${set.name}`,
        regimenReportBodyFromOrderSet(set, options),
        regimenPreviewFilenamePrefix(set.name),
        email,
        result.message
    );
};

window.toggleRegimenFavorite = async function(id, event = null) {
    event?.stopPropagation?.();
    const set = db.orderSets.find(orderSet => orderSet.id === id && !orderSet.memberId);
    if (!set) return;
    set.favorite = !set.favorite;
    addAudit('Regimen favorite changed', set.name || 'Reusable regimen', set.favorite ? 'Marked favorite' : 'Removed favorite');
    await sync();
};

window.toggleRegimenFavoriteAtIndex = async function(index, event = null) {
    event?.stopPropagation?.();
    const set = db.orderSets[index];
    if (!set || set.memberId) return;
    set.favorite = !set.favorite;
    addAudit('Regimen favorite changed', set.name || 'Reusable regimen', set.favorite ? 'Marked favorite' : 'Removed favorite');
    await sync();
};

function renderOrderSets() {
    const memberSelect = document.getElementById('order-set-member');
    const selectedBuilderMember = memberSelect?.value || '';
    if (memberSelect) {
        memberSelect.innerHTML = `<option value="">Reusable template</option>` + db.family
            .slice()
            .sort((a, b) => memberDisplayName(a).localeCompare(memberDisplayName(b), undefined, { sensitivity: 'base' }))
            .map(m => `<option value="${m.id}">${escapeHtml(memberDisplayName(m))}</option>`)
            .join('');
        memberSelect.value = selectedBuilderMember;
    }
    ['order-set-member', 'order-set-name', 'order-set-start', 'order-set-end'].forEach(id => {
        const input = document.getElementById(id);
        if (input && !input.dataset.regimenPreviewBound) {
            input.dataset.regimenPreviewBound = 'true';
            input.addEventListener('input', renderOrderSetBuilderSummary);
            input.addEventListener('change', renderOrderSetBuilderSummary);
        }
    });

    const startInput = document.getElementById('order-set-start');
    if (startInput && !startInput.value) startInput.value = localDateKey();

    const medList = document.getElementById('order-set-med-list');
    if (medList && medList.children.length === 0) {
        addOrderSetMedicationRow();
    }
    renderOrderSetMedicationPreview();
    renderOrderSetBuilderSummary();

    const filter = document.getElementById('order-set-member-filter');
    const selectedFilter = filter?.value || '';
    if (filter) {
        filter.innerHTML = '<option value="">All members</option>' + db.family
            .slice()
            .sort((a, b) => memberDisplayName(a).localeCompare(memberDisplayName(b), undefined, { sensitivity: 'base' }))
            .map(member => `<option value="${escapeHtml(member.id)}">${escapeHtml(memberDisplayName(member))}</option>`)
            .join('');
        filter.value = db.family.some(member => member.id === selectedFilter) ? selectedFilter : '';
    }

    const templateList = document.getElementById('order-set-template-list');
    const assignedList = document.getElementById('order-set-assigned-list');
    if (!templateList || !assignedList) return;

    const orderSetRowHtml = (set, isTemplate) => {
        const setIndex = db.orderSets.indexOf(set);
        const member = db.family.find(m => m.id === set.memberId);
        const itemSummary = set.items.map(item => {
            const med = db.inventory.find(m => m.id === item.medId);
            return med ? med.name : 'Unknown';
        }).join(', ');
        const activeSchedules = db.schedules.filter(schedule => schedule.orderSetId === set.id && !isScheduleArchived(schedule));
        const regimenHold = orderSetHoldInfo(set.id);
        const containerActions = activeSchedules.map(schedule => {
            const med = db.inventory.find(item => item.id === schedule.medId);
            if (!med || !usesContainerTracking(med)) return '';
            return `<button onclick="finishTopicalContainer('${escapeHtml(schedule.id)}')" title="${escapeHtml(med.name)}">${escapeHtml(finishedContainerButtonText(med))}: ${escapeHtml(med.name)}</button>`;
        }).join('');
        const statusText = isTemplate
            ? `${set.items.length} medication${set.items.length === 1 ? '' : 's'}`
            : `${escapeHtml(memberDisplayName(member))} | ${activeSchedules.length} active medication${activeSchedules.length === 1 ? '' : 's'}`;
        const favoriteStar = isTemplate && set.favorite ? '<span class="win98-star" title="Favorite regimen">&#9733;</span>' : '';
        return `<div class="med-item-row ${regimenHold.anyHeld ? 'member-med-held' : ''}" style="border-bottom:1px solid #808080;">
            <div style="flex-grow:1;">
                ${favoriteStar}<strong>${escapeHtml(set.name)}</strong> - <small>${statusText}</small><br>
                <small>${escapeHtml(itemSummary)}</small>
            </div>
            ${isTemplate ? `<button type="button" class="favorite-regimen-button ${set.favorite ? 'favorited' : ''}" onclick="toggleRegimenFavoriteAtIndex(${setIndex}, event)" title="${set.favorite ? 'Remove favorite' : 'Mark as favorite'}">${set.favorite ? '&#9733;' : '&#9734;'} Favorite</button>` : ''}
            ${isTemplate ? `<button onclick="assignOrderSet('${escapeHtml(set.id)}')">Assign</button>` : ''}
            <button onclick="printOrderSetLabel('${escapeHtml(set.id)}')">Regimen Label</button>
            ${!isTemplate && activeSchedules.length ? `<button onclick="printOrderSetMedicationLabel('${escapeHtml(set.id)}')">Individual Labels</button>` : ''}
            ${!isTemplate && activeSchedules.length ? `<button onclick="administerOrderSet('${escapeHtml(set.id)}')">Administer</button>` : ''}
            ${!isTemplate && activeSchedules.length ? `<button class="hold-med-button" onclick="toggleOrderSetHold('${escapeHtml(set.id)}')">&#10074;&#10074; ${regimenHold.anyHeld ? 'Remove Hold' : 'Hold'}</button>` : ''}
            ${!isTemplate ? containerActions : ''}
            <button onclick="editOrderSet('${escapeHtml(set.id)}')">Edit</button>
            <button onclick="deleteOrderSet('${escapeHtml(set.id)}')">Delete</button>
        </div>`;
    };

    const templates = db.orderSets
        .filter(set => !set.memberId)
        .sort((a, b) => Number(Boolean(b.favorite)) - Number(Boolean(a.favorite)) || String(a.name || '').localeCompare(String(b.name || ''), undefined, { sensitivity: 'base' }));
    const assigned = db.orderSets.filter(set => set.memberId && set.status !== 'completed' && (!filter?.value || set.memberId === filter.value));
    templateList.innerHTML = templates.length
        ? templates.map(set => orderSetRowHtml(set, true)).join('')
        : '<div style="padding:6px; font-size:11px;">No reusable regimens saved.</div>';
    assignedList.innerHTML = assigned.length
        ? assigned.map(set => orderSetRowHtml(set, false)).join('')
        : `<div style="padding:6px; font-size:11px;">${filter?.value ? 'No regimens assigned to this member.' : 'No assigned regimens saved.'}</div>`;
}

function prepackItemId() {
    return `prep_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function prepackQueueId() {
    return `queue_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function hashForShortCode(value) {
    let hash = 2166136261;
    String(value || '').split('').forEach(char => {
        hash ^= char.charCodeAt(0);
        hash = Math.imul(hash, 16777619);
    });
    return (hash >>> 0).toString(36).toUpperCase().padStart(6, '0').slice(-6);
}

function prepackPackageScanCode(memberId, date, shift = 'all', uniqueSeed = '') {
    const dateObj = parseLocal(date || localDateKey());
    const epoch = parseLocal('2026-01-01');
    const datePart = dateObj && epoch
        ? Math.max(0, Math.round((dateObj - epoch) / 86400000)).toString(36).toUpperCase().padStart(3, '0').slice(-3)
        : String(date || localDateKey()).replace(/[^0-9]/g, '').slice(-3) || '000';
    const shiftPart = String(shift || 'all').replace(/[^a-z0-9]/gi, '').toUpperCase().slice(0, 1) || 'A';
    const memberHash = hashForShortCode(`${memberId}|${uniqueSeed}`).slice(-4);
    return `P${datePart}${shiftPart}${memberHash}`;
}

function prepackPackageCode(memberId, date, shift = 'all') {
    const memberPart = String(memberId || 'member').replace(/[^a-z0-9]/gi, '').slice(-8).toUpperCase() || 'MEMBER';
    const datePart = String(date || localDateKey()).replace(/[^0-9]/g, '');
    const shiftPart = String(shift || 'all').replace(/[^a-z0-9]/gi, '').toUpperCase() || 'ALL';
    return `PA-PREP-${memberPart}-${datePart}-${shiftPart}`;
}

function ensurePrepackDayCodes(queue) {
    if (!queue) return;
    (queue.days || []).forEach(day => {
        const codeDate = firstDateInPrepackDay(day) || day.date;
        const shift = queue.selection?.prepackShift || 'all';
        if (!day.prepackCode) day.prepackCode = prepackPackageCode(queue.memberId, codeDate, shift);
        if (!day.prepackScanCode) day.prepackScanCode = prepackPackageScanCode(queue.memberId, codeDate, shift, queue.id || '');
    });
}

function prepackDayCodeMatches(day, scannedCode) {
    const normalized = normalizeMedicationCode(scannedCode);
    return !!normalized && [
        day?.prepackScanCode,
        day?.prepackCode
    ].some(code => normalizeMedicationCode(code) === normalized);
}

function prepackDayCodeList(day) {
    return [
        day?.prepackScanCode,
        day?.prepackCode
    ].map(normalizeMedicationCode).filter(Boolean);
}

function findPrepackPackageByScanCode(scannedCode) {
    const normalized = normalizeMedicationCode(scannedCode);
    if (!normalized) return null;
    for (const queue of db.prepackQueues || []) {
        ensurePrepackDayCodes(queue);
        for (const [dayIndex, day] of (queue.days || []).entries()) {
            if (prepackDayCodeMatches(day, normalized)) {
                return {
                    type: 'prepack-package',
                    code: normalized,
                    queueId: queue.id,
                    dayIndex,
                    dayDate: day.date,
                    memberId: queue.memberId || '',
                    medIds: Array.from(new Set((day.items || []).map(item => item.medId).filter(Boolean)))
                };
            }
        }
    }
    return null;
}

function findPrepackItemByScanCode(scannedCode) {
    const scannedCodes = medicationCodesFromScannedPayload(scannedCode);
    if (scannedCodes.length === 0) return null;
    for (const queue of db.prepackQueues || []) {
        ensurePrepackDayCodes(queue);
        for (const [dayIndex, day] of (queue.days || []).entries()) {
            const matches = (day.items || []).filter(item => {
                const itemCodes = [
                    normalizeMedicationCode(item.prepackItemCode),
                    normalizeMedicationCode(item.prepackScanCode),
                    normalizeMedicationCode(item.packageScanCode)
                ].filter(Boolean).filter(code => /^PA-(PREP|UNIT)-|^PREP-/.test(code));
                const prepackedCode = normalizeMedicationCode(item.prepackedBarcodeCode);
                if (prepackedCode) itemCodes.push(prepackedCode);
                return scannedCodes.some(code => itemCodes.includes(code));
            });
            if (matches.length) {
                return {
                    type: 'prepack-item',
                    code: scannedCodes[0],
                    queueId: queue.id,
                    dayIndex,
                    dayDate: day.date,
                    memberId: queue.memberId || '',
                    itemIds: matches.map(item => item.id),
                    medIds: Array.from(new Set(matches.map(item => item.medId).filter(Boolean)))
                };
            }
        }
    }
    return null;
}

function resolveCommandScan(scannedCode, options = {}) {
    const normalized = normalizeMedicationCode(scannedCode);
    if (!normalized) return null;
    const packageMatch = findPrepackPackageByScanCode(normalized);
    if (packageMatch) return packageMatch;
    const prepackItemMatch = findPrepackItemByScanCode(normalized);
    if (prepackItemMatch) return prepackItemMatch;
    const meds = findInventoryMedsByCode(normalized);
    if (meds.length) {
        const memberId = options.memberId || currentEditingMemberId || '';
        return {
            type: 'inventory-label',
            code: normalized,
            memberId,
            medIds: meds.map(med => med.id)
        };
    }
    return null;
}

function commandScanQueue(scan = activeCommandScan) {
    return scan?.queueId ? (db.prepackQueues || []).find(queue => queue.id === scan.queueId) : null;
}

function commandScanDay(scan = activeCommandScan) {
    const queue = commandScanQueue(scan);
    if (!queue) return null;
    return (queue.days || [])[scan.dayIndex] || (queue.days || []).find(day => prepackDayCodeMatches(day, scan.code));
}

function commandScanItems(scan = activeCommandScan) {
    if (!scan) return [];
    const day = commandScanDay(scan);
    if (day) {
        let items = day.items || [];
        if (Array.isArray(scan.itemIds) && scan.itemIds.length) {
            const allowed = new Set(scan.itemIds);
            items = items.filter(item => allowed.has(item.id));
        }
        return items.filter(item => !scan.medId || item.medId === scan.medId);
    }
    return (scan.medIds || [])
        .map(medId => {
            const med = db.inventory.find(item => item.id === medId);
            return med ? {
                id: med.id,
                medId,
                medName: med.name,
                strength: formatLabelMedStrength(med),
                quantity: '',
                dose: '',
                time: ''
            } : null;
        })
        .filter(Boolean);
}

function commandScanMember(scan = activeCommandScan) {
    if (!scan) return null;
    return db.family.find(member => member.id === scan.memberId) || null;
}

function commandDateTimeText(value, fallbackDate = '', fallbackTime = '') {
    if (value) {
        const date = new Date(value);
        if (!Number.isNaN(date.getTime())) {
            return `${localDateKey(date)} ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
        }
    }
    return `${fallbackDate || localDateKey()} ${fallbackTime || ''}`.trim();
}

function commandHistoryEntryWhen(entry) {
    if (entry?.timestamp) {
        const actual = historyEntryDateTime(entry);
        return `${actual.date || ''} ${actual.time || ''}`.trim();
    }
    if (entry?.scheduledDate || entry?.scheduledTime) {
        return `${entry.scheduledDate || ''} ${entry.scheduledTime || ''}`.trim();
    }
    return '';
}

function commandHistoryActionType(entry) {
    const details = String(entry?.details || '').toLowerCase();
    if (entry?.doseStatus === 'wasted' || details.includes('wasted')) return 'Wasted';
    if (details.includes('returned')) return 'Returned';
    if (isGivenAdministrationHistory(entry)) return 'Administered';
    if (details.includes('prepacked') || details.includes('prepack')) return 'Prepacked';
    if (entry?.doseStatus) return doseStatusLabel(entry.doseStatus);
    return 'Record';
}

function prepackReturnDetailText(item, med = null) {
    const qty = parseAmount(item?.returnedQuantity, NaN);
    const fallbackQty = parseAmount(item?.stockDelta, NaN);
    const unit = med?.administrationUnit || (med ? inventoryUnitFor(med) : 'unit');
    const qtyText = Number.isFinite(qty) && qty > 0
        ? `${formatAmount(qty)} ${unit}`
        : (Number.isFinite(fallbackQty) && fallbackQty > 0 ? `${formatAmount(fallbackQty)} ${unit}` : 'quantity recorded');
    const destination = item?.stockSource === 'kit' || item?.kitId ? 'med kit' : 'main inventory';
    const reason = String(item?.returnReason || 'returned').trim();
    return `Returned ${qtyText} to ${destination}; reason: ${reason}.`;
}

function commandScanItemScheduleStatus(item, day = null) {
    if (item?.inventoryWasted) return { label: 'Wasted', className: 'danger', details: 'This prepared dose was documented as wasted.' };
    if (item?.inventoryReturned) return { label: 'Returned', className: 'returned', details: 'This prepared dose was returned to inventory.' };
    const schedule = prepackItemSchedule(item);
    if (!item?.scheduleId) return null;
    if (!schedule) return { label: 'Discontinued', className: 'danger', details: 'The original schedule no longer exists.' };
    if (schedule.status === 'discontinued') return { label: 'Discontinued', className: 'danger', details: 'This medication schedule was discontinued after the label was created.' };
    const date = lastDateInPrepackDay(day) || firstDateInPrepackDay(day) || item.scheduledDate || '';
    if (schedule.endDate && schedule.endDate !== 'Ongoing' && date && date > schedule.endDate) {
        return { label: 'Completed', className: 'warning', details: `Scheduled timeframe ended ${schedule.endDate}.` };
    }
    if (schedule.status === 'completed') return { label: 'Completed', className: 'warning', details: 'The medication schedule is completed.' };
    return null;
}

function commandScanMedSelector(scan = activeCommandScan) {
    const items = commandScanItems({ ...scan, medId: '' });
    const medIds = Array.from(new Set(items.map(item => item.medId).filter(Boolean)));
    if (medIds.length <= 1) return '';
    const current = scan?.medId || 'all';
    const options = medIds.map(medId => {
        const med = db.inventory.find(item => item.id === medId);
        const item = items.find(candidate => candidate.medId === medId);
        const status = commandScanItemScheduleStatus(item, commandScanDay(scan));
        const label = med ? `${med.name} ${formatLabelMedStrength(med)}`.trim() : (item?.medName || 'Medication');
        const suffix = status ? ` - ${status.label}` : '';
        return `<option value="${escapeHtml(medId)}" ${current === medId ? 'selected' : ''}>${escapeHtml(label + suffix)}</option>`;
    }).join('');
    return `<div class="command-scan-med-select">
        <label>View medication
            <select onchange="setCommandScanMedFilter(this.value)">
                <option value="all" ${current === 'all' ? 'selected' : ''}>All medications in this package</option>
                ${options}
            </select>
        </label>
    </div>`;
}

function commandScanTrackingRows(scan = activeCommandScan, medId = 'all') {
    if (!scan) return [];
    const queue = commandScanQueue(scan);
    const day = commandScanDay(scan);
    const selectedItems = commandScanItems({ ...scan, medId: medId === 'all' ? '' : medId });
    const itemIds = new Set(selectedItems.map(item => item.id));
    const medIds = new Set(selectedItems.map(item => item.medId).filter(Boolean));
    const rows = [];
    const addRow = row => rows.push({
        when: row.when || '',
        type: row.type || 'Record',
        medName: row.medName || '',
        details: row.details || '',
        order: Number.isFinite(row.order) ? row.order : 50
    });
    if (queue) {
        addRow({
            order: 1,
            when: commandDateTimeText(queue.createdAt, firstDateInPrepackDay(day), ''),
            type: 'Queued',
            medName: queue.memberName || '',
            details: queue.scheduledFor
                ? `Prepack scheduled for ${queue.scheduledFor.replace('T', ' ')}.`
                : 'Prepack queue created.'
        });
        addRow({
            order: 2,
            when: queue.lastPrintedAt ? commandDateTimeText(queue.lastPrintedAt, firstDateInPrepackDay(day), '') : '',
            type: queue.labelsPrinted ? 'Labels printed' : 'Labels not printed',
            medName: queue.title || queue.sourceLabel || 'Prepack',
            details: day?.needsReprint
                ? 'Labels were printed, but this day needs updated labels because the package changed.'
                : (queue.labelsPrinted ? 'Labels are available for this package.' : 'Print labels before preparation.')
        });
        if (day?.needsReprint) {
            addRow({
                order: 3,
                when: '',
                type: 'Labels need reprint',
                medName: queue.title || 'Prepack',
                details: 'Medication changes affected this package day.'
            });
        }
    }
    if (!queue && scan.type === 'inventory-label') {
        selectedItems.forEach(item => addRow({
            order: 1,
            when: '',
            type: 'Inventory label',
            medName: `${item.medName || ''} ${item.strength || ''}`.trim(),
            details: 'Scanned label is linked to this inventory item. Use the action buttons to document a supplemental dose or schedule future prepacking.'
        }));
    }
    if (queue && day) {
        selectedItems.forEach(item => {
            const medName = `${item.medName || ''} ${item.strength || ''}`.trim();
            const med = db.inventory.find(candidate => candidate.id === item.medId);
            const scheduleStatus = commandScanItemScheduleStatus(item, day);
            if (scheduleStatus) {
                addRow({
                    order: 4,
                    when: '',
                    type: scheduleStatus.label,
                    medName,
                    details: scheduleStatus.details
                });
            }
            if (isPreparedPrepackItem(item)) {
                addRow({
                    order: 10,
                    when: commandDateTimeText(item.stockDeductedAt || item.scannedAt, firstDateInPrepackDay(day), item.time),
                    type: item.verificationMethod === 'manual' ? 'Prepacked manually' : 'Prepacked',
                    medName,
                    details: item.stockLogDetail || `Prepared from ${item.stockSource === 'kit' || item.kitId ? 'med kit' : 'inventory'}.`
                });
            } else if (!item.removedFromPrepack) {
                addRow({
                    order: 9,
                    when: '',
                    type: 'Not yet prepacked',
                    medName,
                    details: item.status === 'wrong'
                        ? 'Last scan did not match this item.'
                        : 'Waiting for scan or manual prepack.'
                });
            }
            if (item.inventoryReturned && !item.inventoryWasted) {
                addRow({
                    order: 70,
                    when: commandDateTimeText(item.returnedAt, firstDateInPrepackDay(day), item.time),
                    type: 'Returned',
                    medName,
                    details: prepackReturnDetailText(item, med)
                });
            }
            if (item.inventoryWasted) {
                addRow({
                    order: 75,
                    when: commandDateTimeText(item.wastedAt || item.returnedAt, firstDateInPrepackDay(day), item.time),
                    type: 'Wasted',
                    medName,
                    details: item.wasteReason || item.returnReason || 'Wasted.'
                });
            }
        });
    }
    const returnedItemIds = new Set(selectedItems.filter(item => item.inventoryReturned && !item.inventoryWasted).map(item => item.id));
    const wastedItemIds = new Set(selectedItems.filter(item => item.inventoryWasted).map(item => item.id));
    (db.history || []).forEach(entry => {
        if (queue && entry.prepackQueueId !== queue.id) {
            const sameDay = day && entry.memberId === queue.memberId && String(entry.scheduledDate || historyEntryDateKey(entry) || '').slice(0, 10) === firstDateInPrepackDay(day);
            if (!sameDay) return;
        }
        if (scan.memberId && entry.memberId && entry.memberId !== scan.memberId) return;
        if (itemIds.size && entry.prepackItemId && !itemIds.has(entry.prepackItemId)) return;
        if (medIds.size && entry.medId && !medIds.has(entry.medId)) return;
        if (!queue && medIds.size && !medIds.has(entry.medId)) return;
        if (!queue && scan.memberId && entry.memberId !== scan.memberId) return;
        const type = commandHistoryActionType(entry);
        if (type === 'Returned' && entry.prepackItemId && returnedItemIds.has(entry.prepackItemId)) return;
        if (type === 'Wasted' && entry.prepackItemId && wastedItemIds.has(entry.prepackItemId)) return;
        if (queue && type === 'Returned' && !entry.prepackItemId && selectedItems.some(item => item.inventoryReturned && !item.inventoryWasted && item.medId === entry.medId)) return;
        if (queue && type === 'Wasted' && !entry.prepackItemId && selectedItems.some(item => item.inventoryWasted && item.medId === entry.medId)) return;
        addRow({
            order: type === 'Administered' ? 60 : 55,
            when: commandHistoryEntryWhen(entry) || commandDateTimeText('', entry.scheduledDate, entry.scheduledTime),
            type,
            medName: entry.medName || db.inventory.find(med => med.id === entry.medId)?.name || 'Medication',
            details: entry.details || entry.doseNote || ''
        });
    });
    const unique = new Map();
    rows.forEach(row => {
        const key = `${row.when}|${row.type}|${row.medName}|${row.details}`;
        if (!unique.has(key)) unique.set(key, row);
    });
    return [...unique.values()].sort((a, b) =>
        a.order - b.order ||
        String(a.when || '').localeCompare(String(b.when || '')) ||
        String(a.medName || '').localeCompare(String(b.medName || ''), undefined, { sensitivity: 'base' })
    );
}

function commandScanHistoryRows(scan = activeCommandScan, medId = 'all') {
    if (!scan) return [];
    const queue = commandScanQueue(scan);
    const day = commandScanDay(scan);
    const selectedItems = commandScanItems({ ...scan, medId: medId === 'all' ? '' : medId });
    const itemIds = new Set(selectedItems.map(item => item.id));
    const medIds = new Set(selectedItems.map(item => item.medId).filter(Boolean));
    const rows = [];
    if (queue && day) {
        (day.items || []).forEach(item => {
            if (itemIds.size && !itemIds.has(item.id)) return;
            const med = db.inventory.find(candidate => candidate.id === item.medId);
            if (item.inventoryDeducted || item.scannedAt || item.verificationMethod) {
                rows.push({
                    key: `prep-${item.id}`,
                    when: commandDateTimeText(item.stockDeductedAt || item.scannedAt, firstDateInPrepackDay(day), item.time),
                    type: 'Prepacked',
                    medName: `${item.medName || ''} ${item.strength || ''}`.trim(),
                    details: item.stockLogDetail || `Prepared from ${item.stockSource === 'kit' || item.kitId ? 'med kit' : 'inventory'}.`
                });
            }
            if (item.inventoryReturned && !item.inventoryWasted) {
                rows.push({
                    key: `return-${item.id}`,
                    when: commandDateTimeText(item.returnedAt, firstDateInPrepackDay(day), item.time),
                    type: 'Returned',
                    medName: `${item.medName || ''} ${item.strength || ''}`.trim(),
                    details: prepackReturnDetailText(item, med)
                });
            }
            if (item.inventoryWasted) {
                rows.push({
                    key: `waste-${item.id}`,
                    when: commandDateTimeText(item.wastedAt || item.returnedAt, firstDateInPrepackDay(day), item.time),
                    type: 'Wasted',
                    medName: `${item.medName || ''} ${item.strength || ''}`.trim(),
                    details: item.wasteReason || item.returnReason || 'Wasted.'
                });
            }
        });
    }
    const returnedItemIds = new Set(selectedItems.filter(item => item.inventoryReturned && !item.inventoryWasted).map(item => item.id));
    const wastedItemIds = new Set(selectedItems.filter(item => item.inventoryWasted).map(item => item.id));
    (db.history || []).forEach(entry => {
        if (queue && entry.prepackQueueId !== queue.id) {
            const sameDay = day && entry.memberId === queue.memberId && String(entry.scheduledDate || historyEntryDateKey(entry) || '').slice(0, 10) === firstDateInPrepackDay(day);
            if (!sameDay) return;
        }
        if (scan.memberId && entry.memberId && entry.memberId !== scan.memberId) return;
        if (itemIds.size && entry.prepackItemId && !itemIds.has(entry.prepackItemId)) return;
        if (medIds.size && entry.medId && !medIds.has(entry.medId)) return;
        if (!queue && medIds.size && !medIds.has(entry.medId)) return;
        if (!queue && scan.memberId && entry.memberId !== scan.memberId) return;
        const type = commandHistoryActionType(entry);
        if (type === 'Returned' && entry.prepackItemId && returnedItemIds.has(entry.prepackItemId)) return;
        if (type === 'Wasted' && entry.prepackItemId && wastedItemIds.has(entry.prepackItemId)) return;
        if (queue && type === 'Returned' && !entry.prepackItemId && selectedItems.some(item => item.inventoryReturned && !item.inventoryWasted && item.medId === entry.medId)) return;
        if (queue && type === 'Wasted' && !entry.prepackItemId && selectedItems.some(item => item.inventoryWasted && item.medId === entry.medId)) return;
        rows.push({
            key: `history-${entry.id}`,
            when: commandHistoryEntryWhen(entry) || commandDateTimeText('', entry.scheduledDate, entry.scheduledTime),
            type,
            medName: entry.medName || db.inventory.find(med => med.id === entry.medId)?.name || 'Medication',
            details: entry.details || entry.doseNote || ''
        });
    });
    const unique = new Map();
    rows.forEach(row => {
        const key = `${row.when}|${row.type}|${row.medName}|${row.details}`;
        if (!unique.has(key)) unique.set(key, row);
    });
    return [...unique.values()].sort((a, b) => String(b.when || '').localeCompare(String(a.when || '')));
}

function isInventoryUnitDoseQueue(queue) {
    return queue?.selection?.kind === 'inventory-unit-dose';
}

function inventoryUnitDoseDefinition(med, values = {}) {
    const prepDate = values.prepDate || localDateKey();
    const prepTime = values.prepTime || '08:00';
    const qtyPerContainer = parseAmount(values.qtyPerContainer, 0);
    const containerCount = Math.max(1, parseInt(values.containerCount, 10) || 1);
    const containerType = values.containerType || 'container';
    const labelName = String(values.labelName || '').trim();
    const instructions = String(values.instructions || '').trim();
    const expirationDate = values.expirationDate || '';
    const prepackedBarcodeCode = values.prepackedBarcodeCode || createMedicationCode();
    const stockUnit = inventoryUnitFor(med);
    const giveUnit = med.administrationUnit || med.formulation || stockUnit || 'unit';
    const strength = formatLabelMedStrength(med);
    const dose = formatPrescribedDose(med, qtyPerContainer);
    const sourceLabel = `${labelName || med.name} | ${containerCount} ${containerType}${containerCount === 1 ? '' : 's'} | ${formatAmount(qtyPerContainer)} ${giveUnit} each${expirationDate ? ` | exp ${expirationDate}` : ''}`;
    const prepUnitName = String(containerType || 'container').replace(/^prefilled\s+/i, '');
    const items = Array.from({ length: containerCount }, (_, index) => ({
        id: prepackItemId(),
        medId: med.id,
        medName: med.name,
        strength,
        quantity: `${formatAmount(qtyPerContainer)} ${giveUnit}`,
        dose,
        instructions,
        time: `${prepUnitName} ${index + 1}`,
        barcodeCode: medicationCodes(med)[0] || '',
        status: 'pending',
        inventoryUnitDose: true,
        containerType,
        expirationDate,
        prepackedBarcodeCode
    }));
    return {
        memberId: '',
        memberName: 'Inventory Unit Dose',
        title: labelName || `${med.name} ${strength}`.trim(),
        sourceLabel,
        selection: {
            kind: 'inventory-unit-dose',
            batchId: `unitdose_${Date.now()}_${Math.random().toString(16).slice(2)}`,
            medId: med.id,
            startDate: prepDate,
            endDate: prepDate,
            prepDate,
            prepTime,
            qtyPerContainer,
            containerCount,
            containerType,
            expirationDate,
            prepackedBarcodeCode,
            labelName,
            instructions
        },
        days: [{
            date: prepDate,
            status: 'pending',
            needsReprint: false,
            items
        }]
    };
}

function preparedUnitDoseInventoryName(sourceMed, queue) {
    const labelName = String(queue.selection?.labelName || '').trim();
    const containerType = queue.selection?.containerType || 'container';
    return labelName || `${sourceMed.name} ${containerType}`;
}

function buildPreparedUnitDoseInventoryItem(sourceMed, queue, totalQty) {
    const qtyPerContainer = parseAmount(queue.selection.qtyPerContainer, 0);
    const preparedCount = preparedInventoryUnitDoseCount(queue);
    const containerCount = Math.max(1, preparedCount || parseInt(queue.selection.containerCount, 10) || 1);
    const containerType = queue.selection.containerType || 'container';
    const expirationDate = queue.selection.expirationDate || '';
    const prepDate = queue.selection.prepDate || queue.days?.[0]?.date || localDateKey();
    const prepTime = queue.selection.prepTime || (queue.scheduledFor || '').slice(11, 16) || '';
    const sourceUnit = sourceMed.administrationUnit || sourceMed.formulation || inventoryUnitFor(sourceMed) || 'unit';
    const barcodeCode = normalizeMedicationCode(queue.selection.prepackedBarcodeCode) || createMedicationCode();
    const isCombo = sourceMed.isCombination && Array.isArray(sourceMed.components) && sourceMed.components.length > 0;
    const calculatedDose = formatPrescribedDose(sourceMed, qtyPerContainer);
    const doseUnit = String(calculatedDose || '').match(/[a-zA-Z%/]+/)?.[0] || String(sourceMed.units || '').split('/')[0] || sourceMed.activeUnit || sourceMed.units || '';
    const doseAmount = parseAmount(calculatedDose, NaN);
    const components = isCombo
        ? sourceMed.components.map(component => ({
            ...component,
            strength: parseAmount(component.strength, 0) * qtyPerContainer,
            strengthAmount: parseAmount(component.strength, 0) * qtyPerContainer,
            perAmount: 1,
            perUnit: containerType
        }))
        : [];
    const name = preparedUnitDoseInventoryName(sourceMed, queue);
    const displayStrength = isCombo
        ? formatCombinationStrength({ ...sourceMed, components }, false, false)
        : (Number.isFinite(doseAmount) && doseUnit ? `${formatAmount(doseAmount)}${doseUnit}` : formatLabelMedStrength(sourceMed));
    return {
        id: `unitdose_${Date.now()}_${Math.random().toString(16).slice(2)}`,
        name,
        strength: Number.isFinite(doseAmount) ? doseAmount : sourceMed.strength,
        units: isCombo ? sourceMed.units : (doseUnit || sourceMed.units || ''),
        displayStrength,
        strengthAmount: isCombo ? null : (Number.isFinite(doseAmount) ? doseAmount : sourceMed.strengthAmount),
        activeUnit: isCombo ? null : (doseUnit || sourceMed.activeUnit || sourceMed.units || ''),
        perAmount: isCombo ? null : 1,
        perUnit: isCombo ? null : containerType,
        formulation: 'Other',
        inventoryUnit: containerType,
        administrationUnit: containerType,
        inventoryBehavior: 'per-dose',
        stock: containerCount,
        maxCapacity: containerCount,
        expiry: expirationDate,
        storage: sourceMed.storage || 'N/A',
        controlLevel: sourceMed.controlLevel || 'N/A',
        isLiquid: false,
        isCombination: isCombo,
        components,
        minThreshold: 1,
        prescriberId: sourceMed.prescriberId || '',
        assignedMemberIds: Array.isArray(sourceMed.assignedMemberIds) ? [...sourceMed.assignedMemberIds] : [],
        barcodeCode,
        barcodeCodes: [barcodeCode],
        imagePath: sourceMed.imagePath || '',
        sourceInventoryId: sourceMed.id,
        prepackedFrom: sourceMed.name,
        prepackQueueId: queue.id,
        notes: [
            `Prepacked from inventory: ${sourceMed.name} ${formatLabelMedStrength(sourceMed)}`,
            `Each ${containerType} contains ${formatAmount(qtyPerContainer)} ${sourceUnit}.`,
            `Calculated dose per ${containerType}: ${calculatedDose || displayStrength}.`,
            `Prepared: ${prepDate}${prepTime ? ` ${prepTime}` : ''}.`,
            `Source stock used: ${formatAmount(totalQty)} ${sourceUnit}.`,
            queue.selection.instructions ? `Instructions: ${queue.selection.instructions}` : ''
        ].filter(Boolean).join('\n')
    };
}

function preparedInventoryUnitDoseCount(queue) {
    return (queue.days || []).reduce((sum, day) =>
        sum + (day.items || []).filter(item => item.inventoryDeducted === true).length,
    0);
}

function ensurePreparedInventoryForUnitDose(queue, sourceMed) {
    const existing = queue.prepackedInventoryId
        ? db.inventory.find(item => item.id === queue.prepackedInventoryId)
        : null;
    if (existing) return existing;
    const preparedItem = buildPreparedUnitDoseInventoryItem(sourceMed, queue, 0);
    preparedItem.stock = 0;
    preparedItem.maxCapacity = Math.max(0, parseInt(queue.selection.containerCount, 10) || 0);
    db.inventory.push(preparedItem);
    queue.prepackedInventoryId = preparedItem.id;
    return preparedItem;
}

function applyInventoryUnitDoseItemStock(queue, item, method = 'scan') {
    if (!isInventoryUnitDoseQueue(queue) || !item || item.inventoryDeducted === true) return true;
    const sourceMed = db.inventory.find(candidate => candidate.id === queue.selection.medId);
    if (!sourceMed) return false;
    const qtyPerContainer = parseAmount(queue.selection.qtyPerContainer, 0);
    if (!Number.isFinite(qtyPerContainer) || qtyPerContainer <= 0) return false;
    if (parseAmount(sourceMed.stock, 0) < qtyPerContainer) return false;
    const preparedItem = ensurePreparedInventoryForUnitDose(queue, sourceMed);
    sourceMed.stock = Math.max(0, parseAmount(sourceMed.stock, 0) - qtyPerContainer);
    preparedItem.stock = parseAmount(preparedItem.stock, 0) + 1;
    if (parseAmount(preparedItem.stock, 0) > parseAmount(preparedItem.maxCapacity, 0)) preparedItem.maxCapacity = preparedItem.stock;
    preparedItem.notes = buildPreparedUnitDoseInventoryItem(sourceMed, queue, qtyPerContainer * parseAmount(preparedItem.stock, 0)).notes;
    item.inventoryDeducted = true;
    item.preparedInventoryId = preparedItem.id;
    db.history.unshift({
        id: Date.now().toString(),
        timestamp: new Date().toLocaleString(),
        medId: sourceMed.id,
        medName: sourceMed.name,
        details: `${item.time} verified by ${method}; -${formatAmount(qtyPerContainer)} ${sourceMed.administrationUnit || inventoryUnitFor(sourceMed)} source stock; +1 ${inventoryUnitFor(preparedItem)} prepared inventory.`
    });
    addAudit('Inventory unit-dose container prepped', sourceMed.name, `${item.time} | -${formatAmount(qtyPerContainer)} ${sourceMed.administrationUnit || inventoryUnitFor(sourceMed)} | +1 ${inventoryUnitFor(preparedItem)}.`);
    return true;
}

function reverseInventoryUnitDoseItemStock(queue, item) {
    if (!isInventoryUnitDoseQueue(queue) || !item?.inventoryDeducted) return;
    const sourceMed = db.inventory.find(candidate => candidate.id === queue.selection.medId);
    const preparedItem = db.inventory.find(candidate => candidate.id === (item.preparedInventoryId || queue.prepackedInventoryId));
    const qtyPerContainer = parseAmount(queue.selection.qtyPerContainer, 0);
    if (sourceMed && Number.isFinite(qtyPerContainer) && qtyPerContainer > 0) {
        sourceMed.stock = parseAmount(sourceMed.stock, 0) + qtyPerContainer;
    }
    if (preparedItem) {
        preparedItem.stock = Math.max(0, parseAmount(preparedItem.stock, 0) - 1);
        if (sourceMed) preparedItem.notes = buildPreparedUnitDoseInventoryItem(sourceMed, queue, qtyPerContainer * parseAmount(preparedItem.stock, 0)).notes;
    }
    db.history.unshift({
        id: Date.now().toString(),
        timestamp: new Date().toLocaleString(),
        medId: sourceMed?.id || item.medId,
        medName: sourceMed?.name || item.medName,
        details: `${item.time} removed from unit-dose prepack; returned ${formatAmount(qtyPerContainer)} ${sourceMed?.administrationUnit || (sourceMed ? inventoryUnitFor(sourceMed) : 'units')} to source stock.`
    });
}

function prepackItemDoseQty(queue, item) {
    const schedule = db.schedules.find(candidate => candidate.id === item?.scheduleId);
    if (String(item?.instanceKey || '').startsWith('range|')) return parseAmount(item.quantity, 0);
    return parseAmount(schedule?.doseQty ?? item?.quantity, 0);
}

function isRangePrepackItem(item) {
    return String(item?.instanceKey || '').startsWith('range|');
}

function prepackItemRangeBounds(day, item) {
    const parts = String(item?.instanceKey || '').split('|');
    if (parts[0] === 'range') {
        return {
            start: parts[2] || firstDateInPrepackDay(day),
            end: parts[3] || parts[2] || lastDateInPrepackDay(day)
        };
    }
    return {
        start: firstDateInPrepackDay(day),
        end: lastDateInPrepackDay(day) || firstDateInPrepackDay(day)
    };
}

function rangePrepackGivenQty(queue, day, item) {
    if (!isRangePrepackItem(item) || !item?.scheduleId) return 0;
    const schedule = prepackItemSchedule(item);
    const med = db.inventory.find(candidate => candidate.id === item.medId);
    const range = prepackItemRangeBounds(day, item);
    return db.history.reduce((sum, entry) => {
        if (!isGivenAdministrationHistory(entry)) return sum;
        const exactPrepackMatch = entry.prepackQueueId === queue?.id && entry.prepackItemId === item.id;
        if (!exactPrepackMatch) {
            if (entry.scheduleId !== item.scheduleId) return sum;
            if (queue?.memberId && entry.memberId && entry.memberId !== queue.memberId) return sum;
            if (item.medId && entry.medId && entry.medId !== item.medId) return sum;
            const entryDate = String(entry.scheduledDate || historyEntryDateKey(entry) || '').slice(0, 10);
            if (!entryDate || (range.start && entryDate < range.start) || (range.end && entryDate > range.end)) return sum;
        }
        const qty = parseAmount(entry.stockDelta, NaN);
        if (Number.isFinite(qty) && qty > 0) return sum + qty;
        return sum + parseAmount(schedule?.doseQty ?? item.dose ?? 0, 0);
    }, 0);
}

function prepackItemReturnableQty(row) {
    const { queue, day, item } = row || {};
    if (!item) return 0;
    const total = parseAmount(item.stockDelta, NaN);
    const packedQty = Number.isFinite(total) && total > 0 ? total : prepackItemDoseQty(queue, item);
    const alreadyReturned = parseAmount(item.returnedQuantity, 0);
    const givenQty = isRangePrepackItem(item) ? rangePrepackGivenQty(queue, day, item) : 0;
    return normalizeNumberForDisplay(Math.max(0, packedQty - givenQty - alreadyReturned));
}

function prepackStockShortagesForItems(queue, items = []) {
    if (isInventoryUnitDoseQueue(queue)) return [];
    const stockLedger = new Map();
    const shortages = [];
    items.forEach(item => {
        if (!item || item.inventoryDeducted === true || item.inventoryReturned === true) return;
        const med = db.inventory.find(candidate => candidate.id === item.medId);
        if (!med) {
            shortages.push(`${item.medName || 'Medication'} is no longer in inventory.`);
            return;
        }
        if (usesContainerTracking(med)) return;
        const qty = prepackItemDoseQty(queue, item);
        if (!Number.isFinite(qty) || qty <= 0) {
            shortages.push(`${med.name} does not have a valid prepack quantity.`);
            return;
        }
        const sourceValue = item.inventorySource || 'main';
        const kitSource = medKitSourceFromValue(sourceValue, med.id);
        const sourceKey = kitSource ? `kit|${kitSource.kitId}|${kitSource.itemId}` : `main|${med.id}`;
        const sourceQty = kitSource ? parseAmount(kitSource.item.qty, 0) : parseAmount(med.stock, 0);
        const sourceLabel = kitSource ? medKitName(kitSource.kit) : 'main inventory';
        const remaining = stockLedger.has(sourceKey) ? stockLedger.get(sourceKey) : sourceQty;
        if (remaining < qty) {
            shortages.push(`${med.name} needs ${formatAmount(qty)} ${med.administrationUnit || inventoryUnitFor(med)} from ${sourceLabel}, but only ${formatAmount(Math.max(0, remaining))} is available.`);
            return;
        }
        stockLedger.set(sourceKey, remaining - qty);
    });
    return shortages;
}

function prepackTogetherGroupItems(day, item) {
    if (!day || !item?.scheduleId) return item ? [item] : [];
    const grouped = new Set([item.id]);
    let changed = true;
    while (changed) {
        changed = false;
        (day.items || []).forEach(candidate => {
            if (!candidate?.scheduleId || grouped.has(candidate.id)) return;
            if (candidate.time !== item.time) return;
            const candidateSchedule = db.schedules.find(schedule => schedule.id === candidate.scheduleId);
            if (!candidateSchedule) return;
            const linkedToGroup = (day.items || []).some(groupItem => {
                if (!grouped.has(groupItem.id)) return false;
                const groupSchedule = db.schedules.find(schedule => schedule.id === groupItem.scheduleId);
                return groupSchedule && scheduleLinkModeBetween(groupSchedule, candidateSchedule) === 'together';
            });
            if (linkedToGroup) {
                grouped.add(candidate.id);
                changed = true;
            }
        });
    }
    return (day.items || []).filter(candidate => grouped.has(candidate.id));
}

function prepackLinkedPrimaryScore(item, groupItems) {
    const schedule = prepackItemSchedule(item);
    if (!schedule) return 0;
    const groupSchedules = groupItems
        .map(candidate => prepackItemSchedule(candidate))
        .filter(Boolean);
    const directTogetherLinks = scheduleLinkRules(schedule)
        .filter(rule => rule.mode === 'together' && groupSchedules.some(target =>
            target.id !== schedule.id && scheduleRuleTargets(rule, target, schedule)
        )).length;
    const connectedTogetherLinks = groupSchedules
        .filter(target => target.id !== schedule.id && scheduleLinkModeBetween(schedule, target) === 'together')
        .length;
    return (directTogetherLinks * 10) + connectedTogetherLinks;
}

function prepackLinkedPrimaryItem(groupItems) {
    return groupItems.slice().sort((a, b) =>
        prepackLinkedPrimaryScore(b, groupItems) - prepackLinkedPrimaryScore(a, groupItems) ||
        timeToMinutes(a.time) - timeToMinutes(b.time) ||
        String(a.medName || '').localeCompare(String(b.medName || ''), undefined, { sensitivity: 'base' })
    )[0] || groupItems[0];
}

function applyPrepackStockForReadyGroup(queue, day, item, method = 'scan') {
    const groupItems = prepackTogetherGroupItems(day, item);
    const pendingGroupItems = groupItems.filter(candidate => candidate.status !== 'correct');
    if (pendingGroupItems.length > 0) return true;
    const shortages = prepackStockShortagesForItems(queue, groupItems);
    if (shortages.length) return false;
    return groupItems.every(candidate => applyPrepackItemStock(queue, candidate, method));
}

function applyPrepackItemStock(queue, item, method = 'scan') {
    if (isInventoryUnitDoseQueue(queue)) return applyInventoryUnitDoseItemStock(queue, item, method);
    if (!queue || !item || item.inventoryDeducted === true || item.inventoryReturned === true) return true;
    const med = db.inventory.find(candidate => candidate.id === item.medId);
    if (!med) return false;
    if (usesContainerTracking(med)) {
        item.inventoryDeducted = true;
        item.stockDelta = 0;
        item.stockLogDetail = `${inventoryUnitFor(med)} inventory will be reduced only when the container is marked finished.`;
        return true;
    }
    const qty = prepackItemDoseQty(queue, item);
    if (!Number.isFinite(qty) || qty <= 0) return false;
    if (item.inventorySource && item.inventorySource !== 'main') {
        const kitResult = consumeFromKitSource(item.inventorySource, med, qty);
        if (kitResult.error) return false;
        item.inventoryDeducted = true;
        item.stockDelta = qty;
        item.stockSource = 'kit';
        item.kitId = kitResult.kitId || '';
        item.kitItemId = kitResult.kitItemId || '';
        item.kitExpiry = kitResult.kitItem?.expiry || med.expiry || '';
        item.stockDeductedAt = new Date().toISOString();
        item.stockDeductionMethod = method;
        item.stockLogDetail = `Prepacked ${formatAmount(qty)} ${med.administrationUnit || inventoryUnitFor(med)} from ${kitResult.sourceLabel}.`;
        db.history.unshift({
            id: Date.now().toString(),
            timestamp: new Date().toLocaleString(),
            memberId: queue.memberId || '',
            memberName: queue.memberName || '',
            medId: med.id,
            medName: med.name,
            scheduleId: item.scheduleId || '',
            prepackQueueId: queue.id,
            prepackItemId: item.id,
            stockSource: 'kit',
            kitId: item.kitId,
            kitItemId: item.kitItemId,
            details: `${item.time} prepacked by ${method}; -${formatAmount(qty)} ${med.administrationUnit || inventoryUnitFor(med)} from ${kitResult.sourceLabel}.`
        });
        addAudit('Prepack kit stock deducted', med.name, `${queue.memberName || 'Prepack'} | ${item.time} | -${formatAmount(qty)} ${med.administrationUnit || inventoryUnitFor(med)} from ${kitResult.sourceLabel}.`);
        return true;
    }
    if (parseAmount(med.stock, 0) < qty) return false;
    med.stock = Math.max(0, parseAmount(med.stock, 0) - qty);
    item.inventoryDeducted = true;
    item.stockDelta = qty;
    item.stockSource = 'main';
    item.stockDeductedAt = new Date().toISOString();
    item.stockDeductionMethod = method;
    item.stockLogDetail = `Prepacked ${formatAmount(qty)} ${med.administrationUnit || inventoryUnitFor(med)} from inventory.`;
    db.history.unshift({
        id: Date.now().toString(),
        timestamp: new Date().toLocaleString(),
        memberId: queue.memberId || '',
        memberName: queue.memberName || '',
        medId: med.id,
        medName: med.name,
        scheduleId: item.scheduleId || '',
        prepackQueueId: queue.id,
        prepackItemId: item.id,
        details: `${item.time} prepacked by ${method}; -${formatAmount(qty)} ${med.administrationUnit || inventoryUnitFor(med)} source stock.`
    });
    addAudit('Prepack stock deducted', med.name, `${queue.memberName || 'Prepack'} | ${item.time} | -${formatAmount(qty)} ${med.administrationUnit || inventoryUnitFor(med)}.`);
    return true;
}

function reversePrepackItemStock(queue, item, reason = 'returned', quantityOverride = null) {
    if (isInventoryUnitDoseQueue(queue)) {
        reverseInventoryUnitDoseItemStock(queue, item);
        item.inventoryReturned = true;
        item.returnReason = reason;
        return;
    }
    if (!queue || !item?.inventoryDeducted || item.inventoryReturned === true) return;
    const med = db.inventory.find(candidate => candidate.id === item.medId);
    const maxQty = parseAmount(item.stockDelta, 0);
    const requestedQty = parseAmount(quantityOverride, NaN);
    const alreadyReturned = parseAmount(item.returnedQuantity, 0);
    const qty = Number.isFinite(requestedQty) && requestedQty > 0
        ? Math.min(requestedQty, Math.max(0, maxQty - alreadyReturned))
        : Math.max(0, maxQty - alreadyReturned);
    if (item.stockSource === 'kit' || item.kitId) {
        if (med && qty > 0) restoreQuantityToKit(item, med, qty);
    } else if (med && qty > 0) {
        med.stock = parseAmount(med.stock, 0) + qty;
    }
    item.returnedQuantity = alreadyReturned + qty;
    item.inventoryReturned = !isRangePrepackItem(item) || item.returnedQuantity >= maxQty - 0.000001;
    item.returnReason = reason;
    item.returnedAt = new Date().toISOString();
    const destination = item.stockSource === 'kit' || item.kitId ? 'med kit' : 'main inventory';
    const unit = med?.administrationUnit || (med ? inventoryUnitFor(med) : 'units');
    const actual = defaultActualDateTime();
    db.history.unshift({
        id: Date.now().toString(),
        timestamp: `${actual.date} ${actual.time}`,
        memberId: queue.memberId || '',
        memberName: queue.memberName || '',
        medId: med?.id || item.medId,
        medName: med?.name || item.medName,
        scheduleId: item.scheduleId || '',
        prepackQueueId: queue.id,
        prepackItemId: item.id,
        details: `Returned ${formatAmount(qty)} ${unit} to ${destination}; reason: ${reason}.`
    });
    if (med) addAudit('Prepack stock returned', med.name, `${queue.memberName || 'Prepack'} | ${item.time} | ${reason} | +${formatAmount(qty)} ${med.administrationUnit || inventoryUnitFor(med)} to ${destination}.`);
    return qty;
}

function undoPrepackItemStock(queue, item, reason = 'prepack undone') {
    if (!queue || !item) return 0;
    let qty = 0;
    if (isInventoryUnitDoseQueue(queue)) {
        if (item.inventoryDeducted && !item.inventoryReturned && !item.inventoryWasted) {
            reverseInventoryUnitDoseItemStock(queue, item);
            qty = parseAmount(queue.selection?.qtyPerContainer, 0);
        }
    } else if (item.inventoryDeducted && !item.inventoryReturned && !item.inventoryWasted) {
        const med = db.inventory.find(candidate => candidate.id === item.medId);
        qty = parseAmount(item.stockDelta, 0);
        if (med && qty > 0 && (item.stockSource === 'kit' || item.kitId)) {
            restoreQuantityToKit(item, med, qty);
            db.history.unshift({
                id: Date.now().toString(),
                timestamp: new Date().toLocaleString(),
                memberId: queue.memberId || '',
                memberName: queue.memberName || '',
                medId: med.id,
                medName: med.name,
                scheduleId: item.scheduleId || '',
                prepackQueueId: queue.id,
                prepackItemId: item.id,
                details: `Prepack undone; +${formatAmount(qty)} ${med.administrationUnit || inventoryUnitFor(med)} returned to med kit.`
            });
            addAudit('Prepack undone', med.name, `${queue.memberName || 'Prepack'} | ${item.time} | +${formatAmount(qty)} ${med.administrationUnit || inventoryUnitFor(med)} to med kit.`);
        } else if (med && qty > 0) {
            med.stock = parseAmount(med.stock, 0) + qty;
            db.history.unshift({
                id: Date.now().toString(),
                timestamp: new Date().toLocaleString(),
                memberId: queue.memberId || '',
                memberName: queue.memberName || '',
                medId: med.id,
                medName: med.name,
                scheduleId: item.scheduleId || '',
                prepackQueueId: queue.id,
                prepackItemId: item.id,
                details: `Prepack undone; +${formatAmount(qty)} ${med.administrationUnit || inventoryUnitFor(med)} returned to inventory.`
            });
            addAudit('Prepack undone', med.name, `${queue.memberName || 'Prepack'} | ${item.time} | +${formatAmount(qty)} ${med.administrationUnit || inventoryUnitFor(med)}.`);
        }
    }
    item.status = 'pending';
    item.scannedCode = '';
    item.scannedAt = '';
    item.verificationMethod = '';
    item.inventoryDeducted = false;
    item.stockDelta = 0;
    item.stockSource = '';
    item.kitId = '';
    item.kitItemId = '';
    item.kitExpiry = '';
    item.stockDeductedAt = '';
    item.stockDeductionMethod = '';
    item.stockLogDetail = '';
    item.inventoryReturned = false;
    item.returnedQuantity = 0;
    item.returnedAt = '';
    item.returnReason = '';
    item.returnNote = '';
    item.inventoryWasted = false;
    item.wastedAt = '';
    item.wasteReason = '';
    item.wasteNote = '';
    item.recordOnlyReturn = false;
    return qty;
}

const returnPrepackCutoffDate = '2026-08-04';

function firstDateInPrepackDay(day) {
    const match = String(day?.date || '').match(/\d{4}-\d{2}-\d{2}/);
    return match ? match[0] : '';
}

function lastDateInPrepackDay(day) {
    const matches = String(day?.date || '').match(/\d{4}-\d{2}-\d{2}/g) || [];
    return matches[matches.length - 1] || matches[0] || '';
}

function isReturnablePrepackDate(day) {
    const date = firstDateInPrepackDay(day);
    return !!date && date > returnPrepackCutoffDate;
}

function isPreparedPrepackItem(item) {
    return item?.status === 'correct' ||
        item?.inventoryDeducted === true ||
        ['manual', 'scan'].includes(String(item?.verificationMethod || '').toLowerCase()) ||
        !!item?.scannedAt;
}

function normalizeRecordOnlyPrepackReturnFlags() {
    let changed = false;
    (db.prepackQueues || []).forEach(queue => {
        if (isInventoryUnitDoseQueue(queue)) return;
        (queue.days || []).forEach(day => {
            (day.items || []).forEach(item => {
                if (item.inventoryReturned && !item.inventoryDeducted && !item.inventoryWasted && !item.recordOnlyReturn) {
                    item.inventoryReturned = false;
                    item.returnReason = '';
                    item.returnedAt = '';
                    item.returnNote = '';
                    changed = true;
                }
            });
        });
    });
    return changed;
}

function prepackItemSchedule(item) {
    return item?.scheduleId ? db.schedules.find(schedule => schedule.id === item.scheduleId) : null;
}

function prepackItemHasDocumentedGivenDose(queue, day, item) {
    if (!item?.scheduleId) return false;
    if (isRangePrepackItem(item)) return false;
    if ((db.history || []).some(entry =>
        entry.prepackQueueId === queue?.id &&
        entry.prepackItemId === item.id &&
        isGivenAdministrationHistory(entry)
    )) return true;
    const sameScheduleItemsThisDay = (day?.items || []).filter(candidate =>
        candidate.scheduleId === item.scheduleId &&
        candidate.medId === item.medId &&
        !isRangePrepackItem(candidate)
    ).length;
    const exactKey = item.instanceKey && !String(item.instanceKey).startsWith('range|')
        ? item.instanceKey
        : (day?.date && item.time && !String(day.date).includes(' - ') && !String(item.time).includes(' - ')
            ? scheduleInstanceKey(item.scheduleId, day.date, item.time)
            : '');
    if (exactKey) {
        if (db.history.some(entry => entry.scheduleInstanceKey === exactKey && isGivenAdministrationHistory(entry))) return true;
    }
    const fallbackStart = firstDateInPrepackDay(day);
    const fallbackEnd = lastDateInPrepackDay(day) || fallbackStart;
    return db.history.some(entry => {
        if (!isGivenAdministrationHistory(entry)) return false;
        if (item.scheduleId) {
            if (entry.scheduleId && entry.scheduleId !== item.scheduleId) return false;
            if (!entry.scheduleId && entry.scheduleInstanceKey && !String(entry.scheduleInstanceKey).startsWith(`${item.scheduleId}|`)) return false;
            if (!entry.scheduleId && !entry.scheduleInstanceKey) return false;
        }
        if (queue.memberId && entry.memberId && entry.memberId !== queue.memberId) return false;
        if (item.medId && entry.medId && entry.medId !== item.medId) return false;
        const entryDate = String(entry.scheduledDate || historyEntryDateKey(entry) || '').slice(0, 10);
        if (!entryDate || (fallbackStart && entryDate < fallbackStart) || (fallbackEnd && entryDate > fallbackEnd)) return false;
        const entryTime = String(entry.scheduledTime || '').slice(0, 5);
        const itemTime = String(item.time || '').slice(0, 5);
        if (sameScheduleItemsThisDay <= 1) return true;
        return !itemTime || String(item.time || '').includes(' - ') || !entryTime || entryTime === itemTime;
    });
}

const returnPrepackExceptionStatuses = ['skipped', 'missed', 'refused', 'held'];

function returnPrepackRelevantHistoryEntries(queue, day, item) {
    if (!item?.scheduleId) return [];
    const fallbackStart = firstDateInPrepackDay(day);
    const fallbackEnd = lastDateInPrepackDay(day) || fallbackStart;
    const exactKey = item.instanceKey && !String(item.instanceKey).startsWith('range|')
        ? item.instanceKey
        : (day?.date && item.time && !String(day.date).includes(' - ') && !String(item.time).includes(' - ')
            ? scheduleInstanceKey(item.scheduleId, day.date, item.time)
            : '');
    return (db.history || []).filter(entry => {
        if (entry.prepackQueueId === queue?.id && entry.prepackItemId === item.id) return true;
        if (exactKey && entry.scheduleInstanceKey === exactKey) return true;
        if (entry.scheduleId && entry.scheduleId !== item.scheduleId) return false;
        if (!entry.scheduleId && entry.scheduleInstanceKey && !String(entry.scheduleInstanceKey).startsWith(`${item.scheduleId}|`)) return false;
        if (!entry.scheduleId && !entry.scheduleInstanceKey) return false;
        if (queue?.memberId && entry.memberId && entry.memberId !== queue.memberId) return false;
        if (item.medId && entry.medId && entry.medId !== item.medId) return false;
        const entryDate = String(entry.scheduledDate || historyEntryDateKey(entry) || '').slice(0, 10);
        if (!entryDate || (fallbackStart && entryDate < fallbackStart) || (fallbackEnd && entryDate > fallbackEnd)) return false;
        const entryTime = String(entry.scheduledTime || '').slice(0, 5);
        const itemTime = String(item.time || '').slice(0, 5);
        if (isRangePrepackItem(item)) return true;
        if (!itemTime || String(item.time || '').includes(' - ') || !entryTime) return true;
        return entryTime === itemTime;
    });
}

function returnPrepackDocumentedException(row) {
    return returnPrepackRelevantHistoryEntries(row?.queue, row?.day, row?.item)
        .find(entry => returnPrepackExceptionStatuses.includes(entry.doseStatus));
}

function returnPrepackHasDocumentedWaste(row) {
    return returnPrepackRelevantHistoryEntries(row?.queue, row?.day, row?.item)
        .some(entry => entry.doseStatus === 'wasted');
}

function returnPrepackRowCategory(row) {
    return returnPrepackDocumentedException(row) ? 'exception' : 'unadministered';
}

function markPrepackItemReturned(row, reason = 'returned', note = '', quantityOverride = null) {
    const { queue, day, item, med } = row;
    const requestedQty = parseAmount(quantityOverride, NaN);
    if (item.inventoryDeducted) {
        const returnedQty = reversePrepackItemStock(queue, item, reason, Number.isFinite(requestedQty) && requestedQty > 0 ? requestedQty : null);
        if (note) item.returnNote = note;
        return returnedQty;
    } else {
        item.inventoryReturned = true;
        item.recordOnlyReturn = true;
        item.returnReason = reason;
        item.returnedAt = new Date().toISOString();
        const actual = defaultActualDateTime();
        db.history.unshift({
            id: Date.now().toString(),
            timestamp: `${actual.date} ${actual.time}`,
            memberId: queue.memberId || '',
            memberName: queue.memberName || '',
            medId: med?.id || item.medId,
            medName: med?.name || item.medName,
            scheduleId: item.scheduleId || '',
            prepackQueueId: queue.id,
            prepackItemId: item.id,
            details: `Prepared prepack item marked returned (${reason}); no inventory quantity was added because this older/prepared record was not marked as deducted from stock.`
        });
        if (med) addAudit('Prepack item returned', med.name, `${queue.memberName || 'Prepack'} | ${day?.date || ''} ${item.time || ''} | no stock change.`);
    }
    if (note) item.returnNote = note;
    return 0;
}

function returnPrepackUnitLabel(row, qtyReturned) {
    const med = row.med || db.inventory.find(candidate => candidate.id === row.item?.medId);
    if (!med) return '';
    const labelCode = medicationCodes(med)[0] || row.item?.barcodeCode || '';
    const barcodeDataUrl = medicationQrDataUrl(labelCode);
    const unit = med.administrationUnit || inventoryUnitFor(med);
    const returnedDate = localDateKey();
    const qtyText = `${formatAmount(qtyReturned)} ${unit || 'unit(s)'}`;
    const labelClass = getLabelClass([
        med.name,
        formatLabelMedStrength(med),
        qtyText,
        med.expiry || '',
        returnedDate,
        med.storage || '',
        med.instructions || med.notes || ''
    ], med.instructions || med.notes ? 7 : 6);
    return `<div class="${labelClass} inventory-return-label">
        <div class="label-title">${escapeHtml(med.name)} ${escapeHtml(formatLabelMedStrength(med))}</div>
        <div class="label-small"><b>Qty returned:</b> ${escapeHtml(qtyText)}</div>
        <div class="label-small"><b>Exp:</b> ${escapeHtml(med.expiry || 'N/A')}</div>
        <div class="label-small"><b>Returned:</b> ${escapeHtml(returnedDate)}</div>
        <div class="label-small"><b>Storage:</b> ${escapeHtml(med.storage || 'N/A')}</div>
        ${med.instructions ? `<div class="label-small"><b>Instructions:</b> ${escapeHtml(med.instructions)}</div>` : ''}
        ${!med.instructions && med.notes ? `<div class="label-small"><b>Notes:</b> ${escapeHtml(med.notes)}</div>` : ''}
        ${barcodeDataUrl ? `<img class="inventory-return-label-code" src="${barcodeDataUrl}" alt="Inventory QR code">` : ''}
    </div>`;
}

function aggregateReturnPrepackLabels(labelRows = []) {
    const grouped = new Map();
    labelRows.forEach(entry => {
        const med = entry.row?.med || db.inventory.find(candidate => candidate.id === entry.row?.item?.medId);
        if (!med) return;
        const key = med.id || `${med.name}|${formatLabelMedStrength(med)}`;
        const existing = grouped.get(key) || { row: { ...entry.row, med }, qty: 0 };
        existing.qty += parseAmount(entry.qty, 0);
        grouped.set(key, existing);
    });
    return [...grouped.values()]
        .sort((a, b) => String(a.row.med?.name || '').localeCompare(String(b.row.med?.name || ''), undefined, { sensitivity: 'base' }))
        .map(entry => returnPrepackUnitLabel(entry.row, entry.qty))
        .join('');
}

function markPrepackItemWasted(row, reason = 'wasted', note = '') {
    const { queue, day, item, med } = row;
    if (!queue || !item) return;
    item.inventoryReturned = true;
    item.inventoryWasted = true;
    item.wasteReason = reason;
    item.returnReason = `wasted: ${reason}`;
    item.returnedAt = new Date().toISOString();
    item.wastedAt = item.returnedAt;
    if (note) item.returnNote = note;
    const qty = parseAmount(item.stockDelta, 0);
    db.history.unshift({
        id: Date.now().toString(),
        timestamp: new Date().toLocaleString(),
        memberId: queue.memberId || '',
        memberName: queue.memberName || '',
        medId: med?.id || item.medId,
        medName: med?.name || item.medName,
        scheduleId: item.scheduleId || '',
        prepackQueueId: queue.id,
        prepackItemId: item.id,
        doseStatus: 'wasted',
        details: `Prepacked dose wasted (${reason}); no inventory quantity returned${qty > 0 ? `; ${formatAmount(qty)} ${med?.administrationUnit || (med ? inventoryUnitFor(med) : 'units')} remains deducted` : ''}.${note ? ` Note: ${note}` : ''}`
    });
    if (med) addAudit('Prepack dose wasted', med.name, `${queue.memberName || 'Prepack'} | ${day?.date || ''} ${item.time || ''} | ${reason} | no stock return.`);
}

function markPrepackCoveredDoseWasted(schedule, actual, historyEntry = null, reason = 'wasted') {
    if (!schedule || !actual) return false;
    const med = db.inventory.find(item => item.id === schedule.medId);
    const scheduledDate = actual.scheduledDate || actual.actualDate || '';
    const scheduledTime = actual.scheduledTime || actual.actualTime || '';
    const covered = prepackedDoseCovers(schedule.id, scheduledDate, scheduledTime, med);
    if (!covered) return false;
    markPrepackItemWasted(covered, reason, actual.doseNote || '');
    if (historyEntry) {
        historyEntry.prepackQueueId = covered.queue?.id || '';
        historyEntry.prepackItemId = covered.item?.id || '';
        historyEntry.stockSource = 'prepack';
        historyEntry.stockLogDetail = 'Prepared prepack dose marked wasted; inventory remains deducted';
        historyEntry.details = `${doseStatusLabel(historyEntry.doseStatus || 'wasted')}; scheduled ${scheduledDate || ''} ${scheduledTime || ''}; Prepared prepack dose marked wasted via ${historyEntry.sourceLabel || 'Schedule'}${actual.doseNote ? `; Note: ${actual.doseNote}` : ''}`;
    }
    return true;
}

function prepackItemMatchesCurrentSchedule(item, schedule, med) {
    if (!item || !schedule || !med) return false;
    if (item.scheduleId !== schedule.id) return false;
    if (item.medId && item.medId !== med.id) return false;
    const normalizedPackedText = value => normalizeSlashPartsText(value).replace(/\s+/g, '').toLowerCase();
    const currentStrength = normalizedPackedText(formatLabelMedStrength(med));
    const packedStrength = normalizedPackedText(item.strength || '');
    if (packedStrength && currentStrength && packedStrength !== currentStrength) return false;
    const currentDose = normalizedPackedText(formatPrescribedDose(med, schedule.doseQty));
    const packedDose = normalizedPackedText(item.dose || '');
    if (packedDose && currentDose && packedDose !== currentDose) return false;
    return true;
}

function prepackedDoseCovers(scheduleId, date, time, med = null) {
    if (!scheduleId || !date || !time) return null;
    const schedule = db.schedules.find(item => item.id === scheduleId);
    const currentMed = med || (schedule ? db.inventory.find(item => item.id === schedule.medId) : null);
    if (!schedule || !currentMed) return null;
    const exactKey = scheduleInstanceKey(scheduleId, date, time);
    for (const queue of db.prepackQueues || []) {
        if (isInventoryUnitDoseQueue(queue)) continue;
        for (const day of queue.days || []) {
            for (const item of day.items || []) {
                if (!item.inventoryDeducted || item.inventoryReturned || item.inventoryWasted) continue;
                if (!prepackItemMatchesCurrentSchedule(item, schedule, currentMed)) continue;
                if (item.instanceKey === exactKey) return { queue, day, item };
                const range = String(item.instanceKey || '').split('|');
                if (range[0] === 'range' && range[1] === scheduleId) {
                    const start = range[2] || '';
                    const end = range[3] || '';
                    const specificTime = range[4] || 'all';
                    if ((!start || date >= start) && (!end || date <= end) && (specificTime === 'all' || specificTime === time)) {
                        return { queue, day, item };
                    }
                }
            }
        }
    }
    return null;
}

function selectedInventoryUnitDoseMedication(body = document.getElementById('action-modal-body')) {
    const query = String(body?.querySelector('[name="medSearch"]')?.value || '').trim();
    if (!query) return null;
    const inventory = sortByName(db.inventory, inventoryDisplayName);
    const lowered = query.toLowerCase();
    const partialMatches = inventory.filter(item => inventoryDisplayName(item).toLowerCase().includes(lowered) || String(item.name || '').toLowerCase().includes(lowered));
    return inventory.find(item => inventoryDisplayName(item) === query)
        || inventory.find(item => item.name.toLowerCase() === lowered)
        || (partialMatches.length === 1 ? partialMatches[0] : null)
        || null;
}

function inventoryUnitDoseExpirationFromForm(body = document.getElementById('action-modal-body')) {
    const mode = body?.querySelector('[name="expirationMode"]')?.value || 'date';
    const prepDate = body?.querySelector('[name="prepDate"]')?.value || localDateKey();
    if (mode === 'days') {
        const days = parseInt(body?.querySelector('[name="expirationDays"]')?.value, 10);
        return Number.isFinite(days) && days >= 0 ? addDaysKey(prepDate, days) : '';
    }
    return body?.querySelector('[name="expirationDate"]')?.value || '';
}

window.updateInventoryUnitDosePrepackPreview = function() {
    const body = document.getElementById('action-modal-body');
    if (!body) return;
    const med = selectedInventoryUnitDoseMedication(body);
    const qty = parseAmount(body.querySelector('[name="qtyPerContainer"]')?.value, NaN);
    const count = parseInt(body.querySelector('[name="containerCount"]')?.value, 10);
    const mode = body.querySelector('[name="expirationMode"]')?.value || 'date';
    const dateWrap = body.querySelector('#unit-dose-expiry-date-wrap');
    const daysWrap = body.querySelector('#unit-dose-expiry-days-wrap');
    if (dateWrap) dateWrap.style.display = mode === 'date' ? 'inline-flex' : 'none';
    if (daysWrap) daysWrap.style.display = mode === 'days' ? 'inline-flex' : 'none';
    const preview = body.querySelector('#unit-dose-calculated-preview');
    if (!preview) return;
    if (!med) {
        preview.innerHTML = 'Select an inventory item to preview the calculated dose and stock needed.';
        return;
    }
    const expirationDateInput = body.querySelector('[name="expirationDate"]');
    if (mode === 'date' && expirationDateInput && !expirationDateInput.value && med.expiry) {
        expirationDateInput.value = med.expiry;
    }
    const giveUnit = med.administrationUnit || med.formulation || inventoryUnitFor(med) || 'unit';
    const totalNeeded = Number.isFinite(qty) && Number.isFinite(count) ? qty * count : NaN;
    const expirationDate = inventoryUnitDoseExpirationFromForm(body);
    preview.innerHTML = `
        <strong>${escapeHtml(med.name)} ${escapeHtml(formatLabelMedStrength(med))}</strong><br>
        Amount per container: ${Number.isFinite(qty) ? `${escapeHtml(formatAmount(qty))} ${escapeHtml(giveUnit)}` : 'Enter amount'}<br>
        Calculated dose per container: ${Number.isFinite(qty) && qty > 0 ? escapeHtml(formatPrescribedDose(med, qty)) : 'Enter amount'}<br>
        Total stock needed: ${Number.isFinite(totalNeeded) ? `${escapeHtml(formatAmount(totalNeeded))} ${escapeHtml(giveUnit)}` : 'Enter amount and container count'} | On hand: ${escapeHtml(formatAmount(parseAmount(med.stock)))} ${escapeHtml(inventoryUnitFor(med))}<br>
        Expiration for prepared container(s): ${escapeHtml(expirationDate || 'Not selected')}
    `;
};

function deductInventoryUnitDoseStock(queue) {
    if (!isInventoryUnitDoseQueue(queue) || queue.inventoryDeducted) return;
    const med = db.inventory.find(item => item.id === queue.selection.medId);
    if (!med) return;
    const preparedCount = preparedInventoryUnitDoseCount(queue);
    const totalQty = parseAmount(queue.selection.qtyPerContainer, 0) * preparedCount;
    if (!Number.isFinite(totalQty) || totalQty <= 0) return;
    queue.inventoryDeducted = true;
    const preparedItem = queue.prepackedInventoryId ? db.inventory.find(item => item.id === queue.prepackedInventoryId) : null;
    db.history.unshift({
        id: Date.now().toString(),
        timestamp: new Date().toLocaleString(),
        medId: med.id,
        medName: med.name,
        details: `Inventory unit-dose prepack completed; ${preparedCount} prepared ${queue.selection.containerType}${preparedCount === 1 ? '' : 's'} in inventory.`
    });
    addAudit('Inventory unit-dose prepack completed', med.name, `${preparedCount} prepared ${preparedItem ? inventoryUnitFor(preparedItem) : queue.selection.containerType}.`);
}

function inventoryUnitDoseLabelHtml(queue, item, index = 0) {
    const med = db.inventory.find(candidate => candidate.id === item.medId);
    const code = normalizeMedicationCode(queue.selection?.prepackedBarcodeCode || item.prepackedBarcodeCode) || (med ? medicationCodes(med)[0] : normalizeMedicationCode(item.barcodeCode));
    const qrDataUrl = medicationQrDataUrl(code);
    const title = `${item.medName} ${item.strength || ''}`.trim();
    const prepDate = queue.selection?.prepDate || queue.days?.[0]?.date || '';
    const lines = [
        title,
        item.quantity,
        item.dose,
        item.expirationDate,
        prepDate,
        item.instructions
    ];
    return `<div class="${getLabelClass(lines, item.instructions ? 6 : 5)} compound-bottle-label inventory-unit-dose-label">
        <div class="compound-label-copy">
            <div class="label-title">${escapeHtml(title)}</div>
            <div class="label-small"><strong>Qty:</strong> ${escapeHtml(item.quantity)}</div>
            <div class="label-small"><strong>Dose:</strong> ${escapeHtml(item.dose || item.strength || '')}</div>
            ${item.expirationDate ? `<div class="label-small"><strong>Exp:</strong> ${escapeHtml(item.expirationDate)}</div>` : ''}
            ${prepDate ? `<div class="label-small"><strong>Prepped:</strong> ${escapeHtml(prepDate)}</div>` : ''}
            ${item.instructions ? `<div class="label-small"><strong>Directions:</strong> ${escapeHtml(item.instructions)}</div>` : ''}
        </div>
        ${qrDataUrl ? `<img class="compound-label-qr" src="${qrDataUrl}" alt="Medication QR code">` : ''}
    </div>`;
}

function labelDosageFormText(med) {
    const formulation = String(med?.formulation || '').trim();
    if (!formulation) return '';
    if (formulation === 'mL') return 'Liquid';
    const defLabel = dosageFormDefinition(formulation)?.label || formulation;
    const cleaned = defLabel.replace(/\s*\([^)]*\)/g, '').trim();
    const stockUnit = String(inventoryUnitFor(med) || '').trim().toLowerCase();
    const adminUnit = String(med?.administrationUnit || '').trim().toLowerCase();
    const normalized = cleaned.toLowerCase();
    if (!cleaned || normalized === stockUnit || normalized === adminUnit) return '';
    return cleaned;
}

function bulkContainerLabelHtml(med) {
    const code = normalizeMedicationCode(med?.barcodeCode) || medicationCodes(med)[0] || '';
    const qrDataUrl = medicationQrDataUrl(code);
    const title = [med?.name, formatLabelMedStrength(med), labelDosageFormText(med)].filter(Boolean).join(' ').trim();
    const lines = [
        title,
        `${formatAmount(parseAmount(med?.stock))} ${inventoryUnitFor(med)}`,
        med?.expiry || '',
        med?.storage || '',
        med?.instructions || ''
    ];
    return `<div class="${getLabelClass(lines, med?.instructions ? 6 : 5)} compound-bottle-label bulk-bottle-label">
        <div class="compound-label-copy">
            <div class="label-title">${escapeHtml(title)}</div>
            <div class="label-small"><strong>Qty:</strong> ${escapeHtml(formatAmount(parseAmount(med?.stock)))} ${escapeHtml(inventoryUnitFor(med))}</div>
            ${med?.expiry ? `<div class="label-small"><strong>Exp:</strong> ${escapeHtml(med.expiry)}</div>` : ''}
            ${med?.preparedDate ? `<div class="label-small"><strong>Prepped:</strong> ${escapeHtml(med.preparedDate)}</div>` : ''}
            <div class="label-small"><strong>Storage:</strong> ${escapeHtml(med?.storage || 'N/A')}</div>
            ${med?.instructions ? `<div class="label-small"><strong>Instructions:</strong> ${escapeHtml(med.instructions)}</div>` : ''}
        </div>
        ${qrDataUrl ? `<img class="compound-label-qr" src="${qrDataUrl}" alt="Medication QR code">` : ''}
    </div>`;
}

function bulkContainerPreviewMed(sourceMed, values = {}) {
    if (!sourceMed) return null;
    const qtyPrepared = parseAmount(values.qtyPrepared, 0);
    const barcodeCode = normalizeMedicationCode(values.barcodeCode) || createMedicationCode();
    return {
        ...sourceMed,
        id: 'bulk_preview',
        name: String(values.labelName || '').trim() || sourceMed.name,
        stock: qtyPrepared,
        maxCapacity: qtyPrepared,
        expiry: values.expiry || sourceMed.expiry || '',
        storage: values.storage || sourceMed.storage || 'Room Temp',
        barcodeCode,
        barcodeCodes: [barcodeCode],
        instructions: String(values.instructions || '').trim(),
        preparedDate: values.prepDate || localDateKey(),
        isBulkPrepack: true
    };
}

window.updateBulkContainerPreview = function() {
    const body = document.getElementById('action-modal-body');
    if (!body) return;
    const sourceMed = selectedInventoryUnitDoseMedication(body);
    const qtyPrepared = parseAmount(body.querySelector('[name="qtyPrepared"]')?.value, NaN);
    const labelNameInput = body.querySelector('[name="labelName"]');
    const expiryInput = body.querySelector('[name="expiry"]');
    const storageInput = body.querySelector('[name="storage"]');
    const barcodeInput = body.querySelector('[name="barcodeCode"]');
    if (sourceMed) {
        if (labelNameInput && !labelNameInput.value) labelNameInput.placeholder = sourceMed.name;
        if (expiryInput && !expiryInput.value && sourceMed.expiry) expiryInput.value = sourceMed.expiry;
        if (storageInput && !storageInput.value) storageInput.value = sourceMed.storage || 'Room Temp';
        if (barcodeInput && !barcodeInput.value) barcodeInput.value = createMedicationCode();
    }
    const info = body.querySelector('#bulk-container-stock-preview');
    const label = body.querySelector('#bulk-container-label-preview');
    if (!sourceMed) {
        if (info) info.innerHTML = 'Select an inventory item to package into a bulk bottle/container.';
        if (label) label.innerHTML = '<div class="empty-state">Label preview will appear here.</div>';
        return;
    }
    const values = collectNamedInputs(body);
    const previewMed = bulkContainerPreviewMed(sourceMed, values);
    const stockUnit = inventoryUnitFor(sourceMed);
    const enoughStock = Number.isFinite(qtyPrepared) && qtyPrepared > 0 && parseAmount(sourceMed.stock, 0) >= qtyPrepared;
    if (info) {
        info.innerHTML = `
            <strong>${escapeHtml(sourceMed.name)} ${escapeHtml(formatLabelMedStrength(sourceMed))}</strong><br>
            Source stock: ${escapeHtml(formatAmount(parseAmount(sourceMed.stock)))} ${escapeHtml(stockUnit)}<br>
            New bulk container qty: ${Number.isFinite(qtyPrepared) && qtyPrepared > 0 ? `${escapeHtml(formatAmount(qtyPrepared))} ${escapeHtml(stockUnit)}` : 'Enter quantity'}<br>
            ${enoughStock ? '<span style="color:green; font-weight:bold;">Stock is available.</span>' : '<span style="color:#b00000; font-weight:bold;">Enter a quantity that is available in inventory.</span>'}
        `;
    }
    if (label && previewMed) label.innerHTML = bulkContainerLabelHtml(previewMed);
};

window.generateBulkContainerCode = function() {
    const input = document.querySelector('#action-modal-body [name="barcodeCode"]');
    if (input) {
        input.value = createMedicationCode();
        updateBulkContainerPreview();
    }
};

function resolveInventorySearchValue(query) {
    const inventory = sortByName(db.inventory, inventoryDisplayName);
    const value = String(query || '').trim();
    const lowered = value.toLowerCase();
    const partialMatches = inventory.filter(item => inventoryDisplayName(item).toLowerCase().includes(lowered) || String(item.name || '').toLowerCase().includes(lowered));
    return inventory.find(item => inventoryDisplayName(item) === value)
        || inventory.find(item => item.name.toLowerCase() === lowered)
        || (partialMatches.length === 1 ? partialMatches[0] : null)
        || null;
}

window.createBulkInventoryContainer = async function() {
    if (!db.inventory.length) {
        await appAlert('Add inventory items before creating a bulk bottle/container.');
        return;
    }
    ensureMedKits();
    const inventory = sortByName(db.inventory, inventoryDisplayName);
    const medOptions = inventory.map(med =>
        `<option value="${escapeHtml(inventoryDisplayName(med))}">${escapeHtml(formatAmount(parseAmount(med.stock)))} ${escapeHtml(inventoryUnitFor(med))} on hand</option>`
    ).join('');
    const destinationOptions = (db.medKits || [])
        .map(kit => `<option value="${escapeHtml(kit.id)}">Med Kit: ${escapeHtml(medKitName(kit))}</option>`)
        .join('');
    const defaults = defaultActualDateTime();
    const result = await showActionModal('Bulk Bottle/Container From Inventory', `
        <div data-action-modal-size="wide" class="bulk-container-preview-shell">
            <div class="bulk-container-form-panel">
                <div class="field-row-stacked">
                    <label>Medication or supplement:</label>
                    <input name="medSearch" list="bulk-container-inventory-options" placeholder="Search inventory..." style="width:100%;" oninput="updateBulkContainerPreview()">
                    <datalist id="bulk-container-inventory-options">${medOptions}</datalist>
                </div>
                <div class="bulk-container-field-grid">
                    <label>Qty
                        <input name="qtyPrepared" type="number" min="0.001" step="any" placeholder="Amount placed in bottle" oninput="updateBulkContainerPreview()">
                    </label>
                    <label>Prepared date
                        <input name="prepDate" type="date" value="${escapeHtml(defaults.date)}" onchange="updateBulkContainerPreview()">
                    </label>
                    <label>Time
                        <input name="prepTime" type="time" value="${escapeHtml(defaults.time)}">
                    </label>
                    <label>Expiration
                        <input name="expiry" type="date" onchange="updateBulkContainerPreview()">
                    </label>
                    <label>Storage
                        <select name="storage" onchange="updateBulkContainerPreview()">
                            <option value="Room Temp">Room Temp</option>
                            <option value="Refrigerate">Refrigerate</option>
                            <option value="Freeze">Freeze</option>
                            <option value="Protect from light">Protect from light</option>
                            <option value="Unknown">Unknown</option>
                        </select>
                    </label>
                    <label>Label name
                        <input name="labelName" type="text" placeholder="Leave blank to use medication name" oninput="updateBulkContainerPreview()">
                    </label>
                    <label>Destination
                        <select name="destinationKitId">
                            <option value="">Main inventory</option>
                            ${destinationOptions}
                        </select>
                    </label>
                </div>
                <div class="bulk-container-qr-row">
                    <label>QR code
                        <input name="barcodeCode" type="text" value="${escapeHtml(createMedicationCode())}" oninput="updateBulkContainerPreview()">
                    </label>
                    <button type="button" onclick="generateBulkContainerCode()">Generate</button>
                </div>
                <div class="field-row-stacked" style="margin-top:8px;">
                    <label>Instructions:</label><textarea name="instructions" rows="3" style="width:100%; resize:none;" oninput="updateBulkContainerPreview()"></textarea>
                </div>
                <div id="bulk-container-stock-preview" class="unit-dose-preview">Select an inventory item to package into a bulk bottle/container.</div>
                <div class="form-help" style="margin-top:8px;">This creates a new orange inventory item from stock you already have. Stock is removed from the source item immediately because the bulk bottle/container becomes its own inventory supply.</div>
            </div>
            <div class="bulk-container-preview-panel">
                <strong>Live label preview</strong>
                <div id="bulk-container-label-preview" class="bulk-container-preview-card"><div class="empty-state">Label preview will appear here.</div></div>
            </div>
        </div>
    `, 'Create Bulk Container');
    if (!result) return;
    const sourceMed = resolveInventorySearchValue(result.medSearch);
    const qtyPrepared = parseAmount(result.qtyPrepared, NaN);
    if (!sourceMed || !Number.isFinite(qtyPrepared) || qtyPrepared <= 0) {
        await appAlert('Select an inventory item and enter the quantity going into the bulk bottle/container.');
        return;
    }
    if (parseAmount(sourceMed.stock, 0) < qtyPrepared) {
        await appAlert(`${sourceMed.name} has ${formatAmount(parseAmount(sourceMed.stock))} ${inventoryUnitFor(sourceMed)} on hand, but this bulk container needs ${formatAmount(qtyPrepared)} ${inventoryUnitFor(sourceMed)}.`);
        return;
    }
    const barcodeCode = normalizeMedicationCode(result.barcodeCode) || createMedicationCode();
    if (await warnBarcodeConflict(barcodeCode)) return;
    const bulkMed = {
        ...sourceMed,
        id: `bulk_${Date.now()}_${Math.random().toString(16).slice(2)}`,
        name: String(result.labelName || '').trim() || sourceMed.name,
        stock: qtyPrepared,
        maxCapacity: qtyPrepared,
        expiry: result.expiry || sourceMed.expiry || '',
        storage: result.storage || sourceMed.storage || 'Room Temp',
        barcodeCode,
        barcodeCodes: [barcodeCode],
        notes: [
            sourceMed.notes || '',
            `Bulk bottle/container prepared from ${sourceMed.name} ${formatLabelMedStrength(sourceMed)} on ${result.prepDate || defaults.date}${result.prepTime ? ` ${result.prepTime}` : ''}.`,
            `Source inventory used: ${formatAmount(qtyPrepared)} ${inventoryUnitFor(sourceMed)}.`
        ].filter(Boolean).join('\n'),
        instructions: String(result.instructions || '').trim(),
        preparedDate: result.prepDate || defaults.date,
        preparedTime: result.prepTime || defaults.time,
        isBulkPrepack: true,
        bulkSourceInventoryId: sourceMed.id,
        sourceInventoryId: sourceMed.id,
        sourceInventoryName: sourceMed.name
    };
    sourceMed.stock = Math.max(0, parseAmount(sourceMed.stock, 0) - qtyPrepared);
    db.inventory.push(bulkMed);
    if (result.destinationKitId) {
        const kit = db.medKits.find(candidate => candidate.id === result.destinationKitId);
        if (kit) {
            kit.items = Array.isArray(kit.items) ? kit.items : [];
            kit.items.push({
                id: medKitItemId(),
                medId: bulkMed.id,
                qty: qtyPrepared,
                unit: inventoryUnitFor(bulkMed),
                expiry: bulkMed.expiry || '',
                addedAt: new Date().toISOString()
            });
            kit.updatedAt = new Date().toISOString();
            bulkMed.stock = 0;
            bulkMed.maxCapacity = Math.max(parseAmount(bulkMed.maxCapacity, 0), qtyPrepared);
            bulkMed.medKitDestinationId = kit.id;
            bulkMed.notes += `\nPlaced into Med Kit: ${medKitName(kit)}.`;
        }
    }
    db.history.unshift({
        id: Date.now().toString(),
        timestamp: new Date().toLocaleString(),
        medId: sourceMed.id,
        medName: sourceMed.name,
        details: `Bulk bottle/container created: ${bulkMed.name}; -${formatAmount(qtyPrepared)} ${inventoryUnitFor(sourceMed)} source stock${result.destinationKitId ? '; placed in med kit' : ''}; new QR ${barcodeCode}.`
    });
    addAudit('Bulk inventory container created', sourceMed.name, `${bulkMed.name} | -${formatAmount(qtyPrepared)} ${inventoryUnitFor(sourceMed)}.`);
    await sync();
    previewLabelHtml(bulkContainerLabelHtml(bulkMed));
};

function prepackShiftForTime(time) {
    const minutes = timeToMinutes(time);
    if (!Number.isFinite(minutes)) return '';
    if (minutes >= 17 * 60) return 'evening';
    if (minutes <= 16 * 60) return 'day';
    return '';
}

function prepackIconForShift(shift) {
    if (shift === 'day') return String.fromCharCode(9728);
    if (shift === 'evening') return String.fromCharCode(9790);
    return '';
}

function labelShiftIconHtml(shift) {
    const icon = prepackIconForShift(shift);
    return icon ? `<span class="label-shift-icon">${escapeHtml(icon)}</span>` : '';
}

function prepackShiftChoiceHtml(current = 'all') {
    const selected = current || 'all';
    const choices = [
        { value: 'all', title: 'All times', detail: 'Keep every scheduled dose together' },
        { value: 'day', title: `${prepackIconForShift('day')} Daytime`, detail: '12:00 AM through 4:00 PM' },
        { value: 'evening', title: `${prepackIconForShift('evening')} Evening`, detail: '5:00 PM through 11:59 PM' }
    ];
    return `<div class="prepack-choice-grid">
        ${choices.map(choice => `
            <label class="prepack-choice" for="prepack-shift-${choice.value}">
                <input id="prepack-shift-${choice.value}" type="radio" name="prepackShift" value="${choice.value}" ${selected === choice.value ? 'checked' : ''}>
                <strong>${escapeHtml(choice.title)}</strong>
                <span>${escapeHtml(choice.detail)}</span>
            </label>
        `).join('')}
    </div>`;
}

function filterRowsByPrepackShift(rows, shift) {
    if (!shift || shift === 'all') return rows;
    return rows.filter(row => prepackShiftForTime(row.instance?.time) === shift);
}

function buildPrepackDefinition(memberId, sourceLabel, rows, selection = null) {
    const member = db.family.find(item => item.id === memberId);
    const byDate = new Map();
    const addedScheduleIds = new Set(selection?.addedScheduleIds || []);
    const queueSeed = selection?.prepackQueueId || '';
    const expandedRows = expandPrepackRowsWithTogetherLinks(rows, selection || { memberId });
    const uniqueRows = [];
    const seenRows = new Set();
    expandedRows.forEach(row => {
        if (!row?.instance?.date || !row.med || !row.schedule) return;
        const rowKey = `${row.schedule.id}|${row.instance.key || scheduleInstanceKey(row.schedule.id, row.instance.date, row.instance.time)}`;
        if (seenRows.has(rowKey)) return;
        seenRows.add(rowKey);
        uniqueRows.push(row);
    });
    uniqueRows.forEach(row => {
        if (!byDate.has(row.instance.date)) byDate.set(row.instance.date, []);
        byDate.get(row.instance.date).push({
            id: prepackItemId(),
            instanceKey: row.instance.key || scheduleInstanceKey(row.schedule.id, row.instance.date, row.instance.time),
            scheduleId: row.schedule.id,
            medId: row.med.id,
            medName: row.med.name,
            strength: formatLabelMedStrength(row.med),
            quantity: formatQtyForSchedule(row.schedule, row.med),
            dose: formatPrescribedDose(row.med, row.schedule.doseQty),
            time: row.instance.time,
            instructions: row.schedule.instructions || '',
            orderSetId: row.schedule.orderSetId || '',
            orderSetName: row.schedule.orderSetName || '',
            isPrepackAdded: row.schedule.prepackAdded === true || addedScheduleIds.has(row.schedule.id),
            barcodeCode: medicationCodes(row.med)[0] || '',
            status: 'pending',
            scannedCode: ''
        });
    });
    let days = Array.from(byDate.entries())
        .sort(([first], [second]) => first.localeCompare(second))
        .map(([date, items]) => ({
            date,
            prepackCode: prepackPackageCode(memberId, date, selection?.prepackShift || 'all'),
            prepackScanCode: prepackPackageScanCode(memberId, date, selection?.prepackShift || 'all', queueSeed),
            status: 'pending',
            needsReprint: false,
            items: items.sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time) || a.medName.localeCompare(b.medName))
        }));
    const singleScheduleIds = new Set(uniqueRows.map(row => row.schedule?.id).filter(Boolean));
    if (selection?.singleMedication && selection.labelLayout === 'range' && uniqueRows.length > 0 && singleScheduleIds.size === 1) {
        const firstRow = uniqueRows[0];
        const totalQuantity = uniqueRows.reduce((sum, row) => sum + parseAmount(row.schedule.doseQty, 0), 0);
        const aggregateItem = {
            id: prepackItemId(),
            instanceKey: `range|${firstRow.schedule.id}|${selection.startDate}|${selection.endDate}|${selection.specificTime || 'all'}`,
            scheduleId: firstRow.schedule.id,
            medId: firstRow.med.id,
            medName: firstRow.med.name,
            strength: formatLabelMedStrength(firstRow.med),
            quantity: formatQtyForSchedule({ ...firstRow.schedule, doseQty: totalQuantity }, firstRow.med),
            dose: formatPrescribedDose(firstRow.med, firstRow.schedule.doseQty),
            time: selection.startDate === selection.endDate
                ? selection.startDate
                : `${selection.startDate} - ${selection.endDate}`,
            instructions: firstRow.schedule.instructions || '',
            orderSetId: firstRow.schedule.orderSetId || '',
            orderSetName: firstRow.schedule.orderSetName || '',
            isPrepackAdded: firstRow.schedule.prepackAdded === true || addedScheduleIds.has(firstRow.schedule.id),
            barcodeCode: medicationCodes(firstRow.med)[0] || '',
            status: 'pending',
            scannedCode: ''
        };
        days = [{
            date: aggregateItem.time,
            prepackCode: prepackPackageCode(memberId, selection.startDate, selection?.prepackShift || 'all'),
            prepackScanCode: prepackPackageScanCode(memberId, selection.startDate, selection?.prepackShift || 'all', queueSeed),
            status: 'pending',
            needsReprint: false,
            items: [aggregateItem]
        }];
    }
    return {
        memberId,
        memberName: memberDisplayName(member),
        sourceLabel,
        queueId: queueSeed,
        title: `${memberDisplayName(member)} | ${days[0]?.date || selection?.startDate || ''}${days.length > 1 ? ` - ${days[days.length - 1].date}` : (!days.length && selection?.endDate && selection.endDate !== selection.startDate ? ` - ${selection.endDate}` : '')}`,
        selection: selection || {
            kind: 'schedule-list',
            scheduleIds: Array.from(new Set(rows.map(row => row.schedule?.id).filter(Boolean))),
            startDate: days[0]?.date || '',
            endDate: days[days.length - 1]?.date || ''
        },
        days
    };
}

function prepackRowsForSelection(selection) {
    if (selection?.kind === 'inventory-unit-dose') return [];
    if (!selection?.startDate || !selection?.endDate) return [];
    let schedules = [];
    if (selection.kind === 'member-range') {
        const excluded = new Set(selection.excludedScheduleIds || []);
        schedules = db.schedules.filter(schedule =>
            schedule.memberId === selection.memberId && !excluded.has(schedule.id) && !isScheduleArchived(schedule)
        );
    } else {
        const scheduleIds = new Set(selection.scheduleIds || []);
        schedules = db.schedules.filter(schedule => scheduleIds.has(schedule.id) && !isScheduleArchived(schedule));
    }
    const excludedInstances = new Set(selection.excludedInstanceKeys || []);
    const excludedPrepackDates = new Set(selection.excludedPrepackDates || []);
    const rows = [];
    schedules.forEach(schedule => {
        const med = db.inventory.find(item => item.id === schedule.medId);
        if (!med) return;
        getScheduleInstancesInRange(schedule, selection.startDate, selection.endDate)
            .filter(instance => !selection.specificTime || instance.time === selection.specificTime)
            .filter(instance => !excludedInstances.has(instance.key))
            .filter(instance => !excludedPrepackDates.has(instance.date))
            .forEach(instance => rows.push({ schedule, med, instance }));
    });
    const expandedRows = expandPrepackRowsWithTogetherLinks(rows, selection);
    return filterRowsByPrepackShift(expandedRows, selection.prepackShift).sort((a, b) =>
        a.instance.date.localeCompare(b.instance.date) ||
        timeToMinutes(a.instance.time) - timeToMinutes(b.instance.time) ||
        a.med.name.localeCompare(b.med.name, undefined, { sensitivity: 'base' })
    );
}

function matchingPrepackInstance(schedule, sourceInstance, excludedInstances = new Set()) {
    if (!schedule || !sourceInstance?.date || !sourceInstance?.time) return null;
    return getScheduleInstancesForDate(schedule, sourceInstance.date)
        .find(instance => instance.time === sourceInstance.time && !excludedInstances.has(instance.key));
}

function expandPrepackRowsWithTogetherLinks(rows, selection = {}) {
    const output = [];
    const queued = new Set();
    const excludedInstances = new Set(selection?.excludedInstanceKeys || []);
    const candidateByMember = new Map();
    const pushRow = (row) => {
        if (!row?.schedule || !row?.med || !row?.instance) return false;
        const key = `${row.schedule.id}|${row.instance.key || scheduleInstanceKey(row.schedule.id, row.instance.date, row.instance.time)}`;
        if (queued.has(key)) return false;
        queued.add(key);
        output.push(row);
        return true;
    };

    rows.forEach(row => pushRow(row));

    for (let index = 0; index < output.length; index++) {
        const row = output[index];
        const memberId = row.schedule.memberId || selection.memberId || '';
        if (!memberId) continue;
        if (!candidateByMember.has(memberId)) {
            candidateByMember.set(memberId, db.schedules.filter(schedule =>
                schedule.memberId === memberId && !isScheduleArchived(schedule)
            ));
        }
        const candidates = candidateByMember.get(memberId);
        linkedSchedulesFor(row.schedule, candidates)
            .filter(linked => scheduleLinkModeBetween(row.schedule, linked) === 'together')
            .forEach(linked => {
                const linkedMed = db.inventory.find(item => item.id === linked.medId);
                const linkedInstance = matchingPrepackInstance(linked, row.instance, excludedInstances);
                if (linkedMed && linkedInstance) pushRow({ schedule: linked, med: linkedMed, instance: linkedInstance });
            });
    }

    return output;
}

function prepackItemFingerprint(item) {
    return [
        item.instanceKey,
        item.medId,
        item.strength,
        item.quantity,
        item.dose,
        item.time,
        item.instructions,
        item.isPrepackAdded ? 'added' : ''
    ].join('|');
}

function reconcilePrepackQueue(queue) {
    if (!queue?.selection) return false;
    if (isInventoryUnitDoseQueue(queue)) return false;
    if (queue.status === 'completed') return false;
    const rows = prepackRowsForSelection(queue.selection);
    const fresh = buildPrepackDefinition(queue.memberId, queue.sourceLabel, rows, queue.selection);
    const previousItems = new Map();
    queue.days.forEach(day => day.items.forEach(item => {
        if (item.instanceKey) previousItems.set(item.instanceKey, item);
    }));
    const previousDays = new Map(queue.days.map(day => [day.date, day]));
    let changed = false;
    fresh.days.forEach(day => {
        day.items.forEach(item => {
            const previous = previousItems.get(item.instanceKey);
            if (previous && prepackItemFingerprint(previous) === prepackItemFingerprint(item)) {
                item.id = previous.id;
                item.status = previous.status;
                item.scannedCode = previous.scannedCode;
                item.scannedAt = previous.scannedAt;
                item.verificationMethod = previous.verificationMethod;
                item.inventoryDeducted = previous.inventoryDeducted;
                item.stockDelta = previous.stockDelta;
                item.stockSource = previous.stockSource;
                item.inventorySource = previous.inventorySource;
                item.kitId = previous.kitId;
                item.kitItemId = previous.kitItemId;
                item.kitExpiry = previous.kitExpiry;
                item.stockDeductedAt = previous.stockDeductedAt;
                item.stockDeductionMethod = previous.stockDeductionMethod;
                item.stockLogDetail = previous.stockLogDetail;
                item.inventoryReturned = previous.inventoryReturned;
                item.returnedQuantity = previous.returnedQuantity;
                item.returnedAt = previous.returnedAt;
                item.returnReason = previous.returnReason;
                item.returnNote = previous.returnNote;
                item.inventoryWasted = previous.inventoryWasted;
                item.wastedAt = previous.wastedAt;
                item.wasteReason = previous.wasteReason;
                item.wasteNote = previous.wasteNote;
                item.recordOnlyReturn = previous.recordOnlyReturn;
            } else {
                changed = true;
            }
        });
        const previousDay = previousDays.get(day.date);
        if (previousDay?.prepackCode) day.prepackCode = previousDay.prepackCode;
        day.prepackScanCode = previousDay?.prepackScanCode || '';
        const oldFingerprints = (previousDay?.items || []).map(prepackItemFingerprint).sort().join('||');
        const newFingerprints = day.items.map(prepackItemFingerprint).sort().join('||');
        const dayChanged = oldFingerprints !== newFingerprints;
        if (dayChanged) changed = true;
        day.needsReprint = queue.labelsPrinted
            ? (dayChanged || !!previousDay?.needsReprint)
            : false;
    });
    queue.days.forEach(day => {
        if (!fresh.days.some(candidate => candidate.date === day.date) && day.items.length > 0) changed = true;
    });
    queue.days = fresh.days;
    queue.memberName = fresh.memberName;
    queue.title = fresh.title;
    updatePrepackQueueStatus(queue);
    return changed;
}

function prepackSelectionFingerprint(selection) {
    if (!selection) return '';
    return JSON.stringify({
        kind: selection.kind || '',
        memberId: selection.memberId || '',
        scheduleIds: (selection.scheduleIds || []).slice().sort(),
        excludedScheduleIds: (selection.excludedScheduleIds || []).slice().sort(),
        excludedPrepackDates: (selection.excludedPrepackDates || []).slice().sort(),
        excludedInstanceKeys: (selection.excludedInstanceKeys || []).slice().sort(),
        startDate: selection.startDate || '',
        endDate: selection.endDate || '',
        specificTime: selection.specificTime || '',
        labelLayout: selection.labelLayout || '',
        singleMedication: selection.singleMedication === true,
        prepackShift: selection.prepackShift || 'all',
        batchId: selection.batchId || '',
        medId: selection.medId || '',
        prepDate: selection.prepDate || '',
        prepTime: selection.prepTime || '',
        qtyPerContainer: selection.qtyPerContainer || '',
        containerCount: selection.containerCount || '',
        containerType: selection.containerType || '',
        expirationDate: selection.expirationDate || '',
        labelName: selection.labelName || ''
    });
}

function nextActivePrepackQueueId(excludedQueueId = '') {
    const next = (db.prepackQueues || []).find(queue => queue.id !== excludedQueueId && queue.status !== 'completed');
    return next?.id || null;
}

async function createPrepackQueue(definition, options = {}) {
    if (!definition.days?.some(day => day.items.length > 0)) return null;
    const fingerprint = prepackSelectionFingerprint(definition.selection);
    const existing = (db.prepackQueues || []).find(queue =>
        queue.status !== 'completed' &&
        prepackSelectionFingerprint(queue.selection) === fingerprint
    );
    if (existing) {
        const previousCodes = new Map((existing.days || []).map(day => [
            day.date,
            { prepackCode: day.prepackCode || '', prepackScanCode: day.prepackScanCode || '' }
        ]));
        existing.memberName = definition.memberName;
        existing.sourceLabel = definition.sourceLabel;
        existing.title = definition.title;
        existing.selection = definition.selection;
        existing.scheduledFor = options.scheduledFor || existing.scheduledFor || '';
        existing.labelsPrinted = existing.labelsPrinted || options.labelsPrinted === true;
        existing.days = definition.days;
        existing.days.forEach(day => {
            const previous = previousCodes.get(day.date);
            day.prepackCode = previous?.prepackCode || day.prepackCode || '';
            day.prepackScanCode = previous?.prepackScanCode || '';
        });
        ensurePrepackDayCodes(existing);
        existing.currentDayIndex = 0;
        updatePrepackQueueStatus(existing);
        activePrepackQueueId = existing.id;
        await sync();
        return existing;
    }
    const queue = {
        id: definition.queueId || prepackQueueId(),
        memberId: definition.memberId,
        memberName: definition.memberName,
        sourceLabel: definition.sourceLabel,
        title: definition.title,
        selection: definition.selection,
        scheduledFor: options.scheduledFor || '',
        labelsPrinted: options.labelsPrinted === true,
        createdAt: new Date().toISOString(),
        lastPrintedAt: options.labelsPrinted ? new Date().toISOString() : '',
        currentDayIndex: 0,
        status: 'pending',
        completedAt: '',
        days: definition.days
    };
    ensurePrepackDayCodes(queue);
    db.prepackQueues.unshift(queue);
    activePrepackQueueId = queue.id;
    await sync();
    return queue;
}

async function commitPrepackPrint(definition) {
    if (definition.existingQueueId) {
        const queue = db.prepackQueues.find(item => item.id === definition.existingQueueId);
        if (!queue) return;
        const dates = new Set(definition.reprintedDates || []);
        queue.days.forEach(day => {
            if (dates.has(day.date)) day.needsReprint = false;
        });
        queue.labelsPrinted = true;
        queue.lastPrintedAt = new Date().toISOString();
        updatePrepackQueueStatus(queue);
        await sync();
        return;
    }
    await createPrepackQueue(definition, { labelsPrinted: true });
}

function updatePrepackQueueStatus(queue) {
    ensurePrepackDayCodes(queue);
    queue.days.forEach(day => {
        day.status = isPrepackDayComplete(day)
            ? 'completed'
            : 'pending';
    });
    const complete = queue.days.length > 0 && queue.days.every(day => day.status === 'completed');
    queue.status = complete ? 'completed' : 'pending';
    if (complete && !queue.completedAt) queue.completedAt = new Date().toISOString();
    if (!complete) queue.completedAt = '';
    if (complete) deductInventoryUnitDoseStock(queue);
}

function isPrepackDayComplete(day) {
    return !!day && day.items.length > 0 && day.items.every(item => item.status === 'correct');
}

function prepackStatusMark(item) {
    if (item.inventoryReturned) return '<span class="prepack-mark">R</span>';
    if (item.status === 'correct') return '<span class="prepack-mark">&#10003;</span>';
    if (item.status === 'wrong') return '<span class="prepack-mark">&#10007;</span>';
    return '<span class="prepack-mark">[ ]</span>';
}

function prepackScannerInputHtml(queueId) {
    const escapedId = escapeHtml(queueId);
    return `<input id="prepack-scan-input" type="text" autocomplete="off"
        oninput="schedulePrepackScan('${escapedId}')"
        onkeydown="if(event.key==='Enter'){event.preventDefault();scanPrepackCode('${escapedId}')}">`;
}

function prepackWorkspaceHtml(queue) {
    const inventoryUnitDose = isInventoryUnitDoseQueue(queue);
    const dayIndex = Math.max(0, Math.min(parseInt(queue.currentDayIndex, 10) || 0, queue.days.length - 1));
    queue.currentDayIndex = dayIndex;
    const day = queue.days[dayIndex];
    if (!day) {
        return `<div class="prepack-workspace-header">
            <div><strong>${escapeHtml(queue.memberName || queue.title)}</strong><br><small>${escapeHtml(queue.sourceLabel || '')}</small></div>
            <div>
                ${queue.selection?.singleMedication || inventoryUnitDose ? '' : `<button type="button" onclick="addProfileMedicationToPrepack('${escapeHtml(queue.id)}')">Add From Profile</button>
                <button type="button" onclick="addLastMinutePrepackItem('${escapeHtml(queue.id)}')">Add New Medication</button>`}
                <button type="button" onclick="deletePrepackQueue('${escapeHtml(queue.id)}')">Delete Queue</button>
            </div>
        </div><div class="empty-state">This queue has no medications to prepare.</div>`;
    }
    const nextItem = day.items.find(item => item.status !== 'correct');
    const itemRows = day.items.map(item => {
        const statusClass = item.status === 'correct'
            ? 'prepack-item-correct'
            : (item.status === 'wrong' ? 'prepack-item-wrong' : '');
        const returnedClass = item.inventoryReturned ? 'prepack-item-returned' : '';
        const addedClass = item.isPrepackAdded ? 'prepack-item-added' : '';
        const orderSetText = item.orderSetName ? ` | ${item.orderSetName}` : '';
        const undoButton = isPreparedPrepackItem(item) && !item.inventoryReturned && !item.inventoryWasted
            ? `<button type="button" onclick="undoPrepackItem('${escapeHtml(queue.id)}','${escapeHtml(day.date)}','${escapeHtml(item.id)}')">Undo</button>`
            : '';
        const manualButton = isPreparedPrepackItem(item) || item.inventoryReturned || item.inventoryWasted
            ? ''
            : `<button type="button" onclick="markPrepackItemManual('${escapeHtml(queue.id)}','${escapeHtml(day.date)}','${escapeHtml(item.id)}')">Manual</button>`;
        const removeButton = queue.selection?.singleMedication
            ? ''
            : `<button type="button" onclick="removePrepackItem('${escapeHtml(queue.id)}','${escapeHtml(day.date)}','${escapeHtml(item.id)}')">Remove</button>`;
        return `<div class="prepack-item ${statusClass} ${returnedClass} ${addedClass}">
            ${prepackStatusMark(item)}
            <div class="prepack-item-copy">
                <strong>${escapeHtml(item.time)} - ${escapeHtml(item.medName)} ${escapeHtml(item.strength || '')}</strong>${item.isPrepackAdded ? ' <span class="prepack-added-badge">Added</span>' : ''}<br>
                <small>Qty: ${escapeHtml(item.quantity)} | Dose: ${escapeHtml(item.dose)}${item.expirationDate ? ` | Exp: ${escapeHtml(item.expirationDate)}` : ''}${item.inventoryReturned ? ` | Returned: ${escapeHtml(item.returnReason || 'returned')}` : ''}${escapeHtml(orderSetText)}</small>
                ${inventoryUnitDose ? '' : prepackItemSourceSelectHtml(queue.id, item)}
                ${item.status === 'wrong' ? `<div class="prepack-scan-error">Wrong scan: ${escapeHtml(item.scannedCode || 'Unknown code')}</div>` : ''}
            </div>
            <div class="prepack-item-actions">${manualButton}${undoButton}${removeButton}</div>
        </div>`;
    }).join('');
    const dayButtons = queue.days.map((entry, index) => {
        const completed = entry.status === 'completed' || isPrepackDayComplete(entry);
        const classes = [
            'prepack-day-button',
            index === dayIndex ? 'active' : '',
            completed ? 'completed' : '',
            entry.needsReprint && !completed ? 'needs-reprint' : ''
        ].filter(Boolean).join(' ');
        const dayLabel = entry.date.includes(' - ') ? entry.date : entry.date.slice(5);
        return `<button type="button" class="${classes}" onclick="selectPrepackDay('${escapeHtml(queue.id)}',${index})">${escapeHtml(dayLabel)}${completed ? ' &#10003;' : ''}</button>`;
    }).join('');
    const scanner = queue.status === 'completed'
        ? '<div class="prepack-complete-banner">&#10003; Prepackage complete</div>'
        : `<div class="prepack-scanner">
            <label for="prepack-scan-input">Scan medication QR code:</label>
            ${prepackScannerInputHtml(queue.id)}
            <button type="button" onclick="markPrepackDayManual('${escapeHtml(queue.id)}')">Prepacked Manually</button>
            <span>${nextItem ? `Next: ${escapeHtml(nextItem.medName)} at ${escapeHtml(nextItem.time)}` : 'Day complete'}</span>
        </div>`;
    const scheduledText = queue.scheduledFor
        ? `Scheduled: ${queue.scheduledFor.replace('T', ' ')}`
        : 'Ready when needed';
    const printButtonText = queue.labelsPrinted ? 'Print Updated Labels' : 'Print Labels';
    const medicationActions = queue.selection?.singleMedication || inventoryUnitDose
        ? ''
        : `<button type="button" onclick="addProfileMedicationToPrepack('${escapeHtml(queue.id)}')">Add From Profile</button>
           <button type="button" onclick="addLastMinutePrepackItem('${escapeHtml(queue.id)}')">Add New Medication</button>`;
    const labelGroupButton = inventoryUnitDose
        ? ''
        : `<button type="button" onclick="editPrepackLabelGroup('${escapeHtml(queue.id)}')">Label Group</button>`;
    return `
        <div class="prepack-workspace-header">
            <div><strong>${escapeHtml(queue.memberName || queue.title)}</strong><br><small>${escapeHtml(queue.sourceLabel || '')} | ${escapeHtml(scheduledText)}</small></div>
            <div>
                ${medicationActions}
                ${labelGroupButton}
                <button type="button" onclick="editPrepackDateRange('${escapeHtml(queue.id)}')">Edit Date Range</button>
                <button type="button" onclick="removePrepackDay('${escapeHtml(queue.id)}','${escapeHtml(day.date)}')">Remove This Day</button>
                <button type="button" onclick="reprintPrepackDay('${escapeHtml(queue.id)}','${escapeHtml(day.date)}')">Reprint This Day</button>
                <button type="button" onclick="reprintPrepackLabels('${escapeHtml(queue.id)}')">Reprint Labels</button>
                <button type="button" onclick="printUpdatedPrepackLabels('${escapeHtml(queue.id)}')">${printButtonText}</button>
                <button type="button" onclick="deletePrepackQueue('${escapeHtml(queue.id)}')">Delete Queue</button>
            </div>
        </div>
        <div class="prepack-day-strip">${dayButtons}</div>
        ${day.needsReprint && !isPrepackDayComplete(day) ? '<div class="prepack-reprint-warning">Labels for this day need to be reprinted.</div>' : ''}
        ${scanner}
        <div class="prepack-items">${itemRows || '<div class="empty-state">No medications queued for this day.</div>'}</div>`;
}

window.renderPrepackageQueues = function() {
    const activeList = document.getElementById('prepack-active-list');
    const completedList = document.getElementById('prepack-completed-list');
    const workspace = document.getElementById('prepack-workspace');
    if (!activeList || !completedList || !workspace) return;
    if (!Array.isArray(db.prepackQueues)) db.prepackQueues = [];
    db.prepackQueues
        .filter(queue => queue.status !== 'completed')
        .forEach(queue => reconcilePrepackQueue(queue));

    const filter = document.getElementById('prepack-member-filter');
    const selectedFilter = filter?.value || '';
    if (filter) {
        filter.innerHTML = '<option value="">All members</option>' + db.family
            .slice()
            .sort((a, b) => memberDisplayName(a).localeCompare(memberDisplayName(b), undefined, { sensitivity: 'base' }))
            .map(member => `<option value="${escapeHtml(member.id)}">${escapeHtml(memberDisplayName(member))}</option>`)
            .join('');
        filter.value = db.family.some(member => member.id === selectedFilter) ? selectedFilter : '';
    }
    const completedFilter = document.getElementById('prepack-completed-member-filter');
    const selectedCompletedFilter = completedFilter?.value || '';
    if (completedFilter) {
        completedFilter.innerHTML = '<option value="">All members</option>' + db.family
            .slice()
            .sort((a, b) => memberDisplayName(a).localeCompare(memberDisplayName(b), undefined, { sensitivity: 'base' }))
            .map(member => `<option value="${escapeHtml(member.id)}">${escapeHtml(memberDisplayName(member))}</option>`)
            .join('');
        completedFilter.value = db.family.some(member => member.id === selectedCompletedFilter) ? selectedCompletedFilter : '';
    }
    const active = db.prepackQueues
        .filter(queue => !filter?.value || queue.memberId === filter.value)
        .filter(queue => queue.status !== 'completed')
        .sort((a, b) => String(a.scheduledFor || '9999').localeCompare(String(b.scheduledFor || '9999')));
    const completed = db.prepackQueues
        .filter(queue => !completedFilter?.value || queue.memberId === completedFilter.value)
        .filter(queue => queue.status === 'completed')
        .sort((a, b) => String(b.completedAt || '').localeCompare(String(a.completedAt || '')));
    const queueRow = (queue, complete = false) => `
        <button type="button" class="prepack-queue-row ${complete ? 'completed' : ''} ${queue.id === activePrepackQueueId ? 'selected' : ''}" onclick="selectPrepackQueue('${escapeHtml(queue.id)}')">
            <strong>${complete ? '&#10003; ' : ''}${escapeHtml(queue.title)}</strong><br>
            <small>${escapeHtml(queue.sourceLabel || '')}${queue.scheduledFor ? ` | ${escapeHtml(queue.scheduledFor.replace('T', ' '))}` : ''}${!queue.labelsPrinted ? ' | LABELS NOT PRINTED' : ''}${queue.days.some(day => day.needsReprint && !isPrepackDayComplete(day)) ? ' | LABELS NEED REPRINT' : ''}</small>
        </button>`;
    activeList.innerHTML = active.length
        ? active.map(queue => queueRow(queue)).join('')
        : '<div class="empty-state">No active prepack queues.</div>';
    completedList.innerHTML = completed.length
        ? completed.map(queue => queueRow(queue, true)).join('')
        : '<div class="empty-state">No completed prepackages.</div>';

    const selected = db.prepackQueues.find(queue => queue.id === activePrepackQueueId);
    workspace.innerHTML = selected
        ? prepackWorkspaceHtml(selected)
        : '<div class="empty-state">Select a prepack queue.</div>';
    setTimeout(() => document.getElementById('prepack-scan-input')?.focus(), 0);
};

window.selectPrepackQueue = function(queueId) {
    activePrepackQueueId = queueId;
    renderPrepackageQueues();
};

window.selectPrepackDay = function(queueId, dayIndex) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    if (!queue) return;
    activePrepackQueueId = queue.id;
    queue.currentDayIndex = dayIndex;
    renderPrepackageQueues();
};

function returnablePrepackItems() {
    normalizeRecordOnlyPrepackReturnFlags();
    const rows = [];
    (db.prepackQueues || []).forEach(queue => {
        if (isInventoryUnitDoseQueue(queue)) return;
        if (!queue.memberId) return;
        (queue.days || []).forEach(day => {
            if (!isReturnablePrepackDate(day)) return;
            (day.items || []).forEach(item => {
                if (item.inventoryReturned) return;
                if (item.inventoryWasted) return;
                if (!isPreparedPrepackItem(item)) return;
                const med = db.inventory.find(candidate => candidate.id === item.medId);
                const schedule = prepackItemSchedule(item);
                const row = { queue, day, item, med, schedule };
                if (returnPrepackHasDocumentedWaste(row)) return;
                if (isRangePrepackItem(item) && prepackItemReturnableQty(row) <= 0) return;
                if (!isRangePrepackItem(item) && prepackItemHasDocumentedGivenDose(queue, day, item)) return;
                rows.push(row);
            });
        });
    });
    return rows.sort((a, b) =>
        String(a.day.date || '').localeCompare(String(b.day.date || '')) ||
        timeToMinutes(a.item.time) - timeToMinutes(b.item.time) ||
        String(a.item.medName || '').localeCompare(String(b.item.medName || ''), undefined, { sensitivity: 'base' })
    ).map((row, returnIndex) => ({ ...row, returnIndex }));
}

function returnPrepackSourceLabel(row) {
    const label = String(row.queue.sourceLabel || row.queue.title || 'Prepack');
    const date = String(row.day.date || '');
    return label.replace(date, '').replace(/\s+\|\s+$/, '').trim() || 'Prepack';
}

function returnPrepackItemTimeLabel(row) {
    const date = String(row.day.date || '');
    const time = String(row.item.time || '');
    if (!time || time === date) return date;
    return time;
}

function returnPrepackGroups(rows) {
    const groups = new Map();
    rows.forEach(row => {
        const key = `${row.queue.id}|${row.day.date}`;
        if (!groups.has(key)) {
            groups.set(key, {
                key,
                queue: row.queue,
                day: row.day,
                rows: []
            });
        }
        groups.get(key).rows.push(row);
    });
    return [...groups.values()];
}

function returnPrepackEligibleItemCount(queue, day) {
    return (day?.items || []).filter(item => {
        if (item.inventoryReturned) return false;
        if (item.inventoryWasted) return false;
        if (!isPreparedPrepackItem(item)) return false;
        const med = db.inventory.find(candidate => candidate.id === item.medId);
        const schedule = prepackItemSchedule(item);
        const row = { queue, day, item, med, schedule };
        if (returnPrepackHasDocumentedWaste(row)) return false;
        if (isRangePrepackItem(item)) return prepackItemReturnableQty(row) > 0;
        return !prepackItemHasDocumentedGivenDose(queue, day, item);
    }).length;
}

function returnPrepackGroupStatus(group) {
    const totalEligible = returnPrepackEligibleItemCount(group.queue, group.day);
    return totalEligible > group.rows.length ? 'partial' : 'complete';
}

function returnPrepackGroupStockMode(group) {
    const deducted = group.rows.filter(row => row.item.inventoryDeducted === true).length;
    if (deducted === group.rows.length) return 'stock';
    if (deducted === 0) return 'record';
    return 'mixed';
}

function returnPrepackGroupReturnCategory(group) {
    const categories = Array.from(new Set((group.rows || []).map(returnPrepackRowCategory)));
    if (categories.length === 1) return categories[0];
    return 'mixed';
}

window.filterReturnPrepackList = function() {
    const body = document.getElementById('action-modal-body');
    if (!body) return;
    const memberId = body.querySelector('[name="returnMemberFilter"]')?.value || '';
    const from = body.querySelector('[name="returnFromDate"]')?.value || '';
    const to = body.querySelector('[name="returnToDate"]')?.value || '';
    const status = body.querySelector('[name="returnPackageStatus"]')?.value || 'all';
    const returnStatus = body.querySelector('[name="returnDoseStatus"]')?.value || 'all';
    let visible = 0;
    body.querySelectorAll('.return-prepack-group').forEach(group => {
        const date = group.dataset.date || '';
        const memberMatch = !memberId || group.dataset.memberId === memberId;
        const dateMatch = (!from || date >= from) && (!to || date <= to);
        const statusMatch = status === 'all' ||
            group.dataset.packageStatus === status ||
            group.dataset.stockMode === status;
        const returnStatusMatch = returnStatus === 'all' ||
            group.dataset.returnCategory === returnStatus;
        const show = memberMatch && dateMatch && statusMatch && returnStatusMatch;
        group.style.display = show ? '' : 'none';
        if (show) visible++;
        if (!show) {
            group.querySelectorAll('input[type="checkbox"]').forEach(input => {
                input.checked = false;
                input.indeterminate = false;
            });
            group.classList.remove('selected');
            group.querySelectorAll('.return-prepack-row.selected').forEach(row => row.classList.remove('selected'));
        }
    });
    const count = body.querySelector('#return-prepack-filter-count');
    if (count) count.textContent = `${visible} package${visible === 1 ? '' : 's'} shown`;
    updateReturnPrepackLabelPreview(false);
};

window.toggleReturnPrepackPackage = function(input) {
    const group = input?.closest('.return-prepack-group');
    if (!group) return;
    if (group.style.display === 'none') return;
    group.querySelectorAll('input[name="returnRows"]').forEach(child => {
        child.checked = input.checked;
        child.closest('.return-prepack-row')?.classList.toggle('selected', child.checked);
    });
    group.classList.toggle('selected', input.checked);
    updateReturnPrepackLabelPreview(false);
};

window.updateReturnPrepackPackageState = function(input) {
    input?.closest('.return-prepack-row')?.classList.toggle('selected', !!input.checked);
    const group = input?.closest('.return-prepack-group');
    const parent = group?.querySelector('input.return-prepack-package-check');
    if (!group || !parent) return;
    const children = [...group.querySelectorAll('input[name="returnRows"]')];
    const checked = children.filter(child => child.checked).length;
    parent.checked = checked === children.length;
    parent.indeterminate = checked > 0 && checked < children.length;
    group.classList.toggle('selected', checked > 0);
    updateReturnPrepackLabelPreview(false);
};

window.selectReturnPrepackByCode = function() {
    const body = document.getElementById('action-modal-body');
    if (!body) return;
    const input = body.querySelector('[name="returnPrepackCode"]');
    const code = normalizeMedicationCode(input?.value || '');
    if (!code) return;
    let matched = null;
    body.querySelectorAll('.return-prepack-group').forEach(group => {
        const groupCodes = String(group.dataset.prepackCodes || group.dataset.prepackCode || '')
            .split('|')
            .map(normalizeMedicationCode)
            .filter(Boolean);
        if (groupCodes.includes(code)) matched = group;
    });
    if (!matched) {
        const status = body.querySelector('#return-prepack-scan-status');
        if (status) status.textContent = 'No returnable package matched that QR code.';
        return;
    }
    body.querySelector('[name="returnMemberFilter"]').value = '';
    body.querySelector('[name="returnPackageStatus"]').value = 'all';
    const matchedDate = matched.dataset.date || '';
    const fromInput = body.querySelector('[name="returnFromDate"]');
    const toInput = body.querySelector('[name="returnToDate"]');
    if (matchedDate && fromInput && toInput) {
        fromInput.value = matchedDate;
        toInput.value = matchedDate;
    }
    const doseStatusFilter = body.querySelector('[name="returnDoseStatus"]');
    if (doseStatusFilter) doseStatusFilter.value = 'all';
    filterReturnPrepackList();
    matched.open = true;
    matched.scrollIntoView({ block: 'center' });
    const packageCheck = matched.querySelector('.return-prepack-package-check');
    if (packageCheck) {
        packageCheck.checked = true;
        packageCheck.indeterminate = false;
        toggleReturnPrepackPackage(packageCheck);
    }
    const status = body.querySelector('#return-prepack-scan-status');
    if (status) status.textContent = 'Package selected. Review items, then process the return or waste.';
    updateReturnPrepackLabelPreview(false);
};

function selectedReturnPrepackLabelRows(body = document.getElementById('action-modal-body')) {
    if (!body) return [];
    const result = collectNamedInputs(body);
    if ((result.handling || 'return') === 'waste') return [];
    const rows = returnablePrepackItems();
    const selected = Array.isArray(result.returnRows) ? result.returnRows : [result.returnRows].filter(value => value !== undefined);
    return selected.map(value => {
        const index = parseInt(value, 10);
        const row = rows[index];
        if (!row) return null;
        if (returnPrepackRowWasteOnly(row)) return null;
        const max = prepackItemReturnableQty(row);
        const rawQty = result[`returnQty_${row.returnIndex ?? index}`];
        const qty = isRangePrepackItem(row.item)
            ? parseAmount(rawQty, NaN)
            : max;
        if (!Number.isFinite(qty) || qty <= 0 || qty > max + 0.000001) return null;
        return { row, qty };
    }).filter(Boolean);
}

window.updateReturnPrepackLabelPreview = function(processed = false) {
    const body = document.getElementById('action-modal-body');
    if (!body) return;
    const preview = body.querySelector('#return-prepack-label-preview');
    const printButton = body.querySelector('#return-print-label-button');
    if (!preview || !printButton) return;
    const result = collectNamedInputs(body);
    if (processed === false) printButton.dataset.returnProcessed = 'false';
    if ((result.handling || 'return') === 'waste') {
        preview.innerHTML = '<div class="return-label-preview-empty">Waste entries do not generate return labels.</div>';
        printButton.disabled = true;
        printButton.classList.remove('return-print-ready');
        return;
    }
    const labelRows = selectedReturnPrepackLabelRows(body);
    const html = aggregateReturnPrepackLabels(labelRows);
    preview.innerHTML = html || '<div class="return-label-preview-empty">Select returnable prepack items to preview their return labels. Printing unlocks after Process Selected.</div>';
    fitLabelPages(preview);
    const canPrint = printButton.dataset.returnProcessed === 'true' && !!html;
    printButton.disabled = !canPrint;
    printButton.classList.toggle('return-print-ready', canPrint);
};

function returnPrepackChoicesHtml(rows, groups) {
    return groups.map((group, groupIndex) => {
        const packageId = `return-prepack-package-${groupIndex}`;
        const sourceLabel = returnPrepackSourceLabel(group.rows[0]);
        const itemText = `${group.rows.length} item${group.rows.length === 1 ? '' : 's'}`;
        const groupStatus = returnPrepackGroupStatus(group);
        const stockMode = returnPrepackGroupStockMode(group);
        const returnCategory = returnPrepackGroupReturnCategory(group);
        const groupDate = firstDateInPrepackDay(group.day);
        const childRows = group.rows.map(row => {
            const inputId = `return-prepack-${row.returnIndex}`;
            const returnableQty = prepackItemReturnableQty(row);
            const unit = row.med?.administrationUnit || (row.med ? inventoryUnitFor(row.med) : 'units');
            const qty = row.item.stockDelta
                ? `${formatAmount(returnableQty || parseAmount(row.item.stockDelta))} ${unit}`
                : (row.item.quantity || 'quantity not recorded');
            const wasteOnly = returnPrepackRowWasteOnly(row);
            const handlingText = returnPrepackRowHandlingText(row);
            const exception = returnPrepackDocumentedException(row);
            const recordText = exception
                ? `${doseStatusLabel(exception.doseStatus)} documented`
                : 'No administration documented';
            const stockText = wasteOnly
                ? handlingText
                : row.item.inventoryDeducted
                ? `${row.item.stockSource === 'kit' || row.item.kitId ? 'Med kit return' : 'Inventory return'}: ${qty}${isRangePrepackItem(row.item) ? ` (packed ${formatAmount(parseAmount(row.item.stockDelta, 0))}, given from this prepack ${formatAmount(rangePrepackGivenQty(row.queue, row.day, row.item))})` : ''}`
                : 'Prepared record only: PharmAtlas did not record an inventory deduction marker for this item, so returning it documents the package without changing stock.';
            const rangeQtyInput = isRangePrepackItem(row.item)
                ? `<label class="return-prepack-qty">Return qty
                    <input name="returnQty_${row.returnIndex}" type="number" step="any" min="0" max="${escapeHtml(returnableQty)}" value="${escapeHtml(returnableQty)}" oninput="updateReturnPrepackLabelPreview(false)">
                    <span>${escapeHtml(unit)}</span>
                </label>`
                : '';
            return `<label class="return-prepack-row${wasteOnly ? ' waste-only' : ''}" for="${inputId}" data-return-mode="${wasteOnly ? 'waste-only' : 'returnable'}">
                <span class="return-prepack-check"><input id="${inputId}" name="returnRows" type="checkbox" value="${row.returnIndex}" onchange="updateReturnPrepackPackageState(this); updateReturnPrepackActionUi();"></span>
                <span class="return-prepack-main">
                    <span class="return-prepack-time">${escapeHtml(returnPrepackItemTimeLabel(row))}</span>
                    <strong>${escapeHtml(row.item.medName)} ${escapeHtml(row.item.strength || '')}</strong>
                    <span class="return-prepack-meta">${escapeHtml(recordText)} | ${escapeHtml(stockText)}</span>
                    ${rangeQtyInput}
                </span>
            </label>`;
        }).join('');
        ensurePrepackDayCodes(group.queue);
        const packageCodes = prepackDayCodeList(group.day);
        return `<details class="return-prepack-group" data-member-id="${escapeHtml(group.queue.memberId || '')}" data-date="${escapeHtml(groupDate)}" data-prepack-code="${escapeHtml(group.day.prepackCode || '')}" data-prepack-codes="${escapeHtml(packageCodes.join('|'))}" data-package-status="${escapeHtml(groupStatus)}" data-stock-mode="${escapeHtml(stockMode)}" data-return-category="${escapeHtml(returnCategory)}">
            <summary class="return-prepack-package">
                <span class="return-prepack-check"><input id="${packageId}" class="return-prepack-package-check" type="checkbox" onclick="event.stopPropagation()" onchange="toggleReturnPrepackPackage(this); updateReturnPrepackActionUi();"></span>
                <span class="return-prepack-main">
                    <span class="return-prepack-time">${escapeHtml(group.day.date)}</span>
                    <strong>${escapeHtml(group.queue.memberName || group.queue.title || 'Prepack package')}</strong>
                    <span class="return-prepack-meta">${escapeHtml(sourceLabel)} | ${escapeHtml(itemText)} available to return/waste | ${groupStatus === 'partial' ? 'Partial package' : 'Complete package'} | ${returnCategory === 'exception' ? 'missed/skipped/refused/held' : returnCategory === 'unadministered' ? 'unadministered' : 'mixed dose records'} | ${stockMode === 'record' ? 'record only/no stock change' : stockMode === 'stock' ? 'stock return available' : 'mixed stock + record'}</span>
                </span>
                <span class="return-prepack-caret" aria-hidden="true"></span>
            </summary>
            <div class="return-prepack-children">${childRows}</div>
        </details>`;
    }).join('');
}

function returnPrepackModalContent(labelHtml = '', statusText = '') {
    const rows = returnablePrepackItems();
    if (rows.length === 0) {
        return `<div data-action-modal-size="wide" class="return-prepack-modal return-prepack-modal-grid">
            <div class="return-prepack-left">
                ${statusText ? `<div id="return-prepack-status" class="return-prepack-status">${escapeHtml(statusText)}</div>` : ''}
                <div class="form-help">No prepared prepack doses are currently available to return or waste.</div>
            </div>
            <div class="return-prepack-preview-panel">
                <div class="return-preview-header">
                    <strong>Return label preview</strong>
                    <button id="return-print-label-button" type="button" class="${labelHtml ? 'return-print-ready' : ''}" data-return-processed="${labelHtml ? 'true' : 'false'}" onclick="printReturnPrepackLabels()" ${labelHtml ? '' : 'disabled'}>Print Return Labels</button>
                </div>
                <div id="return-prepack-label-preview" class="return-prepack-label-preview">${labelHtml || '<div class="return-label-preview-empty">Returned-medication labels appear here after processing a return.</div>'}</div>
            </div>
        </div>`;
    }
    const groups = returnPrepackGroups(rows);
    const dates = groups.map(group => firstDateInPrepackDay(group.day)).filter(Boolean).sort();
    const minDate = dates[0] || '';
    const maxDate = dates[dates.length - 1] || '';
    const memberOptions = [...new Map(groups.map(group => [group.queue.memberId, group.queue.memberName || group.queue.title || 'Unknown member']))]
        .filter(([id]) => id)
        .sort((a, b) => a[1].localeCompare(b[1], undefined, { sensitivity: 'base' }))
        .map(([id, name]) => `<option value="${escapeHtml(id)}">${escapeHtml(name)}</option>`)
        .join('');
    const choices = returnPrepackChoicesHtml(rows, groups);
    return `
        <div data-action-modal-size="wide" class="return-prepack-modal return-prepack-modal-grid">
            <div class="return-prepack-left">
            <div class="form-help" style="margin-bottom:8px;">Use this when a prepacked dose was missed, refused, held, broken, lost, or otherwise not used. Return adds eligible quantities back to inventory. Waste documents the loss and does not change inventory.</div>
            <div class="return-prepack-filter-panel">
                <label>Scan package QR
                    <input name="returnPrepackCode" type="text" placeholder="PA-PREP..." onkeydown="if(event.key==='Enter'){event.preventDefault();selectReturnPrepackByCode()}" style="width:150px;">
                </label>
                <button type="button" onclick="selectReturnPrepackByCode()">Select Package</button>
                <label>Member
                    <select name="returnMemberFilter" onchange="filterReturnPrepackList()">
                        <option value="">All members</option>
                        ${memberOptions}
                    </select>
                </label>
                <label>From
                    <input name="returnFromDate" type="date" value="${escapeHtml(minDate)}" onchange="filterReturnPrepackList()">
                </label>
                <label>To
                    <input name="returnToDate" type="date" value="${escapeHtml(maxDate)}" onchange="filterReturnPrepackList()">
                </label>
                <label>Package status
                    <select name="returnPackageStatus" onchange="filterReturnPrepackList()">
                        <option value="all">All returnable packages</option>
                        <option value="complete">Complete package</option>
                        <option value="partial">Partial package</option>
                        <option value="stock">Stock return available</option>
                        <option value="record">Record only / no stock change</option>
                        <option value="mixed">Mixed stock + record</option>
                    </select>
                </label>
                <label>Dose record
                    <select name="returnDoseStatus" onchange="filterReturnPrepackList()">
                        <option value="all">All dose records</option>
                        <option value="exception">Missed / skipped / refused / held</option>
                        <option value="unadministered">Unadministered / no record</option>
                        <option value="mixed">Mixed package</option>
                    </select>
                </label>
                <label class="return-reason-field">Return reason
                    <select name="returnReason">
                        <option value="missed dose">Missed dose</option>
                        <option value="refused dose">Refused dose</option>
                        <option value="held dose">Held dose</option>
                        <option value="packing error">Packing error</option>
                        <option value="other">Other</option>
                    </select>
                </label>
                <label class="waste-reason-field" style="display:none;">Waste reason
                    <select name="wasteReason">
                        <option value="lost">Lost</option>
                        <option value="broken">Broken</option>
                        <option value="contaminated">Contaminated</option>
                        <option value="discarded">Discarded</option>
                        <option value="other">Other</option>
                    </select>
                </label>
                <label class="return-handling-field">Action
                    <select name="handling" onchange="updateReturnPrepackActionUi(); updateReturnPrepackLabelPreview(false)">
                        <option value="return">Return to inventory</option>
                        <option value="waste">Waste / do not return</option>
                    </select>
                </label>
                <span id="return-prepack-filter-count">${groups.length} package${groups.length === 1 ? '' : 's'} shown</span>
            </div>
            <div id="return-prepack-scan-status" class="form-help" style="margin-top:4px;">Scan a package QR to open/select that day. Nothing is returned until you click Process Selected.</div>
            <div class="field-row-stacked" style="margin-top:8px;">
                <label>Note:</label><textarea name="note" rows="2" style="width:100%; resize:none;" placeholder="Optional return note"></textarea>
            </div>
            ${statusText ? `<div id="return-prepack-status" class="return-prepack-status">${escapeHtml(statusText)}</div>` : '<div id="return-prepack-status" class="return-prepack-status" style="display:none;"></div>'}
            <div class="field-row" style="justify-content:flex-end; margin-top:8px;">
                <button type="button" onclick="processReturnPrepackSelection()">Process Selected</button>
            </div>
            <div class="sunken-panel label-selection-list return-prepack-list" style="margin-top:8px; max-height:330px;">${choices}</div>
            </div>
            <div class="return-prepack-preview-panel">
                <div class="return-preview-header">
                    <strong>Return label preview</strong>
                    <button id="return-print-label-button" type="button" class="${labelHtml ? 'return-print-ready' : ''}" data-return-processed="${labelHtml ? 'true' : 'false'}" onclick="printReturnPrepackLabels()" ${labelHtml ? '' : 'disabled'}>Print Return Labels</button>
                </div>
                <div id="return-prepack-label-preview" class="return-prepack-label-preview">${labelHtml || '<div class="return-label-preview-empty">Returned-medication labels appear here after processing a return. Waste entries do not generate labels.</div>'}</div>
            </div>
        </div>
    `;
}

window.returnPrepackedDispense = async function() {
    const rows = returnablePrepackItems();
    if (rows.length === 0) {
        await appAlert('No prepared prepack doses are available to return.');
        return;
    }
    await showActionModal('Return / Waste Prepacked Dose(s)', returnPrepackModalContent(), 'Close');
};

function commandScanMedFilterButtons(scan = activeCommandScan) {
    const items = commandScanItems(scan);
    const medIds = Array.from(new Set(items.map(item => item.medId).filter(Boolean)));
    if (medIds.length <= 1) return '';
    const current = scan?.medId || 'all';
    const medButtons = medIds.map(medId => {
        const med = db.inventory.find(item => item.id === medId);
        const label = med ? `${med.name} ${formatLabelMedStrength(med)}`.trim() : 'Medication';
        return `<button type="button" class="${current === medId ? 'active' : ''}" onclick="setCommandScanMedFilter('${escapeHtml(medId)}')">${escapeHtml(label)}</button>`;
    }).join('');
    return `<div class="command-scan-filter-strip">
        <button type="button" class="${current === 'all' ? 'active' : ''}" onclick="setCommandScanMedFilter('all')">All meds</button>
        ${medButtons}
    </div>`;
}

function commandScanContentsHtml(scan = activeCommandScan) {
    const items = commandScanItems(scan);
    if (!items.length) return '<div class="empty-state">No medications were found for this scan.</div>';
    const day = commandScanDay(scan);
    return items.map(item => {
        const med = db.inventory.find(candidate => candidate.id === item.medId);
        const scheduleStatus = commandScanItemScheduleStatus(item, day);
        const status = item.inventoryWasted ? 'wasted'
            : item.inventoryReturned ? 'returned'
            : isPreparedPrepackItem(item) ? 'prepacked'
            : 'label';
        const meta = [
            item.time,
            item.quantity ? `Qty ${item.quantity}` : '',
            item.dose ? `Dose ${item.dose}` : '',
            med?.expiry ? `Exp ${med.expiry}` : ''
        ].filter(Boolean).join(' | ');
        return `<div class="command-scan-med-row ${status}">
            <div>
                <strong>${escapeHtml(item.medName || med?.name || 'Medication')} ${escapeHtml(item.strength || (med ? formatLabelMedStrength(med) : ''))}</strong>
                ${scheduleStatus ? `<span class="command-scan-status-badge ${escapeHtml(scheduleStatus.className)}">${escapeHtml(scheduleStatus.label)}</span>` : ''}
                <small>${escapeHtml(meta || 'Medication label scan')}</small>
            </div>
        </div>`;
    }).join('');
}

function commandScanHistoryHtml(scan = activeCommandScan) {
    const rows = commandScanTrackingRows(scan, scan?.medId || 'all');
    if (!rows.length) return '<div class="empty-state">No preparation, administration, return, or waste history found for this scan.</div>';
    return `<table class="command-history-table">
        <thead><tr><th>Action Date/Time</th><th>Action Type</th><th>Medication</th><th>Details</th></tr></thead>
        <tbody>${rows.map(row => `<tr class="command-history-${escapeHtml(row.type.toLowerCase().replace(/[^a-z]+/g, '-'))}">
            <td>${escapeHtml(row.when || '')}</td>
            <td>${escapeHtml(row.type || '')}</td>
            <td>${escapeHtml(row.medName || '')}</td>
            <td>${escapeHtml(row.details || '')}</td>
        </tr>`).join('')}</tbody>
    </table>`;
}

function renderMemberCommandScanPanel() {
    const panel = document.getElementById('member-command-scan-panel');
    if (!panel) return;
    const scan = activeCommandScan && (!activeCommandScan.memberId || activeCommandScan.memberId === currentEditingMemberId)
        ? activeCommandScan
        : null;
    if (!scan) {
        panel.innerHTML = '<div class="empty-state">Scan a prepack or medication label to review package contents and action history.</div>';
        return;
    }
    const queue = commandScanQueue(scan);
    const day = commandScanDay(scan);
    const member = commandScanMember(scan) || db.family.find(item => item.id === currentEditingMemberId);
    const title = queue
        ? `${queue.title || queue.sourceLabel || 'Prepack package'}`
        : `Medication label: ${commandScanItems(scan).map(item => item.medName).join(', ') || scan.code}`;
    const source = queue
        ? `${day?.date || ''} | Package code ${day?.prepackScanCode || day?.prepackCode || scan.code}`
        : `Inventory label code ${scan.code}${member ? ` | ${memberDisplayName(member)}` : ''}`;
    panel.innerHTML = `
        <div class="command-scan-card">
            <div class="command-scan-header">
                <div>
                    <strong>${escapeHtml(title)}</strong>
                    <small>${escapeHtml(source)}</small>
                </div>
                <div class="command-scan-actions">
                    ${queue ? `<button type="button" onclick="openCommandScanQueue()">Open Queue</button>` : `<button type="button" onclick="switchTab('prepackage')">Schedule Prepack</button>`}
                    ${queue ? '' : `<button type="button" onclick="recordCommandScanDose()">Record Dose</button>`}
                    <button type="button" onclick="openReturnForCommandScan()" ${queue ? '' : 'disabled'}>Return / Waste</button>
                    <button type="button" onclick="clearCommandScanPanel()">Clear</button>
                </div>
            </div>
            ${commandScanMedSelector(scan)}
            <div class="command-scan-layout">
                <div>
                    <div class="command-scan-subtitle">Package / label contents</div>
                    <div class="command-scan-med-list">${commandScanContentsHtml(scan)}</div>
                </div>
                <div>
                    <div class="command-scan-subtitle">Dispense and administration history</div>
                    <div class="command-scan-history">${commandScanHistoryHtml(scan)}</div>
                </div>
            </div>
        </div>`;
    enhanceButtonIcons(panel);
}

function renderDashboardCommandScanStatus() {
    const target = document.getElementById('dashboard-command-scan-status');
    if (!target) return;
    if (!activeCommandScan) {
        target.innerHTML = '<span class="rail-muted">Scan an Aztec/package code to jump to the member and review prepack history.</span>';
        return;
    }
    const member = commandScanMember(activeCommandScan);
    const queue = commandScanQueue(activeCommandScan);
    const day = commandScanDay(activeCommandScan);
    const itemCount = commandScanItems(activeCommandScan).length;
    target.innerHTML = `<button type="button" class="rail-list-button ok" onclick="openCommandScanInProfile()">
        <strong>${escapeHtml(queue ? 'Scanned prepack package' : 'Scanned medication label')}</strong>
        <small>${escapeHtml(member ? memberDisplayName(member) : 'Select member from profile')} | ${escapeHtml(day?.date || activeCommandScan.code)} | ${itemCount} item${itemCount === 1 ? '' : 's'}</small>
    </button>`;
}

window.setCommandScanMedFilter = function(medId = 'all') {
    if (!activeCommandScan) return;
    activeCommandScan.medId = medId === 'all' ? '' : medId;
    renderMemberCommandScanPanel();
};

window.clearCommandScanPanel = function() {
    activeCommandScan = null;
    renderMemberCommandScanPanel();
    renderDashboardCommandScanStatus();
};

window.openCommandScanInProfile = async function() {
    if (!activeCommandScan?.memberId) {
        await appAlert('This label is linked to inventory, but not to a specific member. Open the member profile first, then scan again from the Scheduled Medications tab.');
        return;
    }
    await openMemberModal(activeCommandScan.memberId, 'orders');
    renderMemberCommandScanPanel();
};

window.openCommandScanQueue = function() {
    const queue = commandScanQueue(activeCommandScan);
    if (!queue) return;
    const day = commandScanDay(activeCommandScan);
    if (day) {
        const index = (queue.days || []).indexOf(day);
        if (index >= 0) queue.currentDayIndex = index;
    }
    activePrepackQueueId = queue.id;
    switchTab('prepackage');
    renderPrepackageQueues();
};

window.recordCommandScanDose = async function() {
    if (!activeCommandScan) return;
    const medIds = Array.from(new Set(commandScanItems(activeCommandScan).map(item => item.medId).filter(Boolean)));
    if (!medIds.length) return;
    if (medIds.length > 1 && !activeCommandScan.medId) {
        await appAlert('Choose one medication from the View medication menu before recording a dose from this label.');
        return;
    }
    const medId = activeCommandScan.medId || medIds[0];
    await takeDose(medId);
    renderMemberCommandScanPanel();
    renderDashboardCommandScanStatus();
};

window.openReturnForCommandScan = function() {
    const queue = commandScanQueue(activeCommandScan);
    const day = commandScanDay(activeCommandScan);
    if (!queue || !day) return;
    window.returnPrepackedDispense();
    setTimeout(() => {
        const body = document.getElementById('action-modal-body');
        const input = body?.querySelector('[name="returnPrepackCode"]');
        if (!input) return;
        input.value = day.prepackScanCode || day.prepackCode || activeCommandScan.code || '';
        selectReturnPrepackByCode();
    }, 75);
};

window.scanDailyCommandCode = async function(rawCode = '', options = {}) {
    const inputCode = String(rawCode || document.getElementById('daily-command-scan-code')?.value || '').trim();
    const resolved = resolveCommandScan(inputCode, { memberId: currentEditingMemberId, ...options });
    if (!resolved) {
        await appAlert('No matching prepack package or inventory medication code was found.');
        return;
    }
    activeCommandScan = resolved;
    const dashboardInput = document.getElementById('daily-command-scan-code');
    const memberInput = document.getElementById('member-command-scan-code');
    if (dashboardInput) dashboardInput.value = '';
    if (memberInput) memberInput.value = '';
    renderDashboardCommandScanStatus();
    if (resolved.memberId) {
        await openMemberModal(resolved.memberId, 'orders');
    }
    renderMemberCommandScanPanel();
};

window.updateReturnPrepackActionUi = function() {
    const body = document.getElementById('action-modal-body');
    if (!body) return;
    const handling = body.querySelector('[name="handling"]')?.value || 'return';
    body.querySelectorAll('.return-reason-field').forEach(el => { el.style.display = handling === 'return' ? '' : 'none'; });
    body.querySelectorAll('.waste-reason-field').forEach(el => { el.style.display = handling === 'waste' ? '' : 'none'; });
    body.querySelectorAll('.return-prepack-row.waste-only').forEach(row => {
        row.classList.toggle('return-blocked', handling === 'return');
    });
};

function setReturnPrepackStatus(message, severity = 'error') {
    const status = document.getElementById('return-prepack-status');
    if (!status) return;
    status.textContent = message || '';
    status.style.display = message ? '' : 'none';
    status.classList.toggle('return-prepack-status-error', severity === 'error');
    status.classList.toggle('return-prepack-status-ok', severity === 'ok');
}

window.printReturnPrepackLabels = function() {
    const preview = document.getElementById('return-prepack-label-preview');
    if (!preview || preview.querySelector('.return-label-preview-empty')) return;
    pendingLabelHtml = preview.innerHTML;
    const printArea = document.getElementById('print-area');
    if (printArea) {
        printArea.innerHTML = pendingLabelHtml;
        fitLabelPages(printArea);
    }
    printPreparedArea();
};

window.processReturnPrepackSelection = async function() {
    const body = document.getElementById('action-modal-body');
    if (!body) return;
    const result = collectNamedInputs(body);
    const rows = returnablePrepackItems();
    const selected = Array.isArray(result.returnRows) ? result.returnRows : [result.returnRows].filter(value => value !== undefined);
    if (selected.length === 0) {
        setReturnPrepackStatus('Select at least one prepacked dose to return or waste.');
        return;
    }
    const labelRows = [];
    for (const value of selected) {
        const index = parseInt(value, 10);
        const row = rows[index];
        if (!row) continue;
        if (result.handling !== 'waste' && returnPrepackRowWasteOnly(row)) {
            setReturnPrepackStatus(`${row.item.medName} is marked waste-only. Mark the container unopened from the medication schedule before returning it, or change Action to Waste / do not return.`);
            return;
        }
        const qtyOverride = result[`returnQty_${row.returnIndex ?? index}`];
        if (isRangePrepackItem(row.item)) {
            const qty = parseAmount(qtyOverride, NaN);
            const max = prepackItemReturnableQty(row);
            if (!Number.isFinite(qty) || qty <= 0 || qty > max + 0.000001) {
                setReturnPrepackStatus(`Enter a return quantity greater than 0 and up to ${formatAmount(max)} for ${row.item.medName}.`);
                return;
            }
        }
        if (result.handling === 'waste') {
            markPrepackItemWasted(row, result.wasteReason || 'wasted', result.note || '');
        } else {
            const returnedQty = markPrepackItemReturned(row, result.returnReason || 'returned', result.note || '', qtyOverride);
            const labelQty = returnedQty || parseAmount(qtyOverride, 0) || prepackItemReturnableQty(row);
            if (labelQty > 0) labelRows.push({ row, qty: labelQty });
        }
    }
    await sync();
    renderMemberCommandScanPanel();
    renderDashboardCommandScanStatus();
    const labelHtml = result.handling === 'waste' ? '' : aggregateReturnPrepackLabels(labelRows);
    const status = `${selected.length} prepacked dose${selected.length === 1 ? '' : 's'} ${result.handling === 'waste' ? 'marked wasted. No return labels were generated.' : 'returned to inventory.'}`;
    const actionBody = document.getElementById('action-modal-body');
    if (actionBody) {
        actionBody.innerHTML = returnPrepackModalContent(labelHtml, status);
        enhanceButtonIcons(actionBody);
        fitLabelPages(actionBody.querySelector('#return-prepack-label-preview'));
        updateReturnPrepackActionUi();
    }
};

window.toggleScanDoseRow = function(input) {
    input?.closest('.scan-dose-row')?.classList.toggle('selected', !!input.checked);
};

window.wasteScheduledMedicationDose = async function(scheduleId) {
    const schedule = db.schedules.find(item => item.id === scheduleId);
    const med = schedule ? db.inventory.find(item => item.id === schedule.medId) : null;
    if (!schedule || !med) return;
    const rows = returnablePrepackItems().filter(row => row.item.scheduleId === scheduleId);
    if (!rows.length) {
        await appAlert('No prepared prepack doses are available to waste for this medication. If the dose was not prepacked, document it as missed, skipped, refused, or held from Administer.', 'No Prepack To Waste');
        return;
    }
    const choices = rows.map((row, index) => {
        const inputId = `waste-prepack-${index}`;
        const qty = row.item.stockDelta
            ? `${formatAmount(parseAmount(row.item.stockDelta))} ${row.med?.administrationUnit || inventoryUnitFor(row.med)}`
            : (row.item.quantity || 'quantity not recorded');
        return `<label class="return-prepack-row" for="${inputId}">
            <span class="return-prepack-check"><input id="${inputId}" name="wasteRows" type="checkbox" value="${index}" onchange="this.closest('.return-prepack-row')?.classList.toggle('selected', this.checked)"></span>
            <span class="return-prepack-main">
                <span class="return-prepack-time">${escapeHtml(row.day.date)} ${escapeHtml(returnPrepackItemTimeLabel(row))}</span>
                <strong>${escapeHtml(row.item.medName)} ${escapeHtml(row.item.strength || '')}</strong>
                <span class="return-prepack-meta">Waste only: ${escapeHtml(qty)} stays deducted from inventory.</span>
            </span>
        </label>`;
    }).join('');
    const result = await showActionModal(`Waste Prepacked Dose: ${med.name}`, `
        <div data-action-modal-size="wide" class="return-prepack-modal">
            <div class="form-help" style="margin-bottom:8px;">Use this for a prepared dose that was lost, broken, contaminated, discarded, or otherwise cannot be returned to stock. Inventory will not be increased.</div>
            <div class="field-row">
                <label>Reason:
                    <select name="reason">
                        <option value="lost">Lost</option>
                        <option value="broken">Broken</option>
                        <option value="contaminated">Contaminated</option>
                        <option value="discarded">Discarded</option>
                        <option value="other">Other</option>
                    </select>
                </label>
            </div>
            <div class="field-row-stacked" style="margin-top:8px;">
                <label>Note:</label><textarea name="note" rows="2" style="width:100%; resize:none;" placeholder="Optional waste note"></textarea>
            </div>
            <div class="sunken-panel label-selection-list return-prepack-list" style="margin-top:8px; max-height:300px;">${choices}</div>
        </div>
    `, 'Waste Selected');
    if (!result) return;
    const selected = Array.isArray(result.wasteRows) ? result.wasteRows : [result.wasteRows].filter(value => value !== undefined);
    if (!selected.length) {
        await appAlert('Select at least one prepared dose to waste.');
        return;
    }
    selected.forEach(value => {
        const row = rows[parseInt(value, 10)];
        if (row) markPrepackItemWasted(row, result.reason || 'wasted', result.note || '');
    });
    await sync();
    await appAlert(`${selected.length} prepared dose${selected.length === 1 ? '' : 's'} marked wasted. Inventory was not changed.`, 'Waste Documented');
};

window.schedulePrepackScan = function(queueId) {
    clearTimeout(prepackScanTimer);
    prepackScanTimer = setTimeout(() => {
        const input = document.getElementById('prepack-scan-input');
        const queue = db.prepackQueues.find(item => item.id === queueId);
        const day = queue?.days?.[queue.currentDayIndex || 0];
        const nextItem = day?.items.find(candidate => candidate.status !== 'correct');
        const med = nextItem && db.inventory.find(candidate => candidate.id === nextItem.medId);
        const expectedCodes = med ? medicationCodes(med) : [normalizeMedicationCode(nextItem?.barcodeCode)].filter(Boolean);
        const expectedLength = Math.min(...[10, ...expectedCodes.map(code => code.length).filter(Boolean)]);
        const typedLength = normalizeMedicationCode(input?.value).length;
        if (typedLength >= Math.min(Math.max(expectedLength, 1), 4)) window.scanPrepackCode(queueId);
    }, 180);
};

async function choosePrepackItemsFromMultiScan(queue, day, scannedCode) {
    if (!isMultiMedicationScanPayload(scannedCode)) return [];
    const candidates = (day?.items || []).filter(item => {
        if (item.status === 'correct') return false;
        const med = db.inventory.find(candidate => candidate.id === item.medId);
        const expectedCodes = med ? medicationCodes(med) : [normalizeMedicationCode(item.barcodeCode)].filter(Boolean);
        return scannedCodeMatchesMedicationCodes(scannedCode, expectedCodes);
    });
    if (candidates.length <= 1) return candidates;
    const rows = candidates.map(item => {
        const med = db.inventory.find(candidate => candidate.id === item.medId);
        const unit = med ? med.administrationUnit || inventoryUnitFor(med) : item.unit || 'unit';
        return `<label class="scan-med-choice-row">
            <input type="checkbox" name="prepackItemIds" value="${escapeHtml(item.id)}" checked>
            <span>
                <strong>${escapeHtml(item.time || '')} - ${escapeHtml(item.medName || med?.name || 'Medication')}</strong>
                <small>${escapeHtml(formatAmount(prepackItemDoseQty(queue, item)))} ${escapeHtml(unit)}${item.regimenName ? ` | ${escapeHtml(item.regimenName)}` : ''}</small>
            </span>
        </label>`;
    }).join('');
    const result = await showActionModal('Choose Prepacked Medication(s)', `
        <div class="scan-med-choice-shell">
            <div class="form-help">This scanned custom label is linked to multiple inventory items. Select the medication(s) actually placed into this prepack. Medications linked as "must take together" are processed together when selected.</div>
            <div class="scan-med-choice-list">${rows}</div>
        </div>
    `, 'Mark Selected');
    if (!result) return [];
    const selectedIds = new Set(asArray(result.prepackItemIds));
    candidates.forEach(item => {
        if (!selectedIds.has(item.id)) return;
        prepackTogetherGroupItems(day, item).forEach(groupItem => {
            if (candidates.some(candidate => candidate.id === groupItem.id)) selectedIds.add(groupItem.id);
        });
    });
    return candidates.filter(item => selectedIds.has(item.id));
}

async function choosePrepackItemsFromMedKitScan(queue, day, kit) {
    const sourceByMedId = new Map();
    medKitAvailableChoices(kit).forEach(({ item }) => {
        if (!sourceByMedId.has(item.medId)) sourceByMedId.set(item.medId, medKitItemSourceValue(kit, item));
    });
    const candidates = (day?.items || []).filter(item =>
        item.status !== 'correct' &&
        item.medId &&
        sourceByMedId.has(item.medId)
    );
    if (!candidates.length) return [];
    const expandWithTogetherLinks = async selectedItems => {
        const expanded = [];
        const seen = new Set();
        for (const selected of selectedItems) {
            for (const groupItem of prepackTogetherGroupItems(day, selected)) {
                if (!groupItem?.id || groupItem.status === 'correct' || seen.has(groupItem.id)) continue;
                const sourceValue = sourceByMedId.get(groupItem.medId);
                if (!sourceValue) {
                    await appAlert(`${groupItem.medName || 'A linked medication'} must be taken together with ${selected.medName || 'the selected medication'}, but it is not available in ${medKitName(kit)}.`);
                    return null;
                }
                expanded.push({ item: groupItem, sourceValue });
                seen.add(groupItem.id);
            }
        }
        return expanded;
    };
    if (candidates.length === 1) return expandWithTogetherLinks(candidates);
    const rows = candidates.map(item => {
        const med = db.inventory.find(candidate => candidate.id === item.medId);
        const unit = med ? med.administrationUnit || inventoryUnitFor(med) : item.unit || 'unit';
        return `<label class="scan-med-choice-row">
            <input type="checkbox" name="prepackItemIds" value="${escapeHtml(item.id)}">
            <span>
                <strong>${escapeHtml(item.time || '')} - ${escapeHtml(item.medName || med?.name || 'Medication')}</strong>
                <small>${escapeHtml(formatAmount(prepackItemDoseQty(queue, item)))} ${escapeHtml(unit)} from ${escapeHtml(medKitName(kit))}${item.regimenName ? ` | ${escapeHtml(item.regimenName)}` : ''}</small>
            </span>
        </label>`;
    }).join('');
    const result = await showActionModal('Choose Med Kit Item(s)', `
        <div class="scan-med-choice-shell">
            <div class="form-help">This label belongs to <strong>${escapeHtml(medKitName(kit))}</strong>. Select which due prepack medication(s) you are filling from that kit. Only kit inventory will be reduced.</div>
            <div class="scan-med-choice-list">${rows}</div>
        </div>
    `, 'Use Selected');
    if (!result) return null;
    const selectedIds = new Set(asArray(result.prepackItemIds));
    return expandWithTogetherLinks(candidates.filter(item => selectedIds.has(item.id)));
}

window.scanPrepackCode = async function(queueId) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    const input = document.getElementById('prepack-scan-input');
    if (!queue || !input) return;
    ensurePrepackDayCodes(queue);
    const scannedCode = normalizeMedicationCode(input.value);
    if (!scannedCode) return;
    const packageMatch = (db.prepackQueues || []).find(candidate =>
        !isInventoryUnitDoseQueue(candidate) &&
        (candidate.days || []).some(day => prepackDayCodeMatches(day, scannedCode))
    );
    if (packageMatch) {
        ensurePrepackDayCodes(packageMatch);
        activePrepackQueueId = packageMatch.id;
        packageMatch.currentDayIndex = Math.max(0, packageMatch.days.findIndex(day => prepackDayCodeMatches(day, scannedCode)));
        input.value = '';
        renderPrepackageQueues();
        return;
    }
    const day = queue.days[queue.currentDayIndex || 0];
    let item = day?.items.find(candidate => candidate.status !== 'correct');
    if (!day || !item) return;
    const scannedKit = medKitFromScannedPayload(input.value || scannedCode);
    if (scannedKit) {
        const kitScanItems = await choosePrepackItemsFromMedKitScan(queue, day, scannedKit);
        if (kitScanItems === null) {
            input.value = '';
            return;
        }
        if (!kitScanItems.length) {
            input.value = '';
            await appAlert(`No pending medication in this prepack matches medications available in ${medKitName(scannedKit)}.`);
            return;
        }
        const previous = kitScanItems.map(entry => ({
            item: entry.item,
            status: entry.item.status,
            verificationMethod: entry.item.verificationMethod || '',
            scannedCode: entry.item.scannedCode || '',
            scannedAt: entry.item.scannedAt || '',
            inventorySource: entry.item.inventorySource || ''
        }));
        kitScanItems.forEach(entry => {
            entry.item.inventorySource = entry.sourceValue;
            entry.item.scannedCode = scannedCode;
            entry.item.scannedAt = new Date().toISOString();
            entry.item.status = 'correct';
            entry.item.verificationMethod = 'kit-label-scan';
        });
        const stockCheckItems = kitScanItems.map(entry => entry.item);
        const shortages = prepackStockShortagesForItems(queue, stockCheckItems);
        if (shortages.length) {
            previous.forEach(entry => {
                entry.item.status = entry.status;
                entry.item.verificationMethod = entry.verificationMethod;
                entry.item.scannedCode = entry.scannedCode;
                entry.item.scannedAt = entry.scannedAt;
                entry.item.inventorySource = entry.inventorySource;
            });
            input.value = '';
            await appAlert(`Not enough med kit stock to prepack: ${shortages.join(' ')}`);
            return;
        }
        const failed = kitScanItems.some(entry => !applyPrepackStockForReadyGroup(queue, day, entry.item, 'kit-label-scan'));
        if (failed) {
            previous.forEach(entry => {
                entry.item.status = entry.status;
                entry.item.verificationMethod = entry.verificationMethod;
                entry.item.scannedCode = entry.scannedCode;
                entry.item.scannedAt = entry.scannedAt;
                entry.item.inventorySource = entry.inventorySource;
            });
            input.value = '';
            await appAlert('One or more selected medications do not have enough med kit stock to complete this prepack scan.');
            return;
        }
        input.value = '';
        updatePrepackQueueStatus(queue);
        if (queue.status === 'completed') {
            activePrepackQueueId = nextActivePrepackQueueId(queue.id);
        } else if (day.status === 'completed') {
            const nextIndex = queue.days.findIndex((candidate, index) => index > queue.currentDayIndex && candidate.status !== 'completed');
            if (nextIndex >= 0) queue.currentDayIndex = nextIndex;
        }
        await sync();
        return;
    }
    const multiScanItems = await choosePrepackItemsFromMultiScan(queue, day, scannedCode);
    if (multiScanItems === null) {
        input.value = '';
        return;
    }
    if (multiScanItems.length === 1) item = multiScanItems[0];
    if (multiScanItems.length > 1) {
        const stockCheckItems = [];
        const stockCheckIds = new Set();
        multiScanItems.forEach(candidate => {
            prepackTogetherGroupItems(day, candidate).forEach(groupItem => {
                if (stockCheckIds.has(groupItem.id)) return;
                stockCheckIds.add(groupItem.id);
                stockCheckItems.push(groupItem);
            });
        });
        const shortages = prepackStockShortagesForItems(queue, stockCheckItems);
        if (shortages.length) {
            input.value = '';
            await appAlert(`Not enough stock to prepack: ${shortages.join(' ')}`);
            return;
        }
        const previous = multiScanItems.map(candidate => ({
            item: candidate,
            status: candidate.status,
            verificationMethod: candidate.verificationMethod || '',
            scannedCode: candidate.scannedCode || '',
            scannedAt: candidate.scannedAt || ''
        }));
        multiScanItems.forEach(candidate => {
            candidate.scannedCode = scannedCode;
            candidate.scannedAt = new Date().toISOString();
            candidate.status = 'correct';
            candidate.verificationMethod = 'scan';
        });
        const failed = multiScanItems.some(candidate => !applyPrepackStockForReadyGroup(queue, day, candidate, 'scan'));
        if (failed) {
            previous.forEach(entry => {
                entry.item.status = entry.status;
                entry.item.verificationMethod = entry.verificationMethod;
                entry.item.scannedCode = entry.scannedCode;
                entry.item.scannedAt = entry.scannedAt;
            });
            input.value = '';
            await appAlert('One or more selected medications do not have enough stock to complete this linked prepack scan.');
            return;
        }
        input.value = '';
        updatePrepackQueueStatus(queue);
        if (queue.status === 'completed') {
            activePrepackQueueId = nextActivePrepackQueueId(queue.id);
        } else if (day.status === 'completed') {
            const nextIndex = queue.days.findIndex((candidate, index) => index > queue.currentDayIndex && candidate.status !== 'completed');
            if (nextIndex >= 0) queue.currentDayIndex = nextIndex;
        }
        await sync();
        return;
    }
    const med = db.inventory.find(candidate => candidate.id === item.medId);
    const expectedCodes = med ? medicationCodes(med) : [normalizeMedicationCode(item.barcodeCode)].filter(Boolean);
    item.scannedCode = scannedCode;
    item.scannedAt = new Date().toISOString();
    const correctScan = scannedCodeMatchesMedicationCodes(scannedCode, expectedCodes);
    if (correctScan) {
        item.status = 'correct';
        item.verificationMethod = 'scan';
        if (!applyPrepackStockForReadyGroup(queue, day, item, 'scan')) {
            item.status = 'pending';
            item.verificationMethod = '';
            item.scannedCode = '';
            item.scannedAt = '';
            input.value = '';
            await appAlert(`${med?.name || item.medName} and its linked prepack group do not have enough stock to prepare ${item.time}.`);
            return;
        }
    } else {
        item.status = 'wrong';
    }
    input.value = '';
    updatePrepackQueueStatus(queue);
    if (queue.status === 'completed') {
        activePrepackQueueId = nextActivePrepackQueueId(queue.id);
    } else if (day.status === 'completed') {
        const nextIndex = queue.days.findIndex((candidate, index) => index > queue.currentDayIndex && candidate.status !== 'completed');
        if (nextIndex >= 0) queue.currentDayIndex = nextIndex;
    }
    await sync();
};

window.createInventoryUnitDosePrepack = async function() {
    if (!db.inventory.length) {
        await appAlert('Add inventory items before creating an inventory unit-dose prepack.');
        return;
    }
    const inventory = sortByName(db.inventory, inventoryDisplayName);
    const medOptions = inventory.map(med =>
        `<option value="${escapeHtml(inventoryDisplayName(med))}">${escapeHtml(formatAmount(parseAmount(med.stock)))} ${escapeHtml(inventoryUnitFor(med))} on hand</option>`
    ).join('');
    const defaults = defaultActualDateTime();
    const result = await showActionModal('Inventory Unit-Dose Prepack', `
        <div class="field-row-stacked">
            <label>Medication or supplement:</label>
            <input name="medSearch" list="unit-dose-inventory-options" placeholder="Search inventory..." style="width:100%;" oninput="updateInventoryUnitDosePrepackPreview()">
            <datalist id="unit-dose-inventory-options">${medOptions}</datalist>
        </div>
        <div class="field-row" style="margin-top:8px;">
            <label>Amount in each container:</label><input name="qtyPerContainer" type="number" min="0.001" step="any" value="1" style="width:90px;" oninput="updateInventoryUnitDosePrepackPreview()">
            <label>Containers:</label><input name="containerCount" type="number" min="1" step="1" value="1" style="width:70px;" oninput="updateInventoryUnitDosePrepackPreview()">
            <label>Type:</label>
            <select name="containerType" style="width:150px;">
                <option value="prefilled syringe">Prefilled syringe</option>
                <option value="cup">Cup</option>
                <option value="bottle">Bottle</option>
                <option value="packet">Packet</option>
                <option value="capsule">Capsule</option>
                <option value="container">Container</option>
            </select>
        </div>
        <div class="field-row" style="margin-top:8px;">
            <label>Prep date:</label><input name="prepDate" type="date" value="${escapeHtml(defaults.date)}" onchange="updateInventoryUnitDosePrepackPreview()">
            <label>Time:</label><input name="prepTime" type="time" value="${escapeHtml(defaults.time)}">
        </div>
        <fieldset style="margin-top:8px;">
            <legend>Prepared container expiration</legend>
            <div class="field-row">
                <label>Expiration:</label>
                <select name="expirationMode" onchange="updateInventoryUnitDosePrepackPreview()">
                    <option value="date">Calendar date</option>
                    <option value="days">X days after prep</option>
                </select>
                <span id="unit-dose-expiry-date-wrap" class="field-row" style="margin:0;">
                    <label>Date:</label><input name="expirationDate" type="date" onchange="updateInventoryUnitDosePrepackPreview()">
                </span>
                <span id="unit-dose-expiry-days-wrap" class="field-row" style="margin:0; display:none;">
                    <label>Days:</label><input name="expirationDays" type="number" min="0" step="1" placeholder="14" style="width:70px;" oninput="updateInventoryUnitDosePrepackPreview()">
                </span>
            </div>
        </fieldset>
        <div id="unit-dose-calculated-preview" class="unit-dose-preview">Select an inventory item to preview the calculated dose and stock needed.</div>
        <div class="field-row-stacked" style="margin-top:8px;">
            <label>Label name (optional):</label><input name="labelName" type="text" placeholder="Leave blank to use medication name">
        </div>
        <div class="field-row-stacked" style="margin-top:8px;">
            <label>Instructions:</label><textarea name="instructions" rows="2" style="width:100%; resize:none;"></textarea>
        </div>
        <div class="form-help" style="margin-top:8px;">Use this for non-patient-specific prefilled syringes, cups, bottles, packets, or other unit-dose containers. Source stock is removed one container at a time when each item is scanned or manually marked prepacked.</div>
    `, 'Create Queue');
    if (!result) return;
    const query = String(result.medSearch || '').trim();
    const loweredQuery = query.toLowerCase();
    const partialMatches = inventory.filter(item => inventoryDisplayName(item).toLowerCase().includes(loweredQuery) || String(item.name || '').toLowerCase().includes(loweredQuery));
    const med = inventory.find(item => inventoryDisplayName(item) === query)
        || inventory.find(item => item.name.toLowerCase() === loweredQuery)
        || (partialMatches.length === 1 ? partialMatches[0] : null);
    const qtyPerContainer = parseAmount(result.qtyPerContainer, NaN);
    const containerCount = parseInt(result.containerCount, 10);
    const expirationDays = parseInt(result.expirationDays, 10);
    const expirationDate = result.expirationMode === 'days'
        ? (Number.isFinite(expirationDays) && expirationDays >= 0 ? addDaysKey(result.prepDate || defaults.date, expirationDays) : '')
        : (result.expirationDate || '');
    if (!med || !Number.isFinite(qtyPerContainer) || qtyPerContainer <= 0 || !Number.isFinite(containerCount) || containerCount <= 0) {
        await appAlert('Select an inventory item, amount in each container, and number of containers.');
        return;
    }
    if (!expirationDate) {
        await appAlert('Select a prepared container expiration date, or enter how many days after prep the container expires.');
        return;
    }
    const totalNeeded = qtyPerContainer * containerCount;
    if (parseAmount(med.stock, 0) < totalNeeded) {
        await appAlert(`${med.name} has ${formatAmount(parseAmount(med.stock))} ${inventoryUnitFor(med)} on hand, but this prepack needs ${formatAmount(totalNeeded)} ${med.administrationUnit || inventoryUnitFor(med)}.`);
        return;
    }
    if (medicationCodes(med).length === 0) {
        med.barcodeCode = createMedicationCode();
        med.barcodeCodes = [med.barcodeCode];
    }
    const definition = inventoryUnitDoseDefinition(med, {
        prepDate: result.prepDate || defaults.date,
        prepTime: result.prepTime || defaults.time,
        qtyPerContainer,
        containerCount,
        containerType: result.containerType || 'container',
        expirationDate,
        labelName: result.labelName || '',
        instructions: result.instructions || ''
    });
    await createPrepackQueue(definition, {
        scheduledFor: `${definition.selection.prepDate}T${definition.selection.prepTime || '08:00'}`
    });
    switchTab('prepackage');
};

window.editPrepackLabelGroup = async function(queueId) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    if (!queue?.selection) return;
    const currentShift = queue.selection.prepackShift || 'all';
    const result = await showActionModal('Prepack Label Group', `
        <div style="font-size:11px;">Separate this active prepack queue by medication administration time.</div>
        ${prepackShiftChoiceHtml(currentShift)}
        <div class="form-help">Changing the group updates the active queue and marks existing labels for reprint.</div>
    `, 'Apply');
    if (!result) return;
    const nextShift = result.prepackShift || 'all';
    if (nextShift === currentShift) return;
    const matchingRows = prepackRowsForSelection({ ...queue.selection, prepackShift: nextShift });
    if (matchingRows.length === 0) {
        await appAlert('No scheduled doses match that label group for this queue.');
        return;
    }
    queue.selection.prepackShift = nextShift;
    queue.currentDayIndex = 0;
    reconcilePrepackQueue(queue);
    if (queue.labelsPrinted) {
        queue.days.forEach(day => { day.needsReprint = true; });
    }
    activePrepackQueueId = queue.id;
    await sync();
};

window.editPrepackDateRange = async function(queueId) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    if (!queue?.selection) return;
    if (isInventoryUnitDoseQueue(queue)) {
        const currentDate = queue.selection.prepDate || queue.days[0]?.date || localDateKey();
        const currentTime = queue.selection.prepTime || (queue.scheduledFor || '').slice(11, 16) || '08:00';
        const result = await showActionModal('Edit Unit-Dose Prepack Date', `
            <div class="field-row">
                <label>Prep date:</label><input name="prepDate" type="date" value="${escapeHtml(currentDate)}">
                <label>Time:</label><input name="prepTime" type="time" value="${escapeHtml(currentTime)}">
            </div>
            <div class="form-help" style="margin-top:8px;">This changes when the inventory unit-dose prepack is prepared. The queued containers stay the same.</div>
        `, 'Save Date');
        if (!result) return;
        const nextDate = result.prepDate || currentDate;
        const nextTime = result.prepTime || currentTime;
        queue.selection.prepDate = nextDate;
        queue.selection.prepTime = nextTime;
        queue.selection.startDate = nextDate;
        queue.selection.endDate = nextDate;
        queue.scheduledFor = `${nextDate}T${nextTime}`;
        queue.days.forEach(day => {
            day.date = nextDate;
            if (queue.labelsPrinted) day.needsReprint = true;
        });
        activePrepackQueueId = queue.id;
        await sync();
        return;
    }
    const currentStart = queue.selection.startDate || queue.days[0]?.date || localDateKey();
    const currentEnd = queue.selection.endDate || queue.days[queue.days.length - 1]?.date || currentStart;
    const result = await showActionModal('Edit Prepack Date Range', `
        <div class="field-row">
            <label>From:</label><input name="startDate" type="date" value="${escapeHtml(currentStart)}">
            <label>To:</label><input name="endDate" type="date" value="${escapeHtml(currentEnd)}">
        </div>
        <div class="field-row" style="margin-top:8px;">
            <label>Prepack date:</label><input name="prepackDate" type="date" value="${escapeHtml((queue.scheduledFor || '').slice(0, 10))}">
            <label>Time:</label><input name="prepackTime" type="time" value="${escapeHtml((queue.scheduledFor || '').slice(11, 16))}">
        </div>
        <div class="form-help" style="margin-top:8px;">Labels will be marked for reprint if the updated range changes the queued doses.</div>
    `, 'Save Range');
    if (!result) return;
    if (!result.startDate || !result.endDate || result.endDate < result.startDate) {
        await appAlert('Enter a valid prepack date range.');
        return;
    }
    queue.selection.startDate = result.startDate;
    queue.selection.endDate = result.endDate;
    queue.scheduledFor = result.prepackDate
        ? `${result.prepackDate}T${result.prepackTime || '08:00'}`
        : '';
    queue.currentDayIndex = 0;
    reconcilePrepackQueue(queue);
    activePrepackQueueId = queue.id;
    await sync();
};

window.markPrepackDayManual = async function(queueId) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    const day = queue?.days[queue.currentDayIndex || 0];
    if (!queue || !day) return;
    if (!await appConfirm(`Confirm that every medication for ${day.date} was prepacked manually?`, 'Prepacked Manually')) return;
    const shortages = prepackStockShortagesForItems(queue, day.items || []);
    if (shortages.length) {
        await appAlert(`This package was not marked prepacked because inventory is short:\n\n${shortages.join('\n')}`, 'Prepack Stock Check');
        return;
    }
    const manualTimestamp = new Date().toISOString();
    day.items.forEach(item => {
        item.status = 'correct';
        item.scannedCode = '';
        item.scannedAt = manualTimestamp;
        item.verificationMethod = 'manual';
    });
    for (const item of day.items) {
        if (!applyPrepackStockForReadyGroup(queue, day, item, 'manual')) {
            await appAlert(`${item.medName} does not have enough stock to prepack ${item.time}.`);
            return;
        }
    }
    day.needsReprint = false;
    updatePrepackQueueStatus(queue);
    if (queue.status === 'completed') {
        activePrepackQueueId = nextActivePrepackQueueId(queue.id);
    } else {
        const nextIndex = queue.days.findIndex((candidate, index) => index > queue.currentDayIndex && candidate.status !== 'completed');
        if (nextIndex >= 0) queue.currentDayIndex = nextIndex;
    }
    await sync();
};

window.markPrepackItemManual = async function(queueId, date, itemId) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    const day = queue?.days.find(item => item.date === date);
    const item = day?.items.find(candidate => candidate.id === itemId);
    if (!queue || !day || !item) return;
    if (isPreparedPrepackItem(item)) {
        await appAlert(`${item.medName} is already marked prepacked.`);
        return;
    }
    const togetherItems = prepackTogetherGroupItems(day, item);
    const pendingTogether = togetherItems.filter(candidate => candidate.id !== item.id && !isPreparedPrepackItem(candidate));
    const togetherText = pendingTogether.length
        ? ` This medication is linked as "must take together"; stock will be deducted when the remaining linked medication${pendingTogether.length === 1 ? '' : 's'} for this time are also prepacked.`
        : '';
    if (!await appConfirm(`Mark ${item.medName} at ${item.time} as manually prepacked?${togetherText}`, 'Prepack One Medication')) return;
    const previous = {
        status: item.status,
        scannedCode: item.scannedCode,
        scannedAt: item.scannedAt,
        verificationMethod: item.verificationMethod
    };
    item.status = 'correct';
    item.scannedCode = '';
    item.scannedAt = new Date().toISOString();
    item.verificationMethod = 'manual';
    if (!applyPrepackStockForReadyGroup(queue, day, item, 'manual-one')) {
        item.status = previous.status;
        item.scannedCode = previous.scannedCode;
        item.scannedAt = previous.scannedAt;
        item.verificationMethod = previous.verificationMethod;
        await appAlert(`${item.medName} does not have enough available stock to prepack ${item.time}.`);
        return;
    }
    if (isPrepackDayComplete(day)) day.needsReprint = false;
    updatePrepackQueueStatus(queue);
    activePrepackQueueId = queue.id;
    await sync();
    renderPrepackageQueues();
};

window.undoPrepackItem = async function(queueId, date, itemId) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    const day = queue?.days.find(item => item.date === date);
    const item = day?.items.find(candidate => candidate.id === itemId);
    if (!queue || !day || !item) return;
    const groupItems = prepackTogetherGroupItems(day, item)
        .filter(candidate => isPreparedPrepackItem(candidate) && !candidate.inventoryReturned && !candidate.inventoryWasted);
    const targets = groupItems.length ? groupItems : [item];
    const groupText = targets.length > 1
        ? ` This medication is linked as "must take together", so ${targets.length} prepared linked items will be undone together.`
        : '';
    if (!await appConfirm(`Undo prepack verification for ${item.medName} at ${item.time}? Any deducted stock will be returned to inventory.${groupText}`, 'Undo Prepack')) return;
    targets.forEach(target => undoPrepackItemStock(queue, target));
    day.needsReprint = queue.labelsPrinted;
    updatePrepackQueueStatus(queue);
    activePrepackQueueId = queue.id;
    await sync();
};

window.removePrepackItem = async function(queueId, date, itemId) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    const day = queue?.days.find(item => item.date === date);
    const item = day?.items.find(candidate => candidate.id === itemId);
    if (!queue || !day || !item) return;
    const schedule = db.schedules.find(candidate => candidate.id === item.scheduleId);
    if (!schedule || !queue.selection) {
        if (!await appConfirm(`Remove ${item.medName} from this prepack only?`, 'Change Prepack')) return;
        reversePrepackItemStock(queue, item, 'removed from prepack');
        day.items = day.items.filter(candidate => candidate.id !== itemId);
        day.needsReprint = queue.labelsPrinted;
        updatePrepackQueueStatus(queue);
        activePrepackQueueId = queue.id;
        await sync();
        return;
    }

    const discontinueOption = schedule.prepackAdded
        ? `<div class="prepack-remove-option prepack-remove-danger">
            <input id="prepack-remove-order" name="removeAction" type="radio" value="discontinue-order">
            <label for="prepack-remove-order">Discontinue this new medication and remove it from the member profile.</label>
        </div>`
        : '';
    const result = await showActionModal(`Remove From Prepack: ${item.medName}`, `
        <div class="prepack-remove-option">
            <input id="prepack-remove-dose" name="removeAction" type="radio" value="prepack-dose" checked>
            <label for="prepack-remove-dose">Remove only this ${escapeHtml(date)} dose from the prepack. Keep the member order unchanged.</label>
        </div>
        <div class="prepack-remove-option">
            <input id="prepack-remove-all" name="removeAction" type="radio" value="prepack-all">
            <label for="prepack-remove-all">Remove this medication from every date in this prepack. Keep the member order unchanged.</label>
        </div>
        ${discontinueOption}
    `, 'Continue');
    if (!result?.removeAction) return;

    if (result.removeAction === 'prepack-all' || result.removeAction === 'discontinue-order') {
        (queue.days || []).forEach(prepackDay => {
            (prepackDay.items || [])
                .filter(candidate => candidate.scheduleId === schedule.id)
                .forEach(candidate => reversePrepackItemStock(queue, candidate, 'removed from prepack'));
        });
    } else {
        reversePrepackItemStock(queue, item, 'removed from prepack');
    }

    if (result.removeAction === 'discontinue-order' && schedule.prepackAdded) {
        db.schedules = db.schedules.filter(candidate => candidate.id !== schedule.id);
        replaceCareRemindersForSource('schedule', schedule.id, []);
        if (queue.selection.kind === 'schedule-list') {
            queue.selection.scheduleIds = (queue.selection.scheduleIds || []).filter(id => id !== schedule.id);
        }
        queue.selection.addedScheduleIds = (queue.selection.addedScheduleIds || []).filter(id => id !== schedule.id);
    } else if (result.removeAction === 'prepack-all') {
        if (queue.selection.kind === 'member-range') {
            queue.selection.excludedScheduleIds = Array.from(new Set([
                ...(queue.selection.excludedScheduleIds || []),
                schedule.id
            ]));
        } else {
            queue.selection.scheduleIds = (queue.selection.scheduleIds || []).filter(id => id !== schedule.id);
        }
        queue.selection.addedScheduleIds = (queue.selection.addedScheduleIds || []).filter(id => id !== schedule.id);
    } else if (item.instanceKey) {
        queue.selection.excludedInstanceKeys = Array.from(new Set([
            ...(queue.selection.excludedInstanceKeys || []),
            item.instanceKey
        ]));
    }
    reconcilePrepackQueue(queue);
    activePrepackQueueId = queue.id;
    await sync();
};

window.removePrepackDay = async function(queueId, date) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    const day = queue?.days.find(item => item.date === date);
    if (!queue || !day) return;
    const preparedCount = (day.items || []).filter(item => isPreparedPrepackItem(item) && item.inventoryDeducted && !item.inventoryReturned).length;
    const message = preparedCount
        ? `Remove the entire ${date} prepack day? Stock already deducted for ${preparedCount} item${preparedCount === 1 ? '' : 's'} will be returned to inventory.`
        : `Remove the entire ${date} prepack day from this queue?`;
    if (!await appConfirm(message, 'Remove Prepack Day')) return;
    (day.items || []).forEach(item => reversePrepackItemStock(queue, item, 'removed prepack day'));
    queue.selection = queue.selection || {};
    queue.selection.excludedPrepackDates = Array.from(new Set([
        ...(queue.selection.excludedPrepackDates || []),
        firstDateInPrepackDay(day) || date
    ]));
    queue.days = (queue.days || []).filter(item => item.date !== date);
    if (queue.days.length === 0) {
        db.prepackQueues = db.prepackQueues.filter(item => item.id !== queue.id);
        activePrepackQueueId = nextActivePrepackQueueId(queue.id);
        await sync();
        return;
    }
    if (queue.currentDayIndex >= queue.days.length) queue.currentDayIndex = Math.max(0, queue.days.length - 1);
    updatePrepackQueueStatus(queue);
    activePrepackQueueId = queue.days.length ? queue.id : nextActivePrepackQueueId(queue.id);
    await sync();
};

window.updatePrepackAddMedication = function() {
    const body = document.getElementById('action-modal-body');
    const search = body?.querySelector('[name="medSearch"]');
    const select = body?.querySelector('[name="medId"]');
    if (!search || !select) return;
    const query = search.value.trim().toLowerCase();
    const matches = db.inventory
        .filter(med => query && med.name.toLowerCase() === query)
        .sort((a, b) => formatMedStrength(a).localeCompare(formatMedStrength(b), undefined, { numeric: true, sensitivity: 'base' }));
    const previous = select.value;
    select.innerHTML = matches.map(med =>
        `<option value="${escapeHtml(med.id)}">${escapeHtml(formatMedStrength(med))}</option>`
    ).join('') || '<option value="">Select a medication first</option>';
    select.disabled = matches.length === 0;
    if (matches.some(med => med.id === previous)) select.value = previous;
    window.calculatePrepackAddDose();
};

window.calculatePrepackAddDose = function() {
    const body = document.getElementById('action-modal-body');
    const medId = body?.querySelector('[name="medId"]')?.value;
    const doseQty = parseAmount(body?.querySelector('[name="doseQty"]')?.value, 0);
    const calculated = body?.querySelector('[name="calculatedDose"]');
    const unit = body?.querySelector('#prepack-add-qty-unit');
    const med = db.inventory.find(item => item.id === medId);
    if (calculated) calculated.value = med ? formatPrescribedDose(med, doseQty) : '';
    if (unit) unit.textContent = med ? (med.administrationUnit || med.formulation || 'units') : '';
};

window.renderPrepackAddTimes = function() {
    const body = document.getElementById('action-modal-body');
    const freq = body?.querySelector('[name="freq"]')?.value || 'QD';
    const container = body?.querySelector('#prepack-add-times');
    if (!container) return;
    const previous = Array.from(container.querySelectorAll('[name="prepackTimes"]')).map(input => input.value);
    const count = getExpectedTimeCount(freq) || 1;
    container.innerHTML = Array.from({ length: count }, (_, index) => `
        <div class="field-row">
            <label>Dose ${index + 1}:</label>
            <input name="prepackTimes" type="time" value="${escapeHtml(previous[index] || defaultTimeForIndex(index, freq))}">
        </div>`).join('');
};

window.toggleAllPrepackAddDates = function(checked) {
    document.querySelectorAll('#action-modal-body input[name="prepackDates"]').forEach(input => {
        input.checked = checked;
    });
};

window.addProfileMedicationToPrepack = async function(queueId) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    if (!queue || queue.selection?.singleMedication) return;
    const represented = new Set(queue.days.flatMap(day => day.items.map(item => item.scheduleId)));
    const candidates = db.schedules
        .filter(schedule =>
            schedule.memberId === queue.memberId &&
            !isScheduleArchived(schedule) &&
            !represented.has(schedule.id) &&
            getScheduleInstancesInRange(schedule, queue.selection?.startDate, queue.selection?.endDate).length > 0
        )
        .sort((a, b) => {
            const first = db.inventory.find(item => item.id === a.medId)?.name || '';
            const second = db.inventory.find(item => item.id === b.medId)?.name || '';
            return first.localeCompare(second, undefined, { sensitivity: 'base' });
        });
    if (candidates.length === 0) {
        await appAlert('Every eligible medication from this member profile is already included in the prepack.');
        return;
    }
    const choices = candidates.map((schedule, index) => {
        const med = db.inventory.find(item => item.id === schedule.medId);
        const inputId = `prepack-profile-med-${index}`;
        return `<div class="label-selection-item">
            <input id="${inputId}" name="scheduleIds" type="checkbox" value="${escapeHtml(schedule.id)}">
            <label for="${inputId}">${escapeHtml(med?.name || 'Unknown medication')} ${escapeHtml(med ? formatMedStrength(med) : '')} - ${escapeHtml(formatFrequency(schedule))}</label>
        </div>`;
    }).join('');
    const result = await showActionModal('Add Medication From Member Profile', `
        <div class="sunken-panel label-selection-list">${choices}</div>
    `, 'Add Selected');
    if (!result) return;
    const selectedIds = result.scheduleIds || [];
    if (selectedIds.length === 0) {
        await appAlert('Select at least one medication.');
        return;
    }
    if (queue.selection?.kind === 'member-range') {
        const selected = new Set(selectedIds);
        queue.selection.excludedScheduleIds = (queue.selection.excludedScheduleIds || [])
            .filter(id => !selected.has(id));
    } else {
        queue.selection.scheduleIds = Array.from(new Set([...(queue.selection.scheduleIds || []), ...selectedIds]));
    }
    queue.selection.addedScheduleIds = Array.from(new Set([...(queue.selection.addedScheduleIds || []), ...selectedIds]));
    reconcilePrepackQueue(queue);
    activePrepackQueueId = queue.id;
    await sync();
};

window.addLastMinutePrepackItem = async function(queueId) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    if (!queue || db.inventory.length === 0) return;
    const selectableDates = dateKeysInRange(queue.selection?.startDate, queue.selection?.endDate);
    const dateChoices = (selectableDates.length ? selectableDates : queue.days.map(day => day.date)).map((date, index) => {
        const inputId = `prepack-add-date-${index}`;
        return `<span class="weekday-option"><input id="${inputId}" name="prepackDates" type="checkbox" value="${escapeHtml(date)}"><label for="${inputId}">${escapeHtml(date)}</label></span>`;
    }).join('');
    const inventory = db.inventory
        .slice()
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }));
    const medNames = Array.from(new Set(inventory.map(med => med.name)))
        .map(name => `<option value="${escapeHtml(name)}"></option>`)
        .join('');
    const actionWindow = ensureActionModal().querySelector('.window');
    if (actionWindow) actionWindow.style.width = 'min(720px, calc(100vw - 20px))';
    const result = await showActionModal('Add Medication to Prepack and Member Profile', `
        <div class="field-row">
            <label>Medication:</label>
            <input name="medSearch" list="prepack-med-options" value="" placeholder="Search medication..." style="width:190px;" oninput="updatePrepackAddMedication()">
            <datalist id="prepack-med-options">${medNames}</datalist>
            <label>Strength:</label>
            <select name="medId" style="width:150px;" onchange="calculatePrepackAddDose()" disabled><option value="">Select a medication first</option></select>
        </div>
        <div class="field-row" style="margin-top:8px;">
            <label>Quantity:</label><input name="doseQty" type="number" min="0.01" step="any" value="1" style="width:70px;" oninput="calculatePrepackAddDose()">
            <span id="prepack-add-qty-unit"></span>
            <label>Calculated dose:</label><input name="calculatedDose" type="text" value="" disabled style="width:150px;">
        </div>
        <div class="field-row" style="margin-top:8px;">
            <label>Frequency:</label>
            <select name="freq" onchange="renderPrepackAddTimes()">
                <option value="QD">Once per selected date</option>
                <option value="BID">Twice per selected date</option>
                <option value="TID">Three times per selected date</option>
                <option value="QID">Four times per selected date</option>
                <option value="Nightly">Nightly on selected dates</option>
            </select>
            <label>Prescriber:</label>
            <select name="prescriberId" style="width:180px;">${prescriberOptionsHtml('', queue.memberId, false)}</select>
        </div>
        <div class="field-row-stacked" style="margin-top:8px;"><label>Administration time(s):</label><div id="prepack-add-times">
            <div class="field-row"><label>Dose 1:</label><input name="prepackTimes" type="time" value="08:00"></div>
        </div></div>
        <div class="field-row-stacked" style="margin-top:8px;">
            <div class="field-row"><label>Affected date(s):</label><button type="button" onclick="toggleAllPrepackAddDates(true)">Select All</button><button type="button" onclick="toggleAllPrepackAddDates(false)">Clear</button></div>
            <div class="prepack-date-choices">${dateChoices}</div>
        </div>
        <div class="field-row-stacked" style="margin-top:8px;"><label>Instructions:</label><textarea name="instructions" rows="2" style="width:100%; resize:none;"></textarea></div>
    `, 'Add Medication');
    if (actionWindow) actionWindow.style.width = '420px';
    if (!result) return;
    const med = db.inventory.find(item => item.id === result.medId);
    const dates = (result.prepackDates || []).slice().sort();
    const doseQty = parseAmount(result.doseQty, NaN);
    const submittedTimes = Array.isArray(result.prepackTimes)
        ? result.prepackTimes
        : [result.prepackTimes].filter(Boolean);
    const times = Array.from(new Set(submittedTimes)).filter(Boolean).sort();
    const expectedTimes = getExpectedTimeCount(result.freq);
    if (!med || dates.length === 0 || !Number.isFinite(doseQty) || doseQty <= 0 || times.length !== expectedTimes) {
        await appAlert(`Select a medication, one or more dates, a quantity, and ${expectedTimes} administration time${expectedTimes === 1 ? '' : 's'}. Times may match other medications.`);
        return;
    }
    const schedule = {
        id: `prepack_schedule_${Date.now()}_${Math.random().toString(16).slice(2)}`,
        memberId: queue.memberId,
        medId: med.id,
        doseQty: String(doseQty),
        prescriberId: result.prescriberId || med.prescriberId || '',
        freq: result.freq,
        startDate: dates[0],
        endDate: dates[dates.length - 1],
        includedDates: dates,
        excludedInstances: [],
        times,
        instructions: result.instructions || '',
        prepackAdded: true,
        isOneTime: false
    };
    db.schedules.push(schedule);
    if (queue.selection?.kind === 'schedule-list') {
        queue.selection.scheduleIds = Array.from(new Set([...(queue.selection.scheduleIds || []), schedule.id]));
    } else if (!queue.selection) {
        queue.selection = {
            kind: 'schedule-list',
            scheduleIds: [schedule.id],
            startDate: dates[0],
            endDate: dates[dates.length - 1]
        };
    }
    reconcilePrepackQueue(queue);
    queue.currentDayIndex = Math.max(queue.days.findIndex(day => dates.includes(day.date)), 0);
    activePrepackQueueId = queue.id;
    await sync();
};

function prepackItemLabelMedName(item) {
    const schedule = prepackItemSchedule(item);
    const med = db.inventory.find(candidate => candidate.id === item?.medId);
    return schedule && med ? formatMultiMedLabelName(schedule, med) : `${item?.medName || 'Medication'} ${item?.dose || item?.strength || ''}`.trim();
}

function prepackPlainLabelRow(item) {
    return `${item.time} ${prepackItemLabelMedName(item)} ${item.quantity || ''}`;
}

function prepackPlainLabelRowHtml(item) {
    return `<div class="label-med-row"><b>${escapeHtml(item.time)}</b>: ${escapeHtml(prepackItemLabelMedName(item))} (${escapeHtml(item.quantity || '')})</div>`;
}

function prepackLinkedLabelLineHtml(item) {
    return `<div class="label-small linked-label-line"><b>${escapeHtml(item.time)}</b>: ${escapeHtml(prepackItemLabelMedName(item))} Dose ${escapeHtml(item.dose || '')} Qty ${escapeHtml(item.quantity || '')}</div>`;
}

function prepackLinkedGroupLabelBlockHtml(queue, primaryItem, linkedItems) {
    const primarySchedule = prepackItemSchedule(primaryItem);
    const primaryMed = db.inventory.find(candidate => candidate.id === primaryItem?.medId);
    const primaryName = primaryMed && primarySchedule
        ? `${primaryMed.name} ${formatLabelMedStrength(primaryMed)}`
        : `${primaryItem?.medName || 'Medication'} ${primaryItem?.strength || ''}`.trim();
    const primaryDose = primaryItem?.dose || (primaryMed && primarySchedule ? formatPrescribedDose(primaryMed, primarySchedule.doseQty) : '');
    const primaryQty = primaryItem?.quantity || (primaryMed && primarySchedule ? formatQtyForSchedule(primarySchedule, primaryMed) : '');
    const instructionSchedules = [primarySchedule, ...linkedItems.map(prepackItemSchedule)].filter(Boolean);
    const instructionLines = linkedMedicationInstructionLines(instructionSchedules);
    return `<div class="prepack-linked-label-group">
        <div class="label-title">${escapeHtml(primaryName)}</div>
        <div class="label-small">Dose: ${escapeHtml(primaryDose)} | Qty: ${escapeHtml(primaryQty)}</div>
        <div class="label-small">Member: ${escapeHtml(queue.memberName || '')}</div>
        <div class="label-small linked-label-heading"><b>Take together:</b></div>
        ${linkedItems.map(prepackLinkedLabelLineHtml).join('')}
        ${instructionLines.map(line => `<div class="label-small"><b>Instructions:</b> ${escapeHtml(line)}</div>`).join('')}
    </div>`;
}

function prepackDayLabelEntries(day) {
    const seen = new Set();
    const items = (day.items || []).slice().sort((a, b) =>
        timeToMinutes(a.time) - timeToMinutes(b.time) ||
        String(a.medName || '').localeCompare(String(b.medName || ''), undefined, { sensitivity: 'base' })
    );
    return items.map(item => {
        if (seen.has(item.id)) return null;
        const group = prepackTogetherGroupItems(day, item)
            .filter(candidate => candidate && !seen.has(candidate.id))
            .sort((a, b) =>
                timeToMinutes(a.time) - timeToMinutes(b.time) ||
                String(a.medName || '').localeCompare(String(b.medName || ''), undefined, { sensitivity: 'base' })
            );
        if (group.length > 1) {
            const primary = prepackLinkedPrimaryItem(group);
            group.forEach(candidate => seen.add(candidate.id));
            return {
                type: 'linked',
                primary,
                linked: group.filter(candidate => candidate.id !== primary.id)
            };
        }
        seen.add(item.id);
        return { type: 'single', item };
    }).filter(Boolean);
}

function prepackDayLabelHtml(queue, day) {
    ensurePrepackDayCodes(queue);
    const printableCode = day.prepackScanCode || day.prepackCode;
    const barcodeDataUrl = aztecBarcodeDataUrl(printableCode) || code128DataUrl(printableCode);
    const entries = prepackDayLabelEntries(day);
    const labelClass = getLabelClass(
        entries.flatMap(entry => entry.type === 'linked'
            ? [
                entry.primary.medName,
                entry.primary.dose,
                ...entry.linked.map(prepackPlainLabelRow)
            ]
            : [prepackPlainLabelRow(entry.item)]
        ),
        entries.reduce((count, entry) => count + (entry.type === 'linked' ? 5 + entry.linked.length : 1), 1)
    );
    const rows = entries.length
        ? entries.map(entry => entry.type === 'linked'
            ? prepackLinkedGroupLabelBlockHtml(queue, entry.primary, entry.linked)
            : prepackPlainLabelRowHtml(entry.item)
        ).join('')
        : '<div class="label-med-row">No medications in this prepack</div>';
    return `<div class="${labelClass} prepack-day-label${barcodeDataUrl ? ' prepack-coded-label' : ''}">
        <div class="label-date label-date-with-icon">${escapeHtml(day.date)} - ${escapeHtml(queue.memberName || '')}${labelShiftIconHtml(queue.selection?.prepackShift)}</div>
        ${rows}
        ${barcodeDataUrl ? `<img class="prepack-label-code" src="${barcodeDataUrl}" alt="Prepack barcode">` : ''}
    </div>`;
}

window.reprintPrepackLabels = async function(queueId) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    if (!queue) return;
    ensurePrepackDayCodes(queue);
    const currentDate = queue.days?.[queue.currentDayIndex || 0]?.date || '';
    const hasAffectedDays = (queue.days || []).some(day => day.needsReprint);
    const choices = (queue.days || []).map(day => {
        const inputId = `reprint-day-${day.date.replace(/[^a-z0-9]/gi, '-')}`;
        const checked = (hasAffectedDays ? day.needsReprint : day.date === currentDate) ? 'checked' : '';
        const completedText = isPrepackDayComplete(day) ? 'Complete' : 'Pending';
        return `<label class="label-selection-item ${checked ? 'selected' : ''}" for="${escapeHtml(inputId)}">
            <input id="${escapeHtml(inputId)}" name="reprintDates" type="checkbox" value="${escapeHtml(day.date)}" ${checked} onchange="this.closest('.label-selection-item')?.classList.toggle('selected', this.checked)">
            <span><strong>${escapeHtml(day.date)}</strong><br><small>${escapeHtml(completedText)}${day.needsReprint ? ' | needs updated labels' : ''}</small></span>
        </label>`;
    }).join('');
    const result = await showActionModal('Reprint Prepack Labels', `
        <div class="form-help">Select exactly which prepack day labels to preview and reprint. This is useful when a label is lost, torn, or only a few days changed after an order update.</div>
        <div class="sunken-panel label-selection-list" style="margin-top:8px; max-height:360px;">${choices}</div>
    `, 'Preview Labels');
    if (!result) return;
    const dates = Array.isArray(result.reprintDates) ? result.reprintDates : [result.reprintDates].filter(Boolean);
    if (!dates.length) {
        await appAlert('Select at least one day to reprint.');
        return;
    }
    return printUpdatedPrepackLabels(queueId, { selectedDates: dates, reprintOnly: true });
};

window.reprintPrepackDay = async function(queueId, date) {
    if (!date) return;
    return printUpdatedPrepackLabels(queueId, { selectedDates: [date], reprintOnly: true });
};

window.printUpdatedPrepackLabels = async function(queueId, options = {}) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    if (!queue) return;
    if (!options.reprintOnly && !isInventoryUnitDoseQueue(queue)) reconcilePrepackQueue(queue);
    const selectedDates = Array.isArray(options.selectedDates)
        ? new Set(options.selectedDates)
        : null;
    const days = selectedDates
        ? queue.days.filter(day => selectedDates.has(day.date))
        : options.forceAll
        ? queue.days
        : (queue.labelsPrinted ? queue.days.filter(day => day.needsReprint) : queue.days);
    if (days.length === 0) {
        await appAlert(options.forceAll ? 'No labels are available for this prepack queue.' : 'No prepack days currently require updated labels.');
        return;
    }
    let labelHtml = isInventoryUnitDoseQueue(queue)
        ? days.flatMap(day => day.items.map((item, index) => inventoryUnitDoseLabelHtml(queue, item, index))).join('')
        : days.map(day => prepackDayLabelHtml(queue, day)).join('');
    if (queue.selection?.singleMedication) {
        const schedule = db.schedules.find(item => item.id === queue.selection.scheduleIds?.[0]);
        const med = schedule && db.inventory.find(item => item.id === schedule.medId);
        const member = db.family.find(item => item.id === queue.memberId);
        const prepackRows = prepackRowsForSelection(queue.selection);
        const prepackScheduleIds = new Set(prepackRows.map(row => row.schedule?.id).filter(Boolean));
        let instances = prepackRows.map(row => row.instance);
        if (prepackScheduleIds.size > 1) {
            instances = [];
        }
        if (queue.selection.labelLayout !== 'range') {
            const dayDates = new Set(days.map(day => day.date));
            instances = instances.filter(instance => dayDates.has(instance.date));
        }
        if (schedule && med && member && instances.length > 0 && queue.selection.labelLayout === 'range') {
            labelHtml = medicationRangeLabelHtml(
                schedule,
                med,
                member,
                queue.selection.startDate,
                queue.selection.endDate,
                instances,
                queue.selection.prepackShift || 'all',
                days[0]?.prepackScanCode || days[0]?.prepackCode || queue.days?.[0]?.prepackScanCode || queue.days?.[0]?.prepackCode || ''
            );
        } else if (schedule && med && member && instances.length > 0) {
            const byDate = instances.reduce((acc, instance) => {
                if (!acc[instance.date]) acc[instance.date] = [];
                acc[instance.date].push(instance.time);
                return acc;
            }, {});
            labelHtml = Object.entries(byDate).map(([date, times]) =>
                medicationLabelHtml(
                    schedule,
                    med,
                    member,
                    date,
                    times.slice().sort((a, b) => timeToMinutes(a) - timeToMinutes(b)),
                    queue.selection.prepackShift || 'all',
                    queue.days?.find(day => day.date === date)?.prepackScanCode || queue.days?.find(day => day.date === date)?.prepackCode || ''
                )
            ).join('');
        }
    }
    previewLabelHtml(
        labelHtml,
        { existingQueueId: queue.id, reprintedDates: days.map(day => day.date), reprintOnly: options.reprintOnly === true }
    );
};

window.deletePrepackQueue = async function(queueId) {
    const queue = db.prepackQueues.find(item => item.id === queueId);
    const preparedCount = queue?.days?.reduce((count, day) =>
        count + (day.items || []).filter(item => isPreparedPrepackItem(item)).length, 0
    ) || 0;
    const message = preparedCount
        ? 'Delete this prepack queue? This removes the queue record only. It will not return stock that was already scanned or manually prepacked. Use Return/Waste Prepacked Dose(s) first if the medication is physically back in hand.'
        : 'Delete this prepack queue? Inventory has not been reduced unless items were scanned or manually prepacked.';
    if (!await appConfirm(message, 'Delete Prepack Queue')) return;
    db.prepackQueues = db.prepackQueues.filter(item => item.id !== queueId);
    if (activePrepackQueueId === queueId) activePrepackQueueId = null;
    await sync();
};

// --- VITALS ---
function monitoringProfileById(member, monitoringId) {
    return memberMonitoringProfiles(member).find(profile => profile.id === monitoringId);
}

function monitoringDetailsForReading(reading, member) {
    const profile = monitoringProfileById(member, reading?.monitoringId);
    return profile || {
        id: reading?.monitoringId || '',
        medicationName: reading?.medicationName || 'Medication',
        labName: reading?.monitorName || 'Therapeutic Level',
        unit: reading?.monitorUnit || 'value',
        goalLow: reading?.goalLow,
        goalHigh: reading?.goalHigh,
        medId: reading?.medId || ''
    };
}

function monitoringGoalText(profile, { prefix = 'Goal' } = {}) {
    const low = parseAmount(profile?.goalLow, NaN);
    const high = parseAmount(profile?.goalHigh, NaN);
    const unit = profile?.unit || 'value';
    if (Number.isFinite(low) && Number.isFinite(high)) {
        return `${prefix}: ${formatAmount(low)}-${formatAmount(high)} ${unit}`;
    }
    if (Number.isFinite(low)) return `${prefix}: above ${formatAmount(low)} ${unit}`;
    if (Number.isFinite(high)) return `${prefix}: below ${formatAmount(high)} ${unit}`;
    return 'No goal range specified';
}

function vitalTypeLabel(type, reading = null, member = null) {
    if (type === 'med-monitor') {
        const profile = monitoringDetailsForReading(reading, member);
        return `${profile.labName} - ${profile.medicationName}`;
    }
    if (type === 'bp' && reading && !Number.isFinite(parseAmount(reading.systolic, NaN)) && Number.isFinite(parseAmount(reading.hr, NaN))) {
        return 'Heart Rate / Pulse';
    }
    return { bp: 'BP / HR', weight: 'Weight', glucose: 'Blood Glucose', temperature: 'Temperature' }[type] || type;
}

function formatVitalReading(reading) {
    if (reading.type === 'bp') {
        const sys = parseAmount(reading.systolic, NaN);
        const dia = parseAmount(reading.diastolic, NaN);
        const hr = parseAmount(reading.hr, NaN);
        if (!Number.isFinite(sys) && Number.isFinite(hr)) return `HR ${formatAmount(hr)} bpm`;
        const hrText = Number.isFinite(hr) ? `, HR ${formatAmount(hr)}` : '';
        return `${formatAmount(sys)}/${formatAmount(dia)} mmHg${hrText}`;
    }
    if (reading.type === 'weight') return `${reading.weight} ${reading.weightUnit || 'lb'}`;
    if (reading.type === 'glucose') return `${reading.glucose} mg/dL`;
    if (reading.type === 'temperature') return `${reading.temperature} ${reading.temperatureUnit || 'F'}`;
    if (reading.type === 'med-monitor') {
        const member = db.family.find(item => item.id === reading.memberId);
        const profile = monitoringDetailsForReading(reading, member);
        return `${formatAmount(parseAmount(reading.monitorValue))} ${profile.unit || 'value'}`;
    }
    return '';
}

function isVitalOutOfRange(reading, member) {
    const goals = getMemberGoals(member);
    if (reading.type === 'glucose') {
        const value = parseAmount(reading.glucose, NaN);
        return Number.isFinite(value) && (value < goals.glucose.low || value > goals.glucose.high);
    }
    if (reading.type === 'bp') {
        const sys = parseAmount(reading.systolic, NaN);
        const dia = parseAmount(reading.diastolic, NaN);
        const hr = parseAmount(reading.hr, NaN);
        return (Number.isFinite(sys) && (sys < goals.bp.systolicLow || sys > goals.bp.systolicHigh)) ||
            (Number.isFinite(dia) && (dia < goals.bp.diastolicLow || dia > goals.bp.diastolicHigh)) ||
            (Number.isFinite(hr) && (hr < goals.hr.low || hr > goals.hr.high));
    }
    if (reading.type === 'weight') {
        const value = readingSeriesValue(reading, 'weight');
        const low = goals.weight.unit === 'kg' && Number.isFinite(parseAmount(goals.weight.low, NaN))
            ? parseAmount(goals.weight.low) * 2.20462
            : parseAmount(goals.weight.low, NaN);
        const high = goals.weight.unit === 'kg' && Number.isFinite(parseAmount(goals.weight.high, NaN))
            ? parseAmount(goals.weight.high) * 2.20462
            : parseAmount(goals.weight.high, NaN);
        return Number.isFinite(value) && Number.isFinite(low) && Number.isFinite(high) && (value < low || value > high);
    }
    if (reading.type === 'med-monitor') {
        const profile = monitoringDetailsForReading(reading, member);
        const value = parseAmount(reading.monitorValue, NaN);
        const low = parseAmount(profile.goalLow, NaN);
        const high = parseAmount(profile.goalHigh, NaN);
        return Number.isFinite(value) && (
            (Number.isFinite(low) && value < low) ||
            (Number.isFinite(high) && value > high)
        );
    }
    return false;
}

window.renderVitalTypeOptions = function() {
    const select = document.getElementById('vital-type');
    if (!select) return;
    const selected = select.value;
    const member = db.family.find(item => item.id === document.getElementById('vital-member-select')?.value);
    const standardOptions = [
        ['bp', 'BP / Heart Rate'],
        ['weight', 'Weight'],
        ['glucose', 'Blood Glucose'],
        ['temperature', 'Temperature']
    ].map(([value, label]) => `<option value="${value}">${label}</option>`).join('');
    const monitoringOptions = memberMonitoringProfiles(member)
        .map(profile => `<option value="monitor:${escapeHtml(profile.id)}">${escapeHtml(profile.labName)} - ${escapeHtml(profile.medicationName)}</option>`)
        .join('');
    select.innerHTML = `${standardOptions}${monitoringOptions ? `<optgroup label="Medication / Lab Monitoring">${monitoringOptions}</optgroup>` : ''}`;
    if (Array.from(select.options).some(option => option.value === selected)) select.value = selected;
    else select.value = 'bp';
    renderVitalInputs();
};

window.renderVitalInputs = function() {
    const type = document.getElementById('vital-type')?.value || 'bp';
    const container = document.getElementById('vital-input-fields');
    if (!container) return;

    if (type.startsWith('monitor:')) {
        const member = db.family.find(item => item.id === document.getElementById('vital-member-select')?.value);
        const profile = monitoringProfileById(member, type.slice('monitor:'.length));
        container.innerHTML = profile
            ? `<label>${escapeHtml(profile.labName)}:</label><input id="vital-monitor-value" type="number" step="any" style="width:90px;">
                <span>${escapeHtml(profile.unit || 'value')}</span>
                <span class="form-help">${escapeHtml(monitoringGoalText(profile))}</span>`
            : '<span class="form-help">Select a valid medication monitoring profile.</span>';
    } else if (type === 'bp') {
        container.innerHTML = `
            <label>Systolic:</label><input id="vital-systolic" type="number" style="width:60px;">
            <label>Diastolic:</label><input id="vital-diastolic" type="number" style="width:60px;">
            <label>Heart Rate:</label><input id="vital-hr" type="number" style="width:60px;">
        `;
    } else if (type === 'weight') {
        container.innerHTML = `<label>Weight:</label><input id="vital-weight" type="number" step="0.1" style="width:80px;">
            <select id="vital-weight-unit"><option value="lb">lb</option><option value="kg">kg</option></select>`;
    } else {
        container.innerHTML = type === 'temperature'
            ? `<label>Temperature:</label><input id="vital-temperature" type="number" step="0.1" style="width:80px;">
                <select id="vital-temperature-unit"><option value="F">Fahrenheit (F)</option><option value="C">Celsius (C)</option></select>`
            : `<label>Blood Glucose:</label><input id="vital-glucose" type="number" style="width:80px;"> <span>mg/dL</span>`;
    }
};

window.saveVitalReading = async function() {
    const memberId = document.getElementById('vital-member-select').value;
    const selectedType = document.getElementById('vital-type').value;
    const date = document.getElementById('vital-date').value;
    const time = document.getElementById('vital-time').value;
    const notes = document.getElementById('vital-notes')?.value.trim() || '';
    if (!memberId || !date || !time) return void appAlert("Member, date, and time are required.");

    const reading = { id: Date.now().toString(), memberId, type: selectedType, date, time, notes };
    if (selectedType.startsWith('monitor:')) {
        const member = db.family.find(item => item.id === memberId);
        const monitoringId = selectedType.slice('monitor:'.length);
        const profile = monitoringProfileById(member, monitoringId);
        const monitorValue = parseAmount(document.getElementById('vital-monitor-value')?.value, NaN);
        if (!profile || !Number.isFinite(monitorValue)) return void appAlert("A valid monitored lab or level value is required.");
        reading.type = 'med-monitor';
        reading.monitoringId = profile.id;
        reading.monitorValue = monitorValue;
        reading.monitorName = profile.labName;
        reading.medicationName = profile.medicationName;
        reading.monitorUnit = profile.unit;
        reading.goalLow = profile.goalLow;
        reading.goalHigh = profile.goalHigh;
        reading.medId = profile.medId || '';
    } else if (selectedType === 'bp') {
        reading.systolic = parseAmount(document.getElementById('vital-systolic').value, NaN);
        reading.diastolic = parseAmount(document.getElementById('vital-diastolic').value, NaN);
        reading.hr = parseAmount(document.getElementById('vital-hr').value, NaN);
        if (isNaN(reading.systolic) || isNaN(reading.diastolic)) return void appAlert("Systolic and diastolic BP are required.");
        if (isNaN(reading.hr)) reading.hr = '';
    } else if (selectedType === 'weight') {
        reading.weight = parseAmount(document.getElementById('vital-weight').value, NaN);
        reading.weightUnit = document.getElementById('vital-weight-unit').value;
        if (isNaN(reading.weight)) return void appAlert("Weight is required.");
    } else if (selectedType === 'temperature') {
        reading.temperature = parseAmount(document.getElementById('vital-temperature').value, NaN);
        reading.temperatureUnit = document.getElementById('vital-temperature-unit').value;
        if (isNaN(reading.temperature)) return void appAlert("Temperature is required.");
    } else {
        reading.glucose = parseAmount(document.getElementById('vital-glucose').value, NaN);
        if (isNaN(reading.glucose)) return void appAlert("Blood glucose is required.");
    }

    db.vitals.unshift(reading);
    await sync();
    const notesInput = document.getElementById('vital-notes');
    if (notesInput) notesInput.value = '';
    resetVitalReadingDateTime();
    renderVitalInputs();
    refreshMonitoringAfterLog(memberId);
};

function resetVitalReadingDateTime() {
    const dateInput = document.getElementById('vital-date');
    const timeInput = document.getElementById('vital-time');
    if (dateInput) dateInput.value = localDateKey();
    if (timeInput) timeInput.value = currentTimeInputValue();
}

window.deleteVitalReading = async function(id) {
    if (!await appConfirm("Delete this vital reading?", 'Delete Vital Reading')) return;
    const removed = db.vitals.find(v => v.id === id);
    db.vitals = db.vitals.filter(v => v.id !== id);
    await sync();
    refreshMonitoringAfterLog(removed?.memberId || currentEditingMemberId);
};

function readingSeriesValue(reading, seriesKey) {
    if (seriesKey === 'systolic') return parseAmount(reading.systolic, NaN);
    if (seriesKey === 'diastolic') return parseAmount(reading.diastolic, NaN);
    if (seriesKey === 'hr') return parseAmount(reading.hr, NaN);
    if (seriesKey === 'weight') {
        const weight = parseAmount(reading.weight, NaN);
        return reading.weightUnit === 'kg' ? weight * 2.20462 : weight;
    }
    if (seriesKey === 'glucose') return parseAmount(reading.glucose, NaN);
    if (seriesKey === 'temperature') {
        const temperature = parseAmount(reading.temperature, NaN);
        return reading.temperatureUnit === 'C' ? (temperature * 9 / 5) + 32 : temperature;
    }
    if (seriesKey === 'monitorValue') return parseAmount(reading.monitorValue, NaN);
    return NaN;
}

function isChartPointOutOfRange(type, key, value, member, options = {}) {
    const goals = getMemberGoals(member);
    if (type === 'glucose' && key === 'glucose') {
        return value < goals.glucose.low || value > goals.glucose.high;
    }
    if (type === 'bp' && key === 'systolic') {
        return value < goals.bp.systolicLow || value > goals.bp.systolicHigh;
    }
    if (type === 'bp' && key === 'diastolic') {
        return value < goals.bp.diastolicLow || value > goals.bp.diastolicHigh;
    }
    if (type === 'bp' && key === 'hr') {
        return value < goals.hr.low || value > goals.hr.high;
    }
    if (type === 'weight' && key === 'weight') {
        const low = goals.weight.unit === 'kg' && Number.isFinite(parseAmount(goals.weight.low, NaN))
            ? parseAmount(goals.weight.low) * 2.20462
            : parseAmount(goals.weight.low, NaN);
        const high = goals.weight.unit === 'kg' && Number.isFinite(parseAmount(goals.weight.high, NaN))
            ? parseAmount(goals.weight.high) * 2.20462
            : parseAmount(goals.weight.high, NaN);
        return Number.isFinite(low) && Number.isFinite(high) && (value < low || value > high);
    }
    if (type === 'med-monitor' && key === 'monitorValue') {
        const low = parseAmount(options.goalLow, NaN);
        const high = parseAmount(options.goalHigh, NaN);
        return (Number.isFinite(low) && value < low) || (Number.isFinite(high) && value > high);
    }
    return false;
}

function readingDateTime(reading) {
    const value = new Date(`${reading.date}T${reading.time || '00:00'}`);
    return Number.isFinite(value.getTime()) ? value : null;
}

function drawVitalChart(canvas, readings, series, options = {}) {
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);
    ctx.strokeStyle = '#808080';
    ctx.strokeRect(0, 0, width - 1, height - 1);

    const pointsBySeries = series.map(item => ({
        ...item,
        values: readings.map((reading, index) => ({ index, value: readingSeriesValue(reading, item.key) })).filter(p => Number.isFinite(p.value))
    })).filter(item => item.values.length > 0);

    const goalValues = [];
    const goals = getMemberGoals(options.member);
    if (options.type === 'glucose') goalValues.push(70, goals.glucose.low, goals.glucose.high);
    if (options.type === 'bp') goalValues.push(goals.bp.systolicLow, goals.bp.systolicHigh, goals.bp.diastolicLow, goals.bp.diastolicHigh, goals.hr.low, goals.hr.high);
    if (options.type === 'weight') {
        const weightLow = goals.weight.unit === 'kg' && Number.isFinite(parseAmount(goals.weight.low, NaN))
            ? parseAmount(goals.weight.low) * 2.20462
            : parseAmount(goals.weight.low, NaN);
        const weightHigh = goals.weight.unit === 'kg' && Number.isFinite(parseAmount(goals.weight.high, NaN))
            ? parseAmount(goals.weight.high) * 2.20462
            : parseAmount(goals.weight.high, NaN);
        goalValues.push(weightLow, weightHigh);
    }
    if (options.type === 'med-monitor') goalValues.push(parseAmount(options.goalLow, NaN), parseAmount(options.goalHigh, NaN));

    const allValues = pointsBySeries.flatMap(item => item.values.map(p => p.value)).concat(goalValues).filter(Number.isFinite);
    if (allValues.length === 0) {
        ctx.fillStyle = '#000000';
        ctx.font = '10px MS Sans Serif, Arial';
        ctx.fillText('No data', 8, 18);
        return;
    }

    const rawMin = Math.min(...allValues);
    const rawMax = Math.max(...allValues);
    const rawSpread = Math.max(rawMax - rawMin, 1);
    const min = Math.max(0, rawMin - rawSpread * 0.12);
    const max = rawMax + rawSpread * 0.12;
    const spread = Math.max(max - min, 1);
    const leftPad = options.type === 'med-monitor' ? 86 : 58;
    const rightPad = 20;
    const topPad = 24;
    const bottomPad = 34;
    const readingTimes = readings.map(reading => readingDateTime(reading)?.getTime()).filter(Number.isFinite);
    const adherenceTimes = (options.adherenceEntries || [])
        .map(entry => parseHistoryTimestamp(entry.timestamp)?.getTime())
        .filter(Number.isFinite);
    const axisTimes = [...readingTimes, ...adherenceTimes];
    const firstTime = axisTimes.length ? Math.min(...axisTimes) : 0;
    const lastTime = axisTimes.length ? Math.max(...axisTimes) : firstTime;
    const xForTime = time => lastTime === firstTime
        ? (leftPad + width - rightPad) / 2
        : leftPad + ((time - firstTime) / (lastTime - firstTime)) * (width - leftPad - rightPad);
    const xFor = index => {
        const time = readingDateTime(readings[index])?.getTime();
        return Number.isFinite(time) ? xForTime(time) : (leftPad + width - rightPad) / 2;
    };
    const yFor = value => height - bottomPad - ((value - min) / spread) * (height - topPad - bottomPad);
    const axisLabel = value => {
        if (Math.abs(value) >= 100 || Math.abs(value - Math.round(value)) < 0.05) return String(Math.round(value));
        return value.toFixed(1);
    };

    ctx.strokeStyle = '#e0e0e0';
    ctx.fillStyle = '#444444';
    ctx.font = '9px MS Sans Serif, Arial';
    ctx.textAlign = 'right';
    for (let tick = 0; tick <= 4; tick++) {
        const value = min + (spread * tick / 4);
        const y = yFor(value);
        ctx.beginPath();
        ctx.moveTo(leftPad, y);
        ctx.lineTo(width - rightPad, y);
        ctx.stroke();
        ctx.fillText(axisLabel(value), leftPad - 7, y + 3);
    }

    ctx.strokeStyle = '#707070';
    ctx.lineWidth = 1.25;
    ctx.beginPath();
    ctx.moveTo(leftPad, topPad);
    ctx.lineTo(leftPad, height - bottomPad);
    ctx.lineTo(width - rightPad, height - bottomPad);
    ctx.stroke();
    ctx.lineWidth = 1;

    if (options.type === 'glucose') {
        const y70 = yFor(70);
        ctx.strokeStyle = '#ff0000';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(leftPad, y70);
        ctx.lineTo(width - rightPad, y70);
        ctx.stroke();
        ctx.lineWidth = 1;
        ctx.fillStyle = '#ff0000';
        ctx.font = '9px MS Sans Serif, Arial';
        ctx.textAlign = 'right';
        ctx.fillText('70', leftPad - 7, y70 - 4);
        ctx.textAlign = 'left';
    }
    if (options.type === 'med-monitor') {
        [
            [parseAmount(options.goalLow, NaN), `Low ${formatAmount(parseAmount(options.goalLow))}`],
            [parseAmount(options.goalHigh, NaN), `High ${formatAmount(parseAmount(options.goalHigh))}`]
        ].filter(([value]) => Number.isFinite(value)).forEach(([value, label]) => {
            const y = yFor(value);
            ctx.save();
            ctx.strokeStyle = '#008000';
            ctx.setLineDash([4, 3]);
            ctx.beginPath();
            ctx.moveTo(leftPad, y);
            ctx.lineTo(width - rightPad, y);
            ctx.stroke();
            ctx.restore();
            ctx.fillStyle = '#008000';
            ctx.font = '8px MS Sans Serif, Arial';
            ctx.textAlign = 'right';
            ctx.fillText(label, leftPad - 5, y - 2);
            ctx.textAlign = 'left';
        });
    }

    const hoverPoints = [];
    pointsBySeries.forEach(item => {
        ctx.strokeStyle = item.color;
        ctx.fillStyle = item.color;
        ctx.lineWidth = 1.8;
        ctx.beginPath();
        item.values.forEach((point, idx) => {
            const x = xFor(point.index);
            const y = yFor(point.value);
            if (idx === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        });
        ctx.stroke();
        ctx.lineWidth = 1;
        item.values.forEach(point => {
            const x = xFor(point.index);
            const y = yFor(point.value);
            const reading = readings[point.index] || {};
            hoverPoints.push({
                x,
                y,
                label: `${item.label}: ${formatAmount(point.value)} ${options.unit || ''}`.trim(),
                when: `${reading.date || ''} ${reading.time || ''}`.trim()
            });
            ctx.fillStyle = isChartPointOutOfRange(options.type, item.key, point.value, options.member, options) ? '#ff0000' : item.color;
            ctx.beginPath();
            ctx.arc(x, y, 3, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#ffffff';
            ctx.stroke();
        });
    });

    (options.adherenceEntries || []).forEach(entry => {
        const time = parseHistoryTimestamp(entry.timestamp)?.getTime();
        if (!Number.isFinite(time) || time < firstTime || time > lastTime) return;
        const x = xForTime(time);
        const y = height - bottomPad - 5;
        ctx.fillStyle = '#000080';
        ctx.beginPath();
        ctx.moveTo(x, y - 4);
        ctx.lineTo(x + 4, y);
        ctx.lineTo(x, y + 4);
        ctx.lineTo(x - 4, y);
        ctx.closePath();
        ctx.fill();
    });

    ctx.fillStyle = '#000000';
    ctx.font = '9px MS Sans Serif, Arial';
    ctx.textAlign = 'left';
    ctx.fillText(options.unit || '', leftPad, 14);
    if (readings.length > 0) {
        ctx.fillText(readings[0].date.slice(5), leftPad, height - 4);
        ctx.fillText(readings[readings.length - 1].date.slice(5), Math.max(leftPad, width - 42), height - 4);
    }
    canvas._pharmAtlasVitalPoints = hoverPoints;
}

function attachVitalChartHover(canvas) {
    if (!canvas || canvas.dataset.hoverReady) return;
    canvas.dataset.hoverReady = '1';
    canvas.addEventListener('mousemove', event => {
        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / Math.max(rect.width, 1);
        const scaleY = canvas.height / Math.max(rect.height, 1);
        const x = (event.clientX - rect.left) * scaleX;
        const y = (event.clientY - rect.top) * scaleY;
        const nearest = (canvas._pharmAtlasVitalPoints || [])
            .map(point => ({ ...point, distance: Math.hypot(point.x - x, point.y - y) }))
            .sort((a, b) => a.distance - b.distance)[0];
        canvas.title = nearest && nearest.distance <= 12 ? `${nearest.when}\n${nearest.label}` : 'Hover over a point to see its value.';
    });
}

function renderVitals() {
    const memberSelect = document.getElementById('vital-member-select');
    if (memberSelect) {
        const selectedMember = memberSelect.value;
        memberSelect.innerHTML = db.family.map(m => `<option value="${m.id}">${m.lastName}, ${m.firstName}</option>`).join('');
        if (db.family.some(member => member.id === selectedMember)) memberSelect.value = selectedMember;
    }
    const memberFilter = document.getElementById('vital-member-filter');
    if (memberFilter) {
        const selectedFilter = memberFilter.value;
        memberFilter.innerHTML = `<option value="">All members</option>${db.family
            .map(member => `<option value="${member.id}">${escapeHtml(member.lastName)}, ${escapeHtml(member.firstName)}</option>`)
            .join('')}`;
        if (!selectedFilter || db.family.some(member => member.id === selectedFilter)) memberFilter.value = selectedFilter;
    }

    const dateInput = document.getElementById('vital-date');
    const timeInput = document.getElementById('vital-time');
    if (dateInput && !dateInput.value) dateInput.value = localDateKey();
    if (timeInput && !timeInput.value) {
        const now = new Date();
        timeInput.value = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    }
    renderVitalTypeOptions();

    const tableBody = document.getElementById('vital-table-body');
    if (tableBody) {
        const filterMemberId = memberFilter?.value || '';
        const sortedVitals = db.vitals
            .filter(reading => !filterMemberId || reading.memberId === filterMemberId)
            .sort((a, b) => `${b.date} ${b.time}`.localeCompare(`${a.date} ${a.time}`));
        tableBody.innerHTML = sortedVitals.slice(0, 50).map(reading => {
            const member = db.family.find(m => m.id === reading.memberId);
            const warningStyle = isVitalOutOfRange(reading, member) ? 'color:red; font-weight:bold;' : '';
            return `<tr style="${warningStyle}">
                <td>${member ? `${member.lastName}, ${member.firstName}` : '?'}</td>
                <td>${reading.date} ${reading.time}</td>
                <td>${escapeHtml(vitalTypeLabel(reading.type, reading, member))}</td>
                <td>${formatVitalReading(reading)}</td>
                <td>${escapeHtml(reading.notes || '')}</td>
                <td><button onclick="deleteVitalReading('${reading.id}')">Delete</button></td>
            </tr>`;
        }).join('') || '<tr><td colspan="6" style="padding:8px;">No vital readings match this member filter.</td></tr>';
    }
}

function getVitalChartConfigs(member = null) {
    const standardCharts = [
        { type: 'bp', title: 'BP / HR', unit: 'mmHg / bpm', series: [
            { key: 'systolic', label: 'Systolic', color: '#0000aa' },
            { key: 'diastolic', label: 'Diastolic', color: '#008000' },
            { key: 'hr', label: 'Heart Rate', color: '#aa00aa' }
        ] },
        { type: 'weight', title: 'Weight', unit: 'lb', series: [{ key: 'weight', label: 'Weight', color: '#0000aa' }] },
        { type: 'glucose', title: 'Blood Glucose', unit: 'mg/dL', series: [{ key: 'glucose', label: 'Glucose', color: '#070707' }] },
        { type: 'temperature', title: 'Temperature', unit: 'F', series: [{ key: 'temperature', label: 'Temperature', color: '#b34d00' }] }
    ];
    const monitoringCharts = memberMonitoringProfiles(member).map(profile => ({
        type: 'med-monitor',
        monitoringId: profile.id,
        title: `${profile.labName} - ${profile.medicationName}`,
        unit: profile.unit || 'value',
        goalLow: profile.goalLow,
        goalHigh: profile.goalHigh,
        medId: profile.medId || '',
        series: [{ key: 'monitorValue', label: profile.labName, color: '#202020' }]
    }));
    return [...standardCharts, ...monitoringCharts];
}

function readingMatchesChart(reading, chart) {
    return reading.type === chart.type && (chart.type !== 'med-monitor' || reading.monitoringId === chart.monitoringId);
}

function adherenceEntriesForChart(member, chart, readings) {
    if (!member || !chart.medId || readings.length === 0) return [];
    const med = db.inventory.find(item => item.id === chart.medId);
    const firstDate = readings[0].date;
    const lastDate = readings[readings.length - 1].date;
    return db.history
        .filter(entry => entry.memberId === member.id)
        .filter(entry => !entry.doseStatus || ['given', 'late', 'early'].includes(entry.doseStatus))
        .filter(entry => entry.medId === chart.medId || (!!med && entry.medName === med.name))
        .filter(entry => {
            const timestamp = parseHistoryTimestamp(entry.timestamp);
            if (!timestamp) return false;
            const date = localDateKey(timestamp);
            return date >= firstDate && date <= lastDate;
        })
        .sort((a, b) => String(a.timestamp || '').localeCompare(String(b.timestamp || '')));
}

function renderMemberVitalCharts(memberId, container) {
    if (!container) return;
    const member = db.family.find(m => m.id === memberId);
    container.innerHTML = '<div class="vital-chart-grid"></div>';
    const grid = container.querySelector('.vital-chart-grid');

    getVitalChartConfigs(member).forEach(chart => {
        const readings = db.vitals
            .filter(v => v.memberId === memberId && readingMatchesChart(v, chart))
            .sort((a, b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`));
        if (readings.length === 0) return;

        const first = readings[0];
        const last = readings[readings.length - 1];
        const panel = document.createElement('div');
        panel.className = 'vital-chart-panel';
        const legend = chart.series.map(s => `<span><span class="legend-swatch" style="background:${s.color};"></span>${escapeHtml(s.label)}</span>`).join(' ');
        const adherenceEntries = adherenceEntriesForChart(member, chart, readings);
        const hasMonitoringGoal = Number.isFinite(parseAmount(chart.goalLow, NaN)) || Number.isFinite(parseAmount(chart.goalHigh, NaN));
        const monitoringLegend = chart.type === 'med-monitor'
            ? `${hasMonitoringGoal ? '<span><span class="legend-swatch goal-swatch"></span>Goal line</span>' : ''}${chart.medId ? '<span><span class="legend-diamond"></span>Dose taken</span>' : ''}`
            : '';
        panel.innerHTML = `
            <div style="font-size:11px; font-weight:bold;">${escapeHtml(chart.title)}</div>
            <div class="vital-chart-meta">${first.date} to ${last.date} (${readings.length} readings${chart.medId ? `, ${adherenceEntries.length} linked doses` : ''})</div>
            <canvas width="460" height="190" class="vital-chart"></canvas>
            <div class="vital-legend">${legend}${monitoringLegend}<span><span class="legend-swatch" style="background:#ff0000;"></span>Out of goal</span></div>
        `;
        grid.appendChild(panel);
        const canvas = panel.querySelector('canvas');
        drawVitalChart(canvas, readings, chart.series, { ...chart, member, adherenceEntries });
        attachVitalChartHover(canvas);
    });

    if (!grid.children.length) {
        container.innerHTML = '<div style="font-size:11px;">No monitoring readings logged for this member.</div>';
    }
}

function renderMemberVitalProfile(memberId) {
    renderMemberVitalCharts(memberId, document.getElementById('member-vitals-trends'));
}

function memberAdherenceRows(memberId, days = 14) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const start = new Date(today);
    start.setDate(start.getDate() - (days - 1));
    const now = new Date();
    const rows = [];
    const schedules = db.schedules.filter(schedule => schedule.memberId === memberId && schedule.freq !== 'PRN');

    for (let i = 0; i < days; i++) {
        const cursor = new Date(start);
        cursor.setDate(start.getDate() + i);
        const date = localDateKey(cursor);
        let due = 0;
        let given = 0;
        let exceptions = 0;

        schedules.forEach(schedule => {
            getScheduleInstancesForDate(schedule, date).forEach(instance => {
                const instanceDateTime = new Date(`${instance.date}T${instance.time === 'PRN' ? '23:59' : instance.time}`);
                if (instanceDateTime > now) return;
                due++;
                const entry = findHistoryForScheduleInstance(schedule, instance);
                if (entry && isGivenStatus(entry.doseStatus || 'given')) given++;
                else if (entry && ['skipped', 'missed', 'refused', 'held'].includes(entry.doseStatus)) exceptions++;
            });
        });

        rows.push({
            date,
            due,
            given,
            exceptions,
            missed: Math.max(0, due - given - exceptions),
            percent: due > 0 ? Math.round((given / due) * 100) : null
        });
    }
    return rows;
}

function renderMemberAdherenceProfile(memberId) {
    const container = document.getElementById('member-adherence-chart');
    if (!container) return;
    const member = db.family.find(item => item.id === memberId);
    if (!member) {
        container.innerHTML = '<div class="empty-state">Save member before tracking adherence.</div>';
        return;
    }
    const rows = memberAdherenceRows(memberId, 14);
    const totalDue = rows.reduce((sum, row) => sum + row.due, 0);
    const totalGiven = rows.reduce((sum, row) => sum + row.given, 0);
    const totalExceptions = rows.reduce((sum, row) => sum + row.exceptions, 0);
    const overall = totalDue > 0 ? Math.round((totalGiven / totalDue) * 100) : null;
    if (totalDue === 0) {
        container.innerHTML = '<div class="empty-state">No scheduled non-PRN doses were due in the last 14 days.</div>';
        return;
    }
    const statusClass = overall >= 90 ? 'good' : overall >= 75 ? 'watch' : 'risk';
    const bars = rows.map(row => {
        const labelDate = parseLocal(row.date);
        const label = labelDate ? `${labelDate.getMonth() + 1}/${labelDate.getDate()}` : row.date;
        const width = row.percent === null ? 0 : Math.max(2, row.percent);
        const barClass = row.percent === null ? 'empty' : row.percent >= 90 ? 'good' : row.percent >= 75 ? 'watch' : 'risk';
        const title = row.due
            ? `${row.date}: ${row.given}/${row.due} documented, ${row.exceptions} skipped/missed`
            : `${row.date}: no doses due`;
        return `<div class="adherence-day" title="${escapeHtml(title)}">
            <div class="adherence-bar-frame"><div class="adherence-bar ${barClass}" style="height:${width}%;"></div></div>
            <div class="adherence-day-label">${escapeHtml(label)}</div>
        </div>`;
    }).join('');
    container.innerHTML = `
        <div class="adherence-summary ${statusClass}">
            <div><strong>${overall}%</strong><span>Last 14 days</span></div>
            <div>${totalGiven}/${totalDue} scheduled doses documented as given${totalExceptions ? `; ${totalExceptions} skipped/missed documented` : ''}.</div>
        </div>
        <div class="adherence-chart">${bars}</div>
        <div class="adherence-legend">
            <span><i class="good"></i>90%+</span>
            <span><i class="watch"></i>75-89%</span>
            <span><i class="risk"></i>Below 75%</span>
        </div>`;
}

function renderMemberAdministrationLog(memberId) {
    const container = document.getElementById('member-admin-log');
    if (!container) return;

    const entries = db.history
        .filter(entry => entry.memberId === memberId)
        .sort((a, b) => String(b.timestamp || '').localeCompare(String(a.timestamp || '')));

    if (entries.length === 0) {
        container.innerHTML = '<div style="font-size:11px; padding:5px;">No administration history recorded for this member.</div>';
        return;
    }

    container.innerHTML = entries.map(entry => {
        const canEdit = entry.scheduleId && entry.doseStatus !== 'container-finished';
        return `
        <div style="font-size:11px; border-bottom:1px dotted #c0c0c0; padding:4px;">
            <b>${escapeHtml(entry.timestamp || '')}</b> - ${escapeHtml(entry.medName || 'Medication')}<br>
            ${escapeHtml(entry.details || '')}
            ${canEdit ? `<div style="text-align:right; margin-top:3px;"><button type="button" onclick="editAdministration('${entry.id}')">Edit Documentation</button></div>` : ''}
        </div>
    `;
    }).join('');
}

function getTimelineRange() {
    if (!memberTimelineStart) {
        const start = new Date();
        start.setHours(0, 0, 0, 0);
        start.setDate(start.getDate() - 6);
        memberTimelineStart = localDateKey(start);
    }
    const start = parseLocal(memberTimelineStart);
    const end = new Date(start);
    end.setDate(end.getDate() + 6);
    return { start: memberTimelineStart, end: localDateKey(end) };
}

function historyEntryMatchesScheduleInstance(entry, schedule, instance) {
    if (!entry || !schedule || !instance) return false;
    if (entry.scheduleInstanceKey === instance.key) return true;
    if (entry.scheduleId && entry.scheduleId !== schedule.id) return false;
    const actual = historyEntryDateTime(entry);
    const offSchedule = ['late', 'early'].includes(entry.doseStatus || '') ||
        (actual.date && entry.scheduledDate && actual.date !== entry.scheduledDate);
    if (offSchedule &&
        entry.memberId === schedule.memberId &&
        entry.medId === schedule.medId &&
        actual.date === instance.date &&
        entry.scheduledTime === instance.time) {
        return true;
    }
    return entry.memberId === schedule.memberId &&
        entry.medId === schedule.medId &&
        entry.scheduledDate === instance.date &&
        entry.scheduledTime === instance.time;
}

function historyTimeForSort(entry) {
    return entry.scheduledTime || historyEntryDateTime(entry).time || '99:99';
}

function scheduleDateHistoryEntries(schedule, date) {
    return db.history
        .filter(entry => historyEntryMatchesScheduleDate(entry, schedule, date))
        .sort((a, b) => timeToMinutes(historyTimeForSort(a)) - timeToMinutes(historyTimeForSort(b)));
}

function historyEntryMatchesScheduleDate(entry, schedule, date) {
    if (!entry || !schedule || !date) return false;
    if (entry.scheduleId && entry.scheduleId !== schedule.id) return false;
    const actual = historyEntryDateTime(entry);
    const offSchedule = ['late', 'early'].includes(entry.doseStatus || '') ||
        (actual.date && entry.scheduledDate && actual.date !== entry.scheduledDate);
    return entry.memberId === schedule.memberId &&
        entry.medId === schedule.medId &&
        (entry.scheduledDate === date || (offSchedule && actual.date === date));
}

function findHistoryForModifiedScheduleInstance(schedule, instance) {
    const historyEntries = scheduleDateHistoryEntries(schedule, instance.date);
    if (historyEntries.length === 0) return null;

    const instances = getScheduleInstancesForDate(schedule, instance.date)
        .slice()
        .sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time));
    if (instances.length === 1 && historyEntries.length === 1) return historyEntries[0];

    const instanceIndex = instances.findIndex(candidate => candidate.time === instance.time);
    if (instanceIndex < 0) return null;
    if (instances.length === historyEntries.length) return historyEntries[instanceIndex] || null;

    return null;
}

function findHistoryForScheduleInstance(schedule, instance) {
    return db.history.find(item => item.scheduleInstanceKey === instance.key)
        || db.history.find(item => historyEntryMatchesScheduleInstance(item, schedule, instance))
        || findHistoryForModifiedScheduleInstance(schedule, instance);
}

function timelineDoseState(schedule, instance) {
    const entry = findHistoryForScheduleInstance(schedule, instance);
    if (entry) {
        const status = entry.doseStatus || 'given';
        const actual = historyEntryDateTime(entry);
        const wasOffSchedule = ['late', 'early'].includes(status) ||
            (isGivenStatus(status) && (actual.date !== instance.date || actual.time !== instance.time));
        if (['skipped', 'missed', 'refused', 'held'].includes(status)) {
            return {
                className: 'timeline-not-given',
                label: instance.time,
                title: `${doseStatusLabel(status)}. Click to edit.`,
                entryId: entry.id
            };
        }
        if (wasOffSchedule) {
            return {
                className: 'timeline-offschedule',
                label: `${instance.time} (${actual.time})`,
                title: `${doseStatusLabel(status)} at ${actual.date} ${actual.time}. Click to edit.`,
                entryId: entry.id
            };
        }
        return {
            className: 'timeline-given',
            label: instance.time,
            title: `${doseStatusLabel(status)}. Click to edit.`,
            entryId: entry.id
        };
    }

    const now = new Date();
    const due = new Date(`${instance.date}T${instance.time === 'PRN' ? '00:00' : instance.time}`);
    if (due < now) return { className: 'timeline-overdue', label: instance.time, title: 'Not documented at scheduled time. Click to document status.' };
    if (instance.date === localDateKey(now)) return { className: 'timeline-upcoming', label: instance.time, title: 'Upcoming dose. Click to document status.' };
    return { className: 'timeline-future', label: instance.time, title: 'Future scheduled dose. Click to document status.' };
}

window.documentScheduleInstance = async function(scheduleId, scheduledDate, scheduledTime) {
    const schedule = db.schedules.find(item => item.id === scheduleId);
    const med = schedule && db.inventory.find(item => item.id === schedule.medId);
    if (!schedule || !med) return;
    const key = scheduleInstanceKey(schedule.id, scheduledDate, scheduledTime);
    const existing = findHistoryForScheduleInstance(schedule, { date: scheduledDate, time: scheduledTime, key });
    if (existing) {
        await window.editAdministration(existing.id);
        return;
    }
    const isValidInstance = getScheduleInstancesForDate(schedule, scheduledDate)
        .some(instance => instance.time === scheduledTime);
    if (!isValidInstance) {
        await appAlert('This dose is no longer part of the active medication schedule.');
        return;
    }

    const defaults = defaultActualDateTime();
    const result = await showActionModal(`Document Dose: ${med.name}`, `
        <div class="sunken-panel" style="padding:6px; background:white; font-size:11px;">
            Scheduled: <strong>${escapeHtml(scheduledDate)} ${escapeHtml(scheduledTime)}</strong>
        </div>
        <div class="field-row" style="margin-top:8px;">
            <label>Status:</label>
            <select name="doseStatus">
                <option value="given">Given as scheduled</option>
                <option value="late">Given late</option>
                <option value="early">Given early</option>
                <option value="skipped">Skipped</option>
                <option value="missed">Missed / forgotten</option>
                <option value="refused">Refused</option>
                <option value="held">Held</option>
                <option value="wasted">Wasted</option>
            </select>
        </div>
        <div class="field-row" style="margin-top:8px;">
            <label>Date documented/taken:</label><input name="actualDate" type="date" value="${defaults.date}">
            <label>Time:</label><input name="actualTime" type="time" value="${defaults.time}">
        </div>
        ${kitSourceSelectHtml(med.id)}
        <div class="field-row-stacked" style="margin-top:8px;">
            <label>Note:</label>
            <textarea name="doseNote" rows="3" style="width:100%; resize:none;" placeholder="Optional note"></textarea>
        </div>
    `, 'Save Status');
    if (!result) return;
    if (!result.actualDate || !result.actualTime) {
        await appAlert('Documented date and time are required.');
        return;
    }
    result.scheduledDate = scheduledDate;
    result.scheduledTime = scheduledTime;
    normalizeScheduledDoseActualTime(result);
    const documented = await administerScheduleRecord(
        schedule,
        result,
        schedule.orderSetName ? `Regimen (${schedule.orderSetName})` : 'Schedule'
    );
    if (documented) await sync();
};

function historyEntryDateKey(entry) {
    const parsed = historyEntryDateTime(entry);
    return parsed.date;
}

function prnTimelineEntries(schedule, dateKey) {
    return db.history
        .filter(entry => entry.scheduleId === schedule.id && historyEntryDateKey(entry) === dateKey)
        .sort((a, b) => String(a.timestamp || '').localeCompare(String(b.timestamp || '')));
}

function isPrnActiveOnDate(schedule, dateKey) {
    if (!schedule?.startDate || dateKey < schedule.startDate) return false;
    return schedule.endDate === 'Ongoing' || !schedule.endDate || dateKey <= schedule.endDate;
}

function memberMedicationTimelineHtml(schedule) {
    const range = getTimelineRange();
    const start = parseLocal(range.start);
    const days = [];
    for (let i = 0; i < 7; i++) {
        const date = new Date(start);
        date.setDate(date.getDate() + i);
        const dateKey = localDateKey(date);
        let doses = '';
        if (schedule.freq === 'PRN' && !hasScheduledPrnReminders(schedule)) {
            const entries = prnTimelineEntries(schedule, dateKey);
            doses = entries.length
                ? entries.map(entry => {
                    const time = historyEntryDateTime(entry).time;
                    const given = isGivenStatus(entry.doseStatus || 'given');
                    return `<button type="button" class="timeline-dose ${given ? 'timeline-given' : 'timeline-not-given'}" title="${escapeHtml(doseStatusLabel(entry.doseStatus || 'given'))}. Click to edit." onclick="event.stopPropagation(); editAdministration('${entry.id}')">${escapeHtml(time)}</button>`;
                }).join('')
                : `<span class="timeline-dose" title="${isPrnActiveOnDate(schedule, dateKey) ? 'No PRN administrations documented' : 'PRN order not active'}">${isPrnActiveOnDate(schedule, dateKey) ? 'PRN' : '-'}</span>`;
        } else {
            const instances = getScheduleInstancesForDate(schedule, dateKey);
            doses = instances.length
                ? instances.map(instance => {
                    const state = timelineDoseState(schedule, instance);
                    const click = state.entryId
                        ? ` onclick="event.stopPropagation(); editAdministration('${state.entryId}')"`
                        : ` onclick="event.stopPropagation(); documentScheduleInstance('${schedule.id}','${instance.date}','${instance.time}')"`;
                    return `<button type="button" class="timeline-dose ${state.className}" title="${escapeHtml(state.title)}"${click}>${escapeHtml(state.label || instance.time)}</button>`;
                }).join('')
                : '<span class="timeline-dose" title="No scheduled dose">-</span>';
        }
        const todayClass = dateKey === localDateKey() ? ' timeline-today' : '';
        days.push(`<div class="timeline-day${todayClass}"><span class="timeline-date">${date.toLocaleDateString(undefined, { month: 'numeric', day: 'numeric' })}</span>${doses}</div>`);
    }
    return `<div class="med-timeline" aria-label="Medication administration timeline">${days.join('')}</div>`;
}

function memberScheduleViewMode() {
    return db.settings?.memberScheduleViewMode === 'grid' ? 'grid' : 'timeline';
}

function memberScheduleGridRows(memberId) {
    return db.schedules
        .filter(schedule => schedule.memberId === memberId && !isScheduleArchived(schedule))
        .sort((a, b) => {
            const aTime = getScheduleTimes(a)[0] || (a.freq === 'PRN' ? '99:99' : '');
            const bTime = getScheduleTimes(b)[0] || (b.freq === 'PRN' ? '99:99' : '');
            const byTime = timeToMinutes(aTime) - timeToMinutes(bTime);
            if (byTime) return byTime;
            const aMed = db.inventory.find(item => item.id === a.medId);
            const bMed = db.inventory.find(item => item.id === b.medId);
            return String(aMed?.name || '').localeCompare(String(bMed?.name || ''), undefined, { sensitivity: 'base' });
        });
}

function memberScheduleGridHtml(memberId) {
    const schedules = memberScheduleGridRows(memberId);
    if (!schedules.length) return '';
    const range = getTimelineRange();
    const start = parseLocal(range.start);
    const dayKeys = [];
    for (let i = 0; i < 7; i++) {
        const date = new Date(start);
        date.setDate(date.getDate() + i);
        dayKeys.push(localDateKey(date));
    }
    const headerCells = dayKeys.map(dateKey => {
        const date = parseLocal(dateKey);
        const todayClass = dateKey === localDateKey() ? ' member-grid-today' : '';
        return `<th class="${todayClass}">${date.toLocaleDateString(undefined, { month: 'numeric', day: 'numeric' })}</th>`;
    }).join('');
    const gridRowHtml = (schedule) => {
        const med = db.inventory.find(item => item.id === schedule.medId);
        const medName = med ? `${med.name} ${formatMedStrength(med)}` : 'Unknown medication';
        const instructions = schedule.instructions ? `<details class="member-grid-instructions" onclick="event.stopPropagation()">
            <summary><span class="member-grid-caret" aria-hidden="true"></span>Admin Instructions</summary>
            <div class="member-grid-instruction-text">${escapeHtml(schedule.instructions)}</div>
        </details>` : '';
        const doseLine = med ? `${escapeHtml(formatPrescribedDose(med, schedule.doseQty))} (${escapeHtml(formatQtyForSchedule(schedule, med))})` : escapeHtml(schedule.doseQty || '');
        const cells = dayKeys.map(dateKey => {
            if (schedule.freq === 'PRN' && !hasScheduledPrnReminders(schedule)) {
                const entries = prnTimelineEntries(schedule, dateKey);
                const content = entries.length
                    ? entries.map(entry => {
                        const time = historyEntryDateTime(entry).time;
                        const cls = isGivenStatus(entry.doseStatus || 'given') ? 'timeline-given' : 'timeline-not-given';
                        return `<button type="button" class="timeline-dose ${cls}" onclick="event.stopPropagation(); editAdministration('${entry.id}')">${escapeHtml(time)}</button>`;
                    }).join('')
                    : (isPrnActiveOnDate(schedule, dateKey) ? '<span class="member-grid-prn">PRN</span>' : '');
                const todayCellClass = dateKey === localDateKey() ? ' class="member-grid-today"' : '';
                return `<td${todayCellClass}>${content}</td>`;
            }
            const instances = getScheduleInstancesForDate(schedule, dateKey);
            const content = instances.length
                ? instances.map(instance => {
                    const state = timelineDoseState(schedule, instance);
                    const click = state.entryId
                        ? ` onclick="event.stopPropagation(); editAdministration('${state.entryId}')"`
                        : ` onclick="event.stopPropagation(); documentScheduleInstance('${schedule.id}','${instance.date}','${instance.time}')"`;
                    return `<button type="button" class="timeline-dose ${state.className}" title="${escapeHtml(state.title)}"${click}>${escapeHtml(state.label || instance.time)}</button>`;
                }).join('')
                : '';
            const todayCellClass = dateKey === localDateKey() ? ' class="member-grid-today"' : '';
            return `<td${todayCellClass}>${content}</td>`;
        }).join('');
        return `<tr>
            <td class="member-grid-med-cell">
                <strong>${holdIndicatorHtml(schedule)}${escapeHtml(medName)}</strong>
                <div>Dose: ${doseLine}</div>
                <div>Freq: ${escapeHtml(formatFrequency(schedule))} ${escapeHtml(getScheduleTimes(schedule).join(', ') || (schedule.freq === 'PRN' ? 'PRN' : ''))}</div>
                <div>Start: ${escapeHtml(schedule.startDate || '')}${schedule.endDate && schedule.endDate !== 'Ongoing' ? ` End: ${escapeHtml(schedule.endDate)}` : ''}</div>
                ${instructions}
                <div class="member-grid-actions">
                    <button type="button" onclick="event.stopPropagation(); printSingleLabel('${schedule.id}')">Label</button>
                    <button type="button" onclick="event.stopPropagation(); administerDose('${schedule.medId}','${schedule.id}')">Administer</button>
                    <button type="button" onclick="event.stopPropagation(); openOrderModifier('${schedule.id}')">Edit</button>
                </div>
            </td>
            ${cells}
        </tr>`;
    };
    const scheduledRows = schedules.filter(schedule => schedule.freq !== 'PRN').map(gridRowHtml).join('');
    const prnRows = schedules.filter(schedule => schedule.freq === 'PRN').map(gridRowHtml).join('');
    const rows = `${scheduledRows}${prnRows ? `<tr class="member-grid-section-row"><td colspan="${dayKeys.length + 1}">As needed</td></tr>${prnRows}` : ''}`;
    return `<div class="member-schedule-grid-note">Date-grid view is for quick review/documentation. Use timeline cards below for full regimen controls, audit, hold, waste, and discontinue actions.</div>
        <table class="member-schedule-grid">
            <thead><tr><th>Medications</th>${headerCells}</tr></thead>
            <tbody>${rows}</tbody>
        </table>`;
}

function renderMemberScheduleGrid(memberId = currentEditingMemberId) {
    const container = document.getElementById('member-schedule-grid-view');
    if (!container) return;
    const showGrid = memberScheduleViewMode() === 'grid';
    container.style.display = showGrid ? '' : 'none';
    container.innerHTML = showGrid && memberId ? memberScheduleGridHtml(memberId) : '';
}

function renderMemberMedicationTimelines() {
    const rangeLabel = document.getElementById('member-timeline-range');
    const range = getTimelineRange();
    if (rangeLabel) {
        rangeLabel.textContent = `${parseLocal(range.start).toLocaleDateString()} - ${parseLocal(range.end).toLocaleDateString()}`;
    }
    document.querySelectorAll('.member-med-timeline[data-schedule-id]').forEach(container => {
        const schedule = db.schedules.find(item => item.id === container.dataset.scheduleId);
        if (schedule) container.innerHTML = memberMedicationTimelineHtml(schedule);
    });
    renderMemberScheduleGrid();
}

window.shiftMemberTimeline = function(days) {
    const range = getTimelineRange();
    const start = parseLocal(range.start);
    start.setDate(start.getDate() + days);
    memberTimelineStart = localDateKey(start);
    renderMemberMedicationTimelines();
};

window.setMemberScheduleViewMode = async function(mode) {
    db.settings = db.settings || {};
    db.settings.memberScheduleViewMode = mode === 'grid' ? 'grid' : 'timeline';
    renderMemberScheduleGrid();
    await sync();
};

function renderVitalDashboard() {
    const container = document.getElementById('vitals-dashboard');
    if (!container) return;
    container.innerHTML = '';

    const membersWithVitals = db.family.filter(member => db.vitals.some(v => v.memberId === member.id));
    if (membersWithVitals.length === 0) {
        container.innerHTML = '<div style="font-size:11px;">No vitals logged yet.</div>';
        return;
    }

    membersWithVitals.forEach(member => {
        const memberBlock = document.createElement('div');
        memberBlock.className = 'sunken-panel';
        memberBlock.style.cssText = 'background:white; padding:6px; margin-bottom:8px;';
        memberBlock.innerHTML = `<strong>${member.lastName}, ${member.firstName}</strong><div class="member-dashboard-vitals"></div>`;
        container.appendChild(memberBlock);
        renderMemberVitalCharts(member.id, memberBlock.querySelector('.member-dashboard-vitals'));
    });
}

function todayDoseRows() {
    const now = new Date();
    const today = localDateKey(now);
    const currentMinutes = now.getHours() * 60 + now.getMinutes();
    const rows = [];
    db.schedules
        .filter(schedule => !isScheduleArchived(schedule))
        .forEach(schedule => {
            const member = db.family.find(item => item.id === schedule.memberId);
            const med = db.inventory.find(item => item.id === schedule.medId);
            if (!member || !med) return;
            if (schedule.freq === 'PRN' && !hasScheduledPrnReminders(schedule)) {
                rows.push({ type: 'prn', status: 'PRN', schedule, member, med, instance: { date: today, time: 'PRN' }, minutes: 99999 });
                return;
            }
            getScheduleInstancesForDate(schedule, today).forEach(instance => {
                const documented = findHistoryForScheduleInstance(schedule, instance);
                const doseStatus = documented?.doseStatus || '';
                const minutes = timeToMinutes(instance.time);
                const diff = minutes === null ? 99999 : minutes - currentMinutes;
                const status = documented
                    ? (isGivenStatus(doseStatus || 'given') ? 'given' : 'exception')
                    : (diff < 0 ? 'overdue' : (diff <= 60 ? 'soon' : 'later'));
                rows.push({ type: 'scheduled', status, doseStatus, documented, schedule, member, med, instance, minutes: minutes ?? 99999 });
            });
        });
    ensureCareReminderStore()
        .filter(reminder => reminder.enabled !== false)
        .forEach(reminder => {
            const member = db.family.find(item => item.id === reminder.memberId);
            if (!member || !isScheduleDueOnDate(reminder, today)) return;
            getScheduleTimes(reminder).forEach(time => {
                const documented = careReminderReadingLoggedForInstance(reminder, today, time);
                const minutes = timeToMinutes(time);
                const diff = minutes === null ? 99999 : minutes - currentMinutes;
                const status = documented ? 'given' : (diff < 0 ? 'overdue' : (diff <= 60 ? 'soon' : 'later'));
                rows.push({ type: 'care-reminder', status, reminder, member, instance: { date: today, time }, minutes: minutes ?? 99999 });
            });
        });
    ensureCustomEvents()
        .filter(event => customEventOccursOn(event, today))
        .forEach(event => {
            const minutes = event.time ? timeToMinutes(event.time) : 99999;
            const diff = minutes === null ? 99999 : minutes - currentMinutes;
            const members = customEventMembers(event);
            const status = event.status === 'completed'
                ? 'given'
                : (!event.time ? 'later' : (diff < 0 ? 'overdue' : (diff <= 60 ? 'soon' : 'later')));
            rows.push({
                type: 'custom-event',
                status,
                event,
                members,
                member: members[0] || null,
                instance: { date: today, time: event.time || 'Anytime' },
                minutes: minutes ?? 99999
            });
        });
    return rows.sort((a, b) => {
        const order = { overdue: 0, soon: 1, later: 2, exception: 3, given: 4, PRN: 5 };
        return (order[a.status] ?? 9) - (order[b.status] ?? 9) || a.minutes - b.minutes;
    });
}

function todayStatusLabel(row) {
    if (row.status === 'PRN') return 'PRN';
    if (row.status === 'exception') return doseStatusLabel(row.doseStatus || 'missed');
    if (row.status === 'soon') return 'Due soon';
    return row.status.charAt(0).toUpperCase() + row.status.slice(1);
}

function todayStatusIcon(row) {
    if (row.status === 'given') return '&#10003;';
    if (row.status === 'exception') return '!';
    if (row.status === 'overdue') return '&#9888;';
    if (row.status === 'soon') return '&#9679;';
    if (row.status === 'PRN') return '+';
    return '&#8226;';
}

function renderTodayViewDashboard() {
    const container = document.getElementById('today-view-dashboard');
    if (!container) return;
    const rows = todayDoseRows();
    if (rows.length === 0) {
        container.innerHTML = '<div class="status-ok">No scheduled doses for today.</div>';
        renderDashboardRightPanel(rows, {});
        return;
    }
    const counts = rows.reduce((acc, row) => {
        acc[row.status] = (acc[row.status] || 0) + 1;
        return acc;
    }, {});
    const rowHtml = rows.slice(0, 40).map(row => {
        const statusClass = `today-status-${String(row.status).toLowerCase()}`;
        const time = row.instance.time || 'PRN';
        if (row.type === 'care-reminder') {
            const type = monitoringParameterTypeById(row.reminder.type, row.reminder.memberId);
            return `<div class="today-dose-row today-care-reminder ${statusClass}" style="--reminder-color:${type.color};">
                <div class="today-row-main">
                    <span class="today-row-icon">${todayStatusIcon(row)}</span>
                    <div>
                        <strong>${escapeHtml(time)}</strong> - ${escapeHtml(careReminderTypeLabel(row.reminder.type, row.reminder.memberId))}
                        <br><small>${escapeHtml(memberDisplayName(row.member))}${row.reminder.note ? ` | ${escapeHtml(row.reminder.note)}` : ''}</small>
                    </div>
                </div>
                <div class="today-row-actions">
                    <span class="today-status-pill">${escapeHtml(todayStatusLabel(row))}</span>
                    <button type="button" class="today-primary-action" onclick="logCareReminderReading('${escapeHtml(row.reminder.id)}', '${escapeHtml(row.instance.date || '')}', '${escapeHtml(row.instance.time || '')}')">Log</button>
                    <button type="button" class="today-secondary-action" onclick="openMemberModal('${escapeHtml(row.member.id)}', 'monitoring')">Profile</button>
                </div>
            </div>`;
        }
        if (row.type === 'custom-event') {
            const links = customEventLinkSummary(row.event);
            const memberNames = row.members?.length ? row.members.map(memberDisplayName).join(', ') : 'General';
            const urgentMarker = row.event.urgent ? '<span class="custom-event-urgent" title="Urgent">!</span>' : '';
            return `<div class="today-dose-row today-custom-event ${statusClass}">
                <div class="today-row-main">
                    <span class="today-row-icon">${todayStatusIcon(row)}</span>
                    <div>
                        ${urgentMarker}<strong>${escapeHtml(time)}</strong> - ${escapeHtml(row.event.title || customEventTypeLabel(row.event.type))}
                        <br><small>${escapeHtml(memberNames)} | ${escapeHtml(customEventTypeLabel(row.event.type))}${links ? ` | ${escapeHtml(links)}` : ''}${row.event.note ? ` | ${escapeHtml(row.event.note)}` : ''}</small>
                    </div>
                </div>
                <div class="today-row-actions">
                    <span class="today-status-pill">${escapeHtml(todayStatusLabel(row))}</span>
                    <button type="button" class="today-primary-action" onclick="toggleCustomEventDone('${escapeHtml(row.event.id)}')">${row.status === 'given' ? 'Reopen' : 'Done'}</button>
                    <button type="button" class="today-secondary-action" onclick="openCustomEventEditor('${escapeHtml(row.event.id)}')">Edit</button>
                </div>
            </div>`;
        }
        return `<div class="today-dose-row ${statusClass}">
            <div class="today-row-main">
                <span class="today-row-icon">${todayStatusIcon(row)}</span>
                <div>
                    <strong>${escapeHtml(time)}</strong> - ${escapeHtml(row.med.name)} ${escapeHtml(formatMedStrength(row.med))}
                    <br><small>${escapeHtml(memberDisplayName(row.member))} | Qty ${escapeHtml(formatQtyForSchedule(row.schedule, row.med))} | Dose ${escapeHtml(formatPrescribedDose(row.med, row.schedule.doseQty))}${row.status === 'exception' ? ` | ${escapeHtml(doseStatusLabel(row.doseStatus))}` : ''}</small>
                </div>
            </div>
            <div class="today-row-actions">
                <span class="today-status-pill">${escapeHtml(todayStatusLabel(row))}</span>
                ${row.status === 'exception' && row.documented?.id ? `<button type="button" class="today-primary-action" onclick="editAdministration('${escapeHtml(row.documented.id)}')">Edit</button>` : ''}
                ${row.status !== 'given' && row.status !== 'PRN' && row.status !== 'exception' ? `<button type="button" class="today-primary-action" onclick="documentScheduleInstance('${escapeHtml(row.schedule.id)}','${escapeHtml(row.instance.date)}','${escapeHtml(row.instance.time)}')">Document</button>` : ''}
                <button type="button" class="today-secondary-action" onclick="openMemberModal('${escapeHtml(row.member.id)}')">Profile</button>
            </div>
        </div>`;
    }).join('');
    container.innerHTML = `
        <div class="today-summary-strip">
            <span>Overdue: <b>${counts.overdue || 0}</b></span>
            <span>Due soon: <b>${counts.soon || 0}</b></span>
            <span>Later: <b>${counts.later || 0}</b></span>
            <span>Exceptions: <b>${counts.exception || 0}</b></span>
            <span>Given: <b>${counts.given || 0}</b></span>
            <span>PRN: <b>${counts.PRN || 0}</b></span>
            <span>Checks: <b>${rows.filter(row => row.type === 'care-reminder').length}</b></span>
        </div>
        <div class="today-dose-list">${rowHtml}${rows.length > 40 ? `<div class="form-help">Showing 40 of ${rows.length} today items.</div>` : ''}</div>`;
    renderDashboardRightPanel(rows, counts);
}

function renderDashboardRightPanel(rows = todayDoseRows(), counts = null) {
    const container = document.getElementById('dashboard-right-panel');
    if (!container) return;
    const countMap = counts || rows.reduce((acc, row) => {
        acc[row.status] = (acc[row.status] || 0) + 1;
        return acc;
    }, {});
    const groups = getInventoryStatusGroups();
    const nextItems = rows
        .filter(row => ['overdue', 'soon'].includes(row.status))
        .slice(0, 5);
    const nextHtml = nextItems.length ? nextItems.map(row => {
        const title = row.type === 'care-reminder'
            ? careReminderTypeLabel(row.reminder.type, row.reminder.memberId)
            : row.type === 'custom-event'
                ? (row.event.title || customEventTypeLabel(row.event.type))
            : `${row.med.name} ${formatMedStrength(row.med)}`;
        const action = row.type === 'care-reminder'
            ? `openMemberModal('${escapeHtml(row.member.id)}', 'monitoring')`
            : row.type === 'custom-event'
                ? `openCustomEventEditor('${escapeHtml(row.event.id)}')`
                : `openMemberModal('${escapeHtml(row.member.id)}', 'orders')`;
        const memberLabel = row.type === 'custom-event'
            ? (row.members?.length ? row.members.map(memberDisplayName).join(', ') : 'General')
            : memberDisplayName(row.member);
        return `<button type="button" class="rail-list-button ${row.status === 'overdue' ? 'danger' : 'watch'}" onclick="${action}">
            <strong>${escapeHtml(row.instance.time || 'PRN')} ${escapeHtml(title)}</strong>
            <small>${escapeHtml(memberLabel)} | ${escapeHtml(todayStatusLabel(row))}</small>
        </button>`;
    }).join('') : '<div class="rail-empty">No overdue or due-soon items.</div>';
    const inventoryHtml = [
        ['Low stock', groups.low.length, 'low'],
        ['Expired', groups.expired.length, 'danger'],
        ['Expiring soon', groups.expiringSoon.length, 'watch']
    ].map(([label, value, status]) => `
        <button type="button" class="rail-metric ${status}" onclick="switchTab('inventory')">
            <span>${escapeHtml(label)}</span><strong>${value}</strong>
        </button>`).join('');
    container.innerHTML = `
        <div class="rail-metric-grid">
            <button type="button" class="rail-metric danger" onclick="document.querySelector('#today-view-dashboard')?.scrollIntoView({behavior:'smooth', block:'start'})"><span>Overdue</span><strong>${countMap.overdue || 0}</strong></button>
            <button type="button" class="rail-metric watch" onclick="document.querySelector('#today-view-dashboard')?.scrollIntoView({behavior:'smooth', block:'start'})"><span>Due soon</span><strong>${countMap.soon || 0}</strong></button>
            <button type="button" class="rail-metric exception" onclick="document.querySelector('#today-view-dashboard')?.scrollIntoView({behavior:'smooth', block:'start'})"><span>Exceptions</span><strong>${countMap.exception || 0}</strong></button>
            <button type="button" class="rail-metric ok" onclick="document.querySelector('#today-view-dashboard')?.scrollIntoView({behavior:'smooth', block:'start'})"><span>Given</span><strong>${countMap.given || 0}</strong></button>
        </div>
        <fieldset class="rail-section">
            <legend>Next Attention</legend>
            <div class="rail-list">${nextHtml}</div>
        </fieldset>
        <fieldset class="rail-section command-scan-terminal">
            <legend>Scan Terminal</legend>
            <label>Prepack / label code
                <input id="daily-command-scan-code" type="text" placeholder="Scan Aztec code"
                    onkeydown="if(event.key==='Enter'){event.preventDefault();scanDailyCommandCode(this.value, { source: 'dashboard' });}">
            </label>
            <div class="rail-action-grid compact">
                <button type="button" onclick="scanDailyCommandCode(document.getElementById('daily-command-scan-code')?.value, { source: 'dashboard' })">Open Scan</button>
                <button type="button" onclick="clearCommandScanPanel()">Clear</button>
            </div>
            <div id="dashboard-command-scan-status" class="command-scan-status"></div>
        </fieldset>
        <fieldset class="rail-section">
            <legend>Inventory Watch</legend>
            <div class="rail-metric-grid compact">${inventoryHtml}</div>
        </fieldset>
        <fieldset class="rail-section">
            <legend>Quick Actions</legend>
            <div class="rail-action-grid">
                <button type="button" onclick="switchTab('schedules')">Schedule Med</button>
                <button type="button" onclick="switchTab('vitals')">Log Monitoring</button>
                <button type="button" onclick="switchTab('prepackage')">Prepack</button>
                <button type="button" onclick="runDataHealthCheck()">Health Check</button>
            </div>
        </fieldset>`;
    renderDashboardCommandScanStatus();
}

function dataHealthIssues() {
    normalizeRecordOnlyPrepackReturnFlags();
    const issues = [];
    const inventoryIds = new Set(db.inventory.map(item => item.id));
    const memberIds = new Set(db.family.map(item => item.id));
    const barcodeMap = new Map();
    const linkedTimingPairs = new Set();

    db.schedules.forEach(schedule => {
        const scheduleMed = db.inventory.find(item => item.id === schedule.medId);
        if (!memberIds.has(schedule.memberId)) issues.push({ severity: 'high', repairable: true, type: 'orphan-schedule-member', scheduleId: schedule.id, message: `Schedule ${schedule.id} has no matching member.` });
        if (!inventoryIds.has(schedule.medId)) issues.push({ severity: 'high', repairable: true, type: 'orphan-schedule-med', scheduleId: schedule.id, message: `Schedule ${schedule.id} has no matching inventory medication.` });
        if (schedule.freq !== 'PRN' && getScheduleTimes(schedule).length === 0) issues.push({ severity: 'medium', repairable: false, type: 'missing-times', message: `Scheduled medication ${schedule.id} has no administration time.` });
        const doseQty = parseAmount(schedule.doseQty, NaN);
        if (!usesContainerTracking(scheduleMed) && (!Number.isFinite(doseQty) || doseQty <= 0)) issues.push({ severity: 'medium', repairable: false, type: 'invalid-dose-quantity', message: `Scheduled medication ${schedule.id} has a dose quantity of 0 or less.` });
        const intervalHours = parseInt(schedule.intervalHours, 10);
        if (schedule.freq === 'QXH' && (!Number.isInteger(intervalHours) || intervalHours < 1 || intervalHours > 24)) issues.push({ severity: 'medium', repairable: false, type: 'invalid-interval', message: `Every-X-hours schedule ${schedule.id} has an invalid hour interval.` });
        if (schedule.freq === 'QOD' && !(schedule.qodStart || schedule.startDate)) issues.push({ severity: 'medium', repairable: false, type: 'missing-qod-anchor', message: `Every-other-day schedule ${schedule.id} needs an anchor/start date.` });
        if (!isScheduleArchived(schedule)) {
            db.schedules
                .filter(item => item.memberId === schedule.memberId && item.id !== schedule.id && !isScheduleArchived(item))
                .forEach(linked => {
                    const pairKey = [schedule.id, linked.id].sort().join('|');
                    if (linkedTimingPairs.has(pairKey)) return;
                    if (directScheduleLinkModeBetween(schedule, linked) === 'together' && !schedulesHaveAlignedTiming(schedule, linked)) {
                        linkedTimingPairs.add(pairKey);
                        const med = db.inventory.find(item => item.id === schedule.medId);
                        const linkedMed = db.inventory.find(item => item.id === linked.medId);
                        issues.push({ severity: 'medium', repairable: false, type: 'linked-mismatch', message: `Linked meds do not align: ${med?.name || schedule.id} and ${linkedMed?.name || linked.id}.` });
                    }
                });
        }
    });

    // Administration history can intentionally outlive a removed completed schedule.
    // Keeping it out of issue counts prevents preserved logs from looking broken.

    db.inventory.forEach(med => {
        medicationCodes(med).forEach(code => {
            if (!barcodeMap.has(code)) barcodeMap.set(code, []);
            barcodeMap.get(code).push(med.name || med.id);
        });
        if (parseAmount(med.stock, 0) < 0) issues.push({ severity: 'medium', repairable: true, type: 'negative-stock', medId: med.id, message: `${med.name} has negative stock.` });
        if (med.isCombination && (!Array.isArray(med.components) || med.components.length === 0)) {
            issues.push({ severity: 'medium', repairable: false, type: 'missing-combination-components', medId: med.id, message: `${med.name} is marked as a combination product but has no active ingredient components.` });
        }
    });
    barcodeMap.forEach((names, code) => {
        if (names.length > 1) issues.push({ severity: 'high', repairable: false, type: 'duplicate-barcode', message: `Barcode ${code} is assigned to multiple items: ${names.join(', ')}.` });
    });
    (db.prepackQueues || []).forEach(queue => {
        (queue.days || []).forEach(day => {
            (day.items || []).forEach(item => {
                if (item.medId && !inventoryIds.has(item.medId)) issues.push({ severity: 'medium', repairable: false, type: 'orphan-prepack-med', message: `Prepack ${queue.title || queue.sourceLabel || queue.id} includes a medication no longer in inventory.` });
                if (item.scheduleId && !db.schedules.some(schedule => schedule.id === item.scheduleId) && queue.status !== 'completed') issues.push({ severity: 'low', repairable: false, type: 'orphan-prepack-schedule', message: `Active prepack ${queue.title || queue.sourceLabel || queue.id} references a medication schedule that is no longer active.` });
                if (item.inventoryReturned && !item.inventoryDeducted && !item.inventoryWasted && !item.recordOnlyReturn) issues.push({ severity: 'low', repairable: true, type: 'prepack-return-without-deduction', prepackQueueId: queue.id, prepackItemId: item.id, message: `Prepack item ${item.medName || item.id} is marked returned but was not marked deducted.` });
            });
        });
    });

    return issues;
}

function dataHealthSummaryHtml(issues) {
    const counts = issues.reduce((acc, issue) => {
        acc[issue.severity] = (acc[issue.severity] || 0) + 1;
        return acc;
    }, {});
    return `<span class="${issues.length ? 'error-text' : 'status-ok'}">${issues.length ? `${issues.length} issue${issues.length === 1 ? '' : 's'} found` : 'No data health issues found.'}</span>
        ${issues.length ? `<span>High: ${counts.high || 0} | Medium: ${counts.medium || 0} | Low: ${counts.low || 0}</span>` : ''}`;
}

function renderDataHealthSummary() {
    const container = document.getElementById('data-health-summary');
    if (!container) return;
    container.innerHTML = dataHealthSummaryHtml(dataHealthIssues());
}

window.runDataHealthCheck = async function() {
    const issues = dataHealthIssues();
    const rows = issues.map(issue => `<tr><td>${escapeHtml(issue.severity)}</td><td>${escapeHtml(issue.message)}</td><td>${issue.repairable ? 'Yes' : 'Review manually'}</td></tr>`).join('');
    await showActionModal('Data Health Check', `
        <div style="font-size:11px; margin-bottom:6px;">This checks for broken schedule links, orphaned records, duplicate barcodes, missing times, and impossible stock counts.</div>
        <div class="form-help" style="margin-bottom:6px;">Administration history is intentionally preserved when a completed medication record is removed from a profile, so those retained log entries are not counted as data-health issues.</div>
        <table class="win98-report-table">
            <thead><tr><th>Severity</th><th>Finding</th><th>Repair</th></tr></thead>
            <tbody>${rows || '<tr><td colspan="3">No data health issues found.</td></tr>'}</tbody>
        </table>
    `, 'Close');
};

window.repairDataHealthIssues = async function() {
    const issues = dataHealthIssues().filter(issue => issue.repairable);
    if (issues.length === 0) {
        await appAlert('No safe automatic repairs are available.');
        return;
    }
    if (!await appConfirm(`Repair ${issues.length} safe issue${issues.length === 1 ? '' : 's'}? This removes orphaned schedules and corrects negative stock to 0.`, 'Repair Data Health')) return;
    const orphanScheduleIds = new Set(issues.filter(issue => issue.type.startsWith('orphan-schedule')).map(issue => issue.scheduleId).filter(Boolean));
    db.schedules = db.schedules.filter(schedule => !orphanScheduleIds.has(schedule.id));
    issues.filter(issue => issue.type === 'negative-stock').forEach(issue => {
        const med = db.inventory.find(item => item.id === issue.medId);
        if (med) med.stock = 0;
    });
    addAudit('Data repair', 'Data Health', `Repaired ${issues.length} safe issue${issues.length === 1 ? '' : 's'}.`);
    await sync();
    await appAlert('Safe data health repairs are complete.');
};

window.viewAuditTrail = async function() {
    const rows = (db.auditTrail || []).slice(0, 200).map(entry => `<tr><td>${escapeHtml(auditDisplayTime(entry))}</td><td>${escapeHtml(entry.action || '')}</td><td>${escapeHtml(entry.subject || '')}</td><td>${escapeHtml(entry.details || '')}</td></tr>`).join('');
    await showActionModal('Audit Trail', `
        <div style="font-size:11px; margin-bottom:6px;">Recent edits and safety-relevant actions. This log is separate from the activity log.</div>
        <table class="win98-report-table">
            <thead><tr><th>Date/Time</th><th>Action</th><th>Subject</th><th>Details</th></tr></thead>
            <tbody>${rows || '<tr><td colspan="4">No audit entries yet.</td></tr>'}</tbody>
        </table>
    `, 'Close');
};

window.viewMedicationOrderAudit = async function(scheduleId) {
    const schedule = db.schedules.find(item => item.id === scheduleId);
    if (!schedule) {
        await appAlert('That medication order is no longer available.', 'Medication Audit');
        return;
    }
    const med = db.inventory.find(item => item.id === schedule.medId);
    const member = db.family.find(item => item.id === schedule.memberId);
    const medName = med?.name || schedule.medName || 'Medication';
    const memberName = member ? memberDisplayName(member) : schedule.memberName || '';
    const auditRows = (db.auditTrail || [])
        .filter(entry => {
            const meta = entry.meta || {};
            if (meta.scheduleId === scheduleId) return true;
            if (meta.medId && meta.medId === schedule.medId && (!meta.memberId || meta.memberId === schedule.memberId)) return true;
            const searchable = `${entry.subject || ''} ${entry.details || ''}`.toLowerCase();
            return searchable.includes(String(medName).toLowerCase()) && (!memberName || searchable.includes(memberName.toLowerCase()));
        })
        .map(entry => ({
            when: auditDisplayTime(entry),
            type: entry.action || 'Audit',
            details: `${entry.subject || ''}${entry.details ? ` | ${entry.details}` : ''}`
        }));
    const historyRows = (db.history || [])
        .filter(entry => entry.scheduleId === scheduleId)
        .map(entry => ({
            when: entry.timestamp || '',
            type: 'Administration',
            details: `${doseStatusLabel(entry.doseStatus || 'given')}${entry.scheduledDate || entry.scheduledTime ? ` | Scheduled ${entry.scheduledDate || ''} ${entry.scheduledTime || ''}` : ''}${entry.doseNote ? ` | Note: ${entry.doseNote}` : ''}${entry.details ? ` | ${entry.details}` : ''}`
        }));
    const rows = [...auditRows, ...historyRows]
        .sort((a, b) => String(b.when).localeCompare(String(a.when)))
        .map(row => `<tr><td>${escapeHtml(row.when)}</td><td>${escapeHtml(row.type)}</td><td>${escapeHtml(row.details)}</td></tr>`)
        .join('');
    await showActionModal(`Medication Audit: ${medName}`, `
        <div style="font-size:11px; margin-bottom:6px;">
            <strong>${escapeHtml(medName)} ${med ? escapeHtml(formatMedStrength(med)) : ''}</strong>
            ${memberName ? ` | ${escapeHtml(memberName)}` : ''}
        </div>
        <div class="audit-detail-list">
            <table class="win98-report-table">
                <thead><tr><th>Date/Time</th><th>Type</th><th>Details</th></tr></thead>
                <tbody>${rows || '<tr><td colspan="3">No audit or administration history found for this order.</td></tr>'}</tbody>
            </table>
        </div>
    `, 'Close');
};

function getInventoryStatusGroups() {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const expiringCutoff = new Date(today);
    expiringCutoff.setDate(expiringCutoff.getDate() + 15);

    const sorted = [...db.inventory].sort((a, b) => (a.name || '').localeCompare(b.name || '', undefined, { sensitivity: 'base' }));
    return {
        low: sorted.filter(med => parseAmount(med.stock) <= parseAmount(med.minThreshold)),
        expired: sorted.filter(med => {
            const expiry = med.expiry ? parseLocal(med.expiry) : null;
            return expiry && expiry < today;
        }),
        expiringSoon: sorted.filter(med => {
            const expiry = med.expiry ? parseLocal(med.expiry) : null;
            return expiry && expiry >= today && expiry <= expiringCutoff;
        })
    };
}

function inventoryStatusItemHtml(med) {
    const forecast = refillForecastText(med);
    return `<li>${escapeHtml(med.name)} ${escapeHtml(formatMedStrength(med))} - ${escapeHtml(formatAmount(parseAmount(med.stock)))} ${escapeHtml(inventoryUnitFor(med))} on hand, exp ${escapeHtml(med.expiry || 'N/A')}${forecast ? `<br><small>${escapeHtml(forecast)}</small>` : ''}</li>`;
}

function renderInventoryStatus() {
    const container = document.getElementById('inventory-status');
    if (!container) return;

    const groups = getInventoryStatusGroups();
    const section = (title, items, className, mark) => `
        <div class="inventory-status-box ${className}">
            <div class="inventory-status-heading"><span class="inventory-status-mark">${mark}</span><strong>${title}</strong><span class="inventory-status-count">${items.length}</span></div>
            ${items.length
                ? `<ul>${items.slice(0, 8).map(inventoryStatusItemHtml).join('')}${items.length > 8 ? `<li>+${items.length - 8} more</li>` : ''}</ul>`
                : '<div class="status-ok">None</div>'}
        </div>`;

    container.innerHTML = `
        <div class="inventory-status-grid">
            ${section('Low meds (Refill Needed Soon)', groups.low, 'inventory-status-low', '!')}
            ${section('Expired meds', groups.expired, 'inventory-status-expired', 'X')}
            ${section('Expiring in 15 days', groups.expiringSoon, 'inventory-status-soon', '15')}
        </div>`;
}

window.backupAppData = async function() {
    if (!window.api?.backupData) {
        await appAlert('Backup support is not available in this build. Restart the desktop app and try again.');
        return;
    }
    const path = await window.api.backupData(db);
    if (path) await appAlert(`Backup saved:\n${path}`, 'Backup Complete');
};

function dateValueOlderThan(value, cutoffKey) {
    if (!value || !cutoffKey) return false;
    const match = String(value).match(/\d{4}-\d{2}-\d{2}/);
    return !!match && match[0] < cutoffKey;
}

function archiveCompletedPrepackQueue(queue, cutoffKey) {
    if (queue?.status !== 'completed') return false;
    const latestDay = (queue.days || []).map(lastDateInPrepackDay).filter(Boolean).sort().pop() || '';
    return !!latestDay && latestDay < cutoffKey;
}

function archiveReceivedOrder(order, cutoffKey) {
    refreshInventoryOrderReceiptStatus(order);
    return order.status === 'received' && dateValueOlderThan(order.receivedAt || order.createdAt, cutoffKey);
}

function buildArchivePayload(cutoffKey, includeVitals = false) {
    const history = (db.history || []).filter(entry => dateValueOlderThan(entry.timestamp || entry.scheduledDate, cutoffKey));
    const auditTrail = (db.auditTrail || []).filter(entry => dateValueOlderThan(entry.at || entry.timestamp, cutoffKey));
    const compoundPreps = (db.compoundPreps || []).filter(prep => dateValueOlderThan(prep.preparedDate || prep.createdAt, cutoffKey));
    const reminderLog = (db.reminderLog || []).filter(entry => dateValueOlderThan(entry, cutoffKey));
    const prepackQueues = (db.prepackQueues || []).filter(queue => archiveCompletedPrepackQueue(queue, cutoffKey));
    const inventoryOrders = (db.inventoryOrders || []).filter(order => archiveReceivedOrder(order, cutoffKey));
    const vitals = includeVitals ? (db.vitals || []).filter(reading => dateValueOlderThan(reading.date || reading.timestamp, cutoffKey)) : [];
    return {
        cutoffDate: cutoffKey,
        includeVitals,
        archivedAt: new Date().toISOString(),
        counts: {
            history: history.length,
            auditTrail: auditTrail.length,
            compoundPreps: compoundPreps.length,
            reminderLog: reminderLog.length,
            prepackQueues: prepackQueues.length,
            inventoryOrders: inventoryOrders.length,
            vitals: vitals.length
        },
        data: { history, auditTrail, compoundPreps, reminderLog, prepackQueues, inventoryOrders, vitals }
    };
}

function removeArchivedRecords(payload) {
    const ids = (items, key = 'id') => new Set((items || []).map(item => item?.[key]).filter(Boolean));
    const historyIds = ids(payload.data.history);
    const auditIds = ids(payload.data.auditTrail);
    const prepIds = ids(payload.data.compoundPreps);
    const queueIds = ids(payload.data.prepackQueues);
    const orderIds = ids(payload.data.inventoryOrders);
    const vitalIds = ids(payload.data.vitals);
    const reminderSet = new Set(payload.data.reminderLog || []);
    db.history = (db.history || []).filter(entry => !historyIds.has(entry.id));
    db.auditTrail = (db.auditTrail || []).filter(entry => !auditIds.has(entry.id));
    db.compoundPreps = (db.compoundPreps || []).filter(prep => !prepIds.has(prep.id));
    db.prepackQueues = (db.prepackQueues || []).filter(queue => !queueIds.has(queue.id));
    db.inventoryOrders = (db.inventoryOrders || []).filter(order => !orderIds.has(order.id));
    db.reminderLog = (db.reminderLog || []).filter(entry => !reminderSet.has(entry));
    if (payload.includeVitals) db.vitals = (db.vitals || []).filter(reading => !vitalIds.has(reading.id));
    db.settings = { ...(db.settings || {}), lastArchiveAt: payload.archivedAt, lastArchiveCutoff: payload.cutoffDate };
}

window.archiveOldData = async function() {
    if (!window.api?.archiveData) {
        await appAlert('Archive support is not available in this build. Restart the desktop app and try again.');
        return;
    }
    const today = localDateKey();
    const defaultCutoff = addDaysKey(today, -180);
    const result = await showActionModal('Archive Old Data', `
        <div data-action-modal-size="wide">
            <div class="archive-intro"><strong>Archive old logs so screens stay fast.</strong><br>PharmAtlas saves an archive JSON first, then removes old records from the active database.</div>
            <div class="field-row" style="margin-top:8px;">
                <label>Archive records before:</label>
                <input name="cutoffDate" type="date" value="${escapeHtml(defaultCutoff)}">
                <label><input name="includeVitals" type="checkbox" value="yes"> include old monitoring/vital readings</label>
            </div>
            <div class="form-help">Active medications, members, inventory, regimens, open/partial orders, and unfinished prepack queues stay in the live database.</div>
        </div>
    `, 'Preview Archive', body => ({
        cutoffDate: body.querySelector('[name="cutoffDate"]')?.value || defaultCutoff,
        includeVitals: body.querySelector('[name="includeVitals"]')?.checked ? 'yes' : ''
    }));
    if (!result) return;
    if (!result.cutoffDate || result.cutoffDate >= today) {
        await appAlert('Choose a cutoff date before today.');
        return;
    }
    const payload = buildArchivePayload(result.cutoffDate, result.includeVitals === 'yes');
    const total = Object.values(payload.counts).reduce((sum, count) => sum + count, 0);
    if (!total) {
        await appAlert('No old records matched that archive date.');
        return;
    }
    const countsText = Object.entries(payload.counts)
        .filter(([, count]) => count > 0)
        .map(([label, count]) => `${label}: ${count}`)
        .join('\n');
    if (!await appConfirm(`Archive ${total} old record(s) before ${payload.cutoffDate}?\n\n${countsText}\n\nThe live database is only trimmed after the archive file is saved.`, 'Confirm Archive')) return;
    try {
        const archivePath = await window.api.archiveData(payload);
        if (!archivePath) return;
        removeArchivedRecords(payload);
        addAudit('Old data archived', 'Maintenance', `${total} records archived before ${payload.cutoffDate}.`);
        await sync();
        await appAlert(`Archive saved:\n${archivePath}\n\n${total} old record(s) removed from the active database.`, 'Archive Complete');
    } catch (error) {
        console.error(error);
        await appAlert('Unable to archive old data. No active data was removed.', 'Archive Failed');
    }
};

window.restoreAppData = async function() {
    if (!window.api?.restoreData) {
        await appAlert('Restore support is not available in this build. Restart the desktop app and try again.');
        return;
    }
    if (!await appConfirm('Restore will replace the current PharmAtlas data with the selected backup file. Continue?', 'Restore Backup')) return;
    try {
        const restored = await window.api.restoreData();
        if (!restored) return;
        db = { ...emptyDb, ...restored };
        pendingScheduleOrders = [];
        activePrepackQueueId = null;
        renderAll();
        await appAlert('Backup restored successfully.', 'Restore Complete');
    } catch (error) {
        console.error(error);
        await appAlert('Unable to restore that backup file. Make sure it is a valid PharmAtlas JSON backup.', 'Restore Failed');
    }
};

