// --- SCHEDULING ---
window.updateSchedStrength = function() {
    const input = document.getElementById('med-search-input');
    const name = input.value;
    const memberId = document.getElementById('select-member')?.value || '';

    // Find all inventory items that have this exact name
    const matches = db.inventory.filter(m => m.name === name && medicationAssignedToMember(m, memberId));
    const blockedMatches = db.inventory.filter(m => m.name === name && !medicationAssignedToMember(m, memberId));

    const strengthSelect = document.getElementById('sched-strength-display');
    const unitsDisp = document.getElementById('sched-units-display');

    // Clear the dropdown first
    strengthSelect.innerHTML = '';

    if (matches.length > 0) {
        matches.forEach(med => {
            const opt = document.createElement('option');
            opt.value = med.id; // Store the ID so we know exactly which one was picked
            opt.innerText = formatMedStrength(med);
            strengthSelect.appendChild(opt);
        });

        // Update units display based on the first match
        if (unitsDisp) unitsDisp.innerText = matches[0].units;
        const prescriberSelect = document.getElementById('sched-prescriber');
        if (prescriberSelect && !prescriberSelect.value && matches[0].prescriberId) prescriberSelect.value = matches[0].prescriberId;
        input.style.backgroundColor = "#e0ffe0";
        calculateLiveDose();
    } else {
        if (unitsDisp) unitsDisp.innerText = 'units';
        input.style.backgroundColor = blockedMatches.length ? "#ffe0e0" : "";
    }
    updateScheduleMedicationPreview();
};

window.updateScheduleMedicationPreview = function() {
    const preview = document.getElementById('sched-med-preview');
    if (!preview) return;
    const medId = document.getElementById('sched-strength-display')?.value || '';
    const med = db.inventory.find(item => item.id === medId);
    if (!med) {
        preview.innerHTML = '<div class="empty-state">Select a medication.</div>';
        return;
    }
    const image = med.imagePath
        ? `<img src="${imageSrc(med.imagePath)}" alt="${escapeHtml(med.name)}">`
        : '<div class="schedule-med-no-photo">No Photo</div>';
    preview.innerHTML = `
        <div class="schedule-med-photo">${image}</div>
        <div class="schedule-med-details">
            <div><b>${escapeHtml(med.name)}</b></div>
            <div>${escapeHtml(formatMedStrength(med))}</div>
            <div>On hand: ${escapeHtml(formatAmount(parseAmount(med.stock)))} ${escapeHtml(inventoryUnitFor(med))}</div>
            <div>Expires: ${escapeHtml(med.expiry || 'N/A')}</div>
            ${med.notes ? `<div>${escapeHtml(med.notes)}</div>` : ''}
        </div>`;
};

// Scheduler checks every minute to see if medications or monitoring parameters are due.
function reminderWasSent(key) {
    return pendingReminderKeys.has(key) || notifiedDoseKeys.has(key) || (Array.isArray(db.reminderLog) && db.reminderLog.includes(key));
}

function recordReminderSent(key) {
    pendingReminderKeys.add(key);
    notifiedDoseKeys.add(key);
    if (!Array.isArray(db.reminderLog)) db.reminderLog = [];
    if (!db.reminderLog.includes(key)) db.reminderLog.push(key);
}

async function dispatchReminderOnce(key, sendFn) {
    if (!key || reminderWasSent(key)) return false;
    recordReminderSent(key);
    try {
        await Promise.resolve(sendFn());
    } catch (error) {
        console.error('Reminder delivery failed:', key, error);
    }
    return true;
}

function reminderIdentityPart(value) {
    return String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function medicationReminderGroupKey(schedule, med, member, dateKey, time) {
    return [
        dateKey,
        'med',
        member?.id || schedule?.memberId || '',
        med?.id || reminderIdentityPart(`${med?.name || ''} ${med ? formatMedStrength(med) : ''}`),
        reminderIdentityPart(formatQtyForSchedule(schedule, med || {})),
        time
    ].join('|');
}

function careReminderGroupKey(reminder, member, dateKey, time) {
    return [
        dateKey,
        'care',
        member?.id || reminder?.memberId || '',
        reminder?.type || '',
        time
    ].join('|');
}

function pruneReminderLog(todayKey) {
    if (!Array.isArray(db.reminderLog)) db.reminderLog = [];
    const cutoff = parseLocal(todayKey);
    cutoff.setDate(cutoff.getDate() - 14);
    const cutoffKey = localDateKey(cutoff);
    db.reminderLog = db.reminderLog.filter(key => String(key).slice(0, 10) >= cutoffKey);
    notifiedDoseKeys.clear();
    db.reminderLog.forEach(key => notifiedDoseKeys.add(key));
    Array.from(pendingReminderKeys).forEach(key => {
        if (String(key).slice(0, 10) < cutoffKey) pendingReminderKeys.delete(key);
    });
}

async function checkSchedules() {
    if (checkSchedulesRunning) return;
    checkSchedulesRunning = true;
    const now = new Date();
    const todayKey = localDateKey(now);
    const currentTime = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    pruneReminderLog(todayKey);
    let reminderLogChanged = false;

    try {
        const dueMedicationReminders = new Map();
        for (const s of db.schedules) {
            if (!isScheduleDueOnDate(s, todayKey) ||
                !getScheduleTimes(s).includes(currentTime) ||
                isScheduleInstanceDocumented(s.id, todayKey, currentTime)) continue;

            const med = db.inventory.find(m => m.id === s.medId);
            const member = db.family.find(f => f.id === s.memberId);
            if (!med || !member) continue;
            const groupKey = medicationReminderGroupKey(s, med, member, todayKey, currentTime);
            if (!dueMedicationReminders.has(groupKey)) {
                dueMedicationReminders.set(groupKey, { schedule: s, med, member });
            }
        }

        for (const { schedule: s, med, member } of dueMedicationReminders.values()) {
            const notificationPrefs = member.notificationPrefs || {};
            const reminderBaseKey = medicationReminderGroupKey(s, med, member, todayKey, currentTime);
            const desktopKey = `${reminderBaseKey}|desktop`;
            const emailKey = `${reminderBaseKey}|email`;

            if (notificationPrefs.medicationReminders !== false) {
                const sent = await dispatchReminderOnce(desktopKey, () => window.api.notify("Medication Due!", `${member.firstName} needs ${med.name} at ${currentTime}`));
                reminderLogChanged = reminderLogChanged || sent;
            }

            if (member.email && notificationPrefs.emailReminders === true) {
                const sent = await dispatchReminderOnce(emailKey, () => window.api.sendEmail({
                    to: member.email,
                    subject: `PharmAtlas: Medication Reminder for ${member.firstName}`,
                    body: `Hello, this is a reminder to take ${formatQtyForSchedule(s, med)} of ${med.name} (${formatMedStrength(med, true)}) at ${currentTime}.\nInstructions: ${s.instructions || 'None'}`
                }));
                reminderLogChanged = reminderLogChanged || sent;
            }
        }

        const dueCareReminders = new Map();
        for (const reminder of ensureCareReminderStore()) {
            if (reminder.enabled === false ||
                !isScheduleDueOnDate(reminder, todayKey) ||
                !getScheduleTimes(reminder).includes(currentTime) ||
                careReminderReadingLoggedForInstance(reminder, todayKey, currentTime)) continue;

            const member = db.family.find(f => f.id === reminder.memberId);
            if (!member) continue;
            const groupKey = careReminderGroupKey(reminder, member, todayKey, currentTime);
            if (!dueCareReminders.has(groupKey)) {
                dueCareReminders.set(groupKey, { reminder, member });
            }
        }

        for (const { reminder, member } of dueCareReminders.values()) {
            const notificationPrefs = member.notificationPrefs || {};
            const reminderLabel = careReminderTypeLabel(reminder.type, reminder.memberId);
            const note = reminder.note ? ` (${reminder.note})` : '';
            const reminderBaseKey = careReminderGroupKey(reminder, member, todayKey, currentTime);
            const desktopKey = `${reminderBaseKey}|desktop`;
            const emailKey = `${reminderBaseKey}|email`;

            if (notificationPrefs.medicationReminders !== false) {
                const sent = await dispatchReminderOnce(desktopKey, () => window.api.notify("Monitoring Reminder", `${member.firstName}: ${reminderLabel} at ${currentTime}${note}`));
                reminderLogChanged = reminderLogChanged || sent;
            }

            if (member.email && notificationPrefs.emailReminders === true) {
                const sent = await dispatchReminderOnce(emailKey, () => window.api.sendEmail({
                    to: member.email,
                    subject: `PharmAtlas: Monitoring Reminder for ${member.firstName}`,
                    body: `Hello, this is a reminder to ${reminderLabel.toLowerCase()} for ${memberDisplayName(member)} at ${currentTime}.\n${reminder.note ? `Note: ${reminder.note}` : ''}`
                }));
                reminderLogChanged = reminderLogChanged || sent;
            }
        }

        for (const event of ensureCustomEvents()) {
            const eventReminder = customEventReminderMatch(event, todayKey, currentTime);
            if (!eventReminder) continue;

            const linkedMembers = customEventMembers(event);
            const memberNames = linkedMembers.map(memberDisplayName).join(', ');
            const eventBaseKey = `${eventReminder.occurrenceDate}|event|${event.id}|${todayKey}|${currentTime}`;
            const desktopKey = `${eventBaseKey}|desktop`;
            const desktopSent = await dispatchReminderOnce(desktopKey, () => window.api.notify("PharmAtlas Task Due", `${event.title || customEventTypeLabel(event.type)} at ${event.time}${memberNames ? ` for ${memberNames}` : ''}`));
            reminderLogChanged = reminderLogChanged || desktopSent;

            for (const member of linkedMembers) {
                const notificationPrefs = member.notificationPrefs || {};
                const emailKey = `${eventBaseKey}|${member.id}|email`;
                if (!member.email || notificationPrefs.emailReminders !== true) continue;
                const emailSent = await dispatchReminderOnce(emailKey, () => window.api.sendEmail({
                    to: member.email,
                    subject: `PharmAtlas: Task Reminder for ${member.firstName}`,
                    body: `Hello, this is a reminder for: ${event.title || customEventTypeLabel(event.type)}.\nEvent time: ${eventReminder.occurrenceDate} ${event.time}\nReminder sent: ${todayKey} ${currentTime}\n${event.note ? `Note: ${event.note}\n` : ''}${customEventLinkSummary(event) ? `Linked items: ${customEventLinkSummary(event)}` : ''}`
                }));
                reminderLogChanged = reminderLogChanged || emailSent;
            }
        }

        if (reminderLogChanged) await window.api.save(db);
    } finally {
        checkSchedulesRunning = false;
    }
}

setInterval(checkSchedules, 60 * 1000); // Check every minute

window.toggleQODDate = function() {
    renderFrequencyControls('sched');
};

function buildScheduleFromEntry(id = `pending-${Date.now()}-${Math.random().toString(16).slice(2)}`) {
    const memberId = document.getElementById('select-member').value;
    const medId = document.getElementById('sched-strength-display').value;
    const med = db.inventory.find(m => m.id === medId);
    const member = db.family.find(m => m.id === memberId);

    const selectedFreq = document.getElementById('sched-freq')?.value || '';
    const selectedTimingFreq = selectedFreq === 'PRN'
        ? (document.getElementById('sched-prn-schedule-freq')?.value || '')
        : selectedFreq;
    const startDate = selectedTimingFreq === 'QOD'
        ? (document.getElementById('qod-start-date')?.value || document.getElementById('sched-start').value)
        : document.getElementById('sched-start').value;
    const rawEndDate = document.getElementById('sched-end').value || "Ongoing";

    const indication = document.getElementById('sched-indication')?.value.trim() || '';
    const instructions = document.getElementById('sched-instructions').value;

    if (!member) return void appAlert("Select a family member first.");
    if (!med || !startDate) return void appAlert("Select medication name, strength, and start date!");
    if (!medicationAssignedToMember(med, memberId)) {
        return void appAlert(`${med.name} is not assigned to ${memberDisplayName(member)}. Open the medication profile in Inventory to assign it first.`);
    }

    const frequencyDetails = collectFrequencyDetails('sched');
    if (!frequencyDetails) return;
    const endDate = frequencyDetails.timingFreq === 'ONCE' ? startDate : rawEndDate;
    if (endDate !== "Ongoing" && endDate < startDate) return void appAlert("End date cannot be before the start date.");
    const monitoringConfig = collectMonitoringScheduleConfig('sched', memberId);
    if (monitoringConfig.error) return void appAlert(monitoringConfig.error);
    if (frequencyDetails.timingFreq === 'ONCE' && monitoringConfig.schedule) {
        Object.values(monitoringConfig.schedule.byType || {}).forEach(schedule => {
            schedule.startDate = startDate;
            schedule.endDate = startDate;
        });
    }
    const selectedLinkTargetIds = selectedOptionValues(document.getElementById('sched-link-target'));
    const linkMode = document.getElementById('sched-link-mode')?.value || '';
    const linkTargetIds = linkMode ? selectedLinkTargetIds : [];
    const targetChoice = scheduleLinkChoices(memberId).find(choice => choice.id === linkTargetIds[0]);
    const linkGroup = linkMode && targetChoice ? linkGroupFromTarget(targetChoice.id) : '';
    if (selectedLinkTargetIds.length > 0 && !linkMode) return void appAlert("Choose what the medication link means: must take together or choose only one.");
    if (linkMode && linkTargetIds.length === 0) return void appAlert("Select the medication this one is linked to.");

    const schedule = {
        id,
        memberId,
        medId: med.id,
        doseQty: document.getElementById('sched-dose-qty').value,
        prescriberId: document.getElementById('sched-prescriber')?.value || med.prescriberId || '',
        freq: frequencyDetails.freq,
        startDate,
        endDate,
        indication,
        instructions: instructions,
        linkGroup,
        linkMode,
        linkTargetIds,
        linkTargetId: linkTargetIds[0] || '',
        linkRules: linkRulesFromTargets(linkTargetIds, linkMode),
        qodStart: frequencyDetails.timingFreq === 'QOD' ? (document.getElementById('qod-start-date').value || startDate) : "",
        times: frequencyDetails.times,
        intervalHours: frequencyDetails.intervalHours,
        intervalWeeks: frequencyDetails.intervalWeeks || null,
        monthlyAnchor: frequencyDetails.monthlyAnchor || '',
        timesPerWeek: frequencyDetails.timesPerWeek || null,
        weekdays: frequencyDetails.weekdays || [],
        prnScheduleFreq: frequencyDetails.prnScheduleFreq || '',
        prnMaxDoses: frequencyDetails.prnMaxDoses || null,
        prnWindowHours: frequencyDetails.prnWindowHours || 24,
        monitoringReminders: monitoringConfig.types,
        monitoringReminderNote: monitoringConfig.note,
        monitoringReminderSchedule: monitoringConfig.schedule,
        monitoringHoldRule: monitoringConfig.holdRule,
        reorderSourceId: scheduleReorderSourceId || '',
        startTime: frequencyDetails.startTime || frequencyDetails.times[0] || "",
        isOneTime: frequencyDetails.timingFreq === 'ONCE' || (startDate === endDate && endDate !== "Ongoing")
    };
    if (linkMode === 'together') {
        const allChoices = [...db.schedules, ...pendingScheduleOrders];
        const mismatchedTarget = linkTargetIds
            .map(targetId => allChoices.find(choice => choice.id === targetId))
            .find(target => target && !schedulesHaveAlignedTiming(schedule, target));
        if (mismatchedTarget) {
            return void appAlert(`Must-take-together medications need the same date, frequency, and administration time.\n\nThis order: ${timingMismatchLabel(schedule)}\nLinked order: ${timingMismatchLabel(mismatchedTarget)}`);
        }
    }
    return schedule;
}

